/// <summary>v16.0.0 Titan — RSA-2048 비대칭 무결성 + 로컬 ComfyUI I2V 폴백 회귀.</summary>
[Collection("ProcessGcMode")]   // 서명 모드 환경변수는 프로세스 전역 → 직렬화
public class TitanReleaseTests
{
    [Fact]
    public async Task RsaIntegrity_And_LocalI2vFallback_Check()
    {
        // ══ ① 내장 공개키: 2048비트 SPKI · 개인키 미포함 ══
        using (var pub = System.Security.Cryptography.RSA.Create())
        {
            pub.ImportSubjectPublicKeyInfo(Convert.FromBase64String(AppIntegrityGuard.PublicKey), out _);
            Assert.True(pub.KeySize >= AppIntegrityGuard.MinKeyBits);
            Assert.ThrowsAny<System.Security.Cryptography.CryptographicException>(() => pub.ExportPkcs8PrivateKey());
        }
        Assert.Equal("pfi1.manifest", AppIntegrityGuard.ManifestFileName);

        var dir = Path.Combine(Path.GetTempPath(), "pfs-titan-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(dir);
        var prevKey = Environment.GetEnvironmentVariable(AppIntegrityGuard.SigningKeyEnvVar);
        try
        {
            foreach (var f in AppIntegrityGuard.CoreFiles)
                File.WriteAllBytes(Path.Combine(dir, f), System.Security.Cryptography.RandomNumberGenerator.GetBytes(8192));
            File.WriteAllBytes(Path.Combine(dir, "ffmpeg.exe"), System.Security.Cryptography.RandomNumberGenerator.GetBytes(2048));

            // ② 서명(PEM 입력) → 자기 검증 Verified · 매니페스트 SIG 줄 = RSA-2048 서명(256B)
            using var rsa = System.Security.Cryptography.RSA.Create(2048);
            var pubB64 = Convert.ToBase64String(rsa.ExportSubjectPublicKeyInfo());
            var self = AppIntegrityGuard.SignManifest(rsa.ExportPkcs8PrivateKeyPem(), dir, AppIntegrityGuard.CoreFiles);
            Assert.Equal(IntegrityVerdict.Verified, self.Verdict);
            Assert.Equal(AppIntegrityGuard.CoreFiles.Length, self.Checked);
            var mPath = Path.Combine(dir, AppIntegrityGuard.ManifestFileName);
            var lines = File.ReadAllLines(mPath);
            Assert.StartsWith("SIG ", lines[^1]);
            Assert.Equal(256, Convert.FromBase64String(lines[^1].Substring(4)).Length);

            // ③ 공격자 키로 재서명한 매니페스트는 내장 공개키로 거부(위조 불가) · 서명 1비트 변조 → Tampered · 공개키 손상 → KeyUnavailable(종료 안 함)
            Assert.Equal(IntegrityVerdict.Tampered, AppIntegrityGuard.Verify(dir, AppIntegrityGuard.PublicKey).Verdict);
            var sig = Convert.FromBase64String(lines[^1].Substring(4));
            sig[10] ^= 0x01;
            lines[^1] = "SIG " + Convert.ToBase64String(sig);
            File.WriteAllLines(mPath, lines);
            Assert.Equal(IntegrityVerdict.Tampered, AppIntegrityGuard.Verify(dir, pubB64).Verdict);
            var badKey = AppIntegrityGuard.Verify(dir, "not-a-key");
            Assert.Equal(IntegrityVerdict.KeyUnavailable, badKey.Verdict);
            Assert.False(badKey.ShouldShutdown);
            using (var small = System.Security.Cryptography.RSA.Create(1024))
                Assert.Throws<ArgumentException>(() => AppIntegrityGuard.SignManifest(Convert.ToBase64String(small.ExportPkcs8PrivateKey()), dir));

            // ④ CI/CD 서명 모드: 키 없음=2 · 내장 공개키와 쌍이 아닌 개인키=4(ffmpeg.exe 동봉 시 함께 서명)
            Environment.SetEnvironmentVariable(AppIntegrityGuard.SigningKeyEnvVar, null);
            Assert.Equal(2, AppIntegrityGuard.RunSignCommand(dir, out _));
            Environment.SetEnvironmentVariable(AppIntegrityGuard.SigningKeyEnvVar, Convert.ToBase64String(rsa.ExportPkcs8PrivateKey()));
            Assert.Equal(4, AppIntegrityGuard.RunSignCommand(dir, out var msg));
            Assert.Contains("내장 공개키", msg);
            var signed = AppIntegrityGuard.Verify(dir, pubB64);
            Assert.Equal(IntegrityVerdict.Verified, signed.Verdict);
            Assert.Equal(AppIntegrityGuard.CoreFiles.Length + 1, signed.Checked);
            Assert.Contains(File.ReadAllLines(mPath), l => l.EndsWith(" ffmpeg.exe", StringComparison.Ordinal));
        }
        finally
        {
            Environment.SetEnvironmentVariable(AppIntegrityGuard.SigningKeyEnvVar, prevKey);
            try { Directory.Delete(dir, true); } catch (IOException) { }
        }

        // ══ ⑤ 로컬 I2V: http(s) 스트리밍 다운로드(5xx 지수 백오프 재시도) → 임시 파일 소유 ══
        var tmp = Path.Combine(Path.GetTempPath(), "pfs-titan-i2v-" + Guid.NewGuid().ToString("N"));
        try
        {
            var png = System.Security.Cryptography.RandomNumberGenerator.GetBytes(200_000);
            var handler = new FlakyImageHandler(png, failFirst: 1);
            using var http = new System.Net.Http.HttpClient(handler);
            var req = new PromptFlowStudio.Services.Wan.WanVideoRequest { Prompt = "p", ImageUrl = "https://cdn.example.com/a/anchor.JPG?x=1" };
            var (path, owned) = await PromptFlowStudio.Services.Wan.ComfyUiVideoEngine.PrepareI2vImageAsync(req, http, tmp, CancellationToken.None);
            Assert.NotNull(path);
            Assert.True(owned);
            Assert.Equal(".jpg", Path.GetExtension(path));
            Assert.Equal(png, File.ReadAllBytes(path!));
            Assert.Equal(2, handler.Calls);

            // 로컬 ImagePath 우선(다운로드 없음 · 소유 아님)
            var viaPath = await PromptFlowStudio.Services.Wan.ComfyUiVideoEngine.PrepareI2vImageAsync(req with { ImagePath = path }, http, tmp, CancellationToken.None);
            Assert.Equal(Path.GetFullPath(path!), viaPath.Path);
            Assert.False(viaPath.Owned);
            Assert.Equal(2, handler.Calls);

            // oss:// · 4xx → (null,false) — T2V 로 Graceful
            var oss = await PromptFlowStudio.Services.Wan.ComfyUiVideoEngine.PrepareI2vImageAsync(new() { Prompt = "p", ImageUrl = "oss://bucket/x.png" }, http, tmp, CancellationToken.None);
            Assert.Null(oss.Path);
            using var http404 = new System.Net.Http.HttpClient(new FlakyImageHandler(png, failFirst: 0, status: System.Net.HttpStatusCode.NotFound));
            var nf = await PromptFlowStudio.Services.Wan.ComfyUiVideoEngine.PrepareI2vImageAsync(req, http404, tmp, CancellationToken.None);
            Assert.Null(nf.Path);
            Assert.Single(Directory.GetFiles(tmp));   // 실패 경로는 부분 파일을 남기지 않음

            // ⑥ LoadImage 결선: {image} 없으면 --image 추가 · 이미지 없으면 {image}와 앞 플래그 제거
            var baseArgs = new[] { "--prompt", "{prompt}", "--output", "{out}" };
            Assert.Equal(new[] { "--prompt", "{prompt}", "--output", "{out}", "--image", "{image}" },
                PromptFlowStudio.Services.Wan.ComfyUiVideoEngine.BuildI2vTemplate(baseArgs, path));
            var withImg = new[] { "--prompt", "{prompt}", "--load-image", "{image}", "--output", "{out}" };
            Assert.Same(withImg, PromptFlowStudio.Services.Wan.ComfyUiVideoEngine.BuildI2vTemplate(withImg, path));
            Assert.Equal(baseArgs, PromptFlowStudio.Services.Wan.ComfyUiVideoEngine.BuildI2vTemplate(withImg, null));
            Assert.Same(baseArgs, PromptFlowStudio.Services.Wan.ComfyUiVideoEngine.BuildI2vTemplate(baseArgs, null));
        }
        finally { try { Directory.Delete(tmp, true); } catch (IOException) { } }
    }

    [Fact]
    public void InstallerPackaging_And_FfmpegBundle_Check()
    {
        var root = RepoRoot();
        var bundleScript = Path.Combine(root, "scripts", "bundle_ffmpeg.ps1");
        var iss = Path.Combine(root, "installer", "promptflow_studio.iss");
        Assert.True(File.Exists(bundleScript));
        Assert.True(File.Exists(iss));

        // ══ ① 서명 대상 결선: ffmpeg.exe 는 OptionalFiles — 동봉됐을 때만 서명 대상 ══
        Assert.Contains("ffmpeg.exe", AppIntegrityGuard.OptionalFiles);
        var work = Path.Combine(Path.GetTempPath(), "pfs-installer-" + Guid.NewGuid().ToString("N"));
        var pub = Path.Combine(work, "publish");
        var src = Path.Combine(work, "src");
        Directory.CreateDirectory(pub);
        Directory.CreateDirectory(src);
        try
        {
            foreach (var f in AppIntegrityGuard.CoreFiles)
                File.WriteAllBytes(Path.Combine(pub, f), System.Security.Cryptography.RandomNumberGenerator.GetBytes(4096));
            Assert.Equal(AppIntegrityGuard.CoreFiles, AppIntegrityGuard.ResolveSignTargets(pub));

            if (OperatingSystem.IsWindows())
            {
                // ══ ② bundle_ffmpeg.ps1 검증 게이트: 폴더 없음=15 · 원본 없음=10 · 비PE/DLL=11 · 해시 불일치=12 · 정상=0 ══
                var ffSrc = Path.Combine(src, "ffmpeg.exe");
                Assert.Equal(15, RunBundle(bundleScript, Path.Combine(work, "missing"), ffSrc));
                Assert.Equal(10, RunBundle(bundleScript, pub, ffSrc));

                File.WriteAllBytes(ffSrc, System.Security.Cryptography.RandomNumberGenerator.GetBytes(2048));
                Assert.Equal(11, RunBundle(bundleScript, pub, ffSrc));
                File.WriteAllBytes(ffSrc, SyntheticPe(dll: true));
                Assert.Equal(11, RunBundle(bundleScript, pub, ffSrc));

                var pe = SyntheticPe(dll: false);
                File.WriteAllBytes(ffSrc, pe);
                Assert.Equal(12, RunBundle(bundleScript, pub, ffSrc, new string('0', 64)));
                Assert.False(File.Exists(Path.Combine(pub, "ffmpeg.exe")));

                var sha = Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(pe));
                Assert.Equal(0, RunBundle(bundleScript, pub, ffSrc, sha.ToLowerInvariant()));
                Assert.Equal(pe, File.ReadAllBytes(Path.Combine(pub, "ffmpeg.exe")));
            }
            else File.WriteAllBytes(Path.Combine(pub, "ffmpeg.exe"), SyntheticPe(dll: false));

            // ══ ③ 동봉된 ffmpeg.exe → 서명 대상 자동 포함 · 매니페스트 검증 ══
            var targets = AppIntegrityGuard.ResolveSignTargets(pub);
            Assert.Equal(AppIntegrityGuard.CoreFiles.Length + 1, targets.Count);
            Assert.Equal("ffmpeg.exe", targets[^1]);
            using var rsa = System.Security.Cryptography.RSA.Create(2048);
            var signed = AppIntegrityGuard.SignManifest(Convert.ToBase64String(rsa.ExportPkcs8PrivateKey()), pub, targets);
            Assert.Equal(IntegrityVerdict.Verified, signed.Verdict);
            Assert.Contains(File.ReadAllLines(Path.Combine(pub, AppIntegrityGuard.ManifestFileName)), l => l.EndsWith(" ffmpeg.exe", StringComparison.Ordinal));
        }
        finally { try { Directory.Delete(work, true); } catch (IOException) { } }

        // ══ ④ Inno Setup 규격: 서명 게이트 · 매니페스트 동봉 · LocalAppData 권한 · WebView2 검증 ══
        var spec = File.ReadAllText(iss);
        Assert.Contains("#if !FileExists(AddBackslash(PublishDir) + Manifest)", spec);
        Assert.Contains("#define Manifest \"" + AppIntegrityGuard.ManifestFileName + "\"", spec);
        Assert.Contains("Source: \"{#PublishDir}\\{#Manifest}\"; DestDir: \"{app}\"", spec);
        Assert.Contains("Source: \"{#PublishDir}\\ffmpeg.exe\"", spec);
        Assert.Contains("Name: \"{localappdata}\\PromptFlowStudio\"; Flags: uninsneveruninstall", spec);   // v16.4.0: users-modify 폐기(최소 권한)
        Assert.Contains("{F3017226-FE2A-4295-8BDF-00C3A9A7E4C5}", spec);
        Assert.Contains("function IsWebView2Installed: Boolean;", spec);
        Assert.Contains("ArchitecturesInstallIn64BitMode=x64compatible", spec);
        Assert.DoesNotContain("pfi1_signing", spec);   // 개인키 경로/내용이 인스톨러로 새지 않음

        var pipeline = File.ReadAllText(Path.Combine(root, "build_titan_release.ps1"));
        Assert.Contains("scripts\\bundle_ffmpeg.ps1", pipeline);
        Assert.Contains("installer\\promptflow_studio.iss", pipeline);
        Assert.Contains("-p:PublishReadyToRun=true", pipeline);
    }

    [Fact]
    public void CiCdPipeline_And_RedistBundle_Check()
    {
        var root = RepoRoot();
        var yml = File.ReadAllText(Path.Combine(root, ".github", "workflows", "release.yml"));

        // ══ ① 트리거 · runner · 권한: 태그 v* → windows-latest · Release 쓰기 ══
        Assert.Contains("tags: [ 'v*' ]", yml);
        Assert.Contains("runs-on: windows-latest", yml);
        Assert.Contains("contents: write", yml);
        Assert.DoesNotContain("pull_request", yml);   // 서명 시크릿은 PR(포크) 컨텍스트에 노출 금지

        // ══ ② 품질 게이트 → 파이프라인 순서: -warnaserror 빌드 → 테스트 → 서명 파이프라인 → Release 첨부 ══
        int build = yml.IndexOf("-c Release -warnaserror", StringComparison.Ordinal);
        int test = yml.IndexOf("dotnet test PromptFlowStudio.Tests", StringComparison.Ordinal);
        int sign = yml.IndexOf("./build_titan_release.ps1 @titan", StringComparison.Ordinal);
        int release = yml.IndexOf("softprops/action-gh-release@v2", StringComparison.Ordinal);
        Assert.True(build > 0 && build < test && test < sign && sign < release, "워크플로우 스텝 순서 위반");
        Assert.Contains("BuildInstaller        = $true", yml);
        Assert.Contains("RequireWebView2Redist = $true", yml);
        Assert.Contains("FetchWebView2         = $true", yml);
        Assert.Contains("dist/PromptFlowStudio-*-win-x64-setup.exe", yml);
        Assert.Contains("dist/pfi1.manifest", yml);
        Assert.Contains("actions/upload-artifact@v4", yml);
        Assert.Contains("fail_on_unmatched_files: true", yml);

        // ══ ③ 시크릿 결선: PROMPTFLOW_SIGNING_KEY 는 env 매핑으로만 — 명령줄/echo/파일 기록 금지 ══
        const string secretRef = "${{ secrets.PROMPTFLOW_SIGNING_KEY }}";
        Assert.Contains(AppIntegrityGuard.SigningKeyEnvVar + ": " + secretRef, yml);
        int at = 0, refs = 0;
        while ((at = yml.IndexOf(secretRef, at, StringComparison.Ordinal)) >= 0)
        {
            int lineStart = yml.LastIndexOf('\n', at) + 1;
            Assert.Equal(AppIntegrityGuard.SigningKeyEnvVar + ": ", yml.AsSpan(lineStart, at - lineStart).TrimStart().ToString());
            at += secretRef.Length;
            refs++;
        }
        Assert.Equal(2, refs);   // 존재 확인 스텝 + 서명 스텝
        Assert.DoesNotContain("echo $env:PROMPTFLOW_SIGNING_KEY", yml);
        Assert.DoesNotContain("Write-Host $env:PROMPTFLOW_SIGNING_KEY", yml);

        // ══ ④ 파이프라인 스크립트: CI 파라미터 결선 ══
        var pipeline = File.ReadAllText(Path.Combine(root, "build_titan_release.ps1"));
        Assert.Contains("scripts\\fetch_webview2.ps1", pipeline);
        Assert.Contains("'/DRequireWebView2Redist'", pipeline);
        Assert.Contains("'-DownloadUrl', $FfmpegUrl, '-ExpectedArchiveSha256', $FfmpegArchiveSha256", pipeline);
        var fetch = File.ReadAllText(Path.Combine(root, "scripts", "fetch_webview2.ps1"));
        Assert.Contains("Get-AuthenticodeSignature", fetch);
        Assert.Contains("O=Microsoft Corporation", fetch);
        Assert.Contains("https://go.microsoft.com/fwlink/p/?LinkId=2124703", fetch);

        // ══ ⑤ ISS: redist 자동 감지(Standalone 우선) · dontcopy 추출 · 사일런트 설치 · 재검증 · 필수 게이트 ══
        var iss = File.ReadAllText(Path.Combine(root, "installer", "promptflow_studio.iss"));
        int standalone = iss.IndexOf("#if FileExists(WebView2Standalone)", StringComparison.Ordinal);
        int bootstrap = iss.IndexOf("#elif FileExists(WebView2Bootstrapper)", StringComparison.Ordinal);
        Assert.True(standalone > 0 && standalone < bootstrap, "Standalone 오프라인 설치 파일 우선 감지 위반");
        Assert.Contains("Source: \"{#WebView2Redist}\"; Flags: dontcopy", iss);
        Assert.Contains("ExtractTemporaryFile('{#WebView2RedistName}')", iss);
        Assert.Contains("Exec(Exe, '/silent /install', '', SW_HIDE, ewWaitUntilTerminated, ResultCode)", iss);
        Assert.Contains("Result := IsWebView2Installed;", iss);
        Assert.Contains("function PrepareToInstall(var NeedsRestart: Boolean): String;", iss);
        Assert.Contains("#ifdef RequireWebView2Redist", iss);

        // ══ ⑥ redist 실물(존재 시): Windows PE 실행 파일 · 크기 상식선 ══
        var redist = Path.Combine(root, "installer", "redist");
        foreach (var name in new[] { "MicrosoftEdgeWebview2Setup.exe", "MicrosoftEdgeWebView2RuntimeInstallerX64.exe" })
        {
            var path = Path.Combine(redist, name);
            if (!File.Exists(path)) continue;
            Span<byte> head = stackalloc byte[2];
            using (var fs = File.OpenRead(path))
            {
                Assert.Equal(2, fs.Read(head));
                Assert.InRange(fs.Length, 512 * 1024, 512L * 1024 * 1024);
            }
            Assert.True(head[0] == (byte)'M' && head[1] == (byte)'Z', name + " 는 PE 실행 파일이 아님");
        }
    }

    [Fact]
    public void ProductionReleaseVerification_Check()
    {
        var root = RepoRoot();

        // ══ ① --pfi1-verify 검인 모드: 종료 코드 계약(0 Verified · 3 Tampered · 6 Unsealed · 7 KeyUnavailable) ══
        Assert.Equal("--pfi1-verify", AppIntegrityGuard.VerifyCommand);
        var work = Path.Combine(Path.GetTempPath(), "pfs-gm-" + Guid.NewGuid().ToString("N"));
        var publish = Path.Combine(work, "publish");
        Directory.CreateDirectory(Path.Combine(publish, "wwwroot"));
        try
        {
            foreach (var f in AppIntegrityGuard.CoreFiles)
                File.WriteAllBytes(Path.Combine(publish, f), System.Security.Cryptography.RandomNumberGenerator.GetBytes(4096));
            File.WriteAllBytes(Path.Combine(publish, "PromptFlowStudio.exe"), System.Security.Cryptography.RandomNumberGenerator.GetBytes(1024));
            File.WriteAllText(Path.Combine(publish, "wwwroot", "index.html"), "<html/>");

            Assert.Equal(6, AppIntegrityGuard.RunVerifyCommand(publish, out var unsealedMsg));
            Assert.StartsWith("Unsealed", unsealedMsg);
            using var rsa = System.Security.Cryptography.RSA.Create(2048);
            var pub = Convert.ToBase64String(rsa.ExportSubjectPublicKeyInfo());
            AppIntegrityGuard.SignManifest(Convert.ToBase64String(rsa.ExportPkcs8PrivateKey()), publish, AppIntegrityGuard.ResolveSignTargets(publish));
            Assert.Equal(0, AppIntegrityGuard.RunVerifyCommand(publish, out var okMsg, pub));
            Assert.Equal("Verified 2/0", okMsg);
            Assert.Equal(3, AppIntegrityGuard.RunVerifyCommand(publish, out _));          // 내장 공개키 ≠ 테스트 키 → 위조 판정
            Assert.Equal(7, AppIntegrityGuard.RunVerifyCommand(publish, out _, "!!"));

            // ══ ② 설치/제거 사이클 시뮬레이션 — ISS 규칙을 해석해 가상 {app}/{localappdata} 에 적용 ══
            var iss = File.ReadAllText(Path.Combine(root, "installer", "promptflow_studio.iss"));
            var fs = new InnoSandbox(work);
            var userData = fs.SeedUserData();
            fs.Install(iss, publish);
            Assert.True(File.Exists(Path.Combine(fs.App, AppIntegrityGuard.ManifestFileName)));
            Assert.True(File.Exists(Path.Combine(fs.App, "wwwroot", "index.html")));
            Assert.Equal(0, AppIntegrityGuard.RunVerifyCommand(fs.App, out _, pub));   // 설치본도 서명 그대로(바이트 동일 복사)
            fs.Uninstall(iss);
            Assert.False(Directory.Exists(fs.App), "제거 후 {app} 잔존");
            foreach (var (path, bytes) in userData)
                Assert.True(File.Exists(path) && bytes.AsSpan().SequenceEqual(File.ReadAllBytes(path)), "사용자 데이터 손상: " + path);

            // 재설치(업그레이드) 사이클에도 보존
            fs.Install(iss, publish);
            fs.Uninstall(iss);
            foreach (var (path, bytes) in userData)
                Assert.True(bytes.AsSpan().SequenceEqual(File.ReadAllBytes(path)), "재설치 후 사용자 데이터 손상: " + path);

            // 음성 대조: LocalAppData 를 지우는 규칙이 섞이면 시뮬레이터가 vault.enc 소실을 잡아낸다
            var hostile = iss.Replace("[UninstallDelete]", "[UninstallDelete]\r\nType: filesandordirs; Name: \"{localappdata}\\PromptFlowStudio\"", StringComparison.Ordinal);
            var fs2 = new InnoSandbox(Path.Combine(work, "neg"));
            var neg = fs2.SeedUserData();
            fs2.Install(hostile, publish);
            fs2.Uninstall(hostile);
            Assert.False(File.Exists(neg[0].Path));
        }
        finally { try { Directory.Delete(work, true); } catch (IOException) { } }

        // ══ ③ ISS 정적 규칙: 사용자 데이터 루트는 uninsneveruninstall · 삭제 규칙/코드에서 LocalAppData 접근 금지 ══
        var spec = File.ReadAllText(Path.Combine(root, "installer", "promptflow_studio.iss"));
        foreach (var e in InnoSandbox.Entries(spec, "Dirs"))
            if (e["Name"].StartsWith("{localappdata}", StringComparison.Ordinal))
                Assert.Contains("uninsneveruninstall", e.GetValueOrDefault("Flags", ""));
        foreach (var section in new[] { "UninstallDelete", "InstallDelete" })
            foreach (var e in InnoSandbox.Entries(spec, section))
                Assert.False(e["Name"].Contains("{localappdata}", StringComparison.OrdinalIgnoreCase) || e["Name"].Contains("{userappdata}", StringComparison.OrdinalIgnoreCase), section + " 가 사용자 데이터를 가리킴");
        var code = spec[spec.IndexOf("[Code]", StringComparison.Ordinal)..];
        Assert.DoesNotContain("DelTree", code);
        // {localappdata} 접근은 레거시 ACE 회수 1곳뿐(데이터 삭제 경로 없음)
        int lad = code.IndexOf("{localappdata}", StringComparison.Ordinal);
        Assert.True(lad > code.IndexOf("procedure RevokeLegacyUsersAce;", StringComparison.Ordinal) && code.IndexOf("{localappdata}", lad + 1, StringComparison.Ordinal) < 0);

        // ══ ④ verify_release.ps1 · 파이프라인 · CI 결선 ══
        var verify = Path.Combine(root, "scripts", "verify_release.ps1");
        var vs = File.ReadAllText(verify);
        foreach (var needle in new[] { "--pfi1-verify", "'PE32+/AMD64'", "pfs-release-bom/1", "Config\\vault.enc", "Get-AuthenticodeSignature", "-RequireFfmpeg", "InstallCycle", "GOLDEN_MASTER" })
            Assert.Contains(needle, vs);
        Assert.Contains("pfs-release-bom/1", File.ReadAllText(Path.Combine(root, "build_titan_release.ps1")));
        var yml = File.ReadAllText(Path.Combine(root, ".github", "workflows", "release.yml"));
        int pipe = yml.IndexOf("./build_titan_release.ps1 @titan", StringComparison.Ordinal);
        int gm = yml.IndexOf("./scripts/verify_release.ps1 @verify", StringComparison.Ordinal);
        int rel = yml.IndexOf("softprops/action-gh-release@v2", StringComparison.Ordinal);
        Assert.True(pipe > 0 && pipe < gm && gm < rel, "검인 스텝은 빌드 후 · 게시 전");
        Assert.Contains("InstallCycle          = $true", yml);
        Assert.Contains("dist/*.verify.json", yml);

        if (OperatingSystem.IsWindows())
        {
            // 입력 산출물 없음 → 종료 코드 2(검인 거부)
            var psi = new ProcessStartInfo("powershell.exe") { UseShellExecute = false, CreateNoWindow = true, RedirectStandardOutput = true, RedirectStandardError = true };
            foreach (var a in new[] { "-NoProfile", "-NonInteractive", "-ExecutionPolicy", "Bypass", "-File", verify, "-SetupPath", Path.Combine(work, "none-setup.exe") })
                psi.ArgumentList.Add(a);
            using var p = Process.Start(psi)!;
            var so = p.StandardOutput.ReadToEndAsync();
            var se = p.StandardError.ReadToEndAsync();
            Assert.True(p.WaitForExit(60_000));
            Task.WaitAll(so, se);
            Assert.Equal(2, p.ExitCode);
        }
    }

    [Fact]
    public void SecurityAclAndAuthenticodeSign_Check()
    {
        var root = RepoRoot();
        var iss = File.ReadAllText(Path.Combine(root, "installer", "promptflow_studio.iss"));

        // ══ ① ISS 최소 권한: 어떤 항목도 Permissions 를 부여하지 않음(상속 ACL = SYSTEM · Administrators · 현재 사용자) ══
        foreach (var section in new[] { "Dirs", "Files", "Registry" })
            foreach (var e in InnoSandbox.Entries(iss, section))
                Assert.False(e.ContainsKey("Permissions"), section + " 항목에 Permissions 부여: " + e.GetValueOrDefault("Name", e.GetValueOrDefault("Source", "?")));
        var dirs = InnoSandbox.Entries(iss, "Dirs");
        Assert.Contains(dirs, e => e["Name"] == "{localappdata}\\PromptFlowStudio\\Config");
        foreach (var e in dirs) Assert.Contains("uninsneveruninstall", e.GetValueOrDefault("Flags", ""));

        // ══ ② 레거시 BUILTIN\Users ACE 회수: 루트만 · 허용 ACE 만 · 재귀/리셋/추가 부여 금지 · ssInstall 에서 호출 ══
        var code = iss[iss.IndexOf("[Code]", StringComparison.Ordinal)..];
        Assert.Contains("/remove:g *S-1-5-32-545 /C /Q", code);
        Assert.Contains("if CurStep = ssInstall then RevokeLegacyUsersAce;", code);
        Assert.Contains("ExpandConstant('{sys}\\icacls.exe')", code);
        foreach (var banned in new[] { "/grant", "/reset", "/T ", "/inheritance", "/setowner" })
            Assert.DoesNotContain(banned, code);

        if (OperatingSystem.IsWindows())
        {
            // 실제 icacls 로 회수 시뮬레이션: 구버전 users-modify(OI)(CI) 부여 → ISS 동일 인자로 회수 → 루트/하위 모두 Users ACE 소멸, 상속 ACE 유지
            var dir = Path.Combine(Path.GetTempPath(), "pfs-acl-" + Guid.NewGuid().ToString("N"));
            var vault = Path.Combine(dir, "Config", "vault.enc");
            Directory.CreateDirectory(Path.GetDirectoryName(vault)!);
            var secret = System.Security.Cryptography.RandomNumberGenerator.GetBytes(256);
            File.WriteAllBytes(vault, secret);
            try
            {
                var users = new System.Security.Principal.SecurityIdentifier(System.Security.Principal.WellKnownSidType.BuiltinUsersSid, null);
                Assert.Equal(0, RunProcess(Path.Combine(Environment.SystemDirectory, "icacls.exe"), dir, "/grant", "*S-1-5-32-545:(OI)(CI)M", "/C", "/Q"));
                Assert.True(HasExplicitAllow(dir, users) && HasAllow(vault, users));
                int inheritedBefore = CountInherited(dir);

                Assert.Equal(0, RunProcess(Path.Combine(Environment.SystemDirectory, "icacls.exe"), dir, "/remove:g", "*S-1-5-32-545", "/C", "/Q"));
                Assert.False(HasAllow(dir, users), "루트 Users ACE 잔존");
                Assert.False(HasAllow(vault, users), "vault.enc 에 Users ACE 잔존");
                Assert.Equal(inheritedBefore, CountInherited(dir));                  // 프로필 상속 ACE 보존
                Assert.Equal(secret, File.ReadAllBytes(vault));                       // 데이터 무손상
                Assert.Equal(0, RunProcess(Path.Combine(Environment.SystemDirectory, "icacls.exe"), dir, "/remove:g", "*S-1-5-32-545", "/C", "/Q"));   // 멱등(신규 설치)
            }
            finally { try { Directory.Delete(dir, true); } catch (IOException) { } }
        }

        // ══ ③ sign_authenticode.ps1: 선택 단계 계약(종료 코드) · 암호 명령줄 비노출 · 부적격 인증서는 저장소 무접촉 거부 ══
        var signScript = Path.Combine(root, "scripts", "sign_authenticode.ps1");
        var ss = File.ReadAllText(signScript);
        Assert.DoesNotContain(" /p ", ss);                    // SignTool 암호 인자 금지
        Assert.Contains("/fd SHA256 /tr $TimestampUrl /td SHA256", ss);
        Assert.Contains("verify /pa", ss);
        Assert.Contains("1.3.6.1.5.5.7.3.3", ss);
        Assert.True(ss.IndexOf("1.3.6.1.5.5.7.3.3", StringComparison.Ordinal) < ss.IndexOf("$store.Add($cert)", StringComparison.Ordinal), "EKU 검사는 저장소 등록 전");
        Assert.Contains("$store.Remove($imported)", ss);

        if (OperatingSystem.IsWindows())
        {
            var work = Path.Combine(Path.GetTempPath(), "pfs-sign-" + Guid.NewGuid().ToString("N"));
            Directory.CreateDirectory(work);
            try
            {
                var target = Path.Combine(work, "PromptFlowStudio.exe");
                File.WriteAllBytes(target, SyntheticPe(dll: false));
                var before = File.ReadAllBytes(target);

                Assert.Equal(0, RunSign(signScript, null, "-Files", target));                         // 인증서 없음 → 건너뜀
                Assert.Equal(20, RunSign(signScript, null, "-Files", target, "-Require"));            // 필수인데 없음
                Assert.Equal(25, RunSign(signScript, null, "-Files", Path.Combine(work, "missing.exe"), "-PfxPath", Path.Combine(work, "x.pfx")));
                Assert.Equal(21, RunSign(signScript, null, "-Files", target, "-PfxPath", Path.Combine(work, "x.pfx")));
                Assert.Equal(21, RunSign(signScript, null, "-Files", target, "-CertThumbprint", new string('0', 40)));

                const string pass = "titan-test-pass";
                var serverPfx = Path.Combine(work, "server.pfx");
                File.WriteAllBytes(serverPfx, MakePfx(pass, "1.3.6.1.5.5.7.3.1", DateTimeOffset.UtcNow.AddDays(-1), DateTimeOffset.UtcNow.AddDays(30)));
                Assert.Equal(21, RunSign(signScript, pass, "-Files", target, "-PfxPath", serverPfx));    // 서버 인증 EKU → 거부
                Assert.Equal(21, RunSign(signScript, "wrong", "-Files", target, "-PfxPath", serverPfx)); // 암호 불일치
                var expiredPfx = Path.Combine(work, "expired.pfx");
                File.WriteAllBytes(expiredPfx, MakePfx(pass, "1.3.6.1.5.5.7.3.3", DateTimeOffset.UtcNow.AddDays(-30), DateTimeOffset.UtcNow.AddDays(-1)));
                Assert.Equal(21, RunSign(signScript, pass, "-Files", target, "-PfxPath", expiredPfx));   // 만료 코드 서명 인증서 → 거부
                Assert.Equal(before, File.ReadAllBytes(target));                                          // 실패 경로는 대상 무변경
            }
            finally { try { Directory.Delete(work, true); } catch (IOException) { } }
        }

        // ══ ④ 파이프라인 · 검인 · CI 결선: exe 는 RSA 매니페스트 전, setup 은 BOM 해시 전 서명 ══
        var pipeline = File.ReadAllText(Path.Combine(root, "build_titan_release.ps1"));
        int signExe = pipeline.IndexOf("Invoke-Authenticode @($exe)", StringComparison.Ordinal);
        int pfi1 = pipeline.IndexOf("'--pfi1-sign'", StringComparison.Ordinal);
        int signSetup = pipeline.IndexOf("Invoke-Authenticode @($setup)", StringComparison.Ordinal);
        int bom = pipeline.IndexOf("schema         = 'pfs-release-bom/1'", StringComparison.Ordinal);
        Assert.True(signExe > 0 && signExe < pfi1 && pfi1 < signSetup && signSetup < bom, "Authenticode 서명 순서 위반");
        Assert.Contains("authenticode   = $authenticodeSigned", pipeline);
        Assert.Contains("[switch]$RequireAuthenticode", File.ReadAllText(Path.Combine(root, "scripts", "verify_release.ps1")));
        var yml = File.ReadAllText(Path.Combine(root, ".github", "workflows", "release.yml"));
        Assert.Contains("PROMPTFLOW_PFX_PASSWORD: ${{ secrets.PROMPTFLOW_PFX_PASSWORD }}", yml);
        Assert.Contains("Remove-Item $env:PFX_PATH -Force", yml);
        Assert.DoesNotContain("PROMPTFLOW_PFX_PASSWORD }} ", yml.Replace("\r", ""));
    }

    [System.Runtime.Versioning.SupportedOSPlatform("windows")]
    private static bool HasAllow(string path, System.Security.Principal.SecurityIdentifier sid)
    {
        var acl = Directory.Exists(path) ? (System.Security.AccessControl.FileSystemSecurity)new DirectoryInfo(path).GetAccessControl() : new FileInfo(path).GetAccessControl();
        foreach (System.Security.AccessControl.FileSystemAccessRule r in acl.GetAccessRules(true, true, typeof(System.Security.Principal.SecurityIdentifier)))
            if (r.AccessControlType == System.Security.AccessControl.AccessControlType.Allow && sid.Equals(r.IdentityReference)) return true;
        return false;
    }

    [System.Runtime.Versioning.SupportedOSPlatform("windows")]
    private static bool HasExplicitAllow(string path, System.Security.Principal.SecurityIdentifier sid)
    {
        foreach (System.Security.AccessControl.FileSystemAccessRule r in new DirectoryInfo(path).GetAccessControl().GetAccessRules(true, false, typeof(System.Security.Principal.SecurityIdentifier)))
            if (r.AccessControlType == System.Security.AccessControl.AccessControlType.Allow && sid.Equals(r.IdentityReference)) return true;
        return false;
    }

    [System.Runtime.Versioning.SupportedOSPlatform("windows")]
    private static int CountInherited(string path)
    {
        int n = 0;
        foreach (System.Security.AccessControl.FileSystemAccessRule r in new DirectoryInfo(path).GetAccessControl().GetAccessRules(false, true, typeof(System.Security.Principal.SecurityIdentifier)))
            if (r.IsInherited) n++;
        return n;
    }

    private static byte[] MakePfx(string password, string ekuOid, DateTimeOffset notBefore, DateTimeOffset notAfter)
    {
        using var key = System.Security.Cryptography.RSA.Create(2048);
        var req = new System.Security.Cryptography.X509Certificates.CertificateRequest("CN=PromptFlow Titan Test", key, System.Security.Cryptography.HashAlgorithmName.SHA256, System.Security.Cryptography.RSASignaturePadding.Pkcs1);
        req.CertificateExtensions.Add(new System.Security.Cryptography.X509Certificates.X509EnhancedKeyUsageExtension(
            new System.Security.Cryptography.OidCollection { new System.Security.Cryptography.Oid(ekuOid) }, false));
        using var cert = req.CreateSelfSigned(notBefore, notAfter);
        return cert.Export(System.Security.Cryptography.X509Certificates.X509ContentType.Pfx, password);
    }

    private static int RunSign(string script, string? pfxPassword, params string[] args)
    {
        var psi = new ProcessStartInfo("powershell.exe") { UseShellExecute = false, CreateNoWindow = true, RedirectStandardOutput = true, RedirectStandardError = true };
        foreach (var a in new[] { "-NoProfile", "-NonInteractive", "-ExecutionPolicy", "Bypass", "-File", script }) psi.ArgumentList.Add(a);
        foreach (var a in args) psi.ArgumentList.Add(a);
        psi.Environment["PROMPTFLOW_PFX_PASSWORD"] = pfxPassword;   // 암호는 자식 프로세스 환경변수로만
        return Run(psi);
    }

    private static int RunProcess(string exe, params string[] args)
    {
        var psi = new ProcessStartInfo(exe) { UseShellExecute = false, CreateNoWindow = true, RedirectStandardOutput = true, RedirectStandardError = true };
        foreach (var a in args) psi.ArgumentList.Add(a);
        return Run(psi);
    }

    private static int Run(ProcessStartInfo psi)
    {
        using var p = Process.Start(psi)!;
        var so = p.StandardOutput.ReadToEndAsync();
        var se = p.StandardError.ReadToEndAsync();
        if (!p.WaitForExit(60_000)) { p.Kill(true); throw new TimeoutException(psi.FileName + " 60s 초과"); }
        Task.WaitAll(so, se);
        return p.ExitCode;
    }

    /// <summary>Inno Setup 설치/제거 의미론의 최소 시뮬레이터 — [Dirs]·[Files]·[UninstallDelete] 만 해석(실제 레지스트리/ACL 무접촉).</summary>
    private sealed class InnoSandbox
    {
        private readonly string _localAppData;
        public string App { get; }
        private readonly System.Collections.Generic.List<string> _installedFiles = new();
        private readonly System.Collections.Generic.List<string> _createdDirs = new();

        public InnoSandbox(string root)
        {
            _localAppData = Path.Combine(root, "LocalAppData");
            App = Path.Combine(root, "Programs", "PromptFlow Studio");
        }

        public System.Collections.Generic.List<(string Path, byte[] Bytes)> SeedUserData()
        {
            var data = new System.Collections.Generic.List<(string, byte[])>();
            foreach (var rel in new[] { "Config\\vault.enc", "engines.json", "appsettings.override.json", "Keys\\license.key", "logs\\shell.log" })
            {
                var path = Path.Combine(_localAppData, "PromptFlowStudio", rel);
                Directory.CreateDirectory(Path.GetDirectoryName(path)!);
                var bytes = System.Security.Cryptography.RandomNumberGenerator.GetBytes(rel.EndsWith(".enc", StringComparison.Ordinal) ? 2048 : 256);
                File.WriteAllBytes(path, bytes);
                data.Add((path, bytes));
            }
            return data;
        }

        private string Expand(string s) => s.Replace("{localappdata}", _localAppData, StringComparison.Ordinal).Replace("{app}", App, StringComparison.Ordinal);

        public void Install(string iss, string publish)
        {
            _installedFiles.Clear();
            _createdDirs.Clear();
            foreach (var e in Entries(iss, "Dirs"))
            {
                var dir = Expand(e["Name"]);
                if (!Directory.Exists(dir)) { Directory.CreateDirectory(dir); if (!e.GetValueOrDefault("Flags", "").Contains("uninsneveruninstall", StringComparison.Ordinal)) _createdDirs.Add(dir); }
            }
            Directory.CreateDirectory(App);
            foreach (var e in Entries(iss, "Files"))
            {
                if (e.GetValueOrDefault("Flags", "").Contains("dontcopy", StringComparison.Ordinal) || e.GetValueOrDefault("DestDir", "") != "{app}") continue;
                var src = e["Source"];
                var name = src[(src.LastIndexOf('\\') + 1)..];
                if (name == "*")
                {
                    var excludes = e.GetValueOrDefault("Excludes", "").Replace("{#Manifest}", AppIntegrityGuard.ManifestFileName, StringComparison.Ordinal)
                        .Replace("{#AppExe}", "PromptFlowStudio.exe", StringComparison.Ordinal).Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
                    foreach (var file in Directory.EnumerateFiles(publish, "*", SearchOption.AllDirectories))
                    {
                        var rel = Path.GetRelativePath(publish, file);
                        if (!IsExcluded(rel, excludes)) Copy(file, rel);
                    }
                    continue;
                }
                name = name.Replace("{#Manifest}", AppIntegrityGuard.ManifestFileName, StringComparison.Ordinal).Replace("{#AppExe}", "PromptFlowStudio.exe", StringComparison.Ordinal);
                var path = Path.Combine(publish, name);
                if (File.Exists(path)) Copy(path, name);
                else Assert.Contains("skipifsourcedoesntexist", e.GetValueOrDefault("Flags", ""));
            }
            File.WriteAllBytes(Path.Combine(App, "unins000.exe"), new byte[] { (byte)'M', (byte)'Z' });
            _installedFiles.Add(Path.Combine(App, "unins000.exe"));
        }

        public void Uninstall(string iss)
        {
            foreach (var f in _installedFiles) if (File.Exists(f)) File.Delete(f);
            foreach (var e in Entries(iss, "UninstallDelete"))
            {
                var target = Expand(e["Name"]);
                switch (e["Type"])
                {
                    case "files":
                        var dir = Path.GetDirectoryName(target)!;
                        if (Directory.Exists(dir)) foreach (var f in Directory.GetFiles(dir, Path.GetFileName(target))) File.Delete(f);
                        break;
                    case "filesandordirs":
                        if (Directory.Exists(target)) Directory.Delete(target, true);
                        else if (File.Exists(target)) File.Delete(target);
                        break;
                    case "dirifempty":
                        if (Directory.Exists(target) && Directory.GetFileSystemEntries(target).Length == 0) Directory.Delete(target);
                        break;
                }
            }
            foreach (var d in _createdDirs) if (Directory.Exists(d) && Directory.GetFileSystemEntries(d).Length == 0) Directory.Delete(d);
            DeleteEmptyTree(App);   // Inno: 설치가 만든 {app} 하위 빈 폴더 정리
        }

        private void Copy(string src, string rel)
        {
            var dst = Path.Combine(App, rel);
            Directory.CreateDirectory(Path.GetDirectoryName(dst)!);
            File.Copy(src, dst, true);
            _installedFiles.Add(dst);
        }

        private static bool IsExcluded(string rel, string[] patterns)
        {
            var name = Path.GetFileName(rel);
            foreach (var p in patterns)
                if (p.StartsWith("*.", StringComparison.Ordinal) ? name.EndsWith(p[1..], StringComparison.OrdinalIgnoreCase) : string.Equals(rel, p, StringComparison.OrdinalIgnoreCase)) return true;
            return false;
        }

        private static void DeleteEmptyTree(string dir)
        {
            if (!Directory.Exists(dir)) return;
            foreach (var d in Directory.GetDirectories(dir)) DeleteEmptyTree(d);
            if (Directory.GetFileSystemEntries(dir).Length == 0) Directory.Delete(dir);
        }

        /// <summary>섹션 항목 파싱(<c>Key: "value"; Key: value</c>) — 전처리 지시자(#)·주석(;) 줄 제외.</summary>
        public static System.Collections.Generic.List<System.Collections.Generic.Dictionary<string, string>> Entries(string iss, string section)
        {
            var list = new System.Collections.Generic.List<System.Collections.Generic.Dictionary<string, string>>();
            bool inSection = false;
            foreach (var raw in iss.Split('\n'))
            {
                var line = raw.Trim();
                if (line.StartsWith('[') && line.EndsWith(']')) { inSection = line == "[" + section + "]"; continue; }
                if (!inSection || line.Length == 0 || line[0] == ';' || line[0] == '#') continue;
                var entry = new System.Collections.Generic.Dictionary<string, string>(StringComparer.Ordinal);
                int i = 0;
                while (i < line.Length)
                {
                    int colon = line.IndexOf(':', i);
                    if (colon < 0) break;
                    var key = line[i..colon].Trim();
                    int j = colon + 1;
                    while (j < line.Length && line[j] == ' ') j++;
                    string value;
                    if (j < line.Length && line[j] == '"')
                    {
                        int end = line.IndexOf('"', j + 1);
                        value = line[(j + 1)..end];
                        j = end + 1;
                    }
                    else
                    {
                        int end = line.IndexOf(';', j);
                        if (end < 0) end = line.Length;
                        value = line[j..end].Trim();
                        j = end;
                    }
                    entry[key] = value;
                    int semi = line.IndexOf(';', j);
                    i = semi < 0 ? line.Length : semi + 1;
                }
                if (entry.Count > 0) list.Add(entry);
            }
            return list;
        }
    }

    private static string RepoRoot()
    {
        var dir = new DirectoryInfo(AppContext.BaseDirectory);
        while (dir is not null && !File.Exists(Path.Combine(dir.FullName, "build_titan_release.ps1"))) dir = dir.Parent;
        return dir?.FullName ?? throw new DirectoryNotFoundException("저장소 루트(build_titan_release.ps1)를 찾지 못함");
    }

    /// <summary>
    /// v17.63.0 헤드리스 UI 가상 렌더링 · 생명주기 감사 — 6대 카테고리 대표 모달을 내장 HtmlRenderer 로 크래시 없이 렌더하고,
    /// 렌더러 Dispose 후 러너 이벤트 구독자 0(누수 없음) · 전 .razor 구독/해제 쌍 · 사이드바 검색/카탈로그 디스패치 동기화 · 반응형 CSS 가드를 검증.
    /// </summary>
    [Fact]
    public async Task Headless_UI_Rendering_Check()
    {
        // ══ UI-1 7대 카테고리 대표 모달 헤드리스 렌더(Null 참조 · 수명주기 예외 없음) + Dispose 후 이벤트 누수 0 ══
        var cases = new (int Cat, Type Modal, Type Runner, string Css)[]
        {
            (0, typeof(PromptFlowStudio.Blazor.Components.Common.CameraTrackingStudioModal), typeof(Oit.CameraTrackingStudioRunner), "ctm-modal"),
            (1, typeof(PromptFlowStudio.Blazor.Components.Common.GaussianFacialHandStudioModal), typeof(Gfh.GaussianFacialHandStudioRunner), "gfh-modal"),
            (2, typeof(PromptFlowStudio.Blazor.Components.Common.IntelligentStageLightingStudioModal), typeof(SL.IntelligentStageLightingStudioRunner), "-modal"),
            (3, typeof(PromptFlowStudio.Blazor.Components.Common.StreamGatewayClipperStudioModal), typeof(SG.StreamGatewayClipperStudioRunner), "sgc-modal"),
            (4, typeof(PromptFlowStudio.Blazor.Components.Common.ViralReelsStudioModal), typeof(Vr.ViralReelsStudioRunner), "vrl-modal"),
            (5, typeof(PromptFlowStudio.Blazor.Components.Common.LiveTelemetryStudioModal), typeof(Ltm.LiveTelemetryStudioRunner), "-modal"),
            (6, typeof(PromptFlowStudio.Blazor.Components.Common.MultilingualDubbingStudioModal), typeof(PromptFlowStudio.Services.GlobalDubbing.GlobalDubbingStudioRunner), "mds-modal"),
        };
        var seen = new bool[PromptFlowStudio.Services.Ui.StudioCatalog.Categories.Length];
        foreach (var c in cases)
        {
            using var sp = new HeadlessUiRendererCheck.AutoWireProvider();
            var runner = sp.GetService(c.Runner)!;
            Assert.NotNull(runner);
            var html = await HeadlessUiRendererCheck.RenderAsync(c.Modal, sp);
            Assert.True(html.Length > 500 && html.Contains("-scrim", StringComparison.Ordinal) && html.Contains(c.Css, StringComparison.Ordinal), c.Modal.Name + " 렌더 " + html.Length);
            Assert.Equal(0, HeadlessUiRendererCheck.LiveSubscriberCount(runner));
            seen[c.Cat] = true;
        }
        Assert.All(seen, Assert.True);

        // ══ UI-2 전 .razor 정적 생명주기 감사 — 외부 이벤트 += 는 -= 해제 + IDisposable 필수 ══
        var blazor = Path.Combine(RepoRoot(), "PromptFlowStudio", "Blazor");
        var leaks = HeadlessUiRendererCheck.AuditRazorLifecycle(blazor, out var scanned);
        Assert.True(scanned > 200, "스캔 " + scanned);
        Assert.True(leaks.Count == 0, string.Join(" | ", leaks));

        // ══ UI-3 사이드바 검색 — 공백 무시 · 대소문자 무관 · 0건 카테고리 숨김 근거(CountMatches) ══
        var cat = PromptFlowStudio.Services.Ui.StudioCatalog.Entries;
        var all = 0; var blank = 0;
        for (var i = 0; i < PromptFlowStudio.Services.Ui.StudioCatalog.Categories.Length; i++)
        {
            all += PromptFlowStudio.Services.Ui.StudioCatalog.CountMatches(i, "");
            blank += PromptFlowStudio.Services.Ui.StudioCatalog.CountMatches(i, "   ");
            Assert.Equal(PromptFlowStudio.Services.Ui.StudioCatalog.CountIn(i), PromptFlowStudio.Services.Ui.StudioCatalog.CountMatches(i, null));
        }
        Assert.True(all == cat.Length && blank == cat.Length && cat.Length >= 139, "카탈로그 " + all + "/" + blank + "/" + cat.Length);
        var gw = Array.Find(cat, e => e.Key == "_streamGateway")!;
        Assert.True(PromptFlowStudio.Services.Ui.StudioCatalog.Matches(gw, "  스트림 게이트웨이 ") && PromptFlowStudio.Services.Ui.StudioCatalog.Matches(gw, "스트림"));
        Assert.Equal(PromptFlowStudio.Services.Ui.StudioCatalog.CountMatches(3, "ai"), PromptFlowStudio.Services.Ui.StudioCatalog.CountMatches(3, "AI"));
        for (var i = 0; i < PromptFlowStudio.Services.Ui.StudioCatalog.Categories.Length; i++) Assert.Equal(0, PromptFlowStudio.Services.Ui.StudioCatalog.CountMatches(i, "존재하지않는스튜디오zz"));

        // ══ UI-4 카탈로그 ↔ MainLayout 디스패치 동기화 · 단일 활성 스튜디오(z-index 겹침 방지) · 키 중복 없음 ══
        var layout = File.ReadAllText(Path.Combine(blazor, "MainLayout.razor"));
        var keys = new HashSet<string>(StringComparer.Ordinal);
        foreach (var e in cat)
        {
            Assert.True(keys.Add(e.Key), "중복 키 " + e.Key);
            if (e.Key.StartsWith("sb:", StringComparison.Ordinal) || e.Key.StartsWith('@')) continue;
            Assert.True(layout.Contains("case \"" + e.Key + "\":", StringComparison.Ordinal), "SetStudio 누락 " + e.Key);
            Assert.True(layout.Contains("\"" + e.Key + "\" =>", StringComparison.Ordinal), "IsStudioOpen 누락 " + e.Key);
        }
        Assert.Contains("if (e.Key != key && IsStudioOpen(e.Key)) SetStudio(e.Key, false);", layout, StringComparison.Ordinal);
        Assert.Contains("NavFiltering && hits == 0", layout, StringComparison.Ordinal);

        // ══ UI-5 반응형 CSS 가드 — 뷰포트 상한 · 좁은 화면 1열 · 9:16 뷰 높이 상한 ══
        var css = File.ReadAllText(Path.Combine(RepoRoot(), "PromptFlowStudio", "wwwroot", "app.css"));
        Assert.Contains("[class$=\"-scrim\"] > [class$=\"-modal\"] { max-width: calc(100vw - 12px); max-height: calc(100dvh - 12px);", css, StringComparison.Ordinal);
        Assert.Contains("[class$=\"-scrim\"] > [class$=\"-modal\"] > [class$=\"-main\"] { grid-template-columns: minmax(0, 1fr); }", css, StringComparison.Ordinal);
        foreach (var f in new[] { "ViralReelsStudioModal", "VerticalTranscoderStudioModal", "MotionOverlayStudioModal" })
            Assert.Contains("calc(62vh * 9 / 16)", File.ReadAllText(Path.Combine(blazor, "Components", "Common", f + ".razor")), StringComparison.Ordinal);
    }

    // 최소 PE32+ 헤더: MZ · e_lfanew=0x80 · 'PE\0\0' · AMD64 · EXECUTABLE_IMAGE(|DLL) · Magic 0x20B
    private static byte[] SyntheticPe(bool dll)
    {
        var b = new byte[1024];
        b[0] = (byte)'M'; b[1] = (byte)'Z';
        BitConverter.TryWriteBytes(b.AsSpan(0x3C), 0x80);
        b[0x80] = (byte)'P'; b[0x81] = (byte)'E';
        BitConverter.TryWriteBytes(b.AsSpan(0x84), (ushort)0x8664);
        BitConverter.TryWriteBytes(b.AsSpan(0x96), (ushort)(dll ? 0x2022 : 0x0022));
        BitConverter.TryWriteBytes(b.AsSpan(0x98), (ushort)0x20B);
        return b;
    }

    private static int RunBundle(string script, string publishDir, string ffmpegPath, string? sha = null)
    {
        var psi = new ProcessStartInfo("powershell.exe")
        {
            UseShellExecute = false,
            CreateNoWindow = true,
            RedirectStandardOutput = true,
            RedirectStandardError = true,
        };
        foreach (var a in new[] { "-NoProfile", "-NonInteractive", "-ExecutionPolicy", "Bypass", "-File", script, "-PublishDir", publishDir, "-FfmpegPath", ffmpegPath, "-SkipVersionProbe" })
            psi.ArgumentList.Add(a);
        if (sha is not null) { psi.ArgumentList.Add("-ExpectedSha256"); psi.ArgumentList.Add(sha); }
        using var p = Process.Start(psi)!;
        var so = p.StandardOutput.ReadToEndAsync();
        var se = p.StandardError.ReadToEndAsync();
        if (!p.WaitForExit(60_000)) { p.Kill(true); throw new TimeoutException("bundle_ffmpeg.ps1 60s 초과"); }
        Task.WaitAll(so, se);
        return p.ExitCode;
    }

    [Fact]
    public async Task MotionVector_DualKeyframe_And_VideoReverse_Check()
    {
        // ══ ① Motion-Vector: I2V 역방향 방지 네거티브(멱등 · 사용자 네거티브 원형 앞 유지) ══
        Assert.Equal(MotionVectorPromptEngine.ReverseGuardNegative, MotionVectorPromptEngine.AppendReverseGuard(null));
        var neg = MotionVectorPromptEngine.AppendReverseGuard("blurry,");
        Assert.StartsWith("blurry, ", neg);
        Assert.EndsWith(MotionVectorPromptEngine.ReverseGuardNegative, neg);
        Assert.Same(neg, MotionVectorPromptEngine.AppendReverseGuard(neg));

        // ══ ② 폐쇄 공간 → Dolly Out 자동 매핑 · 카메라 지정/개방 공간은 원본 참조 그대로(0B) ══
        Assert.True(MotionVectorPromptEngine.IsEnclosedSpace("a toddler walking down a narrow HALLWAY"));
        Assert.True(MotionVectorPromptEngine.IsEnclosedSpace("아기가 복도를 걷는다"));
        Assert.EndsWith(MotionVectorPromptEngine.DollyOutCamera, MotionVectorPromptEngine.ApplyCameraCorrection("baby in a bedroom, "));
        var cam = "baby in a bedroom, slow zoom in";
        Assert.Same(cam, MotionVectorPromptEngine.ApplyCameraCorrection(cam));
        var open = "golden retriever on a beach";
        Assert.Same(open, MotionVectorPromptEngine.ApplyCameraCorrection(open));

        // ══ ③ 요청 가공: t2v 무변경(동일 참조) · i2v 만 주입 ══
        var t2v = new WanVideoRequest { Prompt = "kitchen scene" };
        Assert.Same(t2v, MotionVectorPromptEngine.Process(t2v));
        var i2v = MotionVectorPromptEngine.Process(new WanVideoRequest { Prompt = "kitchen scene", ImagePath = "a.png", NegativePrompt = "watermark" });
        Assert.Contains("dolly out", i2v.Prompt, StringComparison.Ordinal);
        Assert.Equal("watermark, " + MotionVectorPromptEngine.ReverseGuardNegative, i2v.NegativePrompt);
        var local = WanRenderClient.BuildRequest(new WanPromptBuild("tunnel walk", 30, Array.Empty<string>(), null), null, "data:image/png;base64,AA");
        Assert.Contains("reverse motion", local.NegativePrompt, StringComparison.Ordinal);
        Assert.Contains("dolly out", local.Prompt, StringComparison.Ordinal);
        Assert.DoesNotContain("reverse motion", WanRenderClient.BuildRequest(new WanPromptBuild("tunnel walk", 30, Array.Empty<string>(), null), null).NegativePrompt, StringComparison.Ordinal);

        // ══ ④ Dual Keyframe: 첫+끝 둘 다 있어야 성립 · kf2v DTO 필드(null 생략) ══
        Assert.False(MotionVectorPromptEngine.IsDualKeyframe(new WanVideoRequest { Prompt = "p", LastFramePath = "z.png" }));
        Assert.False(MotionVectorPromptEngine.IsDualKeyframe(new WanVideoRequest { Prompt = "p", ImagePath = "a.png" }));
        Assert.True(MotionVectorPromptEngine.IsDualKeyframe(new WanVideoRequest { Prompt = "p", ImageUrl = "oss://a", LastFrameUrl = "oss://z" }));
        var kf = new DashScopeSubmitBody
        {
            Model = MotionVectorPromptEngine.KeyframeModel,
            Input = new DashScopeInput { Prompt = "p", FirstFrameUrl = "oss://a", LastFrameUrl = "oss://z" },
            Parameters = new DashScopeParameters { Resolution = "720P", PromptExtend = true },
        };
        Assert.Equal("{\"model\":\"wan2.1-kf2v-plus\",\"input\":{\"prompt\":\"p\",\"first_frame_url\":\"oss://a\",\"last_frame_url\":\"oss://z\"},\"parameters\":{\"resolution\":\"720P\",\"prompt_extend\":true}}",
            System.Text.Json.JsonSerializer.Serialize(kf, WanJsonContext.Default.DashScopeSubmitBody));

        // ══ ⑤ 영상 반전: -vf reverse 인자 · _reversed 토글 경로 · 입력 부재 Graceful ══
        var args = VideoReverseService.BuildArguments("in put.mp4", "out.mp4");
        var vf = args.IndexOf("-vf");
        Assert.True(vf >= 0);
        Assert.Equal("reverse", args[vf + 1]);
        Assert.Equal("in put.mp4", args[args.IndexOf("-i") + 1]);
        Assert.Equal("out.mp4", args[^1]);
        var rev = VideoReverseService.BuildOutputPath(Path.Combine("d", "clip.mp4"));
        Assert.Equal(Path.Combine("d", "clip_reversed.mp4"), rev);
        Assert.Equal(Path.Combine("d", "clip_restored.mp4"), VideoReverseService.BuildOutputPath(rev));
        var miss = await VideoReverseService.ReverseAsync(Path.Combine(Path.GetTempPath(), "pfs-none-" + Guid.NewGuid().ToString("N") + ".mp4"));
        Assert.False(miss.Ok);
        Assert.Null(miss.OutputPath);
        var bogus = await VideoReverseService.ReverseAsync(null, customFfmpegPath: "Z:/no/ffmpeg.exe");
        Assert.False(bogus.Ok);
    }

    [Fact]
    public async Task DualKeyframe_Kf2vSubmit_EndToEnd_Check()
    {
        var dir = Path.Combine(Path.GetTempPath(), "pfs-kf2v-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(dir);
        var first = Path.Combine(dir, "first.png");
        var last = Path.Combine(dir, "last.png");
        File.WriteAllBytes(first, new byte[] { 0x89, 0x50, 0x4E, 0x47, 1, 2, 3, 4 });
        File.WriteAllBytes(last, new byte[] { 0x89, 0x50, 0x4E, 0x47, 5, 6, 7, 8 });
        try
        {
            var vault = new WanTokenVault(null);
            vault.UpdateProviderKeys(WanTokenVault.DashScope, new[] { "ds-a" });
            var mock = new WanEngineTests.RouteHandler();
            var svc = new WanApiService(new WanEngineTests.FakeWanConfig(), new QuotaRateGuardService(), vault, mock);

            var r = await svc.SubmitAsync(new WanVideoRequest { Prompt = "toddler walking in a hallway", ImagePath = first, LastFramePath = last });
            Assert.True(r.Ok, r.Message);
            Assert.Equal(2, mock.OssUploads);                                                     // 첫+끝 프레임 각 1회 업로드
            Assert.Contains("\"model\":\"wan2.1-kf2v-plus\"", mock.LastSubmitBody, StringComparison.Ordinal);
            Assert.Contains("\"first_frame_url\":\"oss://", mock.LastSubmitBody, StringComparison.Ordinal);
            Assert.Contains("\"last_frame_url\":\"oss://", mock.LastSubmitBody, StringComparison.Ordinal);
            Assert.DoesNotContain("\"img_url\"", mock.LastSubmitBody, StringComparison.Ordinal);
            Assert.Contains("reverse motion", mock.LastSubmitBody, StringComparison.Ordinal);      // 역방향 방지 네거티브
            Assert.Contains("dolly out", mock.LastSubmitBody, StringComparison.Ordinal);           // 폐쇄 공간 카메라 보정

            // 단일 i2v 는 기존 img_url 경로 유지(회귀 0)
            var r2 = await svc.SubmitAsync(new WanVideoRequest { Prompt = "p", ImagePath = first });
            Assert.True(r2.Ok, r2.Message);
            Assert.Contains("\"img_url\":\"oss://", mock.LastSubmitBody, StringComparison.Ordinal);
            Assert.DoesNotContain("last_frame_url", mock.LastSubmitBody, StringComparison.Ordinal);
        }
        finally { try { Directory.Delete(dir, true); } catch { /* best-effort */ } }
    }

    [Fact]
    public void EverydayBabyThemes_PresetAndSearch_Check()
    {
        var db = new PromptFlowStudio.Services.Storyboard.BabyThemeDatabase();

        // ① 4대 실생활 카테고리 병합 · 테마 수(15/15/14/14 · v16.10.0 +10씩) · 키 전역 유일(Index 구성 시 중복이면 예외)
        var expected = new (string Key, int Count)[]
        {
            (PromptFlowStudio.Services.Storyboard.BabyEverydayThemeDatabase.Playground, 15),
            (PromptFlowStudio.Services.Storyboard.BabyEverydayThemeDatabase.KidsCafe, 15),
            (PromptFlowStudio.Services.Storyboard.BabyEverydayThemeDatabase.AmusementPark, 14),
            (PromptFlowStudio.Services.Storyboard.BabyEverydayThemeDatabase.Everyday, 14),
        };
        foreach (var (key, count) in expected)
        {
            var cat = Assert.Single(db.Categories, c => c.Key == key);
            Assert.Equal(count, cat.Themes.Count);
            foreach (var t in cat.Themes)
            {
                Assert.Equal(key, t.CategoryKey);
                Assert.Same(t, db.Get(t.Key));
                Assert.True(t.Beats.Count >= 4);
                Assert.All(t.Beats, b => Assert.False(string.IsNullOrWhiteSpace(b.Shot)));
            }
            // 카테고리 네거티브 = 역방향 방지 포함
            Assert.Contains("reverse motion", PromptFlowStudio.Services.Storyboard.BabyEverydayThemeDatabase.NegativeFor(key), StringComparison.Ordinal);
        }
        Assert.Null(PromptFlowStudio.Services.Storyboard.BabyEverydayThemeDatabase.NegativeFor("food"));
        Assert.Equal(db.AllThemes.Count, db.AllThemes.Select(t => t.Key).Distinct(StringComparer.OrdinalIgnoreCase).Count());

        // ② 키워드 검색 즉시 필터링(제목·동의어 태그)
        var search = new PromptFlowStudio.Services.Storyboard.ThemeSearchFilterService();
        Assert.Contains(search.Filter(db.AllThemes, "볼풀"), t => t.Key == "kc_ballpit");
        Assert.Contains(search.Filter(db.AllThemes, "그네"), t => t.Key == "pg_swing");
        Assert.Contains(search.Filter(db.AllThemes, "회전목마"), t => t.Key == "ap_carousel");
        Assert.Contains(search.Filter(db.AllThemes, "유모차"), t => t.Key == "ev_stroller");
        Assert.Equal(15, search.Filter(db.AllThemes, "놀이터").Count(t => t.CategoryKey == "playground"));
        Assert.Contains(search.FilterCategories(db.Categories, "트램폴린"), c => c.Key == "kidscafe");

        // ③ 스토리보드 구성 시 컷 네거티브 결선(실생활 테마만) · 전진 모션 Shot
        var factory = new PromptFlowStudio.Services.Storyboard.VideoFormatFactory(db,
            new PromptFlowStudio.Services.Storyboard.CorporateThemeDatabase(), new PromptFlowStudio.Services.Storyboard.AutomotiveEquipmentDatabase());
        var proj = new PromptFlowStudio.Services.Storyboard.StoryboardProject();
        Assert.True(factory.Apply(proj, "pg_slide", PromptFlowStudio.Services.Storyboard.VideoFormat.Shorts));
        Assert.NotEmpty(proj.Scenes);
        Assert.All(proj.Scenes, sc => Assert.Contains("reverse motion", sc.NegativePrompt, StringComparison.Ordinal));
        Assert.Contains(proj.Scenes, sc => sc.Prompt.Contains("forward", StringComparison.OrdinalIgnoreCase));
        Assert.True(factory.Apply(proj, "lemon", PromptFlowStudio.Services.Storyboard.VideoFormat.Longs));
        Assert.All(proj.Scenes, sc => Assert.Null(sc.NegativePrompt));   // 기존 테마 무회귀
    }

    [Fact]
    public void HighEndThemeSystem_CameraBindingAndSmartMatching_Check()
    {
        var db = new PromptFlowStudio.Services.Storyboard.BabyThemeDatabase();
        var all = db.AllThemes;
        Assert.True(all.Count >= 120, $"테마 수 {all.Count}");

        // ① 전 테마 메타 할당 · 범위 · 다양성(편향 없는 분포) · 캐시(같은 인스턴스)
        var cams = new System.Collections.Generic.HashSet<PromptFlowStudio.Services.Storyboard.CameraMotion>();
        var lights = new System.Collections.Generic.HashSet<PromptFlowStudio.Services.Storyboard.ThemeLighting>();
        foreach (var t in all)
        {
            var c = t.Cinematics;
            Assert.Same(c, t.Cinematics);
            Assert.InRange(t.OptimalMotionIntensity, 2, 4);
            Assert.False(string.IsNullOrWhiteSpace(c.Lens));
            Assert.InRange(t.SuggestedSfx.Count, 1, 3);
            Assert.Equal(c.Camera, t.RecommendedCameraMotion);
            cams.Add(t.RecommendedCameraMotion);
            lights.Add(t.RecommendedLighting);
        }
        Assert.True(cams.Count >= 5, $"카메라 종류 {cams.Count}");
        Assert.True(lights.Count >= 5, $"조명 종류 {lights.Count}");
        Assert.Equal(PromptFlowStudio.Services.Storyboard.CameraMotion.Orbit, db.Get("ap_carousel")!.RecommendedCameraMotion);
        Assert.Equal(PromptFlowStudio.Services.Storyboard.ThemeLighting.MoonlightBlue, db.Get("sleeptalk")!.RecommendedLighting);
        Assert.Equal("85mm 인물 보케", PromptFlowStudio.Services.Storyboard.ThemeCinematicsCatalog.LensOf("85mm, backlit"));
        var preset = new PromptFlowStudio.Services.Storyboard.BabyThemePresetService().Themes[0];
        Assert.InRange(preset.OptimalMotionIntensity, 2, 4);

        // ② 테마 적용 → 카메라 토큰(WanCameraStyleStudio 그룹 배타) + 프로젝트 메타 → WanRenderRequest 단일 패스
        var factory = new PromptFlowStudio.Services.Storyboard.VideoFormatFactory(db,
            new PromptFlowStudio.Services.Storyboard.CorporateThemeDatabase(), new PromptFlowStudio.Services.Storyboard.AutomotiveEquipmentDatabase());
        var proj = new PromptFlowStudio.Services.Storyboard.StoryboardProject();
        Assert.True(factory.Apply(proj, "ap_carousel", PromptFlowStudio.Services.Storyboard.VideoFormat.Shorts));
        var orbit = PromptFlowStudio.Services.Ui.WanCameraStyleStudio.Cameras[0];
        Assert.All(proj.Scenes, sc => Assert.Equal(0, PromptFlowStudio.Services.Ui.WanCameraStyleStudio.ActiveIndex(sc.Prompt, PromptFlowStudio.Services.Ui.WanCameraStyleStudio.Cameras)));
        Assert.Equal(orbit.Label, proj.CinematicCamera);
        Assert.Equal(db.Get("ap_carousel")!.OptimalMotionIntensity, proj.CinematicMotionIntensity);
        var req = WanRenderClient.BuildRequest(new WanPromptBuild(proj.Scenes[0].Prompt, 0, Array.Empty<string>(), null), proj);
        Assert.Equal(orbit.Label, req.CameraMotion);
        Assert.Equal(proj.CinematicLighting, req.Lighting);
        Assert.Equal(proj.CinematicMotionIntensity * 20, req.MotionIntensity);
        Assert.NotNull(req.Sfx);
        var json = System.Text.Json.JsonSerializer.Serialize(req, PromptFlowStudio.Services.PromptFlowWireJsonContext.Default.WanRenderRequest);
        Assert.Contains("\"cameraMotion\":\"Orbit\"", json, StringComparison.Ordinal);
        var plain = System.Text.Json.JsonSerializer.Serialize(
            WanRenderClient.BuildRequest(new WanPromptBuild("sunset", 30, Array.Empty<string>(), null), null),
            PromptFlowStudio.Services.PromptFlowWireJsonContext.Default.WanRenderRequest);
        Assert.DoesNotContain("cameraMotion", plain, StringComparison.Ordinal);   // 미적용 → 기존 페이로드

        // ③ 스마트 매처: 합성 사진(잔디 녹색 / 어두운 청색 / 알록달록) → 상위 3 · 카테고리 중복 0 · 장면 적합
        var matcher = new PromptFlowStudio.Services.Storyboard.SmartThemeMatcherService(db);
        static int[] Fill(Func<int, int, int> px)
        {
            var a = new int[32 * 32];
            for (var y = 0; y < 32; y++) for (var x = 0; x < 32; x++) a[y * 32 + x] = px(x, y);
            return a;
        }
        var grass = PromptFlowStudio.Services.Storyboard.PhotoFeatures.FromRgb(Fill((x, y) => y < 10 ? 0x87CEEB : 0x4CAF50), 32, 32);
        Assert.True(grass.GreenRatio > 0.5 && grass.BlueRatio > 0.2);
        var g = matcher.Recommend(grass);
        Assert.Equal(3, g.Count);
        Assert.Equal(3, g.Select(m => db.CategoryOf(m.Key)!.Key).Distinct().Count());
        Assert.Contains(g, m => m.Reason.Contains("녹지", StringComparison.Ordinal) || m.Reason.Contains("하늘", StringComparison.Ordinal));

        var night = PromptFlowStudio.Services.Storyboard.PhotoFeatures.FromRgb(Fill((x, y) => 0x101830), 32, 32);
        Assert.True(night.Brightness < 0.2 && night.Warmth < 0);
        var n = matcher.Recommend(night);
        Assert.Equal(PromptFlowStudio.Services.Storyboard.ThemeLighting.MoonlightBlue, db.Get(n[0].Key)!.RecommendedLighting);

        var palette = new[] { 0xFF4040, 0xFFD040, 0x40C040, 0x4080FF, 0xC040FF, 0xFF80C0, 0x40E0E0, 0xFF9020 };
        var vivid = PromptFlowStudio.Services.Storyboard.PhotoFeatures.FromRgb(Fill((x, y) => palette[(x / 4 + y / 4) % palette.Length]), 32, 32);
        Assert.True(vivid.Colorfulness > 0.45);
        Assert.Equal(3, matcher.Recommend(vivid).Count);
        Assert.Equal(matcher.Recommend(vivid), matcher.Recommend(vivid));   // 결정적

        Assert.Empty(matcher.RecommendForImage(null));
        Assert.Empty(matcher.RecommendForImage(Path.Combine(Path.GetTempPath(), "pfs-none-" + Guid.NewGuid().ToString("N") + ".png")));
    }

    [Fact]
    public void CustomThemeStudio_ImportExportAndTranspiler_Check()
    {
        var root = Path.Combine(Path.GetTempPath(), "pfs-themes-" + Guid.NewGuid().ToString("N"));
        try
        {
            var db = new PromptFlowStudio.Services.Storyboard.BabyThemeDatabase();
            var builtIn = db.AllThemes.Count;
            var reg = new PromptFlowStudio.Services.Storyboard.CustomThemeRegistryService(db, root);
            Assert.Empty(reg.Themes);
            Assert.DoesNotContain(db.Categories, c => c.Key == "custom");

            // ① 저장 → 영구 파일 + 백과사전 동적 병합 + 사용자 메타 공유(인스펙터·팩토리·검색)
            var def = new PromptFlowStudio.Services.Storyboard.CustomThemeDefinition
            {
                Name = "Grandma Yard Hen", Emoji = "🐔", CategoryKey = "everyday",
                Camera = PromptFlowStudio.Services.Storyboard.CameraMotion.CraneUp,
                Lighting = PromptFlowStudio.Services.Storyboard.ThemeLighting.GoldenHour,
                Sfx = { "giggle", "Cute!", "giggle", "pop", "ding" }, MotionIntensity = 9, Negative = "blurry",
                Cuts =
                {
                    new() { Shot = "35mm, sunny yard, a toddler walking forward toward a hen, curious smile", Tension = 40, Sfx = "cute@C,giggle@R20,evil;rm@X" },
                    new() { Shot = "   " },
                    new() { Shot = "85mm, golden light, the toddler laughing as the hen pecks grain", Tension = 80 },
                },
            };
            var key = reg.Save(def, out var err);
            Assert.NotNull(key);
            Assert.Null(err);
            Assert.StartsWith("ct_", key);
            Assert.True(File.Exists(Path.Combine(root, key + ".pftheme")));
            var t = db.Get(key);
            Assert.NotNull(t);
            Assert.Equal(2, t!.Beats.Count);                                         // 빈 컷 제거
            Assert.Equal("cute@C,giggle@R20,evilrm", t.Beats[0].Sfx);                 // 토큰 정제
            Assert.Equal(builtIn + 1, db.AllThemes.Count);
            Assert.Contains(db.Categories, c => c.Key == "custom");
            Assert.Equal(PromptFlowStudio.Services.Storyboard.CameraMotion.CraneUp, t.RecommendedCameraMotion);
            Assert.Equal(4, t.OptimalMotionIntensity);                                // 2~4 클램프
            Assert.Equal(new[] { "giggle", "cute", "pop" }, t.SuggestedSfx);           // 정제·중복 제거·최대 3
            Assert.Contains("reverse motion", t.Cinematics.Negative, StringComparison.Ordinal);
            var factory = new PromptFlowStudio.Services.Storyboard.VideoFormatFactory(db,
                new PromptFlowStudio.Services.Storyboard.CorporateThemeDatabase(), new PromptFlowStudio.Services.Storyboard.AutomotiveEquipmentDatabase());
            var proj = new PromptFlowStudio.Services.Storyboard.StoryboardProject();
            Assert.True(factory.Apply(proj, key!, PromptFlowStudio.Services.Storyboard.VideoFormat.Shorts));
            Assert.All(proj.Scenes, sc => Assert.StartsWith("blurry, ", sc.NegativePrompt));
            Assert.Equal("Crane Up", proj.CinematicCamera);
            Assert.Contains(new PromptFlowStudio.Services.Storyboard.ThemeSearchFilterService().Filter(db.AllThemes, "hen"), x => x.Key == key);
            var matcher = new PromptFlowStudio.Services.Storyboard.SmartThemeMatcherService(db);
            Assert.Equal(3, matcher.Recommend(PromptFlowStudio.Services.Storyboard.PhotoFeatures.FromRgb(new int[16], 4, 4)).Count);

            // ② 재시작(새 DB·새 레지스트리) → 디스크에서 복원
            var db2 = new PromptFlowStudio.Services.Storyboard.BabyThemeDatabase();
            var reg2 = new PromptFlowStudio.Services.Storyboard.CustomThemeRegistryService(db2, root);
            Assert.Single(reg2.Themes);
            Assert.Equal(PromptFlowStudio.Services.Storyboard.CameraMotion.CraneUp, db2.Get(key)!.RecommendedCameraMotion);

            // ③ 다중 내보내기 → 다른 저장소로 가져오기(왕복 무손실) · 키 충돌 재명명 · 거부 항목 [부분 구제]
            Assert.NotNull(reg.Save(new PromptFlowStudio.Services.Storyboard.CustomThemeDefinition { Name = "Second", Cuts = { new() { Shot = "a baby smiling" } } }, out _));
            var json = reg.Export();
            Assert.Contains("\"format\": \"pftheme\"", json, StringComparison.Ordinal);
            Assert.Contains("\"camera\": \"CraneUp\"", json, StringComparison.Ordinal);
            var exported = reg.ExportToFile(null, null, out var exErr);
            Assert.True(exported is not null && File.Exists(exported), exErr);
            var db3 = new PromptFlowStudio.Services.Storyboard.BabyThemeDatabase();
            var reg3 = new PromptFlowStudio.Services.Storyboard.CustomThemeRegistryService(db3, root + "-b");
            var r1 = reg3.Import(File.ReadAllText(exported!));
            Assert.True(r1.Ok);
            Assert.Equal(2, r1.Imported.Count);
            Assert.Equal(reg.Export(new[] { key! }), reg3.Export(new[] { key! }));
            var r2 = reg3.Import(json);                                                 // 같은 키 재가져오기 → 재명명
            Assert.Equal(2, r2.Renamed.Count);
            Assert.Equal(4, reg3.Themes.Count);

            var tampered = json.Replace("\"name\": \"Second\"", "\"name\": \"\"", StringComparison.Ordinal);
            var r3 = new PromptFlowStudio.Services.Storyboard.CustomThemeRegistryService(new PromptFlowStudio.Services.Storyboard.BabyThemeDatabase(), root + "-c").Import(tampered);
            Assert.Single(r3.Imported);
            Assert.Single(r3.Errors);                                                   // 이름 없는 항목만 거부
            Assert.False(reg3.Import("{\"format\":\"zip\",\"version\":1,\"themes\":[]}").Ok);
            Assert.False(reg3.Import("{\"format\":\"pftheme\",\"version\":99,\"themes\":[{}]}").Ok);
            Assert.False(reg3.Import("not json").Ok);
            var k2 = reg3.Save(new PromptFlowStudio.Services.Storyboard.CustomThemeDefinition { Key = "lemon", Name = "x", Cuts = { new() { Shot = "s" } } }, out _);
            Assert.NotNull(k2);
            Assert.NotEqual("lemon", k2);
            Assert.Equal("🍋", db3.Get("lemon")!.Emoji);                               // 내장 테마 보호
            var evil = PromptFlowStudio.Services.Storyboard.CustomThemeRegistryService.SanitizeKey("../../evil");
            Assert.DoesNotContain("..", evil, StringComparison.Ordinal);
            Assert.DoesNotContain("/", evil, StringComparison.Ordinal);

            // ④ 삭제 → 병합 해제
            Assert.True(reg.Delete(key));
            Assert.Null(db.Get(key));
            Assert.False(File.Exists(Path.Combine(root, key + ".pftheme")));

            // ⑤ 멀티 엔진 트랜스파일러
            var cine = new PromptFlowStudio.Services.Storyboard.ThemeCinematics(PromptFlowStudio.Services.Storyboard.CameraMotion.Orbit,
                PromptFlowStudio.Services.Storyboard.ThemeLighting.GoldenHour, "50mm", new[] { "giggle" }, 2, "blurry");
            var scene = "a baby on a carousel horse, slow 360-degree orbit shot around the subject, 4K UHD, photorealistic, hyper-detailed";
            var wan = PromptFlowStudio.Services.Storyboard.MultiEnginePromptTranspiler.Transpile(scene, cine, PromptFlowStudio.Services.Storyboard.VideoEngineTarget.Wan21);
            Assert.Equal(1, CountOf(wan.Prompt, "orbit shot"));                       // 중복 카메라 토큰 제거 후 1회
            Assert.EndsWith("gentle subtle motion", wan.Prompt, StringComparison.Ordinal);
            Assert.DoesNotContain("4K UHD", wan.Prompt, StringComparison.Ordinal);
            Assert.Equal("blurry", wan.Negative);
            var luma = PromptFlowStudio.Services.Storyboard.MultiEnginePromptTranspiler.Transpile(scene, cine, PromptFlowStudio.Services.Storyboard.VideoEngineTarget.LumaDreamMachine);
            Assert.StartsWith("Camera orbits slowly around the subject. A baby on a carousel horse", luma.Prompt, StringComparison.Ordinal);
            Assert.Null(luma.Negative);
            Assert.True(luma.NegativeDropped);
            var runway = PromptFlowStudio.Services.Storyboard.MultiEnginePromptTranspiler.Transpile(scene, cine, PromptFlowStudio.Services.Storyboard.VideoEngineTarget.RunwayGen3);
            Assert.StartsWith("Orbiting shot: A baby on a carousel horse", runway.Prompt, StringComparison.Ordinal);
            var longScene = string.Join(", ", Enumerable.Repeat("a toddler running forward on soft grass", 40));
            var cut = PromptFlowStudio.Services.Storyboard.MultiEnginePromptTranspiler.Transpile(longScene, cine, PromptFlowStudio.Services.Storyboard.VideoEngineTarget.RunwayGen3);
            Assert.True(cut.Truncated);
            Assert.True(cut.Prompt.Length <= PromptFlowStudio.Services.Storyboard.MultiEnginePromptTranspiler.RunwayMaxChars);
            Assert.False(cut.Prompt.EndsWith(",", StringComparison.Ordinal));
            var themed = PromptFlowStudio.Services.Storyboard.MultiEnginePromptTranspiler.TranspileTheme(db.Get("ap_carousel")!, 0, PromptFlowStudio.Services.Storyboard.VideoEngineTarget.Wan21);
            Assert.Contains("orbit", themed.Prompt, StringComparison.Ordinal);
            Assert.Contains("reverse motion", themed.Negative, StringComparison.Ordinal);
        }
        finally
        {
            foreach (var d in new[] { root, root + "-b", root + "-c" })
                try { if (Directory.Exists(d)) Directory.Delete(d, true); } catch { /* best-effort */ }
        }

        static int CountOf(string s, string sub)
        {
            int n = 0, i = 0;
            while ((i = s.IndexOf(sub, i, StringComparison.Ordinal)) >= 0) { n++; i += sub.Length; }
            return n;
        }
    }

    [Fact]
    public async Task CustomThemeRegistry_And_Transpiler_Check()
    {
        var root = Path.Combine(Path.GetTempPath(), "pfs-themes13-" + Guid.NewGuid().ToString("N"));
        try
        {
            // ① 저장 → 갤러리 병합(내장 + 커스텀 카테고리) · OnChange 통지 · 내장 수 불변
            var db = new PromptFlowStudio.Services.Storyboard.BabyThemeDatabase();
            var builtIn = db.AllThemes.Count;
            var reg = new PromptFlowStudio.Services.Storyboard.CustomThemeRegistryService(db, root);
            var changes = 0;
            reg.OnChange += () => changes++;
            var key = reg.Save(new PromptFlowStudio.Services.Storyboard.CustomThemeDefinition
            {
                Key = "my_orbit", Name = "Orbit Picnic", CategoryKey = "everyday",
                Camera = PromptFlowStudio.Services.Storyboard.CameraMotion.Orbit,
                Lighting = PromptFlowStudio.Services.Storyboard.ThemeLighting.MoonlightBlue,
                Sfx = { "giggle" }, MotionIntensity = 4, Negative = "blurry",
                Cuts = { new() { Shot = "a baby waving at the camera on a picnic mat" }, new() { Shot = "the baby crawling forward to a basket" } },
            }, out var err);
            Assert.Null(err);
            Assert.StartsWith("ct_", key, StringComparison.Ordinal);
            Assert.Equal(1, changes);
            Assert.Equal(builtIn + 1, db.AllThemes.Count);
            Assert.Equal(builtIn, db.BuiltInCategories.Sum(c => c.Themes.Count));
            Assert.Contains(db.Categories, c => c.Key == PromptFlowStudio.Services.Storyboard.CustomThemeRegistryService.CategoryKey && c.Themes.Any(t => t.Key == key));
            Assert.True(db.IsBuiltInKey("ap_carousel"));
            Assert.False(db.IsBuiltInKey(key));
            Assert.True(File.Exists(Path.Combine(root, key + PromptFlowStudio.Services.Storyboard.CustomThemeRegistryService.Extension)));

            // ② 영구 저장 — 새 인스턴스(앱 재시작)가 디스크에서 복원
            var db2 = new PromptFlowStudio.Services.Storyboard.BabyThemeDatabase();
            var reg2 = new PromptFlowStudio.Services.Storyboard.CustomThemeRegistryService(db2, root);
            Assert.Equal("Orbit Picnic", reg2.Get(key)!.Name);
            Assert.Equal(2, db2.Get(key)!.Beats.Count);

            // ③ .pftheme 파일 Export → 스트림 Import(드래그 앤 드롭 경로) · 충돌 재명명 vs 덮어쓰기 · 1MB 상한
            var path = reg.ExportToFile(new[] { key! }, Path.Combine(root, "share", "picnic.pftheme"), out var xerr);
            Assert.Null(xerr);
            await using (var fs = File.OpenRead(path!))
            {
                var r = await reg2.ImportAsync(fs);
                Assert.True(r.Ok);
                Assert.Single(r.Renamed);
                Assert.NotEqual(key, r.Imported[0]);
            }
            await using (var fs = File.OpenRead(path!))
            {
                var r = await reg2.ImportAsync(fs, overwriteExisting: true);
                Assert.Equal(key, r.Imported[0]);
                Assert.Empty(r.Renamed);
            }
            Assert.Equal(2, reg2.Themes.Count);
            using (var big = new MemoryStream(new byte[PromptFlowStudio.Services.Storyboard.CustomThemeRegistryService.MaxFileBytes + 1]))
                Assert.False((await reg2.ImportAsync(big)).Ok);

            // ④ 트랜스파일러 — 모든 카메라 무빙이 엔진별 고유 문법으로 매핑 · 빈 장면에서도 공백/구두점 정상
            var cams = Enum.GetValues<PromptFlowStudio.Services.Storyboard.CameraMotion>();
            var luma = new System.Collections.Generic.HashSet<string>();
            var runway = new System.Collections.Generic.HashSet<string>();
            foreach (var cam in cams)
            {
                var c = new PromptFlowStudio.Services.Storyboard.ThemeCinematics(cam, PromptFlowStudio.Services.Storyboard.ThemeLighting.StudioSoft, "50mm", Array.Empty<string>(), 3, null);
                var l = PromptFlowStudio.Services.Storyboard.MultiEnginePromptTranspiler.Transpile("", c, PromptFlowStudio.Services.Storyboard.VideoEngineTarget.LumaDreamMachine);
                var w = PromptFlowStudio.Services.Storyboard.MultiEnginePromptTranspiler.Transpile("", c, PromptFlowStudio.Services.Storyboard.VideoEngineTarget.RunwayGen3);
                foreach (var p in new[] { l.Prompt, w.Prompt })
                {
                    Assert.DoesNotContain("  ", p, StringComparison.Ordinal);
                    Assert.DoesNotContain(": ", p, StringComparison.Ordinal);
                    Assert.Equal(p.Trim(), p);
                }
                Assert.StartsWith("Camera ", l.Prompt, StringComparison.Ordinal);
                luma.Add(l.Prompt[..l.Prompt.IndexOf('.')]);
                runway.Add(w.Prompt[..w.Prompt.IndexOf('.')]);
            }
            Assert.Equal(cams.Length, luma.Count);
            Assert.Equal(cams.Length, runway.Count);

            // ⑤ 커스텀 테마 → 3엔진 변환(authored 네거티브: Wan만 유지, Luma/Runway 폐기 플래그)
            foreach (var engine in Enum.GetValues<PromptFlowStudio.Services.Storyboard.VideoEngineTarget>())
            {
                var t = PromptFlowStudio.Services.Storyboard.MultiEnginePromptTranspiler.TranspileTheme(db.Get(key)!, 1, engine);
                Assert.Contains("crawling forward", t.Prompt, StringComparison.Ordinal);
                Assert.True(t.Prompt.Length <= PromptFlowStudio.Services.Storyboard.MultiEnginePromptTranspiler.MaxChars(engine));
                if (engine == PromptFlowStudio.Services.Storyboard.VideoEngineTarget.Wan21)
                    Assert.StartsWith("blurry", t.Negative, StringComparison.Ordinal);
                else
                    Assert.True(t.Negative is null && t.NegativeDropped);
            }
            var lumaThemed = PromptFlowStudio.Services.Storyboard.MultiEnginePromptTranspiler.TranspileTheme(db.Get(key)!, 0, PromptFlowStudio.Services.Storyboard.VideoEngineTarget.LumaDreamMachine);
            Assert.StartsWith("Camera orbits slowly around the subject. A baby waving", lumaThemed.Prompt, StringComparison.Ordinal);

            // ⑥ 삭제 → 갤러리에서 즉시 제거
            Assert.True(reg.Delete(key));
            Assert.Equal(builtIn, db.AllThemes.Count);
            Assert.DoesNotContain(db.Categories, c => c.Key == PromptFlowStudio.Services.Storyboard.CustomThemeRegistryService.CategoryKey);
        }
        finally
        {
            try { if (Directory.Exists(root)) Directory.Delete(root, true); } catch { /* best-effort */ }
        }
    }

    [Fact]
    public void ArtifactGuardEngine_Injection_Check()
    {
        // ══ ① 컨텍스트 감지(영/한 · 복합 플래그) ══
        Assert.Equal(GuardContext.Human, ContextAwarePromptGuard.Detect("a smiling BABY portrait"));
        Assert.Equal(GuardContext.Human | GuardContext.Nature, ContextAwarePromptGuard.Detect("아기가 정원에서 꽃을 본다"));
        Assert.Equal(GuardContext.Object, ContextAwarePromptGuard.Detect("a red toy car on a table"));
        Assert.Equal(GuardContext.None, ContextAwarePromptGuard.Detect(null));

        // ══ ② 네거티브: 시간적 일관성 기본 + 인물 해부학 / 사물·자연 물리 · 사용자 원형 앞 유지 · 멱등 ══
        var human = ContextAwarePromptGuard.ApplyNegative("watermark,", GuardContext.Human);
        Assert.StartsWith("watermark, " + ContextAwarePromptGuard.TemporalNegative, human);
        Assert.Contains(ContextAwarePromptGuard.AnatomyNegative, human, StringComparison.Ordinal);
        Assert.DoesNotContain("incorrect scale", human, StringComparison.Ordinal);
        Assert.Same(human, ContextAwarePromptGuard.ApplyNegative(human, GuardContext.Human));
        var obj = ContextAwarePromptGuard.ApplyNegative(null, GuardContext.Object);
        Assert.Equal(ContextAwarePromptGuard.TemporalNegative + ", " + ContextAwarePromptGuard.PhysicsNegative, obj);
        Assert.DoesNotContain("extra limbs", obj, StringComparison.Ordinal);
        Assert.Equal(ContextAwarePromptGuard.TemporalNegative, ContextAwarePromptGuard.ApplyNegative("", GuardContext.None));
        foreach (var k in new[] { "melting", "morphing", "flickering", "unstable texture", "mutated hands", "deformed", "floating", "distorted perspective" })
            Assert.Contains(k, ContextAwarePromptGuard.ApplyNegative(null, GuardContext.Human | GuardContext.Nature), StringComparison.Ordinal);

        // ══ ③ 포지티브: 시간적 일관성 + 미세 모션(모션 미서술 · 저모션 강제) · 멱등 · 빈 i2v 프롬프트 보존 · 800자 상한 ══
        var pos = ContextAwarePromptGuard.ApplyPositive("baby sitting on a sofa", GuardContext.Human, null);
        Assert.StartsWith("baby sitting on a sofa, " + ContextAwarePromptGuard.TemporalPositive, pos);
        Assert.EndsWith(ContextAwarePromptGuard.HumanMicroMotion, pos);
        Assert.Same(pos, ContextAwarePromptGuard.ApplyPositive(pos, GuardContext.Human, null));
        Assert.EndsWith(ContextAwarePromptGuard.NatureMicroMotion, ContextAwarePromptGuard.ApplyPositive("misty forest", GuardContext.Nature, null));
        Assert.EndsWith(ContextAwarePromptGuard.TemporalPositive, ContextAwarePromptGuard.ApplyPositive("girl dancing", GuardContext.Human, 127));
        Assert.EndsWith(ContextAwarePromptGuard.HumanMicroMotion, ContextAwarePromptGuard.ApplyPositive("girl dancing", GuardContext.Human, 40));
        Assert.Same("", ContextAwarePromptGuard.ApplyPositive("", GuardContext.Human, 40));
        var full = new string('a', 800);
        Assert.Same(full, ContextAwarePromptGuard.ApplyPositive(full, GuardContext.None, null));

        // ══ ④ 요청 가공: T2V/I2V 모두 주입 · 기존 Motion-Vector 가드와 공존 · 재가공 동일 참조 ══
        var t2v = ContextAwarePromptGuard.Process(new WanVideoRequest { Prompt = "a cup on a kitchen table", Tuning = new WanTuning(30, 6f, 50, false, false) });
        Assert.Contains("natural physics", t2v.Prompt, StringComparison.Ordinal);
        Assert.Contains("incorrect scale", t2v.NegativePrompt, StringComparison.Ordinal);
        Assert.Same(t2v, ContextAwarePromptGuard.Process(t2v));
        var i2v = ContextAwarePromptGuard.Process(MotionVectorPromptEngine.Process(
            new WanVideoRequest { Prompt = "toddler in a bedroom", ImagePath = "a.png", NegativePrompt = "watermark" }));
        Assert.StartsWith("watermark, " + MotionVectorPromptEngine.ReverseGuardNegative, i2v.NegativePrompt);
        Assert.Contains("extra limbs", i2v.NegativePrompt, StringComparison.Ordinal);
        Assert.Contains("dolly out", i2v.Prompt, StringComparison.Ordinal);
        Assert.Contains(ContextAwarePromptGuard.TemporalPositive, i2v.Prompt, StringComparison.Ordinal);
    }

    [Fact]
    public void MassiveThemeExpansion_CountAndMetadata_Check()
    {
        var db = new PromptFlowStudio.Services.Storyboard.BabyThemeDatabase();
        var all = db.AllThemes;

        // ① 총 200+ · 키 전역 유일 · 확장 카테고리 볼륨
        Assert.True(all.Count >= 200, $"테마 {all.Count}개 < 200");
        Assert.Equal(all.Count, all.Select(t => t.Key).Distinct(StringComparer.OrdinalIgnoreCase).Count());
        foreach (var (cat, min) in new[] { ("food", 11), ("sleep", 11), ("daily", 11), ("outdoor", 9), ("special", 17), ("playground", 15), ("kidscafe", 15), ("amusement", 14), ("everyday", 14) })
            Assert.True(Assert.Single(db.Categories, c => c.Key == cat).Themes.Count >= min, cat);

        // ② 전 테마 시네마틱 메타(카메라·조명·렌즈·SFX·강도) 산출 · 정의된 열거값 · 인스턴스 캐시
        foreach (var t in all)
        {
            var c = t.Cinematics;
            Assert.True(Enum.IsDefined(c.Camera), t.Key);
            Assert.True(Enum.IsDefined(c.Lighting), t.Key);
            Assert.False(string.IsNullOrWhiteSpace(c.CameraChip.Label), t.Key);
            Assert.False(string.IsNullOrWhiteSpace(c.LightingSnippet), t.Key);
            Assert.False(string.IsNullOrWhiteSpace(c.Lens), t.Key);
            Assert.InRange(c.Sfx.Count, 1, 3);
            Assert.InRange(c.MotionIntensity, PromptFlowStudio.Services.Storyboard.ThemeCinematics.MinIntensity, PromptFlowStudio.Services.Storyboard.ThemeCinematics.MaxIntensity);
            Assert.Same(c, t.Cinematics);
        }

        // ③ 신규 테마: authored Shot 키워드 → 메타 바인딩(기본값 아님) · Artifact Guard 인물 감지
        string[] added = { "pg_zipline", "ap_teacup", "ap_nightparade", "ap_fireworks", "kc_slime", "ev_puddle", "ev_dognap", "fd_spaghetti", "sl_starfish", "dl_duck", "sp_halloween", "sp_cherry", "sp_watergun", "od_firefly" };
        foreach (var key in added) Assert.NotNull(db.Get(key));
        string[] everydayCats = { "playground", "kidscafe", "amusement", "everyday" };
        foreach (var t in all.Where(t => Array.IndexOf(everydayCats, t.CategoryKey) >= 0 || t.Key.Length > 3 && t.Key[2] == '_' && "fd sl dl od sp".Contains(t.Key[..2], StringComparison.Ordinal)))
        {
            Assert.True(t.Beats.Count >= 4, t.Key);
            Assert.All(t.Beats, b => Assert.True(ContextAwarePromptGuard.Detect(b.Shot).HasFlag(GuardContext.Human), t.Key + ": " + b.Shot));
        }
        Assert.Equal(PromptFlowStudio.Services.Storyboard.CameraMotion.FpvDrone, db.Get("pg_zipline")!.RecommendedCameraMotion);
        Assert.Equal(PromptFlowStudio.Services.Storyboard.CameraMotion.Orbit, db.Get("ap_teacup")!.RecommendedCameraMotion);
        Assert.Equal(PromptFlowStudio.Services.Storyboard.ThemeLighting.NeonFestive, db.Get("ap_nightparade")!.RecommendedLighting);
        Assert.Equal(PromptFlowStudio.Services.Storyboard.ThemeLighting.MoonlightBlue, db.Get("sl_starfish")!.RecommendedLighting);
        Assert.Equal(PromptFlowStudio.Services.Storyboard.ThemeLighting.WarmTungsten, db.Get("sp_halloween")!.RecommendedLighting);

        // ④ 검색(제목·동의어 태그) · 스토리보드 결선(카메라/조명/SFX 프로젝트 반영 · 실생활 네거티브)
        var search = new PromptFlowStudio.Services.Storyboard.ThemeSearchFilterService();
        foreach (var (q, key) in new[] { ("짚라인", "pg_zipline"), ("슬라임", "kc_slime"), ("범퍼카", "ap_bumper"), ("물웅덩이", "ev_puddle"), ("할로윈", "sp_halloween"), ("벚꽃", "sp_cherry"), ("물총", "sp_watergun"), ("스파게티", "fd_spaghetti") })
            Assert.Contains(search.Filter(all, q), t => t.Key == key);

        var factory = new PromptFlowStudio.Services.Storyboard.VideoFormatFactory(db,
            new PromptFlowStudio.Services.Storyboard.CorporateThemeDatabase(), new PromptFlowStudio.Services.Storyboard.AutomotiveEquipmentDatabase());
        var proj = new PromptFlowStudio.Services.Storyboard.StoryboardProject();
        foreach (var t in all)
        {
            Assert.True(factory.Apply(proj, t.Key, PromptFlowStudio.Services.Storyboard.VideoFormat.Shorts), t.Key);
            Assert.NotEmpty(proj.Scenes);
            Assert.Equal(t.Cinematics.CameraChip.Label, proj.CinematicCamera);
            Assert.Equal(t.Cinematics.Lighting.ToString(), proj.CinematicLighting);
            Assert.Equal(t.Cinematics.Sfx, proj.CinematicSfx);
        }
        Assert.True(factory.Apply(proj, "kc_doctorplay", PromptFlowStudio.Services.Storyboard.VideoFormat.Longs));
        Assert.All(proj.Scenes, sc => Assert.Contains("reverse motion", sc.NegativePrompt, StringComparison.Ordinal));
    }

    [Fact]
    public async Task FirstFrameSimulation_LiveRender_Check()
    {
        static string Svg(string? url) => System.Text.Encoding.UTF8.GetString(Convert.FromBase64String(url!["data:image/svg+xml;base64,".Length..]));
        Assert.Equal(500, PromptFlowStudio.Services.Ui.FirstFrameSimulationService.DebounceMs);
        Assert.True(PromptFlowStudio.Services.Ui.FirstFrameSimulationService.IsPortrait("1080x1920"));
        Assert.True(PromptFlowStudio.Services.Ui.FirstFrameSimulationService.IsPortrait("720*1280"));
        Assert.False(PromptFlowStudio.Services.Ui.FirstFrameSimulationService.IsPortrait("1280*720"));
        Assert.False(PromptFlowStudio.Services.Ui.FirstFrameSimulationService.IsPortrait(null));

        using var sim = new PromptFlowStudio.Services.Ui.FirstFrameSimulationService(debounce: TimeSpan.FromMilliseconds(60));
        var t2vDone = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        sim.Changed += () => { if (sim.Current.Kind == PromptFlowStudio.Services.Ui.FirstFrameKind.T2v) t2vDone.TrySetResult(); };
        var orbit = "a baby on a beach, " + PromptFlowStudio.Services.Ui.WanCameraStyleStudio.Cameras[0].Snippet;

        // ① T2V: 연속 입력은 Pending(스켈레톤) → 디바운스 후 1회만 렌더 · 9:16 · 카메라 반영 · 이스케이프
        Assert.Equal(PromptFlowStudio.Services.Ui.FirstFrameKind.Empty, sim.Update("", "1280*720", null).Kind);
        Assert.Equal(PromptFlowStudio.Services.Ui.FirstFrameKind.Pending, sim.Update("a ba", "720*1280", null).Kind);
        Assert.Equal(PromptFlowStudio.Services.Ui.FirstFrameKind.Pending, sim.Update("a baby on a", "720*1280", null).Kind);
        var pending = sim.Update("<script> " + orbit, "720*1280", null);
        Assert.Equal(PromptFlowStudio.Services.Ui.FirstFrameKind.Pending, pending.Kind);
        Assert.Same(pending, sim.Update("<script> " + orbit, "720*1280", null));             // 동일 입력 멱등
        Assert.Equal(0, sim.Renders);
        await t2vDone.Task.WaitAsync(TimeSpan.FromSeconds(10));
        var f = sim.Current;
        Assert.Equal(1, sim.Renders);
        Assert.True(f.Portrait);
        Assert.Equal(0, f.CameraIndex);
        Assert.Equal("ffs-cam-orbit", f.MotionCss);
        var svg = Svg(f.FrameUrl);
        Assert.Contains("viewBox='0 0 360 640'", svg, StringComparison.Ordinal);
        Assert.Contains("9:16 · Orbit", svg, StringComparison.Ordinal);
        Assert.Contains("&lt;script&gt;", svg, StringComparison.Ordinal);
        Assert.DoesNotContain("<script>", svg, StringComparison.Ordinal);

        // ② 새 입력 → Pending 중 직전 프레임 유지(스켈레톤 오버레이) · Flush 즉시 확정 · 되돌리면 캐시 즉시 히트(렌더 0)
        var next = sim.Update("toddler in a kitchen", "720*1280", null);
        Assert.Equal(PromptFlowStudio.Services.Ui.FirstFrameKind.Pending, next.Kind);
        Assert.Equal(f.FrameUrl, next.FrameUrl);
        Assert.True(sim.Flush());
        Assert.Equal(PromptFlowStudio.Services.Ui.FirstFrameKind.T2v, sim.Current.Kind);
        Assert.False(sim.Flush());
        var renders = sim.Renders;
        var cached = sim.Update("<script> " + orbit, "720*1280", null);
        Assert.Equal(PromptFlowStudio.Services.Ui.FirstFrameKind.T2v, cached.Kind);
        Assert.True(cached.FromCache);
        Assert.Equal(f.FrameUrl, cached.FrameUrl);
        Assert.Equal(renders, sim.Renders);
        Assert.Equal(1, sim.CacheHits);

        // ③ 앵커: 디바운스 없이 동기 합성(0.1초 예산) · 16:9 · Dolly Zoom 오버레이 · 대기 중이던 T2V 결과가 덮지 않음
        sim.Update("baby pending text", "1280*720", null);
        var dolly = PromptFlowStudio.Services.Ui.WanCameraStyleStudio.ApplyCamera("baby smiling", 3);
        var sw = Stopwatch.StartNew();
        var anchor = sim.Update(dolly, "1280*720", "https://0.0.0.0/anchor.png");
        sw.Stop();
        Assert.Equal(PromptFlowStudio.Services.Ui.FirstFrameKind.Anchor, anchor.Kind);
        Assert.True(sw.ElapsedMilliseconds < PromptFlowStudio.Services.Ui.FirstFrameSimulationService.AnchorBudgetMs, $"앵커 합성 {sw.ElapsedMilliseconds}ms");
        Assert.Equal("https://0.0.0.0/anchor.png", anchor.AnchorUrl);
        Assert.Equal("ffs-cam-dolly", anchor.MotionCss);
        Assert.False(anchor.Portrait);
        var ov = Svg(anchor.OverlayUrl);
        Assert.Contains("viewBox='0 0 640 360'", ov, StringComparison.Ordinal);
        Assert.Contains("16:9 · Dolly Zoom", ov, StringComparison.Ordinal);
        await Task.Delay(250);
        Assert.Same(anchor, sim.Current);
        var bare = sim.Update("", "1080x1920", "https://0.0.0.0/anchor.png");               // 프롬프트 없이 앵커만 → 즉시 합성
        Assert.Equal(PromptFlowStudio.Services.Ui.FirstFrameKind.Anchor, bare.Kind);
        Assert.Equal("Static", bare.CameraLabel);
        Assert.Equal("9:16", bare.AspectLabel);

        // ④ UI 결선: 공용 덱 → 서비스 · 두 페이지가 해상도·1-Click 생성 콜백 전달
        var root = RepoRoot();
        var deck = File.ReadAllText(Path.Combine(root, "PromptFlowStudio", "Blazor", "Components", "Common", "FirstFramePreviewDeck.razor"));
        Assert.Contains("FirstFrameSimulationService", deck, StringComparison.Ordinal);
        Assert.Contains("ffs-skel", deck, StringComparison.Ordinal);
        Assert.DoesNotContain("@inject", deck, StringComparison.Ordinal);                  // 모바일 서브컴포넌트 안전
        foreach (var page in new[] { "Workspace.razor", "Storyboard.razor" })
        {
            var src = File.ReadAllText(Path.Combine(root, "PromptFlowStudio", "Blazor", "Pages", page));
            Assert.Contains("OnStartGenerate=", src, StringComparison.Ordinal);
            Assert.Contains("Size=", src, StringComparison.Ordinal);
        }
    }

    [Fact]
    public async Task PostProductionEngine_FfmpegMixing_Check()
    {
        var clips = new[] { @"V:\cuts\a 1.mp4", @"V:\cuts\b.mp4", @"V:\cuts\c.mp4" };

        // ① 영상: 정규화(scale+pad+fps+settb) · Crossfade xfade 체인 offset = 누적 − 겹침 · 공백 경로는 인자 1개 · 무음 중간 파일
        var vplan = new PromptFlowStudio.Services.Media.VideoMixPlan(clips, @"V:\out\video.mp4", 1081, 1920, 30,
            PromptFlowStudio.Services.Media.PostTransition.Crossfade, 0.5);
        var va = PromptFlowStudio.Services.Media.FfmpegVideoMixerService.BuildArgs(vplan);
        Assert.Contains(@"V:\cuts\a 1.mp4", va);
        Assert.Equal(3, va.Count(a => a == "-i"));
        var vfc = va[va.IndexOf("-filter_complex") + 1];
        Assert.Equal(3, CountOf(vfc, "scale=1080:1920:force_original_aspect_ratio=decrease,pad=1080:1920"));   // 홀수 해상도 → 짝수
        Assert.Equal(3, CountOf(vfc, "fps=30"));
        Assert.Contains("[v0][v1]xfade=transition=fade:duration=0.5:offset=4.5[x1]", vfc, StringComparison.Ordinal);
        Assert.Contains("[x1][v2]xfade=transition=fade:duration=0.5:offset=9[vout]", vfc, StringComparison.Ordinal);
        Assert.Contains("-an", va);
        Assert.Equal("[vout]", va[va.IndexOf("-map") + 1]);
        Assert.Equal(@"V:\out\video.mp4", va[^1]);
        var tl = PromptFlowStudio.Services.Media.FfmpegVideoMixerService.Timeline(vplan);
        Assert.Equal(new[] { 0.0, 4.5, 9.0 }, tl.CutStarts);
        Assert.Equal(14.0, tl.TotalSeconds);

        // FadeInOut: 컷별 dip-to-black(첫 컷 fade-in·끝 컷 fade-out 없음) + concat · 과도한 트랜지션은 컷 45%로 클램프 · Cut 은 순수 concat
        var fade = new PromptFlowStudio.Services.Media.VideoMixPlan(clips, "o.mp4", 1280, 720, 30, PromptFlowStudio.Services.Media.PostTransition.FadeInOut, 9, new[] { 5.0, 2.0, 5.0 });
        var ffc = PromptFlowStudio.Services.Media.FfmpegVideoMixerService.BuildArgs(fade).Find(a => a.Contains("concat=n=3", StringComparison.Ordinal))!;
        Assert.Equal(0.9, PromptFlowStudio.Services.Media.FfmpegVideoMixerService.EffectiveTransition(fade));
        Assert.Equal(2, CountOf(ffc, "fade=t=in"));
        Assert.Equal(2, CountOf(ffc, "fade=t=out"));
        Assert.Contains("trim=duration=5,setpts=PTS-STARTPTS,fade=t=out:st=4.1:d=0.9,settb=AVTB[v0]", ffc, StringComparison.Ordinal);
        Assert.Equal(12.0, PromptFlowStudio.Services.Media.FfmpegVideoMixerService.Timeline(fade).TotalSeconds);
        var cut = PromptFlowStudio.Services.Media.FfmpegVideoMixerService.BuildArgs(vplan with { Transition = PromptFlowStudio.Services.Media.PostTransition.Cut });
        Assert.DoesNotContain("xfade", string.Join(" ", cut), StringComparison.Ordinal);
        Assert.Contains("[v0][v1][v2]concat=n=3:v=1:a=0[vout]", cut[cut.IndexOf("-filter_complex") + 1], StringComparison.Ordinal);
        Assert.Throws<ArgumentException>(() => PromptFlowStudio.Services.Media.FfmpegVideoMixerService.BuildArgs(vplan with { Inputs = Array.Empty<string>() }));

        // ② SFX 큐: authored 폴리(컷-로컬 ms) 우선 · 폴리 없는 컷은 CinematicSfx 순환(+0.25초) · 미해결 토큰 건너뜀
        var proj = new PromptFlowStudio.Services.Storyboard.StoryboardProject { CinematicSfx = new() { "giggle", "missing" } };
        var scenes = new List<PromptFlowStudio.Services.Storyboard.StoryboardScene>
        {
            new() { PresetFoley = new() { new("whoosh", 300, 0), new("pop", 1200, 0.5) } },
            new(),
            new(),
        };
        string? Resolve(string t) => t == "missing" ? null : @"V:\sfx\" + t + ".wav";
        var cues = PromptFlowStudio.Services.Media.FfmpegAudioMixerService.BuildCues(proj, scenes, tl, Resolve);
        Assert.Equal(new[] { 0.3, 1.2, 4.75 }, cues.Select(c => c.AtSeconds));
        Assert.Equal(@"V:\sfx\giggle.wav", cues[2].Path);                         // 컷2 = giggle · 컷3 = missing(미해결) → 생략

        // ③ 오디오: BGM 무한 루핑 + 영상 길이 절단 + 끝 2초 afade out · SFX adelay(ms) · 중복 파일 asplit · amix normalize=0 · 영상 copy 먹싱
        var dup = new List<PromptFlowStudio.Services.Media.SfxCue>(cues) { new(@"V:\sfx\whoosh.wav", 9.25) };
        var aplan = new PromptFlowStudio.Services.Media.AudioMixPlan(@"V:\out\video.mp4", @"V:\out\final.mp4", tl.TotalSeconds, @"V:\bgm\theme song.mp3", dup);
        var aa = PromptFlowStudio.Services.Media.FfmpegAudioMixerService.BuildArgs(aplan);
        var loop = aa.IndexOf("-stream_loop");
        Assert.True(loop > 0);
        Assert.Equal("-1", aa[loop + 1]);
        Assert.Equal(@"V:\bgm\theme song.mp3", aa[loop + 3]);
        Assert.Equal(5, aa.Count(a => a == "-i"));                                // 영상 + BGM + 고유 SFX 3개(whoosh 중복 1회 입력)
        var afc = aa[aa.IndexOf("-filter_complex") + 1];
        Assert.Contains("[1:a]aresample=48000,atrim=0:14,asetpts=PTS-STARTPTS,volume=0.35,afade=t=in:st=0:d=0.8,afade=t=out:st=12:d=2[bgm]", afc, StringComparison.Ordinal);
        Assert.Contains("asplit=2[f0_0][f0_1]", afc, StringComparison.Ordinal);
        Assert.Contains("adelay=300|300", afc, StringComparison.Ordinal);
        Assert.Contains("adelay=4750|4750", afc, StringComparison.Ordinal);
        Assert.Contains("adelay=9250|9250", afc, StringComparison.Ordinal);
        Assert.Contains("amix=inputs=5:duration=longest:dropout_transition=0:normalize=0,atrim=0:14", afc, StringComparison.Ordinal);
        Assert.Equal("copy", aa[aa.IndexOf("-c:v") + 1]);
        Assert.Equal("[aout]", aa[aa.LastIndexOf("-map") + 1]);
        Assert.Equal(@"V:\out\final.mp4", aa[^1]);

        // 오디오 소스 전무 → 필터 없이 스트림 copy
        var none = PromptFlowStudio.Services.Media.FfmpegAudioMixerService.BuildArgs(aplan with { BgmPath = null, Sfx = Array.Empty<PromptFlowStudio.Services.Media.SfxCue>() });
        Assert.DoesNotContain("-filter_complex", none);
        Assert.Equal("copy", none[none.IndexOf("-c") + 1]);

        // ④ 엔진 Graceful: ffmpeg 부재 · 완료 컷 없음 · 재진입 없음(예외 0)
        var engine = new PromptFlowStudio.Services.Media.PostProductionEngine(
            new PromptFlowStudio.Services.Media.FfmpegVideoMixerService(() => null), new PromptFlowStudio.Services.Media.FfmpegAudioMixerService(() => null));
        Assert.False(engine.IsAvailable);
        var r = await engine.ExportAsync(proj);
        Assert.False(r.Ok);
        Assert.Contains("ffmpeg", r.Message, StringComparison.Ordinal);
        var ready = new PromptFlowStudio.Services.Media.PostProductionEngine(
            new PromptFlowStudio.Services.Media.FfmpegVideoMixerService(() => @"V:\ffmpeg.exe"), new PromptFlowStudio.Services.Media.FfmpegAudioMixerService(() => @"V:\ffmpeg.exe"));
        var r2 = await ready.ExportAsync(proj);
        Assert.False(r2.Ok);
        Assert.Contains("완료된 컷", r2.Message, StringComparison.Ordinal);
        Assert.False(ready.IsBusy);
        var miss = await new PromptFlowStudio.Services.Media.FfmpegVideoMixerService(() => @"V:\ffmpeg.exe").MixAsync(vplan);
        Assert.False(miss.Ok);
        Assert.Contains("컷 1", miss.Message, StringComparison.Ordinal);

        // ⑤ UI 결선(Storyboard 최종 내보내기 버튼 · 탐색기 열기) + DI 양쪽 등록
        var root = RepoRoot();
        var sb = File.ReadAllText(Path.Combine(root, "PromptFlowStudio", "Blazor", "Pages", "Storyboard.razor"));
        Assert.Contains("🎬 최종 영상 내보내기 (BGM+SFX)", sb, StringComparison.Ordinal);
        Assert.Contains("FolderLink.Reveal", sb, StringComparison.Ordinal);
        foreach (var di in new[] { Path.Combine(root, "PromptFlowStudio", "MainForm.cs"), Path.Combine(root, "PromptFlowStudio.Mobile", "MauiProgram.cs") })
            Assert.Contains("PostProductionEngine", File.ReadAllText(di), StringComparison.Ordinal);

        static int CountOf(string s, string sub) { var n = 0; for (var i = s.IndexOf(sub, StringComparison.Ordinal); i >= 0; i = s.IndexOf(sub, i + sub.Length, StringComparison.Ordinal)) n++; return n; }
    }

    [Fact]
    public async Task VoiceoverAndSubtitles_Muxing_Check()
    {
        var tmp = Path.Combine(Path.GetTempPath(), "pf_vo_" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(tmp);
        try
        {
            // ① 톤 × 배속 → 운율(Edge SSML rate/pitch · ElevenLabs speed 0.7~1.2 클램프)
            var fairy = Med.AiVoiceoverTtsService.Prosody(Med.NarrationTone.FairyTale);
            Assert.Equal(("-6%", "+3Hz"), (fairy.Rate, fairy.Pitch));
            var cloud = Med.AiVoiceoverTtsService.Prosody(Med.NarrationTone.Cloud);
            Assert.Equal(("-12%", "-2Hz"), (cloud.Rate, cloud.Pitch));
            var bright = Med.AiVoiceoverTtsService.Prosody(Med.NarrationTone.Bright, 1.15);
            Assert.Equal("+22%", bright.Rate);
            Assert.Equal(1.2, bright.Speed);
            Assert.Equal("+112%", Med.AiVoiceoverTtsService.Prosody(Med.NarrationTone.Bright, 9).Rate);   // 배속 2.0 상한
            Assert.True(Med.AiVoiceoverTtsService.EstimateSeconds("옛날 옛적에 아기 토끼가 살았어요.", speed: 2.0)
                      < Med.AiVoiceoverTtsService.EstimateSeconds("옛날 옛적에 아기 토끼가 살았어요."));
            Assert.Equal(0.0, Med.AiVoiceoverTtsService.EstimateSeconds("  "));

            // ElevenLabs 페이로드 스키마(System.Text.Json)
            using (var doc = System.Text.Json.JsonDocument.Parse(Med.AiVoiceoverTtsService.BuildElevenLabsPayload("안녕 \"아가\"", fairy)))
            {
                Assert.Equal("안녕 \"아가\"", doc.RootElement.GetProperty("text").GetString());
                Assert.Equal(Med.AiVoiceoverTtsService.ElevenModel, doc.RootElement.GetProperty("model_id").GetString());
                Assert.Equal(fairy.Speed, doc.RootElement.GetProperty("voice_settings").GetProperty("speed").GetDouble());
            }

            // ② ElevenLabs: 503 → 지수 백오프 재시도 → MP3(ID3) 저장 · 키 없음/4xx/비-MP3 → Edge 폴백(prosody 전달)
            var edge = new FakeEdge(tmp);
            var mp3 = new byte[] { (byte)'I', (byte)'D', (byte)'3', 4, 0, 0, 0, 0, 0, 0 };
            var flaky = new FlakyImageHandler(mp3, failFirst: 1);
            using (var el = new Med.AiVoiceoverTtsService(edge, null, flaky, () => "test-key"))
            {
                var line = "아기 곰이 꿈나라로 떠나요 " + Guid.NewGuid().ToString("N");
                var path = await el.SynthesizeAsync(line, Med.NarrationTone.Cloud);
                Assert.NotNull(path);
                Assert.True(File.Exists(path));
                Assert.Equal(2, flaky.Calls);
                Assert.Equal(0, edge.Calls);
                Assert.Equal(path, await el.SynthesizeAsync(line, Med.NarrationTone.Cloud));    // 콘텐츠 해시 캐시(재요청 0)
                Assert.Equal(2, flaky.Calls);
            }
            var deny = new FlakyImageHandler(mp3, 0, System.Net.HttpStatusCode.Unauthorized);
            using (var el = new Med.AiVoiceoverTtsService(edge, null, deny, () => "bad-key"))
            {
                Assert.Null(await el.SynthesizeAsync("별님 " + Guid.NewGuid().ToString("N"), Med.NarrationTone.Bright, 1.15));
                Assert.Equal(1, deny.Calls);                                                // 4xx 즉시 포기(재시도 0)
                Assert.Equal(1, edge.Calls);
                Assert.Equal(("+22%", "+6Hz"), (edge.LastRate, edge.LastPitch));
            }
            var junk = new FlakyImageHandler(new byte[] { 1, 2, 3, 4 }, 0);
            using (var el = new Med.AiVoiceoverTtsService(edge, null, junk, () => "k"))
                Assert.Null(await el.SynthesizeAsync("달님 " + Guid.NewGuid().ToString("N"), provider: Med.TtsProvider.ElevenLabs));   // 스키마 검증 실패 · 폴백 없음
            Assert.Equal(1, edge.Calls);
            using (var none = new Med.AiVoiceoverTtsService(null, null, null, () => null))
            {
                Assert.False(none.IsAvailable);
                Assert.Null(await none.SynthesizeAsync("x"));
            }

            // WAV 헤더 실측 길이(byteRate 88200 · data 44100B = 0.5초)
            var wav = Path.Combine(tmp, "n.wav");
            using (var fs = File.Create(wav))
            using (var bw = new BinaryWriter(fs))
            {
                bw.Write("RIFF"u8.ToArray()); bw.Write(36 + 44100); bw.Write("WAVE"u8.ToArray());
                bw.Write("fmt "u8.ToArray()); bw.Write(16); bw.Write((short)1); bw.Write((short)2); bw.Write(22050); bw.Write(88200); bw.Write((short)4); bw.Write((short)16);
                bw.Write("data"u8.ToArray()); bw.Write(44100); bw.Write(new byte[44100]);
            }
            Assert.Equal(0.5, Med.AiVoiceoverTtsService.ProbeSeconds(wav)!.Value);
            Assert.Null(Med.AiVoiceoverTtsService.ProbeSeconds(Path.Combine(tmp, "missing.wav")));

            // 스토리 합성: VoiceText 있는 컷만 · 컷 시작 + 0.3초 · 컷 실패는 건너뜀
            var scenes = new System.Collections.Generic.List<PromptFlowStudio.Services.Storyboard.StoryboardScene>
            {
                new() { VoiceText = "첫 장면이에요." }, new(), new() { VoiceText = "마지막 장면!" },
            };
            var tl = new Med.MixTimeline(new[] { 0.0, 4.5, 9.0 }, 14);
            var wavEdge = new FakeEdge(tmp) { Result = wav };
            using (var story = new Med.AiVoiceoverTtsService(wavEdge, null, null, () => null))
            {
                var vc = await story.SynthesizeStoryAsync(scenes, tl, Med.NarrationTone.FairyTale);
                Assert.Equal(new[] { 0.3, 9.3 }, vc.Select(c => c.AtSeconds));
                Assert.All(vc, c => Assert.Equal(0.5, c.DurationSeconds));
                Assert.Equal("마지막 장면!", vc[1].Text);
            }

            // ③ 세이프존 레이아웃: 하단 UI 높이 → MarginV · 우측 버튼 열 → 좌우 대칭 여백 · 높이 비례 폰트/외곽선
            var tik = Med.AutoSubtitleGenerator.ComputeLayout(Med.SafePlatform.TikTok, 1080, 1920);
            Assert.Equal((576, 162, 162, 74), (tik.MarginV, tik.MarginL, tik.MarginR, tik.FontSize));
            var shorts = Med.AutoSubtitleGenerator.ComputeLayout(Med.SafePlatform.YouTubeShorts, 1080, 1920);
            var reels = Med.AutoSubtitleGenerator.ComputeLayout(Med.SafePlatform.InstagramReels, 1080, 1920);
            Assert.Equal(384, shorts.MarginV);
            Assert.True(tik.MarginV > reels.MarginV && reels.MarginV > shorts.MarginV);
            Assert.True(Med.AutoSubtitleGenerator.ComputeLayout(Med.SafePlatform.None, 1080, 1920).MarginV < shorts.MarginV);
            Assert.Equal(40, Med.AutoSubtitleGenerator.ComputeLayout(Med.SafePlatform.None, 1080, 1920, new Med.SubtitleStyle(FontSize: 40)).FontSize);

            // ④ 자막 분할: 줄당 16자 · 2줄 블록 · 나레이션 구간 내 연속(겹침 0) · 다음 나레이션 시작에서 절단
            var voice = new[]
            {
                new Med.VoiceCue(wav, 0.3, 6.0, "옛날 옛적 깊은 숲속에 작은 아기 토끼가 살았어요. 토끼는 매일 밤 {달님}에게 인사했답니다."),
                new Med.VoiceCue(wav, 5.0, 2.0, "안녕, 달님!"),
            };
            var cues = Med.AutoSubtitleGenerator.BuildCues(voice);
            Assert.True(cues.Count >= 3);
            for (var i = 0; i < cues.Count; i++)
            {
                Assert.Equal(i + 1, cues[i].Index);
                Assert.True(cues[i].End > cues[i].Start);
                if (i > 0) Assert.True(cues[i].Start >= cues[i - 1].End - 1e-9);
                Assert.All(cues[i].Text.Split('\n'), l => Assert.True(l.Length <= 16));
                Assert.True(cues[i].Text.Split('\n').Length <= 2);
            }
            Assert.Equal(5.0, cues[^2].End);
            Assert.Equal((5.0, 7.0, "안녕, 달님!"), (cues[^1].Start, cues[^1].End, cues[^1].Text));

            var srt = Med.AutoSubtitleGenerator.ToSrt(cues);
            Assert.StartsWith("1\r\n00:00:00,300 --> ", srt, StringComparison.Ordinal);
            Assert.Contains("00:00:05,000 --> 00:00:07,000\r\n안녕, 달님!\r\n\r\n", srt, StringComparison.Ordinal);
            var ass = Med.AutoSubtitleGenerator.ToAss(cues, tik);
            Assert.Contains("PlayResX: 1080\r\nPlayResY: 1920", ass, StringComparison.Ordinal);
            Assert.Contains("Style: Narration,Malgun Gothic,74,&H00FFFFFF,&H000000FF,&H00000000,&H64000000,-1,0,0,0,100,100,0,0,1,5.3,1.5,2,162,162,576,1", ass, StringComparison.Ordinal);
            Assert.Contains("Dialogue: 0,0:00:00.30,", ass, StringComparison.Ordinal);
            Assert.Contains("\\N", ass, StringComparison.Ordinal);
            Assert.DoesNotContain("{", ass.Substring(ass.IndexOf("[Events]", StringComparison.Ordinal)), StringComparison.Ordinal);   // 오버라이드 무해화
            Assert.Equal("subtitles=filename='C\\:/out/a b\\'s.ass':fontsdir='C\\:/Windows/Fonts'",
                Med.AutoSubtitleGenerator.BuildBurnFilter(@"C:\out\a b's.ass", @"C:\Windows\Fonts"));
            var assPath = await Med.AutoSubtitleGenerator.WriteAsync(Path.Combine(tmp, "final.mp4"), cues, tik);
            Assert.True(File.Exists(assPath) && File.Exists(Path.ChangeExtension(assPath, ".srt")));
            Assert.Equal(new byte[] { 0xEF, 0xBB, 0xBF }, File.ReadAllBytes(assPath)[..3]);

            // ⑤ 4중 먹싱: 영상 + BGM(사이드체인 덕킹) + SFX + 나레이션 + 자막 번인(영상 재인코딩)
            var plan = new Med.AudioMixPlan(@"V:\out\video.mp4", @"V:\out\final.mp4", 14, @"V:\bgm\song.mp3",
                new[] { new Med.SfxCue(@"V:\sfx\pop.wav", 1.2) }, Voice: voice, SubtitlePath: @"V:\out\final.ass");
            var args = Med.FfmpegAudioMixerService.BuildArgs(plan);
            Assert.Equal(5, args.Count(a => a == "-i"));                                    // 영상 + BGM + SFX 1 + 나레이션 2
            var fc = args[args.IndexOf("-filter_complex") + 1];
            Assert.Contains("afade=t=out:st=12:d=2[bgmraw];", fc, StringComparison.Ordinal);
            Assert.Contains("[3:a]aresample=48000,aformat=channel_layouts=stereo,adelay=300|300,volume=1[v0];", fc, StringComparison.Ordinal);
            Assert.Contains("[4:a]aresample=48000,aformat=channel_layouts=stereo,adelay=5000|5000,volume=1[v1];", fc, StringComparison.Ordinal);
            Assert.Contains("[v0][v1]amix=inputs=2:duration=longest:dropout_transition=0:normalize=0,asplit=2[vo][vkey];[bgmraw][vkey]"
                + Med.FfmpegAudioMixerService.DuckFilter + "8[bgm];", fc, StringComparison.Ordinal);
            Assert.Contains("[0:v]subtitles=filename='V\\:/out/final.ass',format=yuv420p[vout];", fc, StringComparison.Ordinal);
            Assert.Contains("[bgm][s0][vo]amix=inputs=3:duration=longest:dropout_transition=0:normalize=0,atrim=0:14,alimiter=limit=0.95[aout]", fc, StringComparison.Ordinal);
            Assert.Equal("[vout]", args[args.IndexOf("-map") + 1]);
            Assert.Equal("[aout]", args[args.LastIndexOf("-map") + 1]);
            Assert.Equal("libx264", args[args.IndexOf("-c:v") + 1]);
            Assert.Equal("aac", args[args.IndexOf("-c:a") + 1]);

            // 덕킹 off(BGM 없음) → [vo] 직결 · 번인 없음 → 영상 copy 유지
            var noBgm = Med.FfmpegAudioMixerService.BuildArgs(plan with { BgmPath = null, SubtitlePath = null });
            var fc2 = noBgm[noBgm.IndexOf("-filter_complex") + 1];
            Assert.DoesNotContain("sidechaincompress", fc2, StringComparison.Ordinal);
            Assert.Contains("normalize=0[vo];", fc2, StringComparison.Ordinal);
            Assert.Equal("copy", noBgm[noBgm.IndexOf("-c:v") + 1]);
            Assert.Equal("0:v", noBgm[noBgm.IndexOf("-map") + 1]);
            // 오디오 소스 없음 + 번인만 → 비디오 체인 단독 그래프(끝 ';' 없음) · 재인코딩
            var burnOnly = Med.FfmpegAudioMixerService.BuildArgs(plan with { BgmPath = null, Sfx = Array.Empty<Med.SfxCue>(), Voice = null });
            var fc3 = burnOnly[burnOnly.IndexOf("-filter_complex") + 1];
            Assert.EndsWith("[vout]", fc3, StringComparison.Ordinal);
            Assert.DoesNotContain("[aout]", burnOnly);
            Assert.Equal("libx264", burnOnly[burnOnly.IndexOf("-c:v") + 1]);
            // 기존 v16.12.0 경로 바이트 호환(나레이션·자막 미지정)
            var legacy = Med.FfmpegAudioMixerService.BuildArgs(plan with { Voice = null, SubtitlePath = null });
            Assert.Contains("[bgm];", legacy[legacy.IndexOf("-filter_complex") + 1], StringComparison.Ordinal);
            Assert.DoesNotContain("bgmraw", legacy[legacy.IndexOf("-filter_complex") + 1], StringComparison.Ordinal);

            // ⑥ 엔진 결선: 나레이션 엔진 주입 · ffmpeg 부재 Graceful · 옵션 경로 예외 0
            using var tts = new Med.AiVoiceoverTtsService(wavEdge, null, null, () => null);
            var engine = new Med.PostProductionEngine(new Med.FfmpegVideoMixerService(() => null), new Med.FfmpegAudioMixerService(() => null),
                tts, new Med.AutoSubtitleGenerator());
            Assert.True(engine.CanNarrate);
            Assert.True(engine.HasSubtitleEngine);
            var r = await engine.ExportAsync(new PromptFlowStudio.Services.Storyboard.StoryboardProject(), voice: new Med.VoiceoverMixOptions(Platform: Med.SafePlatform.TikTok));
            Assert.False(r.Ok);
            Assert.Contains("ffmpeg", r.Message, StringComparison.Ordinal);
            Assert.False(engine.IsBusy);

            // ⑦ DI 양쪽 · UI 결선
            var root = RepoRoot();
            foreach (var di in new[] { Path.Combine(root, "PromptFlowStudio", "MainForm.cs"), Path.Combine(root, "PromptFlowStudio.Mobile", "MauiProgram.cs") })
            {
                var src = File.ReadAllText(di);
                Assert.Contains("AiVoiceoverTtsService", src, StringComparison.Ordinal);
                Assert.Contains("AutoSubtitleGenerator", src, StringComparison.Ordinal);
            }
            var sb = File.ReadAllText(Path.Combine(root, "PromptFlowStudio", "Blazor", "Pages", "Storyboard.razor"));
            Assert.Contains("VoiceoverMixOptions", sb, StringComparison.Ordinal);
            Assert.Contains("🎙️ 나레이션+자막", sb, StringComparison.Ordinal);
        }
        finally
        {
            try { Directory.Delete(tmp, true); } catch { /* 정리 실패 무시 */ }
        }
    }

    [Fact]
    public async Task OsmuSmartReframing_And_Metadata_Check()
    {
        // ① 대상 규격: 9:16 ×3 · 1:1 · 4:5 ×2 — 메타데이터 채널 매핑
        var specs = Med.OsmuSmartReframingService.Specs;
        Assert.Equal(6, specs.Count);
        Assert.All(new[] { Med.OsmuTarget.YouTubeShorts, Med.OsmuTarget.InstagramReels, Med.OsmuTarget.TikTok },
            t => Assert.Equal((1080, 1920, "9:16"), (Med.OsmuSmartReframingService.SpecOf(t).Width, Med.OsmuSmartReframingService.SpecOf(t).Height, Med.OsmuSmartReframingService.SpecOf(t).Aspect)));
        var feed = Med.OsmuSmartReframingService.SpecOf(Med.OsmuTarget.InstagramFeed);
        Assert.Equal((1080, 1080, "1:1", SB.SocialChannel.Instagram), (feed.Width, feed.Height, feed.Aspect, feed.Channel));
        var pin = Med.OsmuSmartReframingService.SpecOf(Med.OsmuTarget.Pinterest);
        var naver = Med.OsmuSmartReframingService.SpecOf(Med.OsmuTarget.NaverClip);
        Assert.Equal((1080, 1350, "4:5"), (pin.Width, pin.Height, pin.Aspect));
        Assert.Equal((1080, 1350, SB.SocialChannel.NaverClip), (naver.Width, naver.Height, naver.Channel));
        Assert.Equal("naver_clip_4x5", Med.OsmuExportPackager.FolderOf(naver));

        // ② 필터: 센터 프레이밍(초점 크롭) · 블러 배경(1/4 축소 블러 → 확대 + 비율 유지 전경 중앙 overlay) · 홀수 해상도 짝수화
        Assert.Equal("[0:v]scale=1080:1350:force_original_aspect_ratio=increase,crop=1080:1350:(iw-ow)*0.5:(ih-oh)*0.45,setsar=1,format=yuv420p[v]",
            Med.OsmuSmartReframingService.BuildFilter(1080, 1350, Med.OsmuFraming.CenterCrop));
        Assert.Contains("crop=1080:1080:(iw-ow)*1:(ih-oh)*0,setsar=1",
            Med.OsmuSmartReframingService.BuildFilter(1080, 1080, Med.OsmuFraming.CenterCrop, 3, -1), StringComparison.Ordinal);   // 초점 0~1 클램프
        var blur = Med.OsmuSmartReframingService.BuildFilter(1081, 1921, Med.OsmuFraming.BlurBackground);
        Assert.StartsWith("[0:v]split=2[bg][fg];[bg]scale=270:480:force_original_aspect_ratio=increase,crop=270:480,gblur=sigma=12,scale=1080:1920,", blur, StringComparison.Ordinal);
        Assert.Contains("[fg]scale=1080:1920:force_original_aspect_ratio=decrease,setsar=1[fgs];", blur, StringComparison.Ordinal);
        Assert.EndsWith("[bgb][fgs]overlay=(W-w)/2:(H-h)/2,setsar=1,format=yuv420p[v]", blur, StringComparison.Ordinal);

        var args = Med.OsmuSmartReframingService.BuildArgs(@"V:\final cut.mp4", @"V:\out\tiktok.mp4", Med.OsmuSmartReframingService.SpecOf(Med.OsmuTarget.TikTok), Med.OsmuFraming.BlurBackground);
        Assert.Equal(@"V:\final cut.mp4", args[args.IndexOf("-i") + 1]);                // 공백 경로 = 인자 1개
        Assert.Equal("[v]", args[args.IndexOf("-map") + 1]);
        Assert.Equal("0:a?", args[args.LastIndexOf("-map") + 1]);                       // 무음 원본도 안전
        Assert.Equal("libx264", args[args.IndexOf("-c:v") + 1]);
        Assert.Equal(@"V:\out\tiktok.mp4", args[^1]);
        Assert.Throws<ArgumentException>(() => Med.OsmuSmartReframingService.BuildArgs(" ", "o.mp4", feed, Med.OsmuFraming.CenterCrop));

        var noFf = new Med.OsmuSmartReframingService(() => null);
        Assert.False(noFf.IsAvailable);
        Assert.Contains("ffmpeg", (await noFf.ReframeAsync(@"V:\a.mp4", @"V:\b.mp4", feed, Med.OsmuFraming.CenterCrop)).Message, StringComparison.Ordinal);
        Assert.Contains("원본", (await new Med.OsmuSmartReframingService(() => @"V:\ffmpeg.exe").ReframeAsync(@"V:\none.mp4", @"V:\b.mp4", feed, Med.OsmuFraming.CenterCrop)).Message, StringComparison.Ordinal);

        // ③ 요청 구성: VoiceText 우선 · 없으면 프롬프트 · 1500자 상한 · CoverTitle 우선
        var proj = new SB.StoryboardProject { Title = "아기 토끼", CoverTitle = "잠자는 아기 토끼 동화" };
        proj.Scenes.Add(new SB.StoryboardScene { VoiceText = "옛날 옛적 숲속에", Prompt = "forest" });
        proj.Scenes.Add(new SB.StoryboardScene { Prompt = "a bunny sleeping under the moon" });
        proj.Scenes.Add(new SB.StoryboardScene { VoiceText = new string('가', 2000) });
        var req = SB.SocialMetadataAiGenerator.FromProject(proj, "수면 동화");
        Assert.Equal("잠자는 아기 토끼 동화", req.Topic);
        Assert.StartsWith("옛날 옛적 숲속에\na bunny sleeping under the moon\n가", req.Script, StringComparison.Ordinal);
        Assert.Equal(SB.SocialMetadataAiGenerator.MaxScriptChars, req.Script.Length);
        Assert.Equal("수면 동화", req.ThemeCategory);

        var all = new[] { SB.SocialChannel.YouTube, SB.SocialChannel.Instagram, SB.SocialChannel.TikTok, SB.SocialChannel.NaverClip };
        var prompt = SB.SocialMetadataAiGenerator.BuildPrompt(req with { Topic = "토끼 \"꿈\"" }, all);
        Assert.Contains("주제: \"토끼 '꿈'\"", prompt, StringComparison.Ordinal);            // 사용자 따옴표 무해화
        Assert.Contains("테마 카테고리: \"수면 동화\"", prompt, StringComparison.Ordinal);
        Assert.Contains("- youtube: 제목 100자 이하, 본문 5000자 이하, 해시태그 15개 이하", prompt, StringComparison.Ordinal);
        Assert.Contains("- naverclip: 제목 40자 이하", prompt, StringComparison.Ordinal);
        Assert.EndsWith("\"naverclip\":{\"title\":\"\",\"description\":\"\",\"hashtags\":[\"\"]}}", prompt, StringComparison.Ordinal);

        // ④ 스키마 검증 + 해시태그 정규화(# · 공백 · 기호 제거 · 대소문자 중복 제거 · 상한) + 제목 상한 절단
        var json = "```json\n{\"youtube\":{\"title\":\"" + new string('T', 130) + "\",\"description\":\"설명\",\"hashtags\":[\"#Shorts\",\"shorts\",\"#아기 동화\",\"!!\",5]},"
                 + "\"instagram\":{\"title\":\"\",\"description\":\"감성 캡션\",\"hashtags\":[\"#육아스타그램\"]},"
                 + "\"tiktok\":{\"title\":\"훅\",\"hashtags\":[\"fyp\"]},"
                 + "\"naverclip\":\"bad\"}\n```";
        var parsed = SB.SocialMetadataAiGenerator.Parse(json, all);
        Assert.Equal(2, parsed.Count);                                                   // tiktok(description 누락) · naverclip(비객체) 탈락
        Assert.Equal(100, parsed[SB.SocialChannel.YouTube].Title.Length);
        Assert.Equal(new[] { "Shorts", "아기동화" }, parsed[SB.SocialChannel.YouTube].Hashtags);
        Assert.Equal("Instagram Reels", parsed[SB.SocialChannel.Instagram].Platform);
        Assert.Empty(SB.SocialMetadataAiGenerator.Parse("not json", all));
        var capped = new System.Collections.Generic.List<string>();
        for (var i = 0; i < 20; i++) SB.SocialMetadataAiGenerator.AddTag(capped, "tag" + i.ToString(System.Globalization.CultureInfo.InvariantCulture), 8);
        Assert.Equal(8, capped.Count);

        // ⑤ 생성: AI 일부 성공 → 나머지 채널 로컬 템플릿 폴백 · AI 실패 → 전량 폴백 · 키 없음 → 호출 0
        var calls = 0;
        var gen = new SB.SocialMetadataAiGenerator((p, ct) => { calls++; return Task.FromResult(new PromptFlowStudio.Services.Wan.GeminiResult(true, json, "ok")); }, null);
        Assert.True(gen.AiEnabled);
        var res = await gen.GenerateAsync(req, all, proj);
        Assert.Equal(1, calls);
        Assert.Equal(2, res.AiChannels);
        Assert.Contains("폴백", res.Message, StringComparison.Ordinal);
        Assert.Equal(4, res.Posts.Count);
        var tt = res.Posts[SB.SocialChannel.TikTok];
        Assert.Equal("잠자는 아기 토끼 동화 ✨", tt.Title);
        Assert.Contains("fyp", tt.Hashtags);
        Assert.Contains("수면동화", tt.Hashtags);
        Assert.True(tt.Hashtags.Count <= 8);
        Assert.Equal("옛날 옛적 숲속에", res.Posts[SB.SocialChannel.NaverClip].Body);
        Assert.Equal(0, (await gen.GenerateAsync(req, all, proj, useAi: false)).AiChannels);
        Assert.Equal(1, calls);
        var failing = new SB.SocialMetadataAiGenerator((p, ct) => Task.FromResult(new PromptFlowStudio.Services.Wan.GeminiResult(false, null, "HTTP 500")), null);
        var fr = await failing.GenerateAsync(req, all);
        Assert.Equal(0, fr.AiChannels);
        Assert.Contains("HTTP 500", fr.Message, StringComparison.Ordinal);
        Assert.All(fr.Posts.Values, m => Assert.False(string.IsNullOrWhiteSpace(m.Title)));
        var throwing = new SB.SocialMetadataAiGenerator((p, ct) => throw new InvalidOperationException("boom"), null);
        Assert.Equal(4, (await throwing.GenerateAsync(req, all)).Posts.Count);           // 예외 격리
        Assert.False(new SB.SocialMetadataAiGenerator().AiEnabled);

        var txt = SB.SocialMetadataAiGenerator.ToText(new SB.PlatformMeta("TikTok", "🎵", "제목", "1줄\n2줄", new[] { "fyp", "아기" }), "🎵 TikTok · 9:16");
        Assert.Equal("🎵 TikTok · 9:16\r\n\r\n[제목]\r\n제목\r\n\r\n[본문]\r\n1줄\r\n2줄\r\n\r\n[해시태그]\r\n#fyp #아기\r\n", txt);

        // ⑥ 패키저 Graceful: ffmpeg 부재 · 원본 없음 · 대상 0 (예외 0 · 재진입 플래그 해제)
        var pk = new Med.OsmuExportPackager(noFf, gen);
        Assert.False(pk.IsAvailable);
        Assert.Contains("ffmpeg", (await pk.ExportAsync(proj, new Med.OsmuExportRequest(@"V:\m.mp4", new[] { Med.OsmuTarget.TikTok }))).Message, StringComparison.Ordinal);
        var pk2 = new Med.OsmuExportPackager(new Med.OsmuSmartReframingService(() => @"V:\ffmpeg.exe"), gen);
        Assert.Contains("원본 완성 영상", (await pk2.ExportAsync(proj, new Med.OsmuExportRequest(@"V:\m.mp4", new[] { Med.OsmuTarget.TikTok }))).Message, StringComparison.Ordinal);
        var master = Path.Combine(Path.GetTempPath(), "pf_osmu_" + Guid.NewGuid().ToString("N") + ".mp4");
        File.WriteAllBytes(master, new byte[] { 0 });
        try
        {
            var empty = await pk2.ExportAsync(proj, new Med.OsmuExportRequest(master, Array.Empty<Med.OsmuTarget>()));
            Assert.False(empty.Ok);
            Assert.Contains("1개 이상", empty.Message, StringComparison.Ordinal);
        }
        finally { File.Delete(master); }
        Assert.False(pk2.IsBusy);

        // ⑦ DI 양쪽 · 모달/Storyboard 결선
        var root = RepoRoot();
        foreach (var di in new[] { Path.Combine(root, "PromptFlowStudio", "MainForm.cs"), Path.Combine(root, "PromptFlowStudio.Mobile", "MauiProgram.cs") })
        {
            var src = File.ReadAllText(di);
            Assert.Contains("OsmuSmartReframingService", src, StringComparison.Ordinal);
            Assert.Contains("SocialMetadataAiGenerator", src, StringComparison.Ordinal);
            Assert.Contains("OsmuExportPackager", src, StringComparison.Ordinal);
        }
        var modal = File.ReadAllText(Path.Combine(root, "PromptFlowStudio", "Blazor", "Components", "Common", "OsmuExportModal.razor"));
        Assert.Contains("Packager.ExportAsync", modal, StringComparison.Ordinal);
        Assert.Contains("🗜️ ZIP", modal, StringComparison.Ordinal);
        var sbPage = File.ReadAllText(Path.Combine(root, "PromptFlowStudio", "Blazor", "Pages", "Storyboard.razor"));
        Assert.Contains("🌐 OSMU 내보내기", sbPage, StringComparison.Ordinal);
        Assert.Contains("OnReveal=", sbPage, StringComparison.Ordinal);
    }

    [Fact]
    public async Task BatchProduction_QueueAndGovernor_Check()
    {
        // ① 거버너 순수 계산: VRAM/RAM 여유 → 동시 한도 · 지수 백오프(Retry-After 우선 · 120초 상한)
        Assert.Equal(4, SB.QueueResourceGovernor.ComputeLimit(new SB.GovernorResources(8000, 16000, 2000, 12000), 4));
        Assert.Equal(2, SB.QueueResourceGovernor.ComputeLimit(new SB.GovernorResources(8000, 16000, 10000, 12000), 4));   // VRAM 여유 17%
        Assert.Equal(1, SB.QueueResourceGovernor.ComputeLimit(new SB.GovernorResources(8000, 16000, 11500, 12000), 4));   // VRAM 여유 4%
        Assert.Equal(1, SB.QueueResourceGovernor.ComputeLimit(new SB.GovernorResources(800, 16000, null, null), 4));      // RAM 여유 5%
        Assert.Equal(3, SB.QueueResourceGovernor.ComputeLimit(default, 3));                                              // 미샘플 = 여유
        Assert.Equal(new[] { 2, 4, 8, 16, 120 }, new[] { 1, 2, 3, 4, 12 }.Select(h => SB.QueueResourceGovernor.BackoffSeconds(h)));
        Assert.Equal(30, SB.QueueResourceGovernor.BackoffSeconds(1, 30));
        Assert.Equal(120, SB.QueueResourceGovernor.BackoffSeconds(1, 999));

        // ② 429 → 키 소진 표시 + 로테이션(지연 0) · 대체 키 없음 → 백오프 + 쿨다운 · 503 → 로테이션 없음 · 성공 → 히트 리셋
        var vault = new WanTokenVault(null);
        vault.UpdateProviderKeys(WanTokenVault.DashScope, new[] { "sk-a", "sk-b" });
        var delays = new System.Collections.Generic.List<TimeSpan>();
        using (var gov = new SB.QueueResourceGovernor(vault, _ => Task.FromResult(default(SB.GovernorResources)), (d, _) => { delays.Add(d); return Task.CompletedTask; }))
        {
            var d1 = gov.ReportThrottle(429, WanTokenVault.DashScope, "sk-a");
            Assert.True(d1.Rotated);
            Assert.Equal("sk-b", d1.RotatedKey);
            Assert.Equal(TimeSpan.Zero, d1.Delay);
            Assert.True(vault.IsExhausted(WanTokenVault.DashScope, "sk-a"));
            var d2 = gov.ReportThrottle(429, WanTokenVault.DashScope, "sk-b");
            Assert.False(d2.Rotated);
            Assert.Equal(TimeSpan.FromSeconds(4), d2.Delay);
            Assert.True(gov.CooldownRemaining > TimeSpan.FromSeconds(3));
            var d3 = gov.ReportThrottle(503, WanTokenVault.DashScope, "sk-b", retryAfterSeconds: 7);
            Assert.Equal((false, TimeSpan.FromSeconds(7), 3), (d3.Rotated, d3.Delay, d3.ConsecutiveHits));
            Assert.Equal((3, 1L), (gov.ConsecutiveHits, gov.Rotations));
            gov.ReportSuccess();
            Assert.Equal(0, gov.ConsecutiveHits);
        }

        // 쿼터 보호 실행: 429(로테이션 → 즉시) → 503(백오프) → 200
        var vault2 = new WanTokenVault(null);
        vault2.UpdateProviderKeys(WanTokenVault.SiliconFlow, new[] { "k1", "k2" });
        delays.Clear();
        using (var gov = new SB.QueueResourceGovernor(vault2, _ => Task.FromResult(default(SB.GovernorResources)), (d, _) => { delays.Add(d); return Task.CompletedTask; }))
        {
            var statuses = new System.Collections.Generic.Queue<int>(new[] { 429, 503, 200 });
            var usedKeys = new System.Collections.Generic.List<string?>();
            var (st, key) = await gov.RunWithQuotaAsync(WanTokenVault.SiliconFlow, "k1", (k, _) => { usedKeys.Add(k); return Task.FromResult(statuses.Dequeue()); });
            Assert.Equal((200, "k2"), (st, key));
            Assert.Equal(new[] { "k1", "k2", "k2" }, usedKeys);
            Assert.Contains(TimeSpan.FromSeconds(4), delays);                            // 503(2번째 히트) 백오프
            Assert.Equal(0, gov.ConsecutiveHits);
        }

        // ③ 동시성 리미터: FIFO 대기 · 한도 축소 시 신규 진입 차단 · 확대 시 즉시 승인 · 취소 대기자 건너뜀 · 샘플러 기반 자동 조절
        var res = new SB.GovernorResources(8000, 16000, 2000, 12000);
        using (var gov = new SB.QueueResourceGovernor(null, _ => Task.FromResult(res), null))
        {
            gov.SetMaxConcurrency(2);
            var l1 = await gov.AcquireAsync();
            var l2 = await gov.AcquireAsync();
            var w3 = gov.AcquireAsync();
            using var cancel4 = new CancellationTokenSource();
            var w4 = gov.AcquireAsync(cancel4.Token);
            var w5 = gov.AcquireAsync();
            Assert.False(w3.IsCompleted);
            Assert.Equal((2, 3), (gov.ActiveCount, gov.WaitingCount));
            gov.SetLimit(1);
            l1.Dispose();
            l1.Dispose();                                                                 // 중복 Dispose 안전
            Assert.False(w3.IsCompleted);                                                 // 활성 1 = 한도 1 → 대기
            cancel4.Cancel();
            await Assert.ThrowsAnyAsync<OperationCanceledException>(() => w4);
            l2.Dispose();
            var l3 = await w3.WaitAsync(TimeSpan.FromSeconds(5));
            Assert.False(w5.IsCompleted);
            gov.SetLimit(2);
            var l5 = await w5.WaitAsync(TimeSpan.FromSeconds(5));                         // 취소된 w4 건너뛰고 w5 승인
            Assert.Equal(2, gov.ActiveCount);
            l3.Dispose(); l5.Dispose();
            Assert.Equal(0, gov.ActiveCount);

            res = new SB.GovernorResources(8000, 16000, 11800, 12000);                    // VRAM 압박
            Assert.Equal(1, await gov.SampleOnceAsync());
            res = new SB.GovernorResources(8000, 16000, 1000, 12000);
            Assert.Equal(2, await gov.SampleOnceAsync());
            Assert.Equal(1000, gov.LastResources.VramUsedMb);
        }
        using (var bad = new SB.QueueResourceGovernor(null, _ => throw new InvalidOperationException("nvidia-smi"), null))
            Assert.Equal(SB.QueueResourceGovernor.DefaultMaxConcurrency, await bad.SampleOnceAsync());   // 샘플 예외 격리

        // ④ 단계 가중 진행률
        Assert.Equal(new[] { 0, 5, 35, 65, 77, 95, 100 }, new[]
        {
            SB.BatchProductionQueueService.OverallPercent(SB.BatchStage.Submitting, 0),
            SB.BatchProductionQueueService.OverallPercent(SB.BatchStage.Rendering, 0),
            SB.BatchProductionQueueService.OverallPercent(SB.BatchStage.Rendering, 0.5),
            SB.BatchProductionQueueService.OverallPercent(SB.BatchStage.PostProduction, 0),
            SB.BatchProductionQueueService.OverallPercent(SB.BatchStage.PostProduction, 0.5),
            SB.BatchProductionQueueService.OverallPercent(SB.BatchStage.OsmuPackaging, 0.5),
            SB.BatchProductionQueueService.OverallPercent(SB.BatchStage.Completed, 0),
        });

        // ⑤ 큐: 우선순위 디스패치 · 진행 브로드캐스트 · 일시정지(단계 경계) · 개별 취소 · 실패 → 1-Click 재시도 · 구독자 예외 격리
        var runner = new GatedRunner();
        using var qgov = new SB.QueueResourceGovernor(null, _ => Task.FromResult(default(SB.GovernorResources)), null);
        qgov.SetMaxConcurrency(1);
        using var q = new SB.BatchProductionQueueService(runner, qgov);
        var snaps = new System.Collections.Concurrent.ConcurrentQueue<SB.BatchJobSnapshot>();
        q.OnJobChanged += s => snaps.Enqueue(s);
        q.OnChange += () => throw new InvalidOperationException("구독자 오류");
        q.Pause();
        Assert.True(q.IsPaused);
        var a = q.Enqueue(new SB.StoryboardProject { Title = "A" })!;
        var b = q.Enqueue(new SB.StoryboardProject { Title = "B" }, SB.BatchPriority.Low)!;
        var c = q.Enqueue(new SB.StoryboardProject { Title = "C" }, SB.BatchPriority.High)!;
        var n = q.EnqueueThemes(new[] { "t1", "", "bad", "boom" }, k => k switch
        {
            "t1" => new SB.StoryboardProject { Title = "테마1" },
            "boom" => throw new InvalidOperationException("빌드 실패"),
            _ => null,
        }, SB.BatchPriority.Low);
        Assert.Equal(1, n);
        var t1 = q.Jobs.First(j => j.ThemeKey == "t1");
        Assert.Equal(new[] { "C", "A", "B", "테마1" }, q.Jobs.Select(j => j.Title));
        Assert.True(q.EstimateRemaining() >= TimeSpan.FromSeconds(SB.BatchProductionQueueService.DefaultJobSeconds * 4 - 1));
        Assert.True(q.EstimateFor(b.Id) > q.EstimateFor(c.Id));
        Assert.True(q.SetPriority(b.Id, SB.BatchPriority.Normal));
        Assert.True(q.MoveToFront(t1.Id));
        Assert.Equal("테마1", q.Jobs[0].Title);

        q.Start();
        await Task.Delay(100);
        Assert.Equal(0, q.ActiveCount);                                                   // 일시정지 중 디스패치 0
        q.Resume();
        await WaitUntil(() => runner.Started.Count == 1);
        Assert.Equal("테마1", runner.Started[0]);
        await WaitUntil(() => t1.Stage == SB.BatchStage.Rendering && t1.Percent == 35);
        Assert.Contains(snaps, s => s.Id == t1.Id && s.Stage == SB.BatchStage.Rendering && s.Percent == 35);
        Assert.True(q.SubscriberErrors > 0);                                              // 예외 구독자 격리 — 큐는 계속

        q.Pause();                                                                        // 진행 작업은 다음 체크포인트에서 대기
        runner.Release("테마1");
        await WaitUntil(() => t1.StatusText.Contains("일시정지", StringComparison.Ordinal));
        Assert.Equal(SB.BatchStage.Rendering, t1.Stage);
        q.Resume();
        await WaitUntil(() => t1.Stage == SB.BatchStage.Completed);
        Assert.Equal(100, t1.Percent);
        Assert.Equal(@"V:\out\테마1.mp4", t1.OutputPath);

        await WaitUntil(() => runner.Started.Count == 2);
        Assert.Equal("C", runner.Started[1]);                                             // High > Normal(A, B)
        Assert.True(q.Cancel(c.Id));
        await WaitUntil(() => c.Stage == SB.BatchStage.Canceled);
        Assert.True(c.CanRetry);

        await WaitUntil(() => runner.Started.Count == 3);
        Assert.Equal("A", runner.Started[2]);                                             // A(먼저 등록) > B(Normal 승격)
        runner.Fail.Add("A");
        runner.Release("A");
        await WaitUntil(() => a.Stage == SB.BatchStage.Failed);
        Assert.Equal("렌더 실패(테스트)", a.Error);
        Assert.True(q.Cancel(b.Id) || b.IsTerminal);
        await WaitUntil(() => b.IsTerminal);

        runner.Fail.Clear();
        Assert.True(q.Retry(a.Id));
        Assert.False(q.Retry(t1.Id));                                                     // 완료 작업은 재시도 불가
        await WaitUntil(() => runner.Started.Count(s => s == "A") == 2);
        runner.Release("A");
        await WaitUntil(() => a.Stage == SB.BatchStage.Completed);
        Assert.Equal(2, a.Attempts);
        Assert.True(q.AverageJobSeconds < SB.BatchProductionQueueService.DefaultJobSeconds);   // EMA 실측 반영
        Assert.True(q.ClearFinished() >= 2);
        Assert.DoesNotContain(q.Jobs, j => j.Id == a.Id);
        await q.StopAsync();
        Assert.False(q.IsRunning);

        // ⑥ DI · 허브 UI 결선
        var root = RepoRoot();
        var main = File.ReadAllText(Path.Combine(root, "PromptFlowStudio", "MainForm.cs"));
        Assert.Contains("BatchProductionQueueService", main, StringComparison.Ordinal);
        Assert.Contains("IBatchJobRunner, StoryboardBatchJobRunner", main, StringComparison.Ordinal);
        Assert.Contains("QueueResourceGovernor", File.ReadAllText(Path.Combine(root, "PromptFlowStudio.Mobile", "MauiProgram.cs")), StringComparison.Ordinal);
        var hub = File.ReadAllText(Path.Combine(root, "PromptFlowStudio", "Blazor", "Pages", "BatchProductionHub.razor"));
        Assert.Contains("Queue.EnqueueThemes", hub, StringComparison.Ordinal);
        Assert.Contains("Queue.Retry", hub, StringComparison.Ordinal);
        Assert.Contains("Queue.OnChange -= OnQueueChanged", hub, StringComparison.Ordinal);
        Assert.Contains("<BatchProductionHub />", File.ReadAllText(Path.Combine(root, "PromptFlowStudio", "Blazor", "Pages", "BatchStudio.razor")), StringComparison.Ordinal);

        static async Task WaitUntil(Func<bool> cond)
        {
            var sw = Stopwatch.StartNew();
            while (!cond())
            {
                if (sw.Elapsed > TimeSpan.FromSeconds(10)) throw new TimeoutException("조건 대기 시간 초과");
                await Task.Delay(10);
            }
        }
    }

    // 제출 → 렌더 50% 보고 후 Release 까지 대기 → 체크포인트 → 후처리 → 완료/실패.
    private sealed class GatedRunner : SB.IBatchJobRunner
    {
        private readonly System.Collections.Concurrent.ConcurrentDictionary<string, TaskCompletionSource<bool>> _gates = new();
        public readonly System.Collections.Concurrent.ConcurrentBag<string> Fail = new();
        private readonly object _lock = new();
        private readonly System.Collections.Generic.List<string> _started = new();
        public System.Collections.Generic.List<string> Started { get { lock (_lock) return new System.Collections.Generic.List<string>(_started); } }

        public void Release(string title) => Gate(title).TrySetResult(true);

        private TaskCompletionSource<bool> Gate(string title) => _gates.GetOrAdd(title, _ => new TaskCompletionSource<bool>(TaskCreationOptions.RunContinuationsAsynchronously));

        public async Task<SB.BatchJobOutcome> RunAsync(SB.BatchJob job, SB.IBatchJobReporter reporter, SB.QueueResourceGovernor governor, CancellationToken ct)
        {
            var gate = Gate(job.Title);
            lock (_lock) _started.Add(job.Title);
            reporter.Report(SB.BatchStage.Submitting, 1, "제출");
            reporter.Report(SB.BatchStage.Rendering, 0.5, "렌더 50%");
            await gate.Task.WaitAsync(ct);
            _gates.TryRemove(job.Title, out _);
            await reporter.CheckpointAsync(ct);
            if (Fail.Contains(job.Title)) return new SB.BatchJobOutcome(false, null, "렌더 실패(테스트)");
            reporter.Report(SB.BatchStage.PostProduction, 1, "후처리");
            return new SB.BatchJobOutcome(true, @"V:\out\" + job.Title + ".mp4", "ok");
        }
    }

    [Fact]
    public async Task VideoQa_And_SocialPublisher_Bridge_Check()
    {
        // ① ffmpeg stderr 파서: blackdetect · freezedetect(열린 구간은 영상 끝으로 닫음) · astats(피크 최대 · Overall RMS) · Duration
        var p = new Med.FfmpegQaLogParser();
        foreach (var line in new[]
        {
            "  Duration: 00:00:12.50, start: 0.000000, bitrate: 2400 kb/s",
            "[blackdetect @ 000001] black_start:0 black_end:0.3 black_duration:0.3",
            "[blackdetect @ 000001] black_start:5.2 black_end:6.8 black_duration:1.6",
            "[freezedetect @ 000002] lavfi.freezedetect.freeze_start: 2.0",
            "[freezedetect @ 000002] lavfi.freezedetect.freeze_duration: 1.5",
            "[freezedetect @ 000002] lavfi.freezedetect.freeze_end: 3.5",
            "[freezedetect @ 000002] lavfi.freezedetect.freeze_start: 7.5",
            "[Parsed_astats_0 @ 000003] Channel: 1",
            "[Parsed_astats_0 @ 000003] Peak level dB: -3.000000",
            "[Parsed_astats_0 @ 000003] RMS level dB: -18.000000",
            "[Parsed_astats_0 @ 000003] Channel: 2",
            "[Parsed_astats_0 @ 000003] Peak level dB: -0.050000",
            "[Parsed_astats_0 @ 000003] Overall",
            "[Parsed_astats_0 @ 000003] Peak level dB: -0.050000",
            "[Parsed_astats_0 @ 000003] RMS level dB: -20.000000",
        }) p.Feed(line.AsSpan());
        p.Complete();
        Assert.Equal(12.5, p.DurationSeconds, 3);
        Assert.Equal(2, p.Black.Count);
        Assert.Equal(2, p.Freeze.Count);
        Assert.Equal((7.5, 12.5), p.Freeze[1]);
        Assert.Equal(-0.05, p.PeakDbfs, 3);
        Assert.Equal(-20.0, p.RmsDbfs, 3);

        // ② 판정: 블랙 1.6초·정지 5초·클리핑 → 거부 / 블랙 0.3초·정지 1.5초 → 경고 · 결함은 시작 시각 순 + 타임스탬프 보존
        var rep = Med.AutomatedVideoQaInspector.Evaluate(p);
        Assert.Equal(Med.QaVerdict.Reject, rep.Verdict);
        Assert.False(rep.CanPublish);
        Assert.True(rep.Scanned);
        Assert.Contains(rep.Defects, d => d.Kind == Med.QaDefectKind.BlackFrame && d.Severity == Med.QaVerdict.Reject && d.StartSeconds == 5.2 && d.EndSeconds == 6.8);
        Assert.Contains(rep.Defects, d => d.Kind == Med.QaDefectKind.BlackFrame && d.Severity == Med.QaVerdict.Warn);
        Assert.Contains(rep.Defects, d => d.Kind == Med.QaDefectKind.FrozenFrame && d.Severity == Med.QaVerdict.Reject && d.StartSeconds == 7.5);
        Assert.Contains(rep.Defects, d => d.Kind == Med.QaDefectKind.FrozenFrame && d.Severity == Med.QaVerdict.Warn);
        Assert.Contains(rep.Defects, d => d.Kind == Med.QaDefectKind.AudioClipping);
        for (var i = 1; i < rep.Defects.Count; i++) Assert.True(rep.Defects[i - 1].StartSeconds <= rep.Defects[i].StartSeconds);

        var clean = new Med.FfmpegQaLogParser();
        clean.Feed("  Duration: 00:00:08.00, start: 0".AsSpan());
        clean.Feed("[Parsed_astats_0 @ 1] Overall".AsSpan());
        clean.Feed("[Parsed_astats_0 @ 1] Peak level dB: -3.2".AsSpan());
        clean.Feed("[Parsed_astats_0 @ 1] RMS level dB: -19.0".AsSpan());
        clean.Complete();
        Assert.Equal(Med.QaVerdict.Pass, Med.AutomatedVideoQaInspector.Evaluate(clean).Verdict);
        var hot = new Med.FfmpegQaLogParser();
        hot.Feed("[Parsed_astats_0 @ 1] Peak level dB: -0.5".AsSpan());
        hot.Feed("[Parsed_astats_0 @ 1] RMS level dB: -inf".AsSpan());
        var hotRep = Med.AutomatedVideoQaInspector.Evaluate(hot);
        Assert.Equal(Med.QaVerdict.Warn, hotRep.Verdict);
        Assert.Contains(hotRep.Defects, d => d.Kind == Med.QaDefectKind.AudioHeadroom);
        Assert.Contains(hotRep.Defects, d => d.Kind == Med.QaDefectKind.AudioSilence);

        // ③ 자막 가림: 대상 세이프존으로 배치한 레이아웃은 0 · 세이프존 미적용 레이아웃을 틱톡에 올리면 가림
        Assert.Equal(3, Med.AutomatedVideoQaInspector.LineCount("하나\\N둘\n셋"));
        var tiktokLayout = Med.AutoSubtitleGenerator.ComputeLayout(Med.SafePlatform.TikTok, 1080, 1920);
        Assert.Equal(0, Med.AutomatedVideoQaInspector.OcclusionRatio(tiktokLayout, 2, Med.SafePlatform.TikTok), 3);
        var plainLayout = Med.AutoSubtitleGenerator.ComputeLayout(Med.SafePlatform.None, 1080, 1920);
        var occ = Med.AutomatedVideoQaInspector.OcclusionRatio(plainLayout, 2, Med.SafePlatform.TikTok);
        Assert.True(occ >= Med.AutomatedVideoQaInspector.OcclusionRejectRatio, "occ=" + occ);
        var badProbe = new Med.QaSubtitleProbe(plainLayout, new[] { new Med.CaptionCue(1, 1.0, 2.5, "안녕\\N아가") }, Med.SafePlatform.TikTok);

        // ③-b UI 결선(v16.17.0 QA-PUB-3): ASS 사이드카 → 레이아웃/큐 복원 · 결함 라벨 · 타임스탬프 포맷
        var assText = string.Join("\r\n",
            "[Script Info]", "PlayResX: 1080", "PlayResY: 1920", "",
            "[V4+ Styles]",
            "Style: Narration,Malgun Gothic,74,&H00FFFFFF,&H00FFFFFF,&H00000000,&H64000000,-1,0,0,0,100,100,0,0,1,5.3,2,2,54,54,250,1",
            "[Events]",
            "Dialogue: 0,0:00:01.20,0:00:03.40,Narration,,0,0,0,,첫 번째, 쉼표 포함\\N둘째 줄",
            "Dialogue: 0,0:00:04.00,0:00:05.50,Narration,,0,0,0,,셋");
        var parsed = Med.AutomatedVideoQaInspector.ParseAss(assText, Med.SafePlatform.TikTok);
        Assert.NotNull(parsed);
        Assert.Equal(1080, parsed!.Layout.Width);
        Assert.Equal(250, parsed.Layout.MarginV);
        Assert.Equal(74, parsed.Layout.FontSize);
        Assert.Equal(2, parsed.Cues.Count);
        Assert.Equal(1.2, parsed.Cues[0].Start, 3);
        Assert.Equal("첫 번째, 쉼표 포함\\N둘째 줄", parsed.Cues[0].Text);
        Assert.Null(Med.AutomatedVideoQaInspector.ParseAss("[Events]", Med.SafePlatform.TikTok));
        Assert.Null(Med.AutomatedVideoQaInspector.TryLoadSidecarProbe(null, Med.SafePlatform.TikTok));
        Assert.Equal("1:05.3", Med.AutomatedVideoQaInspector.Clock(65.3));
        Assert.Equal("💬 자막 가림", Med.AutomatedVideoQaInspector.LabelOf(Med.QaDefectKind.SubtitleOcclusion));

        // ④ ffmpeg 부재 → 미검사 경고(게시 허용) · 자막 가림은 ffmpeg 없이도 판정 → 거부
        var dir = Path.Combine(Path.GetTempPath(), "pfs-qa-pub-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(dir);
        try
        {
            var video = Path.Combine(dir, "final.mp4");
            File.WriteAllBytes(video, new byte[300_000]);
            var qa = new Med.AutomatedVideoQaInspector(() => null);
            var un = await qa.InspectAsync(video);
            Assert.False(un.Scanned);
            Assert.Equal(Med.QaVerdict.Warn, un.Verdict);
            Assert.True(un.CanPublish);
            var subRep = await qa.InspectAsync(video, badProbe);
            Assert.Equal(Med.QaVerdict.Reject, subRep.Verdict);
            Assert.Equal(1.0, subRep.Defects[0].StartSeconds);
            Assert.Same(subRep, qa.LastReport);
            Assert.Equal(video, subRep.VideoPath);
            File.WriteAllText(Path.ChangeExtension(video, ".ass"), assText);
            Assert.NotNull(Med.AutomatedVideoQaInspector.TryLoadSidecarProbe(video, Med.SafePlatform.YouTubeShorts));

            // ⑤ 순수 빌더: TikTok 청크 계획 · 캡션 정규화 · #Shorts · init 페이로드(기본 SELF_ONLY) · IG 컨테이너 폼 · 토큰 스키마 검증
            Assert.Equal(1, DirectSocialPublisherBridge.PlanTikTokChunks(10_000_000).TotalChunks);
            var big = DirectSocialPublisherBridge.PlanTikTokChunks(DirectSocialPublisherBridge.TikTokSingleChunkMax + 1);
            Assert.Equal(6, big.TotalChunks);
            Assert.Equal(big.VideoSize - 1, big.RangeOf(5).End);
            Assert.True(big.RangeOf(5).End - big.RangeOf(5).Start + 1 < 2 * DirectSocialPublisherBridge.TikTokChunkSize);
            Assert.Equal("아기 첫걸음 #baby #첫걸음", DirectSocialPublisherBridge.BuildCaption("아기 첫걸음", new[] { "#baby", "BABY", "첫걸음", "두 단어", "" }, 2200));
            Assert.Equal("아기 #Shorts", DirectSocialPublisherBridge.ShortsTitle("아기"));
            Assert.Equal("이미 #shorts", DirectSocialPublisherBridge.ShortsTitle("이미 #shorts"));
            Assert.True(DirectSocialPublisherBridge.ShortsTitle(new string('가', 120)).Length <= 100);
            var ttReq = new SocialPublishRequest(SocialPublishTarget.TikTok, video, "첫걸음", "설명", new[] { "baby" });
            using (var j = System.Text.Json.JsonDocument.Parse(DirectSocialPublisherBridge.BuildTikTokInitPayload(ttReq, DirectSocialPublisherBridge.PlanTikTokChunks(300_000))))
            {
                Assert.Equal("SELF_ONLY", j.RootElement.GetProperty("post_info").GetProperty("privacy_level").GetString());
                Assert.Equal("FILE_UPLOAD", j.RootElement.GetProperty("source_info").GetProperty("source").GetString());
                Assert.Equal(300_000, j.RootElement.GetProperty("source_info").GetProperty("video_size").GetInt64());
                Assert.Equal(1, j.RootElement.GetProperty("source_info").GetProperty("total_chunk_count").GetInt32());
            }
            var igForm = DirectSocialPublisherBridge.BuildInstagramContainerForm(ttReq with { Target = SocialPublishTarget.InstagramReels });
            Assert.Equal("REELS", igForm["media_type"]);
            Assert.Equal("resumable", igForm["upload_type"]);
            var now = DateTimeOffset.UtcNow;
            Assert.True(DirectSocialPublisherBridge.TryParseToken("{\"data\":{\"access_token\":\"at\",\"expires_in\":86400,\"refresh_token\":\"rt2\"}}", now, out var tk));
            Assert.Equal("rt2", tk.RefreshToken);
            Assert.True(tk.IsFresh(now));
            Assert.False(DirectSocialPublisherBridge.TryParseToken("{\"access_token\":5}", now, out _));
            Assert.False(DirectSocialPublisherBridge.TryParseToken("not json", now, out _));
            Assert.True(DirectSocialPublisherBridge.IsRetryable(429));
            Assert.False(DirectSocialPublisherBridge.IsRetryable(400));

            // ⑥ 브릿지 E2E(오프라인 핸들러): 자격 없음 → 실패 · TikTok refresh→init→청크 PUT→status · IG 429 백오프→rupload→폴링→publish
            var noCfg = new Microsoft.Extensions.Configuration.ConfigurationBuilder().Build();
            var yt = new FakeYouTube();
            using (var empty = new DirectSocialPublisherBridge(noCfg, yt, qa, new SocialRouteHandler()))
            {
                Assert.False(empty.IsEnabled(SocialPublishTarget.TikTok));
                var r0 = await empty.PublishAsync(ttReq);
                Assert.False(r0.Ok);
                Assert.Equal(SocialPublishState.Failed, r0.State);
            }

            var cfg = Microsoft.Extensions.Configuration.MemoryConfigurationBuilderExtensions.AddInMemoryCollection(new Microsoft.Extensions.Configuration.ConfigurationBuilder(), new System.Collections.Generic.Dictionary<string, string?>
            {
                ["TikTok:ClientKey"] = "ck", ["TikTok:ClientSecret"] = "cs", ["TikTok:RefreshToken"] = "rt",
                ["Instagram:UserId"] = "1789", ["Instagram:AccessToken"] = "igtok",
            }).Build();
            var handler = new SocialRouteHandler { ContainerThrottleFirst = 1 };
            using var bridge = new DirectSocialPublisherBridge(cfg, yt, qa, handler) { PollInterval = TimeSpan.Zero, MaxPolls = 5 };
            var changes = 0;
            bridge.OnChange += () => Interlocked.Increment(ref changes);

            var tt = await bridge.PublishAsync(ttReq);
            Assert.True(tt.Ok, tt.Message);
            Assert.Equal(SocialPublishState.Published, tt.State);
            Assert.Equal("pub-1", tt.PostId);
            Assert.NotNull(tt.Qa);
            Assert.Equal("bytes 0-299999/300000", handler.LastContentRange);
            Assert.Equal(300_000, handler.UploadedBytes);
            Assert.Equal(1, handler.TokenCalls);
            await bridge.PublishAsync(ttReq);
            Assert.Equal(1, handler.TokenCalls);   // 캐시된 토큰 재사용(갱신 1회)

            var igReq = new SocialPublishRequest(SocialPublishTarget.InstagramReels, video, "릴스", "본문", new[] { "baby" });
            var igPrivate = await bridge.PublishAsync(igReq);
            Assert.False(igPrivate.Ok);   // 공개 동의 없으면 게시 금지
            var ig = await bridge.PublishAsync(igReq with { PublicVisibility = true });
            Assert.True(ig.Ok, ig.Message);
            Assert.Equal("media-77", ig.PostId);
            Assert.Equal(2, handler.ContainerCalls);   // 429 1회 → 재시도
            Assert.Equal("OAuth igtok", handler.RuploadAuth);

            var ys = await bridge.PublishAsync(new SocialPublishRequest(SocialPublishTarget.YouTubeShorts, video, "아기", "d", new[] { "baby" }));
            Assert.True(ys.Ok);
            Assert.Equal("아기 #Shorts", yt.LastTitle);
            Assert.Equal("private", yt.LastPrivacy);

            // ⑦ QA 게이트: 자막 가림 거부 → 업로드 차단 → 1-Click 재시도 대상
            var before = handler.InitCalls;
            var blocked = await bridge.PublishAsync(ttReq with { Subtitles = badProbe });
            Assert.Equal(SocialPublishState.QaBlocked, blocked.State);
            Assert.Equal(before, handler.InitCalls);
            var blockedJob = bridge.Jobs[0];
            Assert.Equal(SocialPublishState.QaBlocked, blockedJob.State);
            var retried = bridge.Retry(blockedJob.Id);
            Assert.NotNull(retried);
            Assert.Equal(SocialPublishState.QaBlocked, (await retried!).State);
            Assert.Null(bridge.Retry(Guid.NewGuid()));

            // ⑧ 로컬 예약(TikTok): 등록 → 도래 전 0건 → 도래 후 1건 발행(중복 발행 0)
            var at = DateTime.UtcNow.AddHours(2);
            var sch = await bridge.PublishAsync(ttReq with { ScheduleAtUtc = at });
            Assert.Equal(SocialPublishState.Scheduled, sch.State);
            Assert.Equal(0, bridge.DispatchDue(DateTime.UtcNow));
            Assert.Equal(1, bridge.DispatchDue(at.AddSeconds(1)));
            Assert.Equal(0, bridge.DispatchDue(at.AddSeconds(2)));
            var sw = Stopwatch.StartNew();
            while (bridge.Jobs.First(j => j.Request.ScheduleAtUtc == at).State != SocialPublishState.Published && sw.ElapsedMilliseconds < 5000) await Task.Delay(10);
            Assert.Equal(SocialPublishState.Published, bridge.Jobs.First(j => j.Request.ScheduleAtUtc == at).State);
            Assert.True(Volatile.Read(ref changes) > 0);
        }
        finally { try { Directory.Delete(dir, true); } catch { } }
    }

    [Fact]
    public async Task ProductionCostTracker_And_HardwareTelemetry_Check()
    {
        // ① 요금표 순수 계산: DashScope turbo/plus 초당 · SiliconFlow 건당 · Custom 초당 · Gemini 토큰 · ElevenLabs 문자
        var rates = new Tel.CostRateCard();
        Assert.Equal(0.18, Tel.ProductionCostTrackerService.WanUsd(rates, Tel.CostService.DashScope, "wan2.1-t2v-turbo", 5), 6);
        Assert.Equal(0.50, Tel.ProductionCostTrackerService.WanUsd(rates, Tel.CostService.DashScope, "wan2.1-t2v-plus", 5), 6);
        Assert.Equal(0.29, Tel.ProductionCostTrackerService.WanUsd(rates, Tel.CostService.SiliconFlow, null, 5), 6);
        Assert.Equal(0.50, Tel.ProductionCostTrackerService.WanUsd(rates, Tel.CostService.WanCustom, null, 5), 6);
        Assert.Equal(0.30 + 2.50, Tel.ProductionCostTrackerService.GeminiUsd(rates, 1_000_000, 1_000_000), 6);
        Assert.Equal(0.30, Tel.ProductionCostTrackerService.ElevenLabsUsd(rates, 1000), 6);
        Assert.Equal(Tel.CostService.SiliconFlow, Tel.ProductionCostTrackerService.ServiceOfProvider(WanTokenVault.SiliconFlow));
        Assert.Equal(Tel.CostService.WanCustom, Tel.ProductionCostTrackerService.ServiceOfProvider(WanTokenVault.Custom));
        Assert.Equal(Tel.CostService.DashScope, Tel.ProductionCostTrackerService.ServiceOfProvider(WanTokenVault.DashScope));

        // Gemini usageMetadata 파싱(출력 = candidates + thoughts)
        Assert.True(GeminiClient.TryReadUsage("{\"usageMetadata\":{\"promptTokenCount\":1200,\"candidatesTokenCount\":300,\"thoughtsTokenCount\":50}}", out var gin, out var gout));
        Assert.Equal(1200, gin);
        Assert.Equal(350, gout);
        Assert.False(GeminiClient.TryReadUsage("{\"candidates\":[]}", out _, out _));

        var dir = Path.Combine(Path.GetTempPath(), "pfs-cost-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(dir);
        try
        {
            var ledger = Path.Combine(dir, "Analytics", "cost_ledger.json");
            var now = new DateTimeOffset(2026, 10, 6, 10, 0, 0, TimeSpan.FromHours(9));
            var clock = now;
            using (var cost = new Tel.ProductionCostTrackerService(ledger, () => clock))
            {
                var exceeded = new System.Collections.Generic.List<string>();
                var recovered = 0;
                cost.OnBudgetExceeded += m => exceeded.Add(m);
                cost.OnBudgetRecovered += () => recovered++;

                // ② 기록 + 생산 스코프 귀속(AsyncLocal → Task.Run 하위 호출까지)
                using (var scope = cost.BeginScope("첫걸음", "baby_firststep", "TikTok"))
                {
                    await Task.Run(() => cost.RecordWanSubmit(WanTokenVault.DashScope, "wan2.1-t2v-turbo"));
                    cost.RecordGemini("gemini-2.5-flash", 10_000, 2_000);
                    scope.Succeeded = true;
                }
                using (cost.BeginScope("목욕", "baby_bath", "YouTubeShorts"))
                    cost.RecordWanSubmit(WanTokenVault.SiliconFlow, null);
                cost.RecordElevenLabs(500);
                Assert.Null(cost.CurrentScope);
                Assert.Equal(2, cost.TotalClips);
                Assert.Equal(2, cost.ProductionCount);
                var expected = 0.18 + (10_000 * 0.30 + 2_000 * 2.50) / 1_000_000.0 + 0.29 + 0.15;
                Assert.Equal(expected, cost.TotalUsd, 5);
                Assert.Equal(expected, cost.TodayUsd, 5);
                Assert.Equal(expected, cost.MonthUsd, 5);
                Assert.Equal(1, cost.ServiceCalls(Tel.CostService.Gemini));
                var prods = cost.Productions;
                Assert.Equal("첫걸음", prods[0].Title);
                Assert.True(prods[0].Ok);
                Assert.Equal(1, prods[0].Clips);
                Assert.Equal(0.18 + 0.008, prods[0].Usd, 5);
                Assert.False(prods[1].Ok);
                var byPlatform = cost.Buckets(false);
                Assert.Equal(2, byPlatform.Count);
                Assert.Equal("YouTubeShorts", byPlatform[0].Key);   // USD 내림차순(0.29 > 0.188)
                Assert.Equal(1.0, cost.Buckets(true).Find(b => b.Key == "baby_firststep").SuccessRate, 3);
                Assert.Equal("첫걸음", cost.RecentEntries(10)[^1].Tag);

                // ③ 예산 한도: 일간 $0.5 → 초과 상태 · 이벤트 1회 · 신규 영상 거부 + 차단 카운트
                Assert.Null(cost.CheckVideoAllowed());
                cost.UpdateBudget(0.5, 0, true);
                Assert.Equal(Tel.BudgetState.Exceeded, cost.State);
                Assert.True(cost.IsVideoGenerationBlocked);
                Assert.Single(exceeded);
                Assert.NotNull(cost.CheckVideoAllowed());
                Assert.Equal(1, cost.BlockedRequests);
                cost.UpdateBudget(0.7, 0, true);                      // 0.628 / 0.7 = 90% → 경고
                Assert.Equal(Tel.BudgetState.Warning, cost.State);
                Assert.Equal(1, recovered);
                cost.UpdateBudget(0.5, 0, true);
                Assert.Equal(2, exceeded.Count);
                // 날짜 경계 통과 → 일간 한도 자동 해제
                clock = now.AddDays(1);
                Assert.Null(cost.CheckVideoAllowed());
                Assert.Equal(2, recovered);
                Assert.Equal(0, cost.TodayUsd, 6);
                Assert.Equal(expected, cost.MonthUsd, 5);
                var series = cost.DailySeries(3);
                Assert.Equal(expected, series[1], 5);
                Assert.Equal(0, series[2], 6);
                clock = now;

                // ④ Wan 제출 게이트: 한도 초과 시 HTTP 호출 0 · 해제 후 제출 성공 + 과금 기록
                var vault = new WanTokenVault(null);
                vault.UpdateProviderKeys(WanTokenVault.DashScope, new[] { "ds-1" });
                var mock = new WanEngineTests.RouteHandler();
                var wan = new WanApiService(new WanEngineTests.FakeWanConfig(), new QuotaRateGuardService(), vault, mock, null, cost);
                var blocked = await wan.SubmitAsync(new WanVideoRequest { Prompt = "아기 미소" });
                Assert.False(blocked.Ok);
                Assert.Contains("예산", blocked.Message, StringComparison.Ordinal);
                Assert.Empty(mock.SubmitKeys);
                cost.UpdateBudget(0, 0, true);
                var ok = await wan.SubmitAsync(new WanVideoRequest { Prompt = "아기 미소" });
                Assert.True(ok.Ok, ok.Message);
                Assert.Equal(3, cost.TotalClips);

                // ⑤ 배치 큐: 한도 도달 → 자동 일시정지 · 한도 해제 → 자동 재개 · 사용자 일시정지는 유지
                var runner = new GatedRunner();
                using (var gov = new SB.QueueResourceGovernor(null, _ => Task.FromResult(default(SB.GovernorResources)), null))
                using (var queue = new SB.BatchProductionQueueService(runner, gov, cost))
                {
                    cost.UpdateBudget(0.01, 0, true);
                    Assert.True(queue.IsBudgetPaused);
                    Assert.True(queue.IsPaused);
                    cost.UpdateBudget(0, 0, true);
                    Assert.False(queue.IsBudgetPaused);
                    Assert.False(queue.IsPaused);
                    queue.Pause();
                    cost.UpdateBudget(0.01, 0, true);
                    Assert.False(queue.IsBudgetPaused);
                    cost.UpdateBudget(0, 0, true);
                    Assert.True(queue.IsPaused);
                    queue.Resume();
                }

                // ⑥ 리포트: CSV(수식 주입 무해화 · 인용) · JSON(스키마)
                using (cost.BeginScope("=HYPERLINK(\"x\")", "t,1", "TikTok")) cost.RecordElevenLabs(10);
                var csv = Path.Combine(dir, "r.csv");
                Assert.True(cost.ExportCsv(csv) >= 8);
                var csvText = File.ReadAllText(csv);
                Assert.Contains("\"'=HYPERLINK(\"\"x\"\")\"", csvText, StringComparison.Ordinal);
                Assert.Contains("\"t,1\"", csvText, StringComparison.Ordinal);
                var json = Path.Combine(dir, "r.json");
                cost.ExportJson(json);
                using (var doc = System.Text.Json.JsonDocument.Parse(File.ReadAllText(json)))
                {
                    Assert.Equal(3, doc.RootElement.GetProperty("Summary").GetProperty("Productions").GetInt32());
                    Assert.Equal(5, doc.RootElement.GetProperty("Services").GetArrayLength());
                    Assert.True(doc.RootElement.GetProperty("Entries").GetArrayLength() >= 6);
                }
                cost.UpdateBudget(25, 300, true);
                cost.UpdateRates(new Tel.CostRateCard { SiliconFlowPerVideo = 0.5 });
            }

            // ⑦ 영구 저장: 재시작 후 원장/예산/요금표 복원 · 손상 원장은 빈 원장(예외 0)
            Assert.True(File.Exists(ledger));
            using (var reloaded = new Tel.ProductionCostTrackerService(ledger, () => now))
            {
                Assert.Equal(3, reloaded.TotalClips);
                Assert.Equal(3, reloaded.ProductionCount);
                Assert.Equal(25, reloaded.Budget.DailyCapUsd);
                Assert.Equal(300, reloaded.Budget.MonthlyCapUsd);
                Assert.Equal(0.5, reloaded.Rates.SiliconFlowPerVideo);
                Assert.True(reloaded.TotalUsd > 0.6);
                Assert.Equal(reloaded.TotalUsd, reloaded.MonthUsd, 5);
            }
            File.WriteAllText(ledger, "{ broken");
            using (var corrupt = new Tel.ProductionCostTrackerService(ledger, () => now))
                Assert.Equal(0, corrupt.TotalUsd);
        }
        finally { try { Directory.Delete(dir, true); } catch { } }

        // ⑧ 하드웨어 텔레메트리: EWMA · 링버퍼 · OOM 징후(급증 → Elevated · 2회 연속 <8% → Critical) → 거버너 상한 · 회복 히스테리시스
        using var gov2 = new SB.QueueResourceGovernor(null, _ => Task.FromResult(default(SB.GovernorResources)), null);
        gov2.SetMaxConcurrency(4);
        Assert.Equal(4, gov2.CurrentLimit);
        var samples = new System.Collections.Generic.Queue<Tel.HardwareSample>();
        using var hw = new Tel.SystemHardwareTelemetryMonitor(_ => Task.FromResult(samples.Dequeue()), gov2);
        var signals = new System.Collections.Generic.List<Tel.PressureSignal>();
        hw.OnPressure += s => signals.Add(s);
        static Tel.HardwareSample S(long ramUsed, double? vramUsed, double cpu = 20) => new(DateTimeOffset.Now, cpu, ramUsed, 16000, vramUsed, vramUsed is null ? null : 12000, null, 500);

        samples.Enqueue(S(8000, 6000, 10));                 // 여유 50%
        Assert.True(await hw.SampleOnceAsync());
        Assert.Equal(Tel.MemoryPressure.Normal, hw.Pressure);
        Assert.Equal(0.5, hw.RamEwma, 3);
        Assert.Equal(0.5, hw.VramEwma!.Value, 3);
        hw.Ingest(S(8000, 6000, 30));
        Assert.Equal(16, hw.CpuEwma, 3);                    // 10*0.7 + 30*0.3
        hw.Ingest(S(8000, 9600));                           // VRAM 80% → 여유 20%(급증 30%p) → Elevated
        Assert.Equal(Tel.MemoryPressure.Elevated, hw.Pressure);
        Assert.Single(signals);
        Assert.Equal(3, signals[0].SuggestedConcurrency);
        Assert.Equal(3, gov2.PressureCap);
        Assert.Equal(3, gov2.CurrentLimit);
        hw.Ingest(S(8000, 11400));                          // 여유 5% (1회)
        Assert.Equal(Tel.MemoryPressure.Elevated, hw.Pressure);
        hw.Ingest(S(8000, 11500));                          // 2회 연속 → Critical
        Assert.Equal(Tel.MemoryPressure.Critical, hw.Pressure);
        Assert.Equal(2, signals.Count);
        Assert.Equal(1, signals[1].SuggestedConcurrency);
        Assert.Equal(1, gov2.CurrentLimit);
        Assert.Equal(1, await gov2.SampleOnceAsync());      // 자원 샘플이 여유여도 압박 상한 유지
        hw.Ingest(S(8000, 9800));                           // 여유 18% — 회복선(22%) 미만 → Critical 유지
        Assert.Equal(Tel.MemoryPressure.Critical, hw.Pressure);
        hw.Ingest(S(4000, 4000));                           // 여유 66% → Normal
        Assert.Equal(Tel.MemoryPressure.Normal, hw.Pressure);
        Assert.Equal(2, hw.PressureSignals);
        gov2.SignalPressure(0, TimeSpan.Zero);
        Assert.Equal(0, gov2.PressureCap);
        Assert.Equal(4, await gov2.SampleOnceAsync());

        var buf = new Tel.HardwareSample[Tel.SystemHardwareTelemetryMonitor.HistorySize];
        Assert.Equal(7, hw.CopyHistory(buf));
        Assert.Equal(4000, buf[6].RamUsedMb);
        for (var i = 0; i < Tel.SystemHardwareTelemetryMonitor.HistorySize + 5; i++) hw.Ingest(S(1000 + i, null));
        Assert.Equal(Tel.SystemHardwareTelemetryMonitor.HistorySize, hw.CopyHistory(buf));
        Assert.Equal(1000 + Tel.SystemHardwareTelemetryMonitor.HistorySize + 4, buf[^1].RamUsedMb);   // 최신이 끝

        // 컷 렌더 EWMA · ETA(동시 한도 반영) · 비정상 값 무시
        hw.RecordCutRender(60);
        hw.RecordCutRender(30);
        hw.RecordCutRender(double.NaN);
        hw.RecordCutRender(-1);
        Assert.Equal(2, hw.CutsMeasured);
        Assert.Equal(51, hw.AverageCutSeconds, 3);
        Assert.Equal(30, hw.MinCutSeconds, 3);
        Assert.Equal(60, hw.MaxCutSeconds, 3);
        Assert.Equal(TimeSpan.FromSeconds(Math.Round(51.0 * 8 / 4)), hw.EstimateRemaining(8));

        // 샘플러 예외 격리 · Start/Stop 참조 카운트
        using var bad = new Tel.SystemHardwareTelemetryMonitor(_ => throw new InvalidOperationException("nvidia-smi"));
        Assert.False(await bad.SampleOnceAsync());
        bad.Start(TimeSpan.FromSeconds(30));
        bad.Start(TimeSpan.FromSeconds(30));
        Assert.True(bad.IsRunning);
        bad.Stop();
        Assert.True(bad.IsRunning);
        bad.Stop();
        Assert.False(bad.IsRunning);
        bad.Stop();
        Assert.False(bad.IsRunning);
    }

