    private sealed class SocialRouteHandler : System.Net.Http.HttpMessageHandler
    {
        public int TokenCalls, InitCalls, ContainerCalls, ContainerThrottleFirst;
        public long UploadedBytes;
        public string? LastContentRange, RuploadAuth;

        protected override async Task<System.Net.Http.HttpResponseMessage> SendAsync(System.Net.Http.HttpRequestMessage req, CancellationToken ct)
        {
            var url = req.RequestUri!.ToString();
            var code = System.Net.HttpStatusCode.OK;
            var body = "{}";
            if (url.EndsWith("/v2/oauth/token/", StringComparison.Ordinal)) { Interlocked.Increment(ref TokenCalls); body = "{\"access_token\":\"tt-at\",\"expires_in\":86400,\"refresh_token\":\"rt-2\"}"; }
            else if (url.EndsWith("/post/publish/video/init/", StringComparison.Ordinal)) { Interlocked.Increment(ref InitCalls); body = "{\"data\":{\"publish_id\":\"pub-1\",\"upload_url\":\"https://open-upload.tiktokapis.com/video/?id=1\"},\"error\":{\"code\":\"ok\"}}"; }
            else if (url.StartsWith("https://open-upload.tiktokapis.com/", StringComparison.Ordinal))
            {
                LastContentRange = req.Content!.Headers.ContentRange?.ToString();
                UploadedBytes = (await req.Content.ReadAsByteArrayAsync(ct)).LongLength;
                code = System.Net.HttpStatusCode.Created;
            }
            else if (url.EndsWith("/post/publish/status/fetch/", StringComparison.Ordinal)) body = "{\"data\":{\"status\":\"PUBLISH_COMPLETE\"},\"error\":{\"code\":\"ok\"}}";
            else if (url.EndsWith("/1789/media", StringComparison.Ordinal))
            {
                if (Interlocked.Increment(ref ContainerCalls) <= ContainerThrottleFirst) code = System.Net.HttpStatusCode.TooManyRequests;
                else body = "{\"id\":\"cont-9\",\"uri\":\"https://rupload.facebook.com/ig-api-upload/v21.0/cont-9\"}";
            }
            else if (url.StartsWith(DirectSocialPublisherBridge.RuploadApi, StringComparison.Ordinal))
            {
                RuploadAuth = req.Headers.Authorization?.ToString();
                await req.Content!.ReadAsByteArrayAsync(ct);
                body = "{\"success\":true}";
            }
            else if (url.Contains("cont-9?fields=status_code", StringComparison.Ordinal)) body = "{\"status_code\":\"FINISHED\",\"id\":\"cont-9\"}";
            else if (url.EndsWith("/1789/media_publish", StringComparison.Ordinal)) body = "{\"id\":\"media-77\"}";
            else code = System.Net.HttpStatusCode.NotFound;
            return new System.Net.Http.HttpResponseMessage(code) { Content = new System.Net.Http.StringContent(body) };
        }
    }

    private sealed class FakeEdge(string dir) : Med.IVoiceoverService
    {
        public int Calls;
        public string? LastRate, LastPitch;
        public string? Result;
        public string TtsDir { get; } = dir;
        public Task<string?> SynthesizeAsync(string text, string voice = "ko-KR-SunHiNeural", string? outPath = null, CancellationToken ct = default)
            => SynthesizeProsodyAsync(text, voice, "+0%", "+0Hz", outPath, ct);
        public Task<string?> SynthesizeProsodyAsync(string text, string voice, string rate, string pitch, string? outPath = null, CancellationToken ct = default)
        {
            Calls++;
            LastRate = rate; LastPitch = pitch;
            return Task.FromResult(Result);
        }
    }

    private sealed class FlakyImageHandler(byte[] body, int failFirst, System.Net.HttpStatusCode status = System.Net.HttpStatusCode.OK) : System.Net.Http.HttpMessageHandler
    {
        public int Calls;
        protected override Task<System.Net.Http.HttpResponseMessage> SendAsync(System.Net.Http.HttpRequestMessage request, CancellationToken ct)
        {
            var n = Interlocked.Increment(ref Calls);
            var code = n <= failFirst ? System.Net.HttpStatusCode.ServiceUnavailable : status;
            var resp = new System.Net.Http.HttpResponseMessage(code);
            if (code == System.Net.HttpStatusCode.OK) resp.Content = new System.Net.Http.ByteArrayContent(body);
            return Task.FromResult(resp);
        }
    }

    [Fact]
    public async Task CommercialBrandStudio_Compositing_Check()
    {
        // ① 누끼: 흰 배경 + 빨간 제품(내부 흰 구멍 = 흰 제품 부위) → 테두리 연결 배경만 제거, 내부 흰색 보존
        const int W = 32, H = 32;
        var px = new byte[W * H * 4];
        for (var y = 0; y < H; y++)
            for (var x = 0; x < W; x++)
            {
                var o = (y * W + x) * 4;
                var inProduct = x >= 8 && x < 24 && y >= 8 && y < 24;
                var hole = x >= 14 && x < 18 && y >= 14 && y < 18;
                byte r = 250, g = 250, b = 250;
                if (inProduct && !hole) { r = 220; g = 30; b = 40; }
                px[o] = r; px[o + 1] = g; px[o + 2] = b; px[o + 3] = 255;
            }
        Assert.False(Med.CommercialProductSegmenterService.HasMeaningfulAlpha(px, W, H));
        Assert.True(Med.CommercialProductSegmenterService.EstimateBorderColor(px, W, H, out var br, out var bg, out var bb));
        Assert.Equal((250, 250, 250), (br, bg, bb));
        var mask = Med.CommercialProductSegmenterService.ExtractAlphaMask(px, W, H);
        Assert.Equal(Med.ProductMaskMode.BorderFloodKey, mask.Mode);
        Assert.Equal(0, px[3]);                                   // 모서리 배경 제거
        Assert.Equal(255, px[((16 * W) + 10) * 4 + 3]);           // 제품 몸체 유지
        Assert.Equal(255, px[((15 * W) + 15) * 4 + 3]);           // 내부 흰 구멍 보존(플러드 미도달)
        Assert.InRange(mask.Coverage, 0.24, 0.26);                // 16×16 / 32×32

        // ② 원본 알파 유지 경로
        var alpha = (byte[])px.Clone();
        Assert.True(Med.CommercialProductSegmenterService.HasMeaningfulAlpha(alpha, W, H));
        Assert.Equal(Med.ProductMaskMode.ExistingAlpha, Med.CommercialProductSegmenterService.ExtractAlphaMask(alpha, W, H).Mode);
        Assert.Throws<ArgumentException>(() => Med.CommercialProductSegmenterService.ExtractAlphaMask(new byte[8], W, H));

        // ③ 조명 매칭: 달빛(청색·어두움) 장면 → 제품 평균이 목표 쪽으로 이동 · 보수적 클램프
        var prod = Med.CommercialProductSegmenterService.ComputeStats(px);
        Assert.True(prod.Samples > 0 && prod.R > prod.B);
        var moon = Med.CommercialProductSegmenterService.LightingProfileOf(SB.ThemeLighting.MoonlightBlue);
        var m = Med.CommercialProductSegmenterService.MatchLighting(prod, moon, 1.0);
        Assert.True(m.GainB > m.GainR);
        Assert.InRange(m.GainR, 0.85, 1.15);
        Assert.InRange(m.Contrast, 0.85, 1.15);
        Assert.Equal(Math.Sign(moon.Luma - prod.Luma), Math.Sign(m.Shift));
        Assert.InRange(m.Shift, -40, 40);
        Med.CommercialProductSegmenterService.ApplyLighting(px, m);
        var after = Med.CommercialProductSegmenterService.ComputeStats(px);
        Assert.True(after.B / after.Luma > prod.B / prod.Luma);
        Assert.Equal(0, px[3]);                                   // 투명 픽셀 미접촉
        Assert.Equal(Med.LightingMatch.Identity, Med.CommercialProductSegmenterService.MatchLighting(default, moon));

        // ④ ffmpeg stderr 크기 파싱 · 박스 맞춤
        Assert.True(Med.CommercialProductSegmenterService.TryParseVideoSize(
            "Input #0, png_pipe\n  Stream #0:0: Video: png, rgba(pc, gbr/unknown/unknown), 2400x1600, 25 fps\n", out var sw, out var sh));
        Assert.Equal((2400, 1600), (sw, sh));
        Assert.False(Med.CommercialProductSegmenterService.TryParseVideoSize("no video here", out _, out _));
        Assert.Equal((1024, 682), Med.CommercialProductSegmenterService.FitBox(2400, 1600));
        Assert.Equal((640, 480), Med.CommercialProductSegmenterService.FitBox(640, 480));

        // ⑤ 세이프존 · 레이아웃 · 앵커 추천
        var safe = Med.SponsorVideoCompositorService.SafeZoneOf(1080, 1920);
        Assert.Equal(new Med.SafeRect(64, 230, 952, 1268), safe);
        var sq = Med.SponsorVideoCompositorService.SafeZoneOf(1080, 1080);
        Assert.Equal(54, sq.X);
        var lay = Med.SponsorVideoCompositorService.LayoutOf(1080, 1920, 0.38);
        Assert.True(lay.CtaY + lay.CtaH <= safe.Bottom && lay.CtaY >= safe.Y);
        Assert.Equal(0, lay.ProductW % 2);
        Assert.Equal(Med.ProductAnchor.BottomRight, Med.SponsorVideoCompositorService.SuggestAnchor(null));
        Assert.Equal(Med.ProductAnchor.Right, Med.SponsorVideoCompositorService.SuggestAnchor(
            new SB.ThemeCinematics(SB.CameraMotion.SmoothPan, SB.ThemeLighting.GoldenHour, "35mm", Array.Empty<string>(), 3)));
        Assert.Equal(9.0, Med.SponsorVideoCompositorService.CtaStartOf(15, 0.4));
        Assert.Equal("FF4F8B", Med.SponsorVideoCompositorService.Hex("zz"));
        Assert.Equal("00AAFF", Med.SponsorVideoCompositorService.Hex("#00aaff"));

        // ⑥ 필터 그래프/인자(순수): 누끼 페이드·섀도·플로팅 · 로고 · PPL · CTA(끝 40%) · 오디오 교체 인덱스
        var req = new Med.SponsorSceneRequest(@"C:\v\scene 1.mp4", @"C:\v\cut.png", @"C:\v\out.mp4", 1080, 1920, Med.ProductAnchor.BottomRight, 0.38, 15,
            AudioPath: @"C:\v\jingle.m4a");
        var ov = new Med.BrandOverlaySpec(@"C:\v\logo.png");
        var fc = Med.SponsorVideoCompositorService.BuildFilter(req, ov, true, "C\\:/t/ppl.txt", "C\\:/t/cta.txt", "C\\:/f/malgun.ttf");
        Assert.Contains("fade=t=in:st=0.3:d=0.6:alpha=1", fc);
        Assert.Contains("gblur=sigma=14[sh]", fc);
        Assert.Contains("sin(2*PI*t/3)", fc);
        Assert.Contains("[2:v]format=rgba", fc);
        Assert.Contains("textfile='C\\:/t/ppl.txt'", fc);
        Assert.Contains("drawbox=x=64:y=", fc);
        Assert.Contains("enable='gte(t,9)'", fc);
        Assert.Contains("shortest=1", fc);
        Assert.EndsWith(",format=yuv420p[v]", fc);
        var args = Med.SponsorVideoCompositorService.BuildArgs(req, ov, null, null, null);
        Assert.Equal(@"C:\v\scene 1.mp4", args[args.IndexOf("-i") + 1]);
        Assert.Equal("3:a", args[args.LastIndexOf("-map") + 1]);
        Assert.Equal(@"C:\v\out.mp4", args[^1]);
        var bare = Med.SponsorVideoCompositorService.BuildFilter(req with { DropShadow = false, FloatMotion = false }, new Med.BrandOverlaySpec(), false, null, null, null);
        Assert.DoesNotContain("drawtext", bare);
        Assert.DoesNotContain("[2:v]", bare);
        Assert.Contains("null,format=yuv420p[v]", bare);
        Assert.Throws<ArgumentException>(() => Med.SponsorVideoCompositorService.BuildArgs(req with { ProductCutoutPath = "" }, ov, null, null, null));

        // ⑦ CM 카피: Gemini 파싱 · 타임라인 정규화(합계 = 15초) · BPM 클램프 · 표시광고 점검 · 폴백
        var brief = new SB.AdProductBrief("뽀송 아기 물티슈", "포근베베", new[] { "도톰한 엠보싱", "저자극 성분", "캡형 리드" }, "신생아 부모", "목욕 시간");
        var prompt = SB.CommercialAdScriptAiGenerator.BuildPrompt(brief, SB.AdDuration.Sec15, SB.AdTone.Playful);
        Assert.Contains("15초", prompt);
        Assert.Contains("\"lines\"", prompt);
        const string json = "```json\n{\"headline\":\"최고의 물티슈\",\"cta\":\"지금 구매\",\"narrationTone\":\"발랄\",\"bgm\":{\"mood\":\"경쾌\",\"bpm\":300,\"instruments\":\"우쿨렐레\",\"jingle\":\"포근베베~\"},"
            + "\"lines\":[{\"sec\":2,\"narration\":\"쉿, 아기가 자요\",\"onScreen\":\"쉿!\"},{\"sec\":8,\"narration\":\"도톰한 엠보싱\",\"onScreen\":\"도톰\"},{\"sec\":10,\"narration\":\"지금 만나요\",\"onScreen\":\"지금\"}]}\n```";
        var calls = 0;
        var ai = new SB.CommercialAdScriptAiGenerator((p, ct) => { calls++; return Task.FromResult(new GeminiResult(true, json, "ok")); });
        var s1 = await ai.GenerateAsync(brief, SB.AdDuration.Sec15, SB.AdTone.Playful);
        Assert.Equal(1, calls);
        Assert.True(s1.AiUsed);
        Assert.Equal("Gemini AI", s1.Message);
        Assert.Equal(160, s1.Bgm.Bpm);
        Assert.Equal(3, s1.Lines.Count);
        Assert.Equal(0, s1.Lines[0].Start);
        Assert.Equal(15.0, Math.Round(s1.Lines.Sum(l => l.Seconds), 1));
        Assert.Contains(s1.ComplianceNotes, n => n.Contains("'최고'"));
        Assert.Null(SB.CommercialAdScriptAiGenerator.Parse("{\"headline\":\"x\"}", SB.AdDuration.Sec15));
        Assert.Null(SB.CommercialAdScriptAiGenerator.Parse("not json", SB.AdDuration.Sec30));

        var failing = new SB.CommercialAdScriptAiGenerator((p, ct) => Task.FromResult(new GeminiResult(false, null, "HTTP 500")));
        var s2 = await failing.GenerateAsync(brief, SB.AdDuration.Sec30, SB.AdTone.Warm);
        Assert.False(s2.AiUsed);
        Assert.Contains("HTTP 500", s2.Message);
        Assert.Equal(30.0, Math.Round(s2.Lines.Sum(l => l.Seconds), 1));
        Assert.Contains("포근베베", s2.Bgm.Jingle);
        Assert.True(s2.Lines.Count <= SB.CommercialAdScriptAiGenerator.MaxLinesOf(SB.AdDuration.Sec30));
        Assert.Contains("[0.0s +", SB.CommercialAdScriptAiGenerator.ToText(s2, brief));
        var offline = await new SB.CommercialAdScriptAiGenerator((GeminiClient?)null).GenerateAsync(brief);
        Assert.Equal("로컬 템플릿", offline.Message);

        // ⑧ 캠페인 매니저: ffmpeg 부재/입력 누락 → 예외 없이 실패 결과 · 이력 상한 · OnChange
        var noFf = new Med.CommercialBrandCampaignService(new Med.CommercialProductSegmenterService(() => null),
            new Med.SponsorVideoCompositorService(() => null), failing);
        var changes = 0;
        noFf.OnChange += () => changes++;
        var creq = new Med.BrandCampaignRequest("런칭 캠페인", "missing.png", new[] { "missing.mp4" }, brief, new Med.BrandOverlaySpec());
        var cr = await noFf.RunAsync(creq);
        Assert.False(cr.Ok);
        Assert.Contains("ffmpeg", cr.Message);
        Assert.False(noFf.IsBusy);
        Assert.True(changes >= 2);
        Assert.Single(noFf.History);
        Assert.Equal("런칭_캠페인", Med.CommercialBrandCampaignService.Safe("런칭 캠페인"));

        var withFf = new Med.CommercialBrandCampaignService(new Med.CommercialProductSegmenterService(() => "ffmpeg.exe"),
            new Med.SponsorVideoCompositorService(() => "ffmpeg.exe"), failing);
        Assert.Contains("제품 사진", (await withFf.RunAsync(creq)).Message);
        var segMissing = await new Med.CommercialProductSegmenterService(() => "ffmpeg.exe").SegmentAsync("missing.png", "out.png");
        Assert.False(segMissing.Ok);
        var compMissing = await new Med.SponsorVideoCompositorService(() => "ffmpeg.exe").CompositeAsync(req, ov);
        Assert.False(compMissing.Ok);
        for (var i = 0; i < Med.CommercialBrandCampaignService.HistoryCap + 5; i++) await noFf.RunAsync(creq);
        Assert.Equal(Med.CommercialBrandCampaignService.HistoryCap, noFf.History.Count);
        noFf.ClearHistory();
        Assert.Empty(noFf.History);
    }

    [Fact]
    public async Task LipSync_And_EmotionPuppeteer_Check()
    {
        // ① 감정 키워드 탐지 · 아기 피사체 · 프리셋
        Assert.Equal(SB.FacialEmotion.Giggle, SB.FacialEmotionPuppeteerEngine.Detect("아기가 까르르 웃어요"));
        Assert.Equal(SB.FacialEmotion.Pout, SB.FacialEmotionPuppeteerEngine.Detect("toddler pouting at dinner"));
        Assert.Equal(SB.FacialEmotion.Surprised, SB.FacialEmotionPuppeteerEngine.Detect("깜짝 놀란 표정"));
        Assert.Equal(SB.FacialEmotion.Curious, SB.FacialEmotionPuppeteerEngine.Detect("궁금한 듯 바라봐요"));
        Assert.Equal(SB.FacialEmotion.HappySmile, SB.FacialEmotionPuppeteerEngine.Detect("방긋 미소"));
        Assert.Equal(SB.FacialEmotion.Neutral, SB.FacialEmotionPuppeteerEngine.Detect("a quiet park"));
        Assert.True(SB.FacialEmotionPuppeteerEngine.IsBabySubject("cute baby in bath"));
        Assert.False(SB.FacialEmotionPuppeteerEngine.IsBabySubject("adult chef cooking"));
        Assert.Equal(6, SB.FacialEmotionPuppeteerEngine.Presets.Count);
        Assert.Equal("🥺 삐침/칭얼거림", SB.FacialEmotionPuppeteerEngine.LabelOf(SB.FacialEmotion.Pout));

        // ② 표정 주입: 상충 단어 제거 · 표정/정체성 구문 · 얼굴 보호 네거티브 · 멱등 · Neutral 무변경
        var inj = SB.FacialEmotionPuppeteerEngine.Apply("a crying baby sitting on a sofa", "blurry", SB.FacialEmotion.HappySmile, 1.0);
        Assert.True(inj.Changed && inj.BabyProfile);
        Assert.DoesNotContain("crying", inj.Prompt);
        Assert.Contains("happy smile", inj.Prompt);
        Assert.Contains(SB.FacialEmotionPuppeteerEngine.IdentityGuard, inj.Prompt);
        Assert.StartsWith("blurry, ", inj.Negative);
        Assert.Contains("distorted face", inj.Negative);
        Assert.Equal(SB.FacialEmotionPuppeteerEngine.BabyIntensityCap, inj.Intensity);
        Assert.Contains("clear bright happy smile", inj.Prompt);
        Assert.StartsWith("a baby sitting", inj.Prompt);
        var again = SB.FacialEmotionPuppeteerEngine.Apply(inj.Prompt, inj.Negative, SB.FacialEmotion.HappySmile, 1.0);
        Assert.Equal(inj.Prompt, again.Prompt);
        Assert.Equal(inj.Negative, again.Negative);
        Assert.False(again.Changed);
        var neutral = SB.FacialEmotionPuppeteerEngine.Apply(" a dog ", null, SB.FacialEmotion.Neutral);
        Assert.Equal("a dog", neutral.Prompt);
        Assert.Null(neutral.Negative);
        Assert.DoesNotContain("crying", SB.FacialEmotionPuppeteerEngine.Apply("crying crybaby", null, SB.FacialEmotion.Giggle).Prompt.Replace("crybaby", ""));
        Assert.Contains("crybaby", SB.FacialEmotionPuppeteerEngine.Apply("crying crybaby", null, SB.FacialEmotion.Giggle).Prompt);   // 단어 경계

        // ③ 안면 보호: 랜드마크 상한(아기 0.55 · 성인 0.8) · 강도 문구 · 입모양 배율
        var babyG = SB.FacialEmotionPuppeteerEngine.GuideOf(SB.FacialEmotion.Giggle, 1.0, baby: true);
        var adultG = SB.FacialEmotionPuppeteerEngine.GuideOf(SB.FacialEmotion.Giggle, 1.0, baby: false);
        Assert.True(babyG.MaxMagnitude <= SB.FacialEmotionPuppeteerEngine.BabyLandmarkCap + 1e-9);
        Assert.True(adultG.MaxMagnitude <= SB.FacialEmotionPuppeteerEngine.AdultLandmarkCap + 1e-9);
        Assert.True(babyG.MouthCornerLift > 0 && babyG.MouthCornerLift < adultG.MouthCornerLift);
        Assert.Equal("subtle", SB.FacialEmotionPuppeteerEngine.IntensityWord(0.2));
        Assert.Equal("gentle", SB.FacialEmotionPuppeteerEngine.IntensityWord(0.6));
        Assert.Equal("clear", SB.FacialEmotionPuppeteerEngine.IntensityWord(0.9));
        Assert.True(SB.FacialEmotionPuppeteerEngine.MouthScaleOf(SB.FacialEmotion.Giggle) > 1.0);
        Assert.True(SB.FacialEmotionPuppeteerEngine.MouthScaleOf(SB.FacialEmotion.Pout) < 1.0);
        Assert.Equal(1.0, SB.FacialEmotionPuppeteerEngine.MouthScaleOf(SB.FacialEmotion.Neutral));
        Assert.Equal(SB.FacialEmotionPuppeteerEngine.DefaultIntensity, SB.FacialEmotionPuppeteerEngine.SafeIntensity(double.NaN, false));
        Assert.Contains("입꼬리 +", SB.FacialEmotionPuppeteerEngine.Describe(babyG));

        // ④ 컷 연속성 완화 · 자동 할당
        var ints = new[] { 0.2, 1.0, 0.1 };
        Assert.Equal(2, SB.FacialEmotionPuppeteerEngine.SmoothIntensities(ints));
        Assert.Equal(0.55, ints[1], 6);
        Assert.Equal(0.2, ints[2], 6);
        var scenes = new[]
        {
            new SB.StoryboardScene { VoiceText = "우와 깜짝이야!" },
            new SB.StoryboardScene { Prompt = "baby giggling with bubbles" },
            new SB.StoryboardScene { Prompt = "empty room" },
            new SB.StoryboardScene { Prompt = "baby smiling", Emotion = SB.FacialEmotion.Pout },
        };
        Assert.Equal(2, SB.FacialEmotionPuppeteerEngine.AutoAssign(scenes));
        Assert.Equal((SB.FacialEmotion.Surprised, SB.FacialEmotion.Giggle, SB.FacialEmotion.Neutral, SB.FacialEmotion.Pout),
            (scenes[0].Emotion, scenes[1].Emotion, scenes[2].Emotion, scenes[3].Emotion));
        var json = System.Text.Json.JsonSerializer.Serialize(scenes[3]);
        Assert.Contains("\"Pout\"", json);

        // ⑤ 대사 → 입모양: 한글 중성/종성(양순음) · 라틴 · 구두점 Rest
        var vis = new Med.Viseme[32];
        var vn = Med.AiAudioDrivenLipSyncService.TranscriptToVisemes("아밤 우리", vis);
        Assert.Equal(new[] { Med.Viseme.A, Med.Viseme.A, Med.Viseme.Closed, Med.Viseme.Rest, Med.Viseme.U, Med.Viseme.I }, vis[..vn]);
        Assert.Equal(3, Med.AiAudioDrivenLipSyncService.TranscriptToVisemes("mao", vis));

        // ⑥ 합성 WAV(16kHz mono): 0.3초 무음 → 0.6초 톤 → 0.3초 무음 → 0.4초 톤 · 엔벨로프 · 유성 · 타임라인
        const int sr = 16000;
        var wav = MakeWav(sr, (0.3, 0.0), (0.6, 0.5), (0.3, 0.0), (0.4, 0.4));
        Assert.True(Med.AiAudioDrivenLipSyncService.TryParseWav(wav, out var off, out var len, out var ch, out var rate, out var bits));
        Assert.Equal((44, 1, sr, 16), (off, ch, rate, bits));
        Assert.Equal(sr * 16 / 10 * 2, len);
        var (act, cues) = Med.AiAudioDrivenLipSyncService.Analyze(wav, "아빠 엄마 안녕", 1.2);
        Assert.Equal(1.6, act.DurationSeconds, 2);
        Assert.InRange(act.OnsetSeconds, 0.26, 0.34);
        Assert.InRange(act.VoicedRatio, 0.55, 0.70);
        Assert.Equal(80, act.Frames);
        Assert.Equal(Med.Viseme.Rest, cues[0].Shape);
        Assert.Contains(cues, c => c.Shape == Med.Viseme.A && c.Openness > 0.5);
        Assert.Contains(cues, c => c.Shape == Med.Viseme.Closed);
        for (var i = 1; i < cues.Count; i++) Assert.Equal(cues[i - 1].End, cues[i].Start, 3);
        Assert.Equal(1.6, cues[^1].End, 2);
        var (_, energyCues) = Med.AiAudioDrivenLipSyncService.Analyze(wav, null);
        Assert.Contains(energyCues, c => c.Shape != Med.Viseme.Rest);
        Assert.False(Med.AiAudioDrivenLipSyncService.TryParseWav(new byte[20], out _, out _, out _, out _, out _));
        Assert.Equal(default, Med.AiAudioDrivenLipSyncService.Analyze(new byte[10], "x").Activity);
        Assert.StartsWith("[{\"s\":0,", Med.AiAudioDrivenLipSyncService.VisemesJson(cues));

        // ⑦ FFmpeg 프레임 보정 인자: 발화 정렬 atrim · ≤20% setpts 리타임 · 초과 tpad 복제
        var a1 = Med.AiAudioDrivenLipSyncService.BuildRealignArgs(@"C:\v\in clip.mp4", @"C:\v\n.wav", @"C:\v\out.mp4", 5.0, 5.6, 0.5);
        var fc1 = a1[a1.IndexOf("-filter_complex") + 1];
        Assert.Contains("atrim=start=0.4", fc1);
        Assert.Contains("setpts=1.04*PTS", fc1);
        Assert.Contains("fps=30", fc1);
        Assert.Equal("5.2", a1[a1.IndexOf("-t") + 1]);
        Assert.Equal(@"C:\v\in clip.mp4", a1[a1.IndexOf("-i") + 1]);
        var a2 = Med.AiAudioDrivenLipSyncService.BuildRealignArgs("v.mp4", "a.wav", "o.mp4", 4.0, 8.0, 0);
        var fc2 = a2[a2.IndexOf("-filter_complex") + 1];
        Assert.Contains("tpad=stop_mode=clone:stop_duration=4", fc2);
        Assert.DoesNotContain("setpts=2", fc2);
        Assert.Equal(83.5, Med.AiAudioDrivenLipSyncService.ParseDuration("  Duration: 00:01:23.50, start: 0.000000"));
        Assert.Equal(0, Med.AiAudioDrivenLipSyncService.ParseDuration("garbage"));

        // ⑧ 원격 응답 스키마 검증
        Assert.Equal("job_42", Med.AiAudioDrivenLipSyncService.ParseSubmit("{\"job_id\":\"job_42\"}"));
        Assert.Null(Med.AiAudioDrivenLipSyncService.ParseSubmit("{\"id\":\"../etc\"}"));
        Assert.Null(Med.AiAudioDrivenLipSyncService.ParseSubmit("[1]"));
        Assert.Equal(("succeeded", "https://cdn.example.com/o.mp4", (string?)null),
            Med.AiAudioDrivenLipSyncService.ParseStatus("{\"status\":\"completed\",\"output_url\":\"https://cdn.example.com/o.mp4\"}"));
        Assert.Equal("invalid", Med.AiAudioDrivenLipSyncService.ParseStatus("{\"status\":\"done\",\"output_url\":\"http://evil.example.com/o.mp4\"}").Status);
        Assert.Equal("running", Med.AiAudioDrivenLipSyncService.ParseStatus("{\"status\":\"processing\"}").Status);
        Assert.Equal(("failed", (string?)null, "oom"), Med.AiAudioDrivenLipSyncService.ParseStatus("{\"status\":\"error\",\"error\":\"oom\"}"));
        Assert.False(new Med.LipSyncApiConfig("http://remote.example.com", null, Med.LipSyncBackend.Wav2LipApi).IsConfigured);
        Assert.True(new Med.LipSyncApiConfig("http://127.0.0.1:7860", null, Med.LipSyncBackend.MuseTalkApi).IsConfigured);

        // ⑨ 오케스트레이션: 원격(500×3 백오프 실패) → 로컬 엔진 폴백 · 원격 성공 경로 · 입력 누락
        var dir = Path.Combine(Path.GetTempPath(), "pfs_lip_test_" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(dir);
        try
        {
            var video = Path.Combine(dir, "clip.mp4");
            var audio = Path.Combine(dir, "narr.wav");
            await File.WriteAllBytesAsync(video, new byte[] { 0, 0, 0, 24, 0x66, 0x74, 0x79, 0x70 });
            await File.WriteAllBytesAsync(audio, wav);
            var cfg = new Med.LipSyncApiConfig("https://lipsync.example.com", "test-key", Med.LipSyncBackend.MuseTalkApi);
            var failing = new LipApiHandler(submitStatus: System.Net.HttpStatusCode.InternalServerError);
            var local = new FakeLocalLip(ok: true);
            using (var svc = new Med.AiAudioDrivenLipSyncService(() => null, local, () => cfg, failing, TimeSpan.Zero))
            {
                Assert.True(svc.AiAvailable && svc.RemoteConfigured);
                Assert.Equal(Med.LipSyncBackend.MuseTalkApi, svc.PreferredBackend);
                var r = await svc.SyncAsync(new Med.AudioLipSyncRequest(video, audio, Path.Combine(dir, "o1.mp4"), "아빠 엄마", SB.FacialEmotion.Giggle));
                Assert.True(r.Ok);
                Assert.Equal(Med.LipSyncBackend.LatentSyncLocal, r.Backend);
                Assert.Contains("MuseTalk API 실패(HTTP 500)", r.Message);
                Assert.Equal(Med.AiAudioDrivenLipSyncService.MaxSubmitAttempts, failing.Submits);
                Assert.Equal("Bearer test-key", failing.LastAuth);
                Assert.True(r.Visemes.Count > 0);
                Assert.Equal(1, local.Calls);
            }

            var good = new LipApiHandler(System.Net.HttpStatusCode.OK, pollsBeforeDone: 2);
            using (var svc = new Med.AiAudioDrivenLipSyncService(() => null, null, () => cfg, good, TimeSpan.Zero))
            {
                var outPath = Path.Combine(dir, "o2.mp4");
                var r = await svc.SyncAsync(new Med.AudioLipSyncRequest(video, audio, outPath, "안녕", SB.FacialEmotion.Pout, 0.8));
                Assert.True(r.Ok, r.Message);
                Assert.Equal(Med.LipSyncBackend.MuseTalkApi, r.Backend);
                Assert.Equal(3, good.Polls);
                Assert.Equal(4, new FileInfo(outPath).Length);
                Assert.Contains("name=mouth_scale", good.LastForm);
                Assert.Contains("musetalk", good.LastForm);
            }

            using (var none = new Med.AiAudioDrivenLipSyncService(() => null, new FakeLocalLip(ok: false), () => new Med.LipSyncApiConfig(null, null, Med.LipSyncBackend.Wav2LipApi), null, TimeSpan.Zero))
            {
                Assert.False(none.IsAvailable);
                Assert.Equal(Med.LipSyncBackend.None, none.PreferredBackend);
                var r = await none.SyncAsync(new Med.AudioLipSyncRequest(video, audio, Path.Combine(dir, "o3.mp4")));
                Assert.False(r.Ok);
                Assert.Contains("ffmpeg", r.Message);
                Assert.False((await none.SyncAsync(new Med.AudioLipSyncRequest("missing.mp4", audio, "o.mp4"))).Ok);
                Assert.False((await none.RealignAsync(video, audio, "o.mp4")).Ok);
            }
        }
        finally { try { Directory.Delete(dir, true); } catch { } }
    }

    private static byte[] MakeWav(int sampleRate, params (double Seconds, double Amp)[] parts)
    {
        var samples = 0;
        foreach (var p in parts) samples += (int)(p.Seconds * sampleRate);
        var data = samples * 2;
        var buf = new byte[44 + data];
        "RIFF"u8.CopyTo(buf);
        System.Buffers.Binary.BinaryPrimitives.WriteInt32LittleEndian(buf.AsSpan(4), 36 + data);
        "WAVEfmt "u8.CopyTo(buf.AsSpan(8));
        System.Buffers.Binary.BinaryPrimitives.WriteInt32LittleEndian(buf.AsSpan(16), 16);
        System.Buffers.Binary.BinaryPrimitives.WriteInt16LittleEndian(buf.AsSpan(20), 1);
        System.Buffers.Binary.BinaryPrimitives.WriteInt16LittleEndian(buf.AsSpan(22), 1);
        System.Buffers.Binary.BinaryPrimitives.WriteInt32LittleEndian(buf.AsSpan(24), sampleRate);
        System.Buffers.Binary.BinaryPrimitives.WriteInt32LittleEndian(buf.AsSpan(28), sampleRate * 2);
        System.Buffers.Binary.BinaryPrimitives.WriteInt16LittleEndian(buf.AsSpan(32), 2);
        System.Buffers.Binary.BinaryPrimitives.WriteInt16LittleEndian(buf.AsSpan(34), 16);
        "data"u8.CopyTo(buf.AsSpan(36));
        System.Buffers.Binary.BinaryPrimitives.WriteInt32LittleEndian(buf.AsSpan(40), data);
        var o = 44;
        var t = 0;
        foreach (var (sec, amp) in parts)
        {
            var n = (int)(sec * sampleRate);
            for (var i = 0; i < n; i++, t++, o += 2)
                System.Buffers.Binary.BinaryPrimitives.WriteInt16LittleEndian(buf.AsSpan(o), (short)(Math.Sin(2 * Math.PI * 220 * t / sampleRate) * amp * 32767));
        }
        return buf;
    }

    private sealed class FakeLocalLip(bool ok) : Med.ILipSyncService
    {
        public int Calls;
        public bool IsAvailable => ok;
        public Task<Med.LipSyncResult> ApplyAsync(string videoPath, string audioPath, string outputPath, IProgress<string>? status = null, CancellationToken ct = default)
        {
            Calls++;
            return Task.FromResult(new Med.LipSyncResult(ok, ok ? outputPath : null, ok ? "ok" : "fail"));
        }
    }

    private sealed class LipApiHandler(System.Net.HttpStatusCode submitStatus, int pollsBeforeDone = 0) : System.Net.Http.HttpMessageHandler
    {
        public int Submits, Polls;
        public string? LastAuth, LastForm;
        protected override async Task<System.Net.Http.HttpResponseMessage> SendAsync(System.Net.Http.HttpRequestMessage request, CancellationToken ct)
        {
            LastAuth = request.Headers.Authorization?.ToString() ?? LastAuth;
            var path = request.RequestUri!.AbsolutePath;
            if (request.Method == System.Net.Http.HttpMethod.Post && path == "/lipsync")
            {
                Submits++;
                LastForm = await request.Content!.ReadAsStringAsync(ct);
                return submitStatus == System.Net.HttpStatusCode.OK
                    ? new System.Net.Http.HttpResponseMessage(submitStatus) { Content = new System.Net.Http.StringContent("{\"id\":\"abc-1\"}") }
                    : new System.Net.Http.HttpResponseMessage(submitStatus);
            }
            if (path == "/lipsync/abc-1")
            {
                Polls++;
                var body = Polls <= pollsBeforeDone ? "{\"status\":\"running\"}" : "{\"status\":\"succeeded\",\"output_url\":\"https://lipsync.example.com/files/abc-1.mp4\"}";
                return new System.Net.Http.HttpResponseMessage(System.Net.HttpStatusCode.OK) { Content = new System.Net.Http.StringContent(body) };
            }
            if (path == "/files/abc-1.mp4")
                return new System.Net.Http.HttpResponseMessage(System.Net.HttpStatusCode.OK) { Content = new System.Net.Http.ByteArrayContent(new byte[] { 1, 2, 3, 4 }) };
            return new System.Net.Http.HttpResponseMessage(System.Net.HttpStatusCode.NotFound);
        }
    }

    [Fact]
    public async Task NodeGraph_And_InteractiveCanvas_Check()
    {
        // ① 그래프 규칙: 타입 · 자기연결 · 순환 · 입력 대체 · 컴파일 레벨
        var g = new Flow.VisualNodeGraph();
        g.LoadDefaultTemplate("baby with blocks");
        Assert.Equal(7, g.NodeCount);
        Assert.Equal(6, g.EdgeCount);
        var plan = g.Compile();
        Assert.True(plan.Ok, plan.Message);
        Assert.Equal(5, plan.Plan!.Levels);
        Assert.Equal(2, plan.Plan.MaxWidth);
        var nodes = g.SnapshotNodes();
        string IdOf(Flow.VisualNodeKind k) { foreach (var n in nodes) if (n.Kind == k) return n.Id; return ""; }
        var prompt = IdOf(Flow.VisualNodeKind.Prompt);
        var wan = IdOf(Flow.VisualNodeKind.WanGenerator);
        var up = IdOf(Flow.VisualNodeKind.Upscaler);
        Assert.False(g.CanConnect(prompt, up).Ok);                       // Text → Video 불가
        Assert.True(Flow.VisualNodeGraph.Compatible(Flow.VisualPortType.Text, Flow.VisualPortType.Control));
        Assert.False(g.CanConnect(wan, wan).Ok);
        var extraPost = g.Add(Flow.VisualNodeKind.PostProcess, 900, 400)!;
        Assert.True(g.Connect(up, extraPost.Id).Ok);
        Assert.False(g.CanConnect(extraPost.Id, up).Ok);                 // 순환
        Assert.True(g.Connect(wan, extraPost.Id).Ok);                    // 입력 대체
        Assert.Equal(7, g.EdgeCount);
        var lonely = g.Add(Flow.VisualNodeKind.Upscaler, 0, 0)!;
        var bad = g.Compile();
        Assert.False(bad.Ok);
        Assert.Contains("입력이 연결되지", bad.Message);
        Assert.True(g.Remove(lonely.Id));
        Assert.True(g.Remove(extraPost.Id));

        // ② 직렬화 왕복 · 집계 필드 불일치 거부
        var json = g.ToJson();
        var g2 = new Flow.VisualNodeGraph();
        Assert.True(g2.LoadJson(json).Ok);
        Assert.Equal((g.NodeCount, g.EdgeCount), (g2.NodeCount, g2.EdgeCount));
        var dto = g.ToDto();
        Assert.False(g2.LoadDto(dto with { NodeCount = 99 }).Ok);
        Assert.False(g2.LoadJson("{bad").Ok);
        Assert.False(Flow.VisualNodeGraph.IsSafeId("../x"));
        Assert.Equal(g.NodeCount, g2.NodeCount);

        // ③ 레벨 병렬 실행 — 업스케일/후처리 분기가 동시에 실행(배리어) · Output 수집
        var started = 0;
        var barrier = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        async ValueTask<Flow.NodeValue> Branch(Flow.VisualNode n, Flow.NodeValue input)
        {
            if (Interlocked.Increment(ref started) == 2) barrier.TrySetResult();
            await barrier.Task.WaitAsync(TimeSpan.FromSeconds(5));
            return input with { Path = input.Path + "." + n.Kind.ToString().ToLowerInvariant() };
        }
        var execs = new System.Collections.Generic.Dictionary<Flow.VisualNodeKind, Flow.INodeExecutor>
        {
            [Flow.VisualNodeKind.Prompt] = new Flow.DelegateNodeExecutor((n, _, _, _) => ValueTask.FromResult(new Flow.NodeValue(Flow.VisualPortType.Text, n.Text, null))),
            [Flow.VisualNodeKind.ControlNet] = new Flow.DelegateNodeExecutor((n, i, _, _) => ValueTask.FromResult(Flow.NodeGraphExecutionPipeline.BuildControl(n, i))),
            [Flow.VisualNodeKind.WanGenerator] = new Flow.DelegateNodeExecutor((n, i, _, _) => ValueTask.FromResult(new Flow.NodeValue(Flow.VisualPortType.Video, i.Text, "clip.mp4"))),
            [Flow.VisualNodeKind.Upscaler] = new Flow.DelegateNodeExecutor((n, i, _, _) => Branch(n, i)),
            [Flow.VisualNodeKind.PostProcess] = new Flow.DelegateNodeExecutor((n, i, _, _) => Branch(n, i)),
            [Flow.VisualNodeKind.Output] = new Flow.DelegateNodeExecutor((n, i, _, _) => ValueTask.FromResult(i)),
        };
        var root = Path.Combine(Path.GetTempPath(), "pfs_ng_test_" + Guid.NewGuid().ToString("N"));
        try
        {
            var pipe = new Flow.NodeGraphExecutionPipeline(execs);
            var changes = 0;
            g.OnChanged += () => Interlocked.Increment(ref changes);
            var r = await pipe.ExecuteAsync(g, new Flow.GraphRunOptions(2, root));
            Assert.True(r.Ok, r.Message);
            Assert.Equal(Flow.GraphRunBackend.Local, r.Backend);
            Assert.Equal(7, r.Executed);
            Assert.Equal(2, r.Outputs.Count);
            Assert.Contains("clip.mp4.upscaler", r.Outputs);
            Assert.Contains("clip.mp4.postprocess", r.Outputs);
            Assert.True(changes > 7);
            Assert.Equal(7, g.CountState(Flow.VisualNodeState.Completed));
            Assert.False(pipe.IsRunning);

            // ④ 분기 실패 → 하위 Skipped · 다른 분기 계속([부분 구제])
            execs[Flow.VisualNodeKind.Upscaler] = new Flow.DelegateNodeExecutor((_, _, _, _) => throw new InvalidOperationException("GPU OOM"));
            execs[Flow.VisualNodeKind.PostProcess] = new Flow.DelegateNodeExecutor((n, i, _, _) => ValueTask.FromResult(i with { Path = "post.mp4" }));
            var pipe2 = new Flow.NodeGraphExecutionPipeline(execs);
            var r2 = await pipe2.ExecuteAsync(g, new Flow.GraphRunOptions(1, root));
            Assert.False(r2.Ok);
            Assert.Equal((5, 1, 1), (r2.Executed, r2.Faulted, r2.Skipped));
            Assert.Equal(new[] { "post.mp4" }, r2.Outputs);
            Assert.Equal("GPU OOM", g.Find(up)!.Status);

            // ⑤ 원격 오프로딩 성공 · 실패 시 로컬 폴백
            var remoteOk = new FakeRemoteRunner(true);
            var r3 = await new Flow.NodeGraphExecutionPipeline(execs, remoteOk).ExecuteAsync(g, new Flow.GraphRunOptions(2, root, OffloadToRemote: true));
            Assert.True(r3.Ok);
            Assert.Equal(Flow.GraphRunBackend.RemoteGpu, r3.Backend);
            var r4 = await new Flow.NodeGraphExecutionPipeline(execs, new FakeRemoteRunner(false)).ExecuteAsync(g, new Flow.GraphRunOptions(2, root, OffloadToRemote: true));
            Assert.Equal(Flow.GraphRunBackend.Local, r4.Backend);
            Assert.StartsWith("원격 GPU 실패(down) → 로컬 실행", r4.Message);
            using (var cts = new CancellationTokenSource())
            {
                cts.Cancel();
                Assert.Equal("취소됨", (await pipe.ExecuteAsync(g, new Flow.GraphRunOptions(2, root), cts.Token)).Message);
            }
        }
        finally { try { Directory.Delete(root, true); } catch { } }

        // ⑥ ControlNet 변환 · 후처리 필터
        var cn = new Flow.VisualNode { Kind = Flow.VisualNodeKind.ControlNet, Text = "inpaint", Strength = 2 };
        var cv = Flow.NodeGraphExecutionPipeline.BuildControl(cn, new Flow.NodeValue(Flow.VisualPortType.Text, "a baby", null));
        Assert.Equal(("reference", "a baby", 1.0), (cv.Hint, cv.Text, cv.Strength));   // 마스크·참조 없음 → 원문 유지
        Assert.Throws<InvalidOperationException>(() => Flow.NodeGraphExecutionPipeline.BuildControl(cn, Flow.NodeValue.Empty));
        Assert.Contains("masked region", Flow.NodeGraphExecutionPipeline.ControlTokens("inpaint"));
        Assert.Equal("null", Flow.NodeGraphExecutionPipeline.PostFilter("none"));
        Assert.StartsWith("unsharp", Flow.NodeGraphExecutionPipeline.PostFilter("SHARPEN"));

        // ⑦ 마스크 래스터 · 지우개 · 박스 · 페더
        const int W = 64, H = 48;
        var mask = new byte[W * H];
        Med.CanvasMaskingService.RasterizeStroke(mask, W, H, new Med.MaskStroke(new[] { new Med.MaskPoint(0.25f, 0.5f), new Med.MaskPoint(0.75f, 0.5f) }, 0.05f, false));
        var box = Med.CanvasMaskingService.ComputeBounds(mask, W, H);
        Assert.InRange(box.X, 12, 14);
        Assert.InRange(box.X + box.W, 50, 52);
        Assert.InRange(box.Y, 20, 22);
        Med.CanvasMaskingService.RasterizeStroke(mask, W, H, new Med.MaskStroke(new[] { new Med.MaskPoint(0.5f, 0.5f) }, 0.1f, true));
        Assert.Equal(0, mask[24 * W + 32]);
        Assert.Equal(255, mask[24 * W + 16]);
        var feathered = (byte[])mask.Clone();
        Med.CanvasMaskingService.Feather(feathered, W, H, 2);
        Assert.InRange((int)feathered[24 * W + 13], 1, 254);
        Assert.True(Med.CanvasMaskingService.ComputeBounds(new byte[W * H], W, H).IsEmpty);

        // ⑧ 키프레임 보간(선형/이즈/홀드/범위 밖) · 변환 적용
        var track = new Med.KeyframeTrack();
        Assert.Equal(Med.MaskTransform.Identity, track.Evaluate(1));
        Assert.True(track.Set(new Med.MaskKeyframe(0, 0, 0, 1, 0, 1)));
        Assert.True(track.Set(new Med.MaskKeyframe(2, 0.4f, -0.2f, 2, 90, 0.5f)));
        Assert.True(track.Set(new Med.MaskKeyframe(2.0004, 0.2f, 0, 1, 0, 1)));       // ±1ms 대체
        Assert.Equal(2, track.Count);
        Assert.True(track.Set(new Med.MaskKeyframe(2, 0.4f, -0.2f, 2, 90, 0.5f)));
        var mid = track.Evaluate(1);
        Assert.Equal(0.2f, mid.Dx, 3);
        Assert.Equal(1.5f, mid.Scale, 3);
        Assert.Equal(45f, mid.Rotation, 3);
        Assert.Equal(0.4f, track.Evaluate(99).Dx, 3);
        Assert.False(track.Set(new Med.MaskKeyframe(-1, 0, 0, 1, 0, 1)));
        track.Set(new Med.MaskKeyframe(0, 0, 0, 1, 0, 1, Med.KeyEase.Hold));
        Assert.Equal(0f, track.Evaluate(1.9).Dx, 3);
        Assert.True(track.RemoveAt(2));
        var shifted = new byte[W * H];
        Med.CanvasMaskingService.TransformMask(mask, shifted, W, H, new Med.MaskTransform(0.25f, 0, 1, 0, 1));
        Assert.Equal(mask[24 * W + 16], shifted[24 * W + 32]);
        Assert.Equal(0, shifted[24 * W + 2]);

        // ⑨ 박스 추적(SAD) — 밝은 사각형 +5/−3 이동
        var f0 = new byte[Med.CanvasMaskingService.TrackW * Med.CanvasMaskingService.TrackH];
        var f1 = new byte[f0.Length];
        void Paint(byte[] f, int x, int y) { for (var yy = 0; yy < 14; yy++) for (var xx = 0; xx < 18; xx++) f[(y + yy) * Med.CanvasMaskingService.TrackW + x + xx] = (byte)(120 + (xx * 7 + yy * 3) % 120); }
        Paint(f0, 60, 40);
        Paint(f1, 65, 37);
        var (tb, err) = Med.CanvasMaskingService.TrackBox(f0, f1, Med.CanvasMaskingService.TrackW, Med.CanvasMaskingService.TrackH, new Med.MaskBox(60, 40, 18, 14, 0));
        Assert.Equal((65, 37), (tb.X, tb.Y));
        Assert.True(err < 0.01);

        // ⑩ PNG 인코딩(시그니처 · IHDR CRC · IDAT 해제 길이)
        var png = Med.CanvasMaskingService.EncodePng(mask, W, H);
        Assert.Equal(new byte[] { 0x89, 0x50, 0x4E, 0x47 }, png[..4]);
        Assert.Equal(W, System.Buffers.Binary.BinaryPrimitives.ReadInt32BigEndian(png.AsSpan(16)));
        var crc = System.Buffers.Binary.BinaryPrimitives.ReadUInt32BigEndian(png.AsSpan(29));
        Assert.Equal(Med.CanvasMaskingService.Crc32(png.AsSpan(12, 4), png.AsSpan(16, 13)), crc);
        var idatLen = System.Buffers.Binary.BinaryPrimitives.ReadInt32BigEndian(png.AsSpan(33));
        using (var z = new System.IO.Compression.ZLibStream(new MemoryStream(png, 41, idatLen), System.IO.Compression.CompressionMode.Decompress))
        using (var outMs = new MemoryStream())
        {
            z.CopyTo(outMs);
            Assert.Equal(H * (W + 1), outMs.Length);
        }
        Assert.Equal("IEND", System.Text.Encoding.ASCII.GetString(png, png.Length - 8, 4));

        // ⑪ 마스킹 서비스 문서: 스트로크 수명 · 박스 · 직렬화(양자화) · 거부 · 내보내기
        var svc = new Med.CanvasMaskingService(() => null);
        var mchanges = 0;
        svc.OnChange += () => mchanges++;
        svc.SetMedia(null, 320, 180);
        svc.BeginStroke(new Med.MaskPoint(0.2f, 0.2f), 0.03f, false);
        Assert.False(svc.AddPoint(new Med.MaskPoint(0.2001f, 0.2f)));       // 근접 점 무시
        Assert.True(svc.AddPoint(new Med.MaskPoint(0.6f, 0.4f)));
        Assert.NotNull(svc.EndStroke());
        Assert.False(svc.LastBox.IsEmpty);
        Assert.True(svc.SetKeyframe(new Med.MaskKeyframe(1.5, 0.1f, 0, 1, 0, 1)));
        var mjson = svc.ToJson();
        var svc2 = new Med.CanvasMaskingService(() => null);
        Assert.True(svc2.LoadJson(mjson).Ok);
        Assert.Equal((1, 1, 320), (svc2.StrokeCount, svc2.Track.Count, svc2.Width));
        Assert.Equal(0.6f, svc2.Strokes[0].Points[1].X, 3);
        Assert.False(svc2.LoadDto(svc.ToDto() with { StrokeCount = 5 }).Ok);
        Assert.False(svc2.LoadDto(svc.ToDto() with { Strokes = new[] { new Med.MaskStrokeDto(new ushort[] { 1 }, 0.1f, false) }, StrokeCount = 1 }).Ok);
        Assert.Equal(0, await svc.TrackAcrossAsync(0, 2));                     // ffmpeg 없음 → 0(Graceful)
        var exportDir = Path.Combine(Path.GetTempPath(), "pfs_mask_test_" + Guid.NewGuid().ToString("N"));
        try
        {
            var pngPath = await svc.ExportAsync(exportDir, 1.5);
            Assert.NotNull(pngPath);
            Assert.True(File.Exists(pngPath));
            Assert.True(File.Exists(Path.ChangeExtension(pngPath, ".json")));
        }
        finally { try { Directory.Delete(exportDir, true); } catch { } }
        Assert.True(svc.Undo());
        Assert.True(svc.LastBox.IsEmpty);
        Assert.True(mchanges >= 4);

        // ⑫ 라이브 동기화 브릿지: 토큰 · 봉투 검증 · 실제 WebSocket 왕복(스냅숏 · 방송 · 수신 · 재중계 · 거부)
        Assert.Null(Int.LiveSessionSyncBridge.ParseEnvelope("{\"T\":\"evil\",\"Seq\":1,\"Src\":\"x\",\"At\":0,\"Data\":\"{}\"}"u8));
        Assert.NotNull(Int.LiveSessionSyncBridge.ParseEnvelope("{\"T\":\"stroke\",\"Seq\":1,\"Src\":\"x\",\"At\":0,\"Data\":\"{}\"}"u8));
        Assert.Null(Int.LiveSessionSyncBridge.ParseEnvelope(new byte[Int.LiveSessionSyncBridge.MaxInboundBytes + 1]));
        Assert.Equal(TimeSpan.FromSeconds(30), Int.LiveSessionSyncClient.BackoffOf(9));
        Assert.True(Int.LiveSessionSyncClient.IsValidUrl("ws://192.168.0.5:8791/pfs-live/ws"));
        Assert.False(Int.LiveSessionSyncClient.IsValidUrl("ws://example.com/ws"));
        using (var bridge = new Int.LiveSessionSyncBridge())
        {
            Assert.True(bridge.ValidateToken(bridge.Token));
            Assert.False(bridge.ValidateToken("short-token"));
            var started2 = false;
            for (var attempt = 0; attempt < 5 && !started2; attempt++) started2 = bridge.Start(Random.Shared.Next(20000, 60000));
            Assert.True(started2, bridge.LastError);
            Assert.True(bridge.PublishGraph(g) == 0);                            // 접속 전 → 스냅숏 캐시만

            using (var badWs = new System.Net.WebSockets.ClientWebSocket())
                await Assert.ThrowsAnyAsync<Exception>(() => badWs.ConnectAsync(new Uri(bridge.JoinUrl!.Replace(bridge.Token, "wrong")), CancellationToken.None));
            await WaitUntil(() => bridge.Rejected >= 1);

            var remote = new System.Collections.Concurrent.ConcurrentQueue<Int.LiveSyncEnvelope>();
            bridge.OnRemoteMessage += remote.Enqueue;
            using var a = new Int.LiveSessionSyncClient();
            using var b = new Int.LiveSessionSyncClient();
            var aGot = new System.Collections.Concurrent.ConcurrentQueue<Int.LiveSyncEnvelope>();
            var bGot = new System.Collections.Concurrent.ConcurrentQueue<Int.LiveSyncEnvelope>();
            a.OnMessage += aGot.Enqueue;
            b.OnMessage += bGot.Enqueue;
            Assert.True(await a.ConnectAsync(bridge.JoinUrl!));
            Assert.True(await b.ConnectAsync(bridge.JoinUrl!));
            await WaitUntil(() => bridge.ClientCount == 2 && aGot.Count >= 1);
            Assert.Contains(aGot, e => e.T == Int.LiveSyncTypes.Graph);         // 입장 스냅숏

            Assert.Equal(2, bridge.PublishNodeStates(g));
            await WaitUntil(() => bGot.Any(e => e.T == Int.LiveSyncTypes.NodeState));
            Assert.True(bridge.PublishCursor(0.1f, 0.2f, true) >= 0);
            Assert.Equal(-1, bridge.PublishCursor(0.1f, 0.3f, true));          // 33ms 스로틀 드롭
            Assert.True(bridge.Dropped >= 1);

            Assert.True(await a.SendAsync(Int.LiveSyncTypes.Stroke, "{\"xy\":[1,2],\"r\":0.02}"));
            await WaitUntil(() => remote.Count >= 1 && bGot.Any(e => e.T == Int.LiveSyncTypes.Stroke));
            Assert.Equal(a.SiteId, remote.First().Src);
            Assert.DoesNotContain(aGot, e => e.T == Int.LiveSyncTypes.Stroke);   // 발신자 제외 재중계
            Assert.False(await a.SendAsync("evil", "{}"));
            bridge.Stop();
            Assert.False(bridge.IsListening);
            await WaitUntil(() => bridge.ClientCount == 0);
        }

        // ⑬ 원격 GPU 릴레이: 서명(집계 포함 canonical) · 상태 검증 · 제출→폴링→다운로드 · 프로브 실패 폴백
        var canon = Int.RemoteGpuOffloadRelay.CanonicalBody(g.ToDto());
        Assert.Contains("\"nodeCount\":7", canon);
        var sig = Int.RemoteGpuOffloadRelay.Sign("k", canon);
        Assert.True(Int.RemoteGpuOffloadRelay.VerifySignature("k", canon, sig));
        Assert.False(Int.RemoteGpuOffloadRelay.VerifySignature("k", canon + " ", sig));
        Assert.False(Int.RemoteGpuOffloadRelay.VerifySignature("k", canon, "zz"));
        Assert.Equal("invalid", Int.RemoteGpuOffloadRelay.ParseStatus("{\"status\":\"done\",\"outputs\":[\"http://evil.example.com/a.mp4\"]}").Status);
        var ps = Int.RemoteGpuOffloadRelay.ParseStatus("{\"status\":\"running\",\"nodes\":[{\"id\":\"" + wan + "\",\"state\":\"Running\",\"message\":\"gpu0\"},{\"id\":\"../x\",\"state\":\"Completed\"}]}");
        Assert.Equal(("running", 1), (ps.Status, ps.Nodes.Count));
        Assert.False(new Int.GpuWorkerConfig("https://gpu.example.com", null).IsConfigured);

        var cfg = new Int.GpuWorkerConfig("https://gpu.example.com", "secret");
        var handler = new GpuWorkerHandler(healthy: true);
        var outDir = Path.Combine(Path.GetTempPath(), "pfs_gpu_test_" + Guid.NewGuid().ToString("N"));
        try
        {
            using (var relay = new Int.RemoteGpuOffloadRelay(() => cfg, handler, TimeSpan.Zero))
            {
                var rr = await relay.RunAsync(g, outDir, CancellationToken.None);
                Assert.True(rr.Ok, rr.Message);
                Assert.Equal(Flow.GraphRunBackend.RemoteGpu, rr.Backend);
                Assert.Single(rr.Outputs);
                Assert.Equal(3, new FileInfo(rr.Outputs[0]).Length);
                Assert.True(Int.RemoteGpuOffloadRelay.VerifySignature("secret", handler.Body!, handler.Signature));
                Assert.Equal(2, handler.Polls);
                Assert.Equal(1, relay.Offloaded);
                Assert.StartsWith("☁️", g.Find(wan)!.Status);
            }
            using (var down = new Int.RemoteGpuOffloadRelay(() => cfg, new GpuWorkerHandler(healthy: false), TimeSpan.Zero))
            {
                var sw = System.Diagnostics.Stopwatch.StartNew();
                var rr = await down.RunAsync(g, outDir, CancellationToken.None);
                Assert.False(rr.Ok);
                Assert.Contains("1초", rr.Message);
                Assert.True(sw.Elapsed < TimeSpan.FromSeconds(3));
                Assert.Equal(1, down.Fallbacks);
            }
        }
        finally { try { Directory.Delete(outDir, true); } catch { } }
    }

    private static async Task WaitUntil(Func<bool> cond, int timeoutMs = 5000)
    {
        var sw = Stopwatch.StartNew();
        while (!cond())
        {
            if (sw.ElapsedMilliseconds > timeoutMs) Assert.Fail("조건 대기 시간 초과");
            await Task.Delay(20);
        }
    }

    private sealed class FakeRemoteRunner(bool ok) : Flow.IRemoteGraphRunner
    {
        public bool IsConfigured => true;
        public Task<Flow.GraphRunResult> RunAsync(Flow.VisualNodeGraph graph, string outputRoot, CancellationToken ct)
            => Task.FromResult(new Flow.GraphRunResult(ok, Flow.GraphRunBackend.RemoteGpu, ok ? graph.NodeCount : 0, 0, 0,
                ok ? new[] { "remote.mp4" } : Array.Empty<string>(), 1, ok ? "ok" : "down"));
    }

    private sealed class GpuWorkerHandler(bool healthy) : System.Net.Http.HttpMessageHandler
    {
        public string? Body, Signature;
        public int Polls;
        protected override async Task<System.Net.Http.HttpResponseMessage> SendAsync(System.Net.Http.HttpRequestMessage request, CancellationToken ct)
        {
            var path = request.RequestUri!.AbsolutePath;
            if (path == "/health")
            {
                if (!healthy) { await Task.Delay(TimeSpan.FromSeconds(10), ct); }
                return new System.Net.Http.HttpResponseMessage(System.Net.HttpStatusCode.OK);
            }
            if (path == "/graph/run" && request.Method == System.Net.Http.HttpMethod.Post)
            {
                Body = await request.Content!.ReadAsStringAsync(ct);
                Signature = request.Headers.TryGetValues("X-PFS-Signature", out var v) ? v.First() : null;
                return new System.Net.Http.HttpResponseMessage(System.Net.HttpStatusCode.OK) { Content = new System.Net.Http.StringContent("{\"id\":\"run-1\"}") };
            }
            if (path == "/graph/run/run-1")
            {
                Polls++;
                var wanId = "";
                using (var doc = System.Text.Json.JsonDocument.Parse(Body!))
                    foreach (var n in doc.RootElement.GetProperty("graph").GetProperty("Nodes").EnumerateArray())
                        if (n.GetProperty("Kind").GetInt32() == (int)Flow.VisualNodeKind.WanGenerator) wanId = n.GetProperty("Id").GetString()!;
                var body = Polls < 2
                    ? "{\"status\":\"running\",\"nodes\":[{\"id\":\"" + wanId + "\",\"state\":\"Running\",\"message\":\"gpu0\"}]}"
                    : "{\"status\":\"succeeded\",\"outputs\":[\"https://gpu.example.com/out/1.mp4\"],\"nodes\":[{\"id\":\"" + wanId + "\",\"state\":\"Completed\",\"message\":\"done\"}]}";
                return new System.Net.Http.HttpResponseMessage(System.Net.HttpStatusCode.OK) { Content = new System.Net.Http.StringContent(body) };
            }
            if (path == "/out/1.mp4")
                return new System.Net.Http.HttpResponseMessage(System.Net.HttpStatusCode.OK) { Content = new System.Net.Http.ByteArrayContent(new byte[] { 1, 2, 3 }) };
            return new System.Net.Http.HttpResponseMessage(System.Net.HttpStatusCode.NotFound);
        }
    }

    [Fact]
    public async Task CharacterIdentity_And_OutfitTransfer_Check()
    {
        // ① 특징 벡터: 동일 얼굴(밝기만 변화) 고정 · 다른 얼굴 이탈 · 순수/무할당 경로
        const int S = 96;
        byte[] Face(int eyeY, int mouthW, (byte R, byte G, byte B) skin, int brighten = 0)
        {
            var img = new byte[S * S * 3];
            for (var y = 0; y < S; y++)
                for (var x = 0; x < S; x++)
                {
                    var o = (y * S + x) * 3;
                    var (r, g, b) = ((byte)200, (byte)220, (byte)240);                     // 배경
                    var dx = x - 48; var dy = y - 40;
                    if (dx * dx + dy * dy < 30 * 30) (r, g, b) = skin;                    // 얼굴
                    if ((Math.Abs(x - 36) < 4 || Math.Abs(x - 60) < 4) && Math.Abs(y - eyeY) < 3) (r, g, b) = (20, 20, 30);   // 눈
                    if (Math.Abs(x - 48) < mouthW && Math.Abs(y - 56) < 2) (r, g, b) = (190, 60, 70);                        // 입
                    img[o] = (byte)Math.Clamp(r + brighten, 0, 255); img[o + 1] = (byte)Math.Clamp(g + brighten, 0, 255); img[o + 2] = (byte)Math.Clamp(b + brighten, 0, 255);
                }
            return img;
        }
        var region = SB.FaceRegion.Default;
        var baby = Face(34, 8, (245, 205, 180));
        var same = Face(34, 8, (245, 205, 180), brighten: 6);
        var other = Face(26, 16, (150, 100, 70));
        var fv = new float[SB.CharacterIdentityLockService.Dimensions];
        var lum = SB.CharacterIdentityLockService.ComputeFeatures(baby, S, S, region, fv);
        Assert.InRange(lum, 100, 255);
        double norm = 0; for (var i = 0; i < 8; i++) norm += fv[i] * fv[i];
        Assert.True(norm < 1.0001);
        Assert.Throws<ArgumentException>(() => SB.CharacterIdentityLockService.ComputeFeatures(new byte[10], S, S, region, fv));
        var sSame = SB.CharacterIdentityLockService.Compare(baby, S, S, region, same, S, S, region);
        var sOther = SB.CharacterIdentityLockService.Compare(baby, S, S, region, other, S, S, region);
        Assert.Equal(SB.IdentityVerdict.Locked, sSame.Verdict);
        Assert.True(sSame.Confidence >= 90, sSame.ToString());
        Assert.True(sOther.Confidence < sSame.Confidence - 20, sOther.ToString());
        Assert.NotEqual(SB.IdentityVerdict.Locked, sOther.Verdict);
        Assert.Equal(0, SB.CharacterIdentityLockService.Cosine(new float[3], new float[3]));
        Assert.Equal((0.0, SB.IdentityVerdict.Lost), (SB.CharacterIdentityLockService.Score(0.5, 0).Confidence, SB.CharacterIdentityLockService.Score(0.5, 0).Verdict));
        Assert.Equal(100.0, SB.CharacterIdentityLockService.Score(1.0, 100).Confidence);
        var profile = new SB.CharacterProfile { Name = "예준", FaceImagePath = "face.png", Features = (float[])fv.Clone(), FaceHash = SB.CharacterIdentityLockService.RegionHash(baby, S, S, region) };
        Assert.True(profile.HasFace);
        Assert.Equal(SB.IdentityVerdict.Locked, SB.CharacterIdentityLockService.ScoreAgainst(profile, same, S, S).Verdict);
        Assert.Equal(SB.IdentityScore.None, SB.CharacterIdentityLockService.ScoreAgainst(new SB.CharacterProfile(), same, S, S));
        var clamped = new SB.FaceRegion(2, -1, 5, float.NaN).Clamp();
        Assert.Equal((0.95f, 0f, 1f), (clamped.X, clamped.Y, clamped.H));
        Assert.Equal(0.05f, clamped.W, 4);

        // ② 정체성 프롬프트(멱등) · ComfyUI 워크플로 결선(InstantID/PuLID)
        var (ip, ineg) = SB.CharacterIdentityLockService.ApplyPrompt("baby in a bath", "blurry");
        Assert.Contains(SB.CharacterIdentityLockService.IdentityPrompt, ip);
        Assert.StartsWith("blurry, different person", ineg);
        Assert.Equal((ip, ineg), SB.CharacterIdentityLockService.ApplyPrompt(ip, ineg));
        System.Text.Json.Nodes.JsonObject Wf() => new()
        {
            ["3"] = new System.Text.Json.Nodes.JsonObject { ["class_type"] = "KSampler", ["inputs"] = new System.Text.Json.Nodes.JsonObject {
                ["model"] = new System.Text.Json.Nodes.JsonArray("4", 0), ["positive"] = new System.Text.Json.Nodes.JsonArray("6", 0), ["negative"] = new System.Text.Json.Nodes.JsonArray("7", 0) } },
            ["4"] = new System.Text.Json.Nodes.JsonObject { ["class_type"] = "CheckpointLoaderSimple", ["inputs"] = new System.Text.Json.Nodes.JsonObject() },
        };
        var wf = Wf();
        Assert.Equal(5, SB.CharacterIdentityLockService.InjectComfyWorkflow(wf, new SB.IdentityConditioning(SB.IdentityAdapter.PuLid, 2.0, 0, 1, "face.png"), "face.png"));
        Assert.Equal("ApplyPulid", (string?)wf["9"]!["class_type"]);
        Assert.Equal("9", (string?)wf["3"]!["inputs"]!["model"]![0]);
        Assert.Equal("4", (string?)wf["9"]!["inputs"]!["model"]![0]);
        Assert.Equal(1.5, (double)wf["9"]!["inputs"]!["weight"]!);
        var wf2 = Wf();
        Assert.Equal(4, SB.CharacterIdentityLockService.InjectComfyWorkflow(wf2, new SB.IdentityConditioning(SB.IdentityAdapter.InstantId, 0.8, 0.1, 0.9, "face.png"), "face.png"));
        Assert.Equal(("8", 1, 2), ((string?)wf2["3"]!["inputs"]!["positive"]![0], (int)wf2["3"]!["inputs"]!["positive"]![1]!, (int)wf2["3"]!["inputs"]!["negative"]![1]!));
        Assert.Equal("6", (string?)wf2["8"]!["inputs"]!["positive"]![0]);
        Assert.Equal(0, SB.CharacterIdentityLockService.InjectComfyWorkflow(Wf(), new SB.IdentityConditioning(SB.IdentityAdapter.None, 1, 0, 1, "x"), "x"));
        Assert.Equal(0, SB.CharacterIdentityLockService.InjectComfyWorkflow(new System.Text.Json.Nodes.JsonObject(), new SB.IdentityConditioning(SB.IdentityAdapter.PuLid, 1, 0, 1, "x"), "x"));

        // ③ 의상/소품: 대표색 · 명명색 · 구문 · 상충 색 제거 · 네거티브 · 멱등 · 그래프 결선
        var shirt = new byte[S * S * 3];
        for (var i = 0; i < S * S; i++) { var bg = i % S < 10; shirt[i * 3] = bg ? (byte)250 : (byte)70; shirt[i * 3 + 1] = bg ? (byte)250 : (byte)120; shirt[i * 3 + 2] = bg ? (byte)250 : (byte)200; }
        var dc = SB.PropOutfitTransferEngine.AnalyzeDominantColor(shirt, S, S, new SB.FaceRegion(0, 0, 1, 1));
        Assert.Equal("#4678C8", dc.Hex);
        Assert.Equal(("blue", "파랑"), (dc.Name, dc.Korean));
        Assert.True(dc.Share > 0.9);
        Assert.Equal(("navy", "네이비"), SB.PropOutfitTransferEngine.ColorNameOf("#1F2E60"));
        Assert.False(SB.PropOutfitTransferEngine.TryParseHex("#12", out _, out _, out _));
        var overalls = new SB.StyleAnchor(SB.AnchorKind.Outfit, "dungaree overalls", "멜빵바지", "#3264C8", "striped", "soft denim");
        var bunny = new SB.StyleAnchor(SB.AnchorKind.Prop, "bunny plush toy", "애착 토끼", "#F5F5F5");
        Assert.Equal("wearing the same blue striped soft denim dungaree overalls", SB.PropOutfitTransferEngine.ClauseOf(overalls));
        Assert.Equal("with the same white bunny plush toy", SB.PropOutfitTransferEngine.ClauseOf(bunny));
        var anchors = new[] { overalls, bunny };
        var applied = SB.PropOutfitTransferEngine.Apply("baby in red dungaree overalls playing", "blurry", anchors);
        Assert.Equal(2, applied.Injected);
        Assert.DoesNotContain("red dungaree", applied.Prompt);
        Assert.Contains("wearing the same blue", applied.Prompt);
        Assert.Contains("missing bunny plush toy", applied.Negative);
        Assert.Contains("different outfit", applied.Negative);
        var (c1, c2) = SB.PropOutfitTransferEngine.ContrastColors(overalls.ColorHex);
        Assert.Contains(c1 + " dungaree overalls", applied.Negative);
        Assert.NotEqual("blue", c1);
        Assert.NotEqual(c1, c2);
        var again = SB.PropOutfitTransferEngine.Apply(applied.Prompt, applied.Negative, anchors);
        Assert.Equal((applied.Prompt, applied.Negative, 0), (again.Prompt, again.Negative, again.Injected));
        Assert.Equal(0, SB.PropOutfitTransferEngine.Apply("x", null, null).Injected);
        Assert.Equal("🧸 흰색 애착 토끼", SB.PropOutfitTransferEngine.Describe(bunny));
        var graph = new Flow.VisualNodeGraph();
        graph.LoadDefaultTemplate();
        Assert.Equal(1, SB.PropOutfitTransferEngine.ApplyToGraph(graph, "face.png", anchors));
        Assert.Equal(0, SB.PropOutfitTransferEngine.ApplyToGraph(graph, "face2.png", anchors));     // 이미 결선된 노드는 유지
        Assert.Equal(0, SB.PropOutfitTransferEngine.ApplyToGraph(new Flow.VisualNodeGraph(), null, anchors));

        // ④ 드리프트: 계열 · 진단 · 억제(영속) · 제출 합성(비영속 · 멱등)
        const string style = "photorealistic, soft pastel color grading, 50mm lens";
        Assert.Equal(0, SB.EpisodicStorySeriesBuilder.FamilyOf(style));
        Assert.Equal(1, SB.EpisodicStorySeriesBuilder.FamilyOf("cute anime style"));
        Assert.Equal(-1, SB.EpisodicStorySeriesBuilder.FamilyOf("a baby"));
        Assert.Equal(3, SB.EpisodicStorySeriesBuilder.ParseTokens(style + ", 50MM LENS,").Count);
        var d0 = SB.EpisodicStorySeriesBuilder.Diagnose(0, "baby, anime, cartoon look", style);
        Assert.Equal((3, 2), (d0.MissingTokens, d0.Conflicts));
        Assert.Equal(1, d0.Score);
        var fixedPrompt = SB.EpisodicStorySeriesBuilder.SuppressPrompt("baby, anime, cartoon look", style, out var ch);
        Assert.True(ch);
        Assert.Equal("baby, look, photorealistic, soft pastel color grading, 50mm lens", fixedPrompt);
        Assert.Equal(0, SB.EpisodicStorySeriesBuilder.Diagnose(0, fixedPrompt, style).Score);
        Assert.StartsWith("animated balloons, ", SB.EpisodicStorySeriesBuilder.SuppressPrompt("animated balloons", style, out _));   // 단어 경계(anime ≠ animated)
        var proj = new SB.StoryboardProject();
        proj.Scenes.Add(new SB.StoryboardScene { Prompt = "baby, 3d render" });
        proj.Scenes.Add(new SB.StoryboardScene { Prompt = fixedPrompt });
        var rep = SB.EpisodicStorySeriesBuilder.AnalyzeDrift(proj, style);
        Assert.Equal(0, rep.Corrected);
        Assert.True(rep.AverageScore > 0);
        var rep2 = SB.EpisodicStorySeriesBuilder.AnalyzeDrift(proj, style, apply: true);
        Assert.Equal((1, 0.0), (rep2.Corrected, rep2.AverageScore));

        var lk = new SB.CharacterLockSnapshot { ProfileId = "p1", Name = "예준", FaceImagePath = "face.png", Anchors = new() { overalls }, StyleTokens = style, Seed = 42 };
        var (cp, cn) = SB.EpisodicStorySeriesBuilder.ComposeScenePrompt("baby in red dungaree overalls, anime", "blurry", lk);
        Assert.Contains(SB.CharacterIdentityLockService.IdentityPrompt, cp);
        Assert.Contains("wearing the same blue", cp);
        Assert.DoesNotContain("anime", cp);
        Assert.DoesNotContain("red dungaree", cp);
        Assert.Contains("different person", cn);
        Assert.Equal((cp, cn), SB.EpisodicStorySeriesBuilder.ComposeScenePrompt(cp, cn, lk));
        Assert.Equal(("a dog", ""), SB.EpisodicStorySeriesBuilder.ComposeScenePrompt(" a dog ", null, null));

        // ⑤ 시리즈 빌더: 프로필(ffmpeg 없음 → 사진 앵커만) · 시리즈 · 에피소드 · 전파 · 영속 왕복 · 직렬화
        var root = Path.Combine(Path.GetTempPath(), "pfs_series_test_" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(root);
        try
        {
            var face = Path.Combine(root, "face.png");
            await File.WriteAllBytesAsync(face, new byte[] { 1, 2, 3 });
            var saved = new System.Collections.Generic.List<SB.StoryboardProject>();
            var identity = new SB.CharacterIdentityLockService(() => null);
            var builder = new SB.EpisodicStorySeriesBuilder(identity, root, p => { saved.Add(p); return Path.Combine(root, p.Id + ".json"); });
            var changes = 0;
            builder.OnChange += () => changes++;
            var (prof, msg) = await builder.CreateProfileAsync("예준", face);
            Assert.NotNull(prof);
            Assert.Contains("특징 추출 실패", msg);
            Assert.False(prof!.HasFace);
            Assert.True(prof.Seed > 0);
            Assert.Null((await builder.CreateProfileAsync("x", Path.Combine(root, "missing.png"))).Profile);
            prof.Anchors.Add(overalls);
            prof.Anchors.Add(bunny);
            prof.StyleTokens = style;
            prof.Features = (float[])fv.Clone();
            builder.Upsert(prof);

            Assert.Null(builder.CreateSeries("x", "nope"));
            var series = builder.CreateSeries("예준이의 하루", prof.Id)!;
            Assert.Equal(style, series.StyleTokens);
            Assert.Equal(prof.Seed, series.Seed);
            var (ep, epProj, epMsg) = builder.AddEpisode(series.Id, 2, "첫 목욕", "목욕 시간", new[] { "baby splashing water", "", "baby wrapped in towel, cartoon" });
            Assert.NotNull(ep);
            Assert.Contains("저장됨", epMsg);
            Assert.Equal(2, epProj!.Scenes.Count);
            Assert.Equal(face, epProj.AnchorImagePath);
            Assert.Equal("예준", epProj.BabyName);
            Assert.Equal((prof.Id, series.Id, ep!.Id, 2, prof.Seed), (epProj.CharacterLock!.ProfileId, epProj.CharacterLock.SeriesId, epProj.CharacterLock.EpisodeId, epProj.CharacterLock.Anchors.Count, epProj.CharacterLock.Seed));
            Assert.Contains("S02E01", epProj.Title);
            Assert.Equal(2, series.Seasons.Count);
            Assert.Single(saved);
            Assert.Null(builder.AddEpisode(series.Id, 1, "빈", "", new[] { " " }).Episode);
            builder.RecordEpisodeConfidence(ep.Id, 87.26);
            Assert.True(changes >= 4);

            var json = System.Text.Json.JsonSerializer.Serialize(epProj);
            var back = new SB.StoryboardRepository().Deserialize(json)!;   // 소스 생성 컨텍스트 왕복
            Assert.Equal(SB.AnchorKind.Prop, back.CharacterLock!.Anchors[1].Kind);
            Assert.Equal("#3264C8", back.CharacterLock.Anchors[0].ColorHex);
            Assert.Contains("\"Outfit\"", json);

            var reloaded = new SB.EpisodicStorySeriesBuilder(identity, root, _ => null);
            Assert.Single(reloaded.Profiles);
            Assert.Equal(SB.CharacterIdentityLockService.Dimensions, reloaded.Profiles[0].Features!.Length);
            Assert.Equal(prof.Region, reloaded.Profiles[0].Region);
            Assert.Equal(87.3, reloaded.Series[0].Seasons[1].Episodes[0].AvgConfidence);
            Assert.Contains("메모리에만", reloaded.AddEpisode(series.Id, 1, "둘째 날", "", new[] { "baby crawling" }).Message);
            Assert.True(reloaded.RemoveSeries(series.Id));
            Assert.True(reloaded.RemoveProfile(prof.Id));
            Assert.Empty(new SB.EpisodicStorySeriesBuilder(identity, root, _ => null).Profiles);

            // ⑥ 정합성 측정(ffmpeg 없음 → None · 예외 0)
            Assert.Equal(SB.IdentityScore.None, await identity.ScoreAsync(prof, face));
            Assert.Null(await identity.ExtractAsync(face, region));
            Assert.False(identity.IsAvailable);
        }
        finally { try { Directory.Delete(root, true); } catch { } }
    }
    // ── v16.23.0 AI 바이럴 후킹 감독: A/B/C 후킹 필터 · 오프닝 분석 · 유지율 곡선/위험 구간(무할당) · 램핑 필터 · A/B 패키저 ──
    [Fact]
    public async Task ViralDirector_HookAndRetention_Check()
    {
        // 1) 오프닝 분석 — 질문+클로즈업 보유 → 남은 신호(파이어링 카피) 추천 · 빈 프로젝트 → 0점/질문형
        var proj = new SB.StoryboardProject { Title = "아기 공룡의 첫 비행 대모험 이야기 특별편" };
        proj.Scenes.Add(new SB.StoryboardScene { Prompt = "extreme close-up of a baby dinosaur face, eyes sparkling, wind blowing, cinematic soft light", VoiceText = "이 아기 공룡, 날 수 있을까?" });
        proj.Scenes.Add(new SB.StoryboardScene { Prompt = "a room", VoiceText = "" });
        proj.Scenes.Add(new SB.StoryboardScene { Prompt = "baby dinosaur run and jump then fly fast over the canyon, dynamic camera chase, golden hour", VoiceText = "드디어 하늘을 날아요! 정말 멋져요!" });
        var op = Med.ViralHookVariantGeneratorService.Analyze(proj);
        Assert.True(op.HasQuestion && op.HasCloseUp);
        Assert.Equal(Med.ViralHookStyle.FiringCopy, op.Recommended);
        Assert.InRange(op.Score, 60, 100);
        var empty = Med.ViralHookVariantGeneratorService.Analyze(new SB.StoryboardProject());
        Assert.Equal(0, empty.Score);
        Assert.Equal(Med.ViralHookStyle.ShockQuestion, empty.Recommended);

        // 2) 카피·주제 — 18자 상한 말줄임 · 스타일별 문구
        var topic = Med.ViralHookVariantGeneratorService.TopicOf(proj);
        Assert.True(topic.Length <= Med.ViralHookVariantGeneratorService.MaxTopicChars + 1);
        Assert.EndsWith("…", topic);
        Assert.Contains("?", Med.ViralHookVariantGeneratorService.BuildCopy(Med.ViralHookStyle.ShockQuestion, topic));
        Assert.Contains("이 영상", Med.ViralHookVariantGeneratorService.BuildCopy(Med.ViralHookStyle.FiringCopy, ""));

        // 3) 후킹 필터 — 1080x1920 · 첫 3초 한정 · B 줌아웃 / C 경고 밴드 · 경로 이스케이프
        var fa = Med.ViralHookVariantGeneratorService.BuildFilter(Med.ViralHookStyle.ShockQuestion, @"C:\t\a.txt", @"C:\f\k.ttf");
        Assert.StartsWith("[0:v]scale=1080:1920", fa);
        Assert.Contains("enable='lt(t,3)'", fa);
        Assert.Contains("textfile=C\\:/t/a.txt", fa);
        Assert.Contains("fontfile=C\\:/f/k.ttf", fa);
        Assert.EndsWith("format=yuv420p[v]", fa);
        Assert.Contains("zoompan=z='if(lt(on,90),1.6-0.6*on/90,1)'", Med.ViralHookVariantGeneratorService.BuildFilter(Med.ViralHookStyle.ExtremeCloseUp, "a.txt", null));
        var fc = Med.ViralHookVariantGeneratorService.BuildFilter(Med.ViralHookStyle.FiringCopy, "a.txt", null);
        Assert.Contains("drawbox=", fc);
        Assert.DoesNotContain("fontfile=", fc);
        var hargs = Med.ViralHookVariantGeneratorService.BuildArgs("in.mp4", "out.mp4", Med.ViralHookStyle.FiringCopy, "a.txt", null);
        Assert.Contains("0:a?", hargs);
        Assert.Equal("out.mp4", hargs[^1]);
        Assert.Equal("hook_B.mp4", Med.ViralHookVariantGeneratorService.FileNameOf(Med.ViralHookStyle.ExtremeCloseUp));

        // 4) 유지율 곡선 — 15초(3컷×5초) · 0.5초 빈 31개 · 단조 감소 · 지루한 2번째 컷만 위험 구간(1.2~1.5x · 1.08~1.15 줌)
        var (bins, zoneCount, zone, monotone, alloc) = RetentionCore(proj);
        Assert.Equal(31, bins);
        Assert.True(monotone);
        Assert.Equal(1, zoneCount);
        Assert.Equal(1, zone.Scene);
        Assert.Equal(5.0, zone.Start, 3);
        Assert.Equal(10.0, zone.End, 3);
        Assert.InRange(zone.Speed, Med.RetentionHeatmapPredictorEngine.MinSpeed, Med.RetentionHeatmapPredictorEngine.MaxSpeed);
        Assert.InRange(zone.Zoom, 1.08, 1.15);
        Assert.Equal(0, alloc);   // 핫패스 무할당(워밍업 후 측정)

        var pred = Med.RetentionHeatmapPredictorEngine.Compute(proj, op.Score / 100.0);
        Assert.Equal(15.0, pred.TotalSeconds, 3);
        Assert.Single(pred.Zones);
        Assert.True(pred.RampedTotalSeconds < pred.TotalSeconds);
        Assert.True(pred.RampedCurve[^1] > pred.Curve[^1]);   // 램핑 후 끝 유지율 개선
        Assert.InRange(pred.AverageRetention, 0.3, 1.0);
        Assert.Equal("#22c55e", Med.RetentionHeatmapPredictorEngine.HeatColorOf(0.8));
        Assert.Equal("#ef4444", Med.RetentionHeatmapPredictorEngine.HeatColorOf(0.2));

        // 5) 램핑 필터 인젝션 — 3세그먼트 · setpts/atempo/zoompan · 무음 변형 · 구간 없음 → 단일 세그먼트
        var zones = new[] { new Med.RetentionRiskZone(1, 5, 10, 0.08, 1.3, 1.1) };
        var rf = Med.RetentionHeatmapPredictorEngine.BuildRampFilter(zones, 15, 1080, 1920, audio: true);
        Assert.Contains("trim=start=5:end=10", rf);
        Assert.Contains("setpts=PTS/1.3", rf);
        Assert.Contains("atempo=1.3", rf);
        Assert.Contains("zoompan=z='min(1+0.1*on/12,1.1)'", rf);
        Assert.EndsWith("concat=n=3:v=1:a=1[v][a]", rf);
        var rfMute = Med.RetentionHeatmapPredictorEngine.BuildRampFilter(zones, 15, 1080, 1920, audio: false);
        Assert.DoesNotContain("[0:a]", rfMute);
        Assert.EndsWith("concat=n=3:v=1:a=0[v]", rfMute);
        Assert.EndsWith("concat=n=1:v=1:a=0[v]", Med.RetentionHeatmapPredictorEngine.BuildRampFilter(ReadOnlySpan<Med.RetentionRiskZone>.Empty, 15, 1080, 1920, false));
        var rargs = Med.RetentionHeatmapPredictorEngine.BuildRampArgs("in.mp4", "out.mp4", zones, 15, 1080, 1920, audio: true);
        Assert.Contains("[a]", rargs);
        var scaled = Med.RetentionHeatmapPredictorEngine.ScaleZones(zones, 15, 12);
        Assert.Equal(4.0, scaled[0].Start, 3);
        Assert.Equal(5.0, zones[0].Start, 3);   // 원본 불변

        // 6) A/B 패키저 순수부 — 제목 접두 · 실험/후킹 태그 우선 · 정규화/중복 제거 · 변주×대상 요청(기본 비공개)
        Assert.StartsWith("❓ ", MultiVariantPublishPackager.TitleOf(Med.ViralHookStyle.ShockQuestion, "공룡"));
        var tags = MultiVariantPublishPackager.MergeTags(new[] { "#공룡", "충격", "baby dino" }, Med.ViralHookStyle.ShockQuestion, 'A');
        Assert.Equal("ab_a", tags[0]);
        Assert.Contains("babydino", tags);
        Assert.Equal(tags.Count, tags.Distinct(StringComparer.OrdinalIgnoreCase).Count());
        Assert.True(MultiVariantPublishPackager.MergeTags(Enumerable.Range(0, 40).Select(i => "t" + i).ToArray(), Med.ViralHookStyle.FiringCopy, 'C').Count <= MultiVariantPublishPackager.MaxHashtags);
        var pkg = new AbExperimentPackage(Guid.NewGuid(), "r", new[]
        {
            new AbVariantPackage('A', Med.ViralHookStyle.ShockQuestion, "a.mp4", null, "ta", "d", tags, null),
            new AbVariantPackage('B', Med.ViralHookStyle.ExtremeCloseUp, "b.mp4", null, "tb", "d", tags, null),
        }, "m.json", "ok");
        var reqs = MultiVariantPublishPackager.BuildRequests(pkg, new[] { SocialPublishTarget.YouTubeShorts, SocialPublishTarget.TikTok });
        Assert.Equal(4, reqs.Count);
        Assert.All(reqs, r => Assert.False(r.PublicVisibility));
        Assert.Equal("b.mp4", reqs[3].VideoPath);

        // 7) ffmpeg 부재 Graceful — 결과 record · 상태/이벤트 갱신 · 예외 0
        var hooks = new Med.ViralHookVariantGeneratorService(() => null);
        var raised = 0;
        hooks.OnChange += () => raised++;
        var br = await hooks.RenderVariantsAsync("missing.mp4", topic, new[] { Med.ViralHookStyle.ShockQuestion });
        Assert.False(br.Ok);
        Assert.Contains("ffmpeg", br.Message);
        Assert.Equal(1, raised);
        Assert.NotNull(hooks.LastAction);
        Assert.False(hooks.IsBusy);
        Assert.Null(await hooks.ExtractThumbnailAsync("missing.mp4", "x.jpg"));
        var engine = new Med.RetentionHeatmapPredictorEngine(() => null);
        var ar = await engine.ApplySpeedRampAsync("missing.mp4", "o.mp4", pred);
        Assert.False(ar.Ok);
        Assert.Equal(0, engine.AppliedCount);
        engine.Analyze(proj, 0.5);
        Assert.NotNull(engine.LastPrediction);
    }

    private static (int Bins, int Zones, Med.RetentionRiskZone Zone, bool Monotone, long Alloc) RetentionCore(SB.StoryboardProject proj)
    {
        Span<Med.RetentionSceneInput> scenes = stackalloc Med.RetentionSceneInput[16];
        Span<float> curve = stackalloc float[Med.RetentionHeatmapPredictorEngine.MaxBins];
        Span<Med.RetentionRiskZone> zones = stackalloc Med.RetentionRiskZone[8];
        int n = 0, bins = 0, zn = 0;
        for (var w = 0; w < 3; w++)   // 워밍업(JIT/정적 초기화)
        {
            n = Med.RetentionHeatmapPredictorEngine.BuildInputs(proj, scenes);
            bins = Med.RetentionHeatmapPredictorEngine.Predict(scenes[..n], curve, 0.5, 0.6);
            zn = Med.RetentionHeatmapPredictorEngine.DetectRiskZones(scenes[..n], curve[..bins], zones);
        }
        var before = GC.GetAllocatedBytesForCurrentThread();
        for (var k = 0; k < 50; k++)
        {
            n = Med.RetentionHeatmapPredictorEngine.BuildInputs(proj, scenes);
            bins = Med.RetentionHeatmapPredictorEngine.Predict(scenes[..n], curve, 0.5, 0.6);
            zn = Med.RetentionHeatmapPredictorEngine.DetectRiskZones(scenes[..n], curve[..bins], zones);
        }
        var alloc = GC.GetAllocatedBytesForCurrentThread() - before;
        var mono = curve[0] == 1f;
        for (var i = 1; i < bins; i++) mono &= curve[i] <= curve[i - 1];
        return (bins, zn, zn > 0 ? zones[0] : default, mono, alloc);
    }
    // ── v16.24.0 글로벌 다국어 더빙: 로캘 카탈로그 · 화폐/단위/관용구/금기어 · Gemini 검증/폴백 · 타임 스트레칭 정렬(무할당) · 음색 F0 · 보이스 매칭 ──
    [Fact]
    public async Task MultilingualDubbing_And_Localization_Check()
    {
        // 1) 로캘 카탈로그 — 30+ 대상 · 코드 고유 · 언어만 지정 조회
        var locs = SB.CulturalLocalizationTranspiler.Locales;
        Assert.True(locs.Count - 1 >= 30);
        Assert.Equal(locs.Count, locs.Select(l => l.Code).Distinct(StringComparer.OrdinalIgnoreCase).Count());
        Assert.All(locs, l => Assert.True(l.EdgeFemale.StartsWith(l.Code, StringComparison.Ordinal) && l.EdgeMale.StartsWith(l.Code, StringComparison.Ordinal)));
        var en = SB.CulturalLocalizationTranspiler.LocaleOf("en-US")!;
        var ja = SB.CulturalLocalizationTranspiler.LocaleOf("ja")!;
        var ar = SB.CulturalLocalizationTranspiler.LocaleOf("ar-SA")!;
        Assert.Equal("ja-JP", ja.Code);
        Assert.Null(SB.CulturalLocalizationTranspiler.LocaleOf("xx"));

        // 2) 화폐 — 만/천/₩ 표기 · 통화별 자릿수 · 환율 덮어쓰기(잘못된 항목 무시)
        var ch = new System.Collections.Generic.List<SB.LocalizationChange>();
        var usd = SB.CulturalLocalizationTranspiler.ConvertCurrency("가격 5만원, 배송비 3,000원, 쿠폰 1만 2천원, ₩13,800", "USD", null, ch);
        Assert.Contains("$36.23", usd);
        Assert.Contains("$2.17", usd);
        Assert.Contains("$8.70", usd);
        Assert.Contains("$10.00", usd);
        Assert.Equal(4, ch.Count);
        Assert.Contains("¥5,435", SB.CulturalLocalizationTranspiler.ConvertCurrency("5만원", "JPY", null, null));
        Assert.Equal("1,234.50 zł", SB.CulturalLocalizationTranspiler.FormatMoney(1234.5, "PLN"));
        Assert.Equal("원본 5만원", SB.CulturalLocalizationTranspiler.ConvertCurrency("원본 5만원", "KRW", null, null));
        var rates = SB.CulturalLocalizationTranspiler.LoadRates("USD=1000;BAD;JPY=x;EUR=-1");
        Assert.Equal(1000, rates["USD"]);
        Assert.Equal(9.2, rates["JPY"]);
        Assert.Equal(1500, rates["EUR"]);
        Assert.Contains("$50.00", SB.CulturalLocalizationTranspiler.ConvertCurrency("5만원", "USD", rates, null));

        // 3) 단위 — 미국 야드파운드 환산 · 미터법 기호 정규화 · 단어 경계
        var imp = SB.CulturalLocalizationTranspiler.ConvertUnits("키 100cm, 몸무게 10kg, 기온 20℃, 5 mins", true, null);
        Assert.Contains("39.4 in", imp);
        Assert.Contains("22 lb", imp);
        Assert.Contains("68 °F", imp);
        Assert.Contains("5 mins", imp);
        Assert.Equal("길이 10 cm", SB.CulturalLocalizationTranspiler.ConvertUnits("길이 10센티미터", false, null));

        // 4) 관용구·금기어(로캘별) · 한국어 대상은 원문 유지
        var notes = new System.Collections.Generic.List<string>();
        var pre = SB.CulturalLocalizationTranspiler.PreTransform("돼지고기 요리는 누워서 떡 먹기", ar, null, null, notes);
        Assert.Equal("소고기 요리는 아주 쉬운 일", pre);
        Assert.Single(notes);
        Assert.Equal("돼지고기 요리는 아주 쉬운 일", SB.CulturalLocalizationTranspiler.PreTransform("돼지고기 요리는 누워서 떡 먹기", en, null, null, null));
        Assert.Equal("누워서 떡 먹기 5만원", SB.CulturalLocalizationTranspiler.PreTransform("누워서 떡 먹기 5만원", SB.CulturalLocalizationTranspiler.LocaleOf("ko-KR")!, null, null, null));

        // 5) Gemini 응답 스키마 검증 · 펜스 허용 · 줄 수 불일치/비문자열 거부
        Assert.NotNull(SB.CulturalLocalizationTranspiler.ParseResponse("```json\n{\"lines\":[\"a\",\"b\"],\"cta\":\"c\",\"notes\":[\"n\"]}\n```", 2));
        Assert.Null(SB.CulturalLocalizationTranspiler.ParseResponse("{\"lines\":[\"a\"]}", 2));
        Assert.Null(SB.CulturalLocalizationTranspiler.ParseResponse("{\"lines\":[\"a\",3]}", 2));
        Assert.Null(SB.CulturalLocalizationTranspiler.ParseResponse("not json", 1));
        var prompt = SB.CulturalLocalizationTranspiler.BuildPrompt(new[] { "안녕" }, "구독", ja, true);
        Assert.Contains("ja-JP", prompt);
        Assert.Contains("exactly 1 items", prompt);

        // 6) 현지화 — AI 성공(검증 통과) · AI 실패 → 오프라인 글로서리 폴백 · 사전 변환 유지
        var src = new[] { "가격은 5만원이에요!", "누워서 떡 먹기죠." };
        string? seen = null;
        var aiOk = new SB.CulturalLocalizationTranspiler((p, ct) => { seen = p; return Task.FromResult(new GeminiResult(true, "{\"lines\":[\"It's only $36.23!\",\"Piece of cake.\"],\"cta\":\"Subscribe\",\"notes\":[\"idiom adapted\"]}", "ok")); });
        var r1 = await aiOk.LocalizeAsync(src, "구독하세요", en);
        Assert.True(r1.AiUsed);
        Assert.Equal("Piece of cake.", r1.Lines[1]);
        Assert.Equal("Subscribe", r1.Cta);
        Assert.Contains("$36.23", seen);           // 지시문엔 변환 금액 전달
        Assert.Contains("아주 쉬운 일", seen);     // 관용구 평이화 전달
        Assert.Contains("idiom adapted", r1.Notes);
        Assert.Equal(1, aiOk.AiCallCount);
        var aiBad = new SB.CulturalLocalizationTranspiler((p, ct) => Task.FromResult(new GeminiResult(true, "{\"lines\":[\"only one\"]}", "ok")));
        var r2 = await aiBad.LocalizeAsync(src, "", en);
        Assert.False(r2.AiUsed);
        Assert.Equal(2, r2.Lines.Count);
        Assert.Contains("$36.23", r2.Lines[0]);
        Assert.Contains("검증 실패", r2.Message);
        var r3 = await aiBad.LocalizeAsync(src, "", en, culturalAdapt: false, useAi: false);
        Assert.Contains("누워서 떡 먹기", r3.Lines[1]);   // 각색 끔 → 관용구 유지(화폐만 변환)
        Assert.Contains("$36.23", r3.Lines[0]);

        // 7) 타임 스트레칭 정렬 — 템포 상한 1.35 · 앞당김 · 잘림 · 겹침 없음 · 무할당
        var (aligned, alloc) = AlignCore();
        Assert.Equal(1.0, aligned[0].Tempo);
        Assert.False(aligned[0].Overflow);
        Assert.Equal(Med.MultilingualLipSyncAndSubtitleAligner.MaxTempo, aligned[1].Tempo);
        Assert.True(aligned[1].Overflow && !aligned[1].Trimmed);
        Assert.Equal(4.995, aligned[1].At, 3);
        Assert.True(aligned[2].Trimmed);
        Assert.Equal(4.7, aligned[2].Seconds, 3);
        for (var i = 1; i < aligned.Length; i++) Assert.True(aligned[i - 1].At + aligned[i - 1].Seconds <= aligned[i].At + 1e-6);
        Assert.Equal(0, alloc);

        // 8) 음절 추정 · viseme 재정렬 · 문자 체계별 자막 스타일 · 템포 인자 · 자막 큐
        Assert.Equal(3, Med.MultilingualLipSyncAndSubtitleAligner.CountSyllables("hello world"));
        Assert.Equal(5, Med.MultilingualLipSyncAndSubtitleAligner.CountSyllables("こんにちは"));
        Assert.Equal(5, Med.MultilingualLipSyncAndSubtitleAligner.CountSyllables("안녕하세요"));
        Assert.Equal(0.914, Med.MultilingualLipSyncAndSubtitleAligner.EstimateSeconds("Hello world.", en), 3);
        var vis = new[] { new Med.VisemeCue(0.1, 0.3, Med.Viseme.A, 0.8) };
        Med.MultilingualLipSyncAndSubtitleAligner.RetimeVisemes(vis, 2.0, 2.0);
        Assert.Equal(2.05, vis[0].Start, 3);
        Assert.Equal(2.15, vis[0].End, 3);
        Assert.Equal(14, Med.MultilingualLipSyncAndSubtitleAligner.StyleFor(ja).MaxCharsPerLine);
        Assert.Equal("Yu Gothic", Med.MultilingualLipSyncAndSubtitleAligner.StyleFor(ja).FontName);
        Assert.Equal(30, Med.MultilingualLipSyncAndSubtitleAligner.StyleFor(en).MaxCharsPerLine);
        var targs = Med.MultilingualLipSyncAndSubtitleAligner.BuildTempoArgs("a.mp3", "b.wav", 1.35, 4.7);
        Assert.Contains(targs, a => a.Contains("atempo=1.35", StringComparison.Ordinal) && a.Contains("atrim=0:4.7", StringComparison.Ordinal));
        var cap = Med.MultilingualLipSyncAndSubtitleAligner.ToCaptionTiming(aligned, new[] { "one", " ", "three" });
        Assert.Equal(2, cap.Count);
        Assert.Equal("three", cap[1].Text);

        // 9) 음색 F0 — 220Hz(여성형) · 110Hz(남성형) · 무음 무효 · WAV 경로 · 무할당
        var (f220, f110, silent, talloc) = TimbreCore();
        Assert.InRange(f220.MedianF0, 210, 230);
        Assert.False(f220.IsMale);
        Assert.InRange(f110.MedianF0, 105, 115);
        Assert.True(f110.IsMale);
        Assert.False(silent.IsValid);
        Assert.Equal(0, talloc);
        var wavP = Med.MultilingualVoiceCloningDubbingService.AnalyzeWav(SineWav(16000, 180, 1.0));
        Assert.InRange(wavP.MedianF0, 172, 188);

        // 10) 보이스 매칭 — 성별 음성 · 피치 오프셋 · 감정 가감 · 음색 없음 → 여성 기본
        var mm = Med.MultilingualVoiceCloningDubbingService.MatchVoice(f110, ja);
        Assert.Equal("ja-JP-KeitaNeural", mm.EdgeVoice);
        var fm = Med.MultilingualVoiceCloningDubbingService.MatchVoice(new Med.VoiceTimbreProfile(250, 0.1, 0.05, 0.2, 0.6, false), en);
        Assert.Equal("en-US-JennyNeural", fm.EdgeVoice);
        Assert.Equal("+27Hz", fm.Pitch);
        var gig = Med.MultilingualVoiceCloningDubbingService.MatchVoice(new Med.VoiceTimbreProfile(250, 0.1, 0.05, 0.2, 0.6, false), en, SB.FacialEmotion.Giggle, 1.0);
        Assert.Equal("+35Hz", gig.Pitch);
        Assert.True(gig.Style > fm.Style && gig.Speed > fm.Speed);
        Assert.Equal("en-US-JennyNeural", Med.MultilingualVoiceCloningDubbingService.MatchVoice(null, en).EdgeVoice);

        // 11) 복제 응답 검증
        Assert.Equal("AbCdEf1234567890", Med.MultilingualVoiceCloningDubbingService.ParseCloneResponse("{\"voice_id\":\"AbCdEf1234567890\"}"));
        Assert.Null(Med.MultilingualVoiceCloningDubbingService.ParseCloneResponse("{\"voice_id\":\"../evil\"}"));
        Assert.Null(Med.MultilingualVoiceCloningDubbingService.ParseCloneResponse("{\"voice_id\":\"abc\"}"));
        Assert.Null(Med.MultilingualVoiceCloningDubbingService.ParseCloneResponse("[]"));

        // 12) 원본 대사 타임라인(완료 컷 없음 → 균등) · ffmpeg 부재 Graceful · 메타데이터 텍스트
        var proj = new SB.StoryboardProject { Title = "글로벌" };
        proj.Scenes.Add(new SB.StoryboardScene { Prompt = "p1", VoiceText = "첫 대사" });
        proj.Scenes.Add(new SB.StoryboardScene { Prompt = "p2", VoiceText = "" });
        proj.Scenes.Add(new SB.StoryboardScene { Prompt = "p3", VoiceText = "셋째 대사", Emotion = SB.FacialEmotion.Giggle });
        var sl = Med.MultilingualVoiceCloningDubbingService.SourceLines(proj, 15);
        Assert.Equal(2, sl.Lines.Count);
        Assert.Equal(0.3, sl.Starts[0], 3);
        Assert.Equal(10.3, sl.Starts[1], 3);
        Assert.Equal(SB.FacialEmotion.Giggle, sl.Emotions[1]);
        using var dub = new Med.MultilingualVoiceCloningDubbingService(() => null, aiBad, null, null, null, apiKey: () => null);
        var raised = 0;
        dub.OnChange += () => raised++;
        var br = await dub.ExportAsync(proj, "missing.mp4", new Med.DubbingRequest(new[] { "en-US" }));
        Assert.False(br.Ok);
        Assert.Contains("ffmpeg", br.Message);
        Assert.True(raised >= 1);
        Assert.False(dub.IsBusy);
        Assert.False(dub.CanClone);
        Assert.Null(await dub.AnalyzeSourceAsync("missing.mp4"));
        Assert.Null(await dub.CloneVoiceAsync("missing.mp4", "x"));
        Assert.Null(await dub.PreviewAsync(en));
        var txt = Med.MultilingualVoiceCloningDubbingService.LocalizationText(r2, aligned);
        Assert.Contains("[Conversions]", txt);
        Assert.Contains("en-US", txt);
    }

    // ── v16.30.0 마스터 스위트: 제로 트러스트(KEK DPAPI-NG · 비밀 · 인가/스텝업/디바이스 · 스트리밍 AES-GCM 변조/절단 · HMAC 감사 체인 · KEK 회전) · OIDC(RS256/JWKS/nonce/PKCE) · SAML2(XML-DSig/XSW) · CDC 델타 동기화(무할당 경계 · 증분 · 복원 · 릴레이 · 수렴 암호화) · 30 모듈 매트릭스/파이프라인 ──
    [Fact]
    public async Task UniversalMasterSuite_And_ZeroTrustShield_Check()
    {
        var root = Path.Combine(Path.GetTempPath(), "pfs_master_" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(root);
        try
        {
            // 1) 쉴드 — KEK 보호 · 로컬 세션 · 비밀 · 인가 매트릭스 · 스텝업 · 디바이스 바인딩
            var now = DateTimeOffset.UtcNow;
            var seed = System.Security.Cryptography.RandomNumberGenerator.GetBytes(32);
            var zdir = Path.Combine(root, "zt");
            using (var z = new Master.ZeroTrustSecurityShieldService(zdir, () => seed, null, () => now, true))
            {
                Assert.True(z.Unlock()); Assert.True(z.Unlock());
                Assert.Contains("DPAPI", z.KeyProtection);
                Assert.False(z.SetSecret(null, "OPENAI_API_KEY", "sk-test"));
                var s = z.IssueLocalSession()!;
                Assert.Equal(Master.ZtRole.Admin, s.Role);
                Assert.True(z.SetSecret(s.Token, "OPENAI_API_KEY", "sk-test-12345"));
                Assert.False(z.SetSecret(s.Token, "bad name!", "x"));
                Assert.DoesNotContain("sk-test-12345", File.ReadAllText(Path.Combine(zdir, "secrets.vault")));
                char[] leaked;
                using (var lease = z.Lease(s.Token, "OPENAI_API_KEY")!)
                {
                    Assert.Equal("sk-test-12345", lease.Value.ToString());
                    leaked = (char[])typeof(Master.SecretLease).GetField("_buf", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance)!.GetValue(lease)!;
                }
                Assert.All(leaked, c => Assert.Equal('\0', c));
                Assert.False(z.Authorize(s.Token, "secret:OPENAI_API_KEY", "read", "other-device").Allowed);
                var viewer = z.IssueSession(new Master.SsoIdentity(true, "v@corp", "acme", Master.ZtRole.Viewer, Array.Empty<string>(), "oidc", "ok"))!;
                Assert.False(z.Authorize(viewer.Token, "pipeline:generate", "run").Allowed);
                Assert.True(z.Authorize(viewer.Token, "pipeline:generate", "read").Allowed);
                Assert.Null(z.Lease(viewer.Token, "OPENAI_API_KEY"));
                now = now.AddMinutes(11);
                var stepUp = z.Authorize(s.Token, "secret:OPENAI_API_KEY", "read");
                Assert.False(stepUp.Allowed); Assert.True(stepUp.StepUpRequired);
                Assert.True(z.Authorize(s.Token, "pipeline:generate", "run").Allowed);
                now = now.AddMinutes(30);
                Assert.Equal("세션 만료", z.Authorize(s.Token, "pipeline:generate", "run").Reason);
                z.EnforceSso = true;
                Assert.Null(z.IssueLocalSession());
                z.EnforceSso = false;
                var s2 = z.IssueLocalSession()!;

                // 스트리밍 자산 암호화 — 2.5 프레임 · 왕복 · 변조 · 절단
                var plain = new byte[(int)(Master.ZeroTrustSecurityShieldService.FrameSize * 2.5)];
                new Random(3).NextBytes(plain);
                var pf = Path.Combine(root, "asset.bin"); var ef = Path.Combine(root, "asset.enc"); var df = Path.Combine(root, "asset.dec");
                File.WriteAllBytes(pf, plain);
                Assert.True(await z.EncryptFileAsync(s2.Token, pf, ef));
                Assert.True(await z.DecryptFileAsync(s2.Token, ef, df));
                Assert.True(File.ReadAllBytes(df).AsSpan().SequenceEqual(plain));
                var enc = File.ReadAllBytes(ef);
                var tampered = (byte[])enc.Clone(); tampered[tampered.Length / 2] ^= 0x40;
                File.WriteAllBytes(ef + ".t", tampered);
                Assert.False(await z.DecryptFileAsync(s2.Token, ef + ".t", df + ".t"));
                Assert.False(File.Exists(df + ".t"));
                File.WriteAllBytes(ef + ".cut", enc.AsSpan(0, 8 + 12 + 2 * (20 + Master.ZeroTrustSecurityShieldService.FrameSize)).ToArray());
                Assert.False(await z.DecryptFileAsync(s2.Token, ef + ".cut", df + ".c"));

                // 감사 체인 — 정상 → 변조 탐지
                Assert.True(z.VerifyAudit().Ok);
                Assert.True(z.DeniedCount >= 5);
                Assert.True(z.RotateKek(s2.Token));
            }
            using (var z2 = new Master.ZeroTrustSecurityShieldService(zdir, () => seed, null, null, true))
            {
                Assert.True(z2.Unlock());
                var s = z2.IssueLocalSession()!;
                using (var lease = z2.Lease(s.Token, "OPENAI_API_KEY")!) Assert.Equal("sk-test-12345", lease.Value.ToString());
                var v = z2.VerifyAudit();
                Assert.True(v.Ok, v.Message);
                var lines = File.ReadAllLines(Path.Combine(zdir, "audit.jsonl"));
                lines[3] = lines[3].Replace("\"detail\":\"", "\"detail\":\"X");
                File.WriteAllLines(Path.Combine(zdir, "audit.jsonl"), lines);
                var broken = z2.VerifyAudit();
                Assert.False(broken.Ok); Assert.Equal(4, broken.BrokenAt);
            }

            // 2) OIDC — RS256 · JWKS · iss/aud/exp/nonce · alg 고정 · PKCE · 디스커버리
            using var signer = System.Security.Cryptography.RSA.Create(2048);
            var meta = new Master.OidcMetadata("https://idp.example.com", "https://idp.example.com/authorize", "https://idp.example.com/token", "https://idp.example.com/jwks");
            var pub = signer.ExportParameters(false);
            var jwks = "{\"keys\":[{\"kty\":\"RSA\",\"kid\":\"k1\",\"n\":\"" + Master.ZeroTrustSecurityShieldService.B64Url(pub.Modulus) + "\",\"e\":\"" + Master.ZeroTrustSecurityShieldService.B64Url(pub.Exponent) + "\"}]}";
            var keys = Master.ZeroTrustSecurityShieldService.ParseJwks(jwks);
            Assert.True(keys.ContainsKey("k1"));
            using var zo = new Master.ZeroTrustSecurityShieldService(Path.Combine(root, "zo"), () => seed, null, null, false);
            zo.Unlock();
            zo.SetJwks(keys, meta, "pfs-client");
            var nowS = DateTimeOffset.UtcNow.ToUnixTimeSeconds();
            string Jwt(string alg, string kid, string payload, System.Security.Cryptography.RSA key)
            {
                var h = Master.ZeroTrustSecurityShieldService.B64Url(System.Text.Encoding.UTF8.GetBytes("{\"alg\":\"" + alg + "\",\"kid\":\"" + kid + "\"}"));
                var p = Master.ZeroTrustSecurityShieldService.B64Url(System.Text.Encoding.UTF8.GetBytes(payload));
                var sig = key.SignData(System.Text.Encoding.ASCII.GetBytes(h + "." + p), System.Security.Cryptography.HashAlgorithmName.SHA256, System.Security.Cryptography.RSASignaturePadding.Pkcs1);
                return h + "." + p + "." + Master.ZeroTrustSecurityShieldService.B64Url(sig);
            }
            string Payload(string aud = "pfs-client", long? exp = null, string nonce = "n-1") =>
                "{\"iss\":\"https://idp.example.com\",\"aud\":\"" + aud + "\",\"sub\":\"u1\",\"email\":\"kim@corp.com\",\"tid\":\"acme\",\"exp\":" + (exp ?? nowS + 600) + ",\"iat\":" + nowS + ",\"nonce\":\"" + nonce + "\",\"groups\":[\"PFS-Producers\"]}";
            var id = zo.ValidateIdToken(Jwt("RS256", "k1", Payload(), signer), "n-1");
            Assert.True(id.Valid, id.Reason);
            Assert.Equal("kim@corp.com", id.Subject); Assert.Equal("acme", id.Tenant); Assert.Equal(Master.ZtRole.Operator, id.Role);
            Assert.NotNull(zo.IssueSession(id));
            Assert.Equal("nonce 불일치(재전송 의심)", zo.ValidateIdToken(Jwt("RS256", "k1", Payload(), signer), "other").Reason);
            Assert.Equal("aud 불일치", zo.ValidateIdToken(Jwt("RS256", "k1", Payload(aud: "evil"), signer), "n-1").Reason);
            Assert.Equal("토큰 만료", zo.ValidateIdToken(Jwt("RS256", "k1", Payload(exp: nowS - 600), signer), "n-1").Reason);
            Assert.Equal("알 수 없는 kid", zo.ValidateIdToken(Jwt("RS256", "k9", Payload(), signer), "n-1").Reason);
            using (var attacker = System.Security.Cryptography.RSA.Create(2048))
                Assert.Equal("서명 불일치", zo.ValidateIdToken(Jwt("RS256", "k1", Payload(), attacker), "n-1").Reason);
            var noneTok = Master.ZeroTrustSecurityShieldService.B64Url("{\"alg\":\"none\"}"u8) + "." + Master.ZeroTrustSecurityShieldService.B64Url(System.Text.Encoding.UTF8.GetBytes(Payload())) + ".";
            Assert.False(zo.ValidateIdToken(noneTok, "n-1").Valid);
            var (verifier, challenge) = Master.ZeroTrustSecurityShieldService.CreatePkce();
            Assert.Equal(challenge, Master.ZeroTrustSecurityShieldService.B64Url(System.Security.Cryptography.SHA256.HashData(System.Text.Encoding.ASCII.GetBytes(verifier))));
            var ar = zo.BuildAuthorizationRequest("http://127.0.0.1:5000/callback/")!;
            Assert.Contains("code_challenge_method=S256", ar.Url); Assert.Contains("state=" + ar.State, ar.Url);
            Assert.Null(Master.ZeroTrustSecurityShieldService.ParseDiscovery("{\"issuer\":\"http://x\",\"authorization_endpoint\":\"https://a\",\"token_endpoint\":\"https://t\",\"jwks_uri\":\"https://j\"}"));

            // 3) SAML2 — XML-DSig · 조건 · XSW · 변조
            using var idpKey = System.Security.Cryptography.RSA.Create(2048);
            var certReq = new System.Security.Cryptography.X509Certificates.CertificateRequest("CN=Test IdP", idpKey, System.Security.Cryptography.HashAlgorithmName.SHA256, System.Security.Cryptography.RSASignaturePadding.Pkcs1);
            using var idpCert = certReq.CreateSelfSigned(DateTimeOffset.UtcNow.AddDays(-1), DateTimeOffset.UtcNow.AddDays(1));
            string Saml(DateTime notOnOrAfter, string nameId = "lee@corp.com", bool twoAssertions = false)
            {
                var xml = "<samlp:Response xmlns:samlp=\"urn:oasis:names:tc:SAML:2.0:protocol\"><saml:Assertion xmlns:saml=\"urn:oasis:names:tc:SAML:2.0:assertion\" ID=\"_a1\" Version=\"2.0\">"
                    + "<saml:Issuer>https://idp.example.com/saml</saml:Issuer><saml:Subject><saml:NameID>" + nameId + "</saml:NameID></saml:Subject>"
                    + "<saml:Conditions NotBefore=\"" + DateTime.UtcNow.AddMinutes(-5).ToString("yyyy-MM-ddTHH:mm:ssZ") + "\" NotOnOrAfter=\"" + notOnOrAfter.ToString("yyyy-MM-ddTHH:mm:ssZ") + "\">"
                    + "<saml:AudienceRestriction><saml:Audience>pfs-sp</saml:Audience></saml:AudienceRestriction></saml:Conditions>"
                    + "<saml:AttributeStatement><saml:Attribute Name=\"role\"><saml:AttributeValue>Admins</saml:AttributeValue></saml:Attribute><saml:Attribute Name=\"tenant\"><saml:AttributeValue>acme</saml:AttributeValue></saml:Attribute></saml:AttributeStatement>"
                    + "</saml:Assertion></samlp:Response>";
                var doc = new System.Xml.XmlDocument { PreserveWhitespace = true };
                doc.LoadXml(xml);
                var assertion = (System.Xml.XmlElement)doc.GetElementsByTagName("saml:Assertion")[0]!;
                var sx = new System.Security.Cryptography.Xml.SignedXml(assertion) { SigningKey = idpKey };
                var reference = new System.Security.Cryptography.Xml.Reference("#_a1");
                reference.AddTransform(new System.Security.Cryptography.Xml.XmlDsigEnvelopedSignatureTransform());
                reference.AddTransform(new System.Security.Cryptography.Xml.XmlDsigExcC14NTransform());
                sx.AddReference(reference);
                sx.SignedInfo.CanonicalizationMethod = System.Security.Cryptography.Xml.SignedXml.XmlDsigExcC14NTransformUrl;
                sx.ComputeSignature();
                assertion.AppendChild(doc.ImportNode(sx.GetXml(), true));
                if (twoAssertions)
                {
                    var evil = (System.Xml.XmlElement)assertion.CloneNode(true);
                    evil.SetAttribute("ID", "_evil");
                    doc.DocumentElement!.AppendChild(evil);
                }
                return doc.OuterXml;
            }
            var saml = zo.ValidateSaml(Saml(DateTime.UtcNow.AddMinutes(10)), idpCert, "https://idp.example.com/saml", "pfs-sp");
            Assert.True(saml.Valid, saml.Reason);
            Assert.Equal("lee@corp.com", saml.Subject); Assert.Equal(Master.ZtRole.Admin, saml.Role); Assert.Equal("acme", saml.Tenant);
            Assert.False(zo.ValidateSaml(Saml(DateTime.UtcNow.AddMinutes(10)).Replace("lee@corp.com", "attacker@corp.com"), idpCert, "https://idp.example.com/saml", "pfs-sp").Valid);
            Assert.False(zo.ValidateSaml(Saml(DateTime.UtcNow.AddMinutes(-10)), idpCert, "https://idp.example.com/saml", "pfs-sp").Valid);
            Assert.False(zo.ValidateSaml(Saml(DateTime.UtcNow.AddMinutes(10)), idpCert, "https://idp.example.com/saml", "other-sp").Valid);
            Assert.Contains("XSW", zo.ValidateSaml(Saml(DateTime.UtcNow.AddMinutes(10), twoAssertions: true), idpCert, "https://idp.example.com/saml", "pfs-sp").Reason);
            Assert.False(zo.ValidateSaml("<!DOCTYPE x [<!ENTITY e SYSTEM \"file:///c:/windows/win.ini\">]><x>&e;</x>", idpCert, "a", "b").Valid);

            // 4) CDC 델타 — 무할당 경계 · 삽입 내성 · 업로드/증분/복원/재사용/변조/릴레이/수렴 암호화
            var p = Master.CdcParams.Small;
            var data = new byte[600_000];
            new Random(9).NextBytes(data);
            var c1 = Master.CloudDeltaAssetSyncEngine.ChunkBuffer(data, p);
            Assert.True(c1.Count > 20);
            Assert.All(c1, c => Assert.InRange(c.Length, 1, p.Max));
            var edited = new byte[data.Length + 100];
            data.AsSpan(0, 300_000).CopyTo(edited); new Random(1).NextBytes(edited.AsSpan(300_000, 100)); data.AsSpan(300_000).CopyTo(edited.AsSpan(300_100));
            var c2 = Master.CloudDeltaAssetSyncEngine.ChunkBuffer(edited, p);
            var common = 0;
            var set1 = new HashSet<string>(c1.Select(c => c.Hash));
            foreach (var c in c2) if (set1.Contains(c.Hash)) common++;
            Assert.True(common >= c2.Count - 3, "공유 청크 " + common + "/" + c2.Count);
            var seq = new System.Buffers.ReadOnlySequence<byte>(data);
            var cutSum = 0;
            for (var i = 0; i < 16; i++) cutSum += Master.CloudDeltaAssetSyncEngine.FindCut(seq, p, true);
            var a0 = GC.GetAllocatedBytesForCurrentThread();
            for (var i = 0; i < 256; i++) cutSum += Master.CloudDeltaAssetSyncEngine.FindCut(seq, p, true);
            Assert.Equal(0, GC.GetAllocatedBytesForCurrentThread() - a0);
            Assert.True(cutSum > 0);

            using var zs = new Master.ZeroTrustSecurityShieldService(Path.Combine(root, "zs"), () => seed, null, null, false);
            zs.Unlock();
            var sess = zs.IssueLocalSession()!;
            var sync = new Master.CloudDeltaAssetSyncEngine(zs) { Params = p };
            var vfile = Path.Combine(root, "video.mp4");
            var big = new byte[2_500_000];
            new Random(5).NextBytes(big);
            File.WriteAllBytes(vfile, big);
            var store = new Master.LocalFolderChunkStore(Path.Combine(root, "cloud"), "cloud");
            Assert.False((await sync.UploadAsync(vfile, "video", store, null)).Ok);
            var up1 = await sync.UploadAsync(vfile, "video", store, sess.Token);
            Assert.True(up1.Ok, up1.Message); Assert.Equal(up1.Chunks, up1.Transferred + up1.Deduplicated); Assert.Equal(big.Length, up1.BytesTransferred);
            var m1 = await store.GetManifestAsync("video", default);
            Assert.Equal(Master.CloudDeltaAssetSyncEngine.ChunkBuffer(big, p).Count, m1!.Chunks.Count);
            var big2 = (byte[])big.Clone();
            new Random(6).NextBytes(big2.AsSpan(1_200_000, 5_000));
            File.WriteAllBytes(vfile, big2);
            var up2 = await sync.UploadAsync(vfile, "video", store, sess.Token);
            Assert.True(up2.Ok); Assert.True(up2.BytesTransferred < big.Length / 10, "증분 " + up2.BytesTransferred);
            Assert.True(up2.SavingRatio > 0.9);
            var restore = Path.Combine(root, "restore.mp4");
            var dn = await sync.DownloadAsync("video", store, restore, sess.Token);
            Assert.True(dn.Ok, dn.Message); Assert.True(File.ReadAllBytes(restore).AsSpan().SequenceEqual(big2));
            File.WriteAllBytes(restore, big);
            var dn2 = await sync.DownloadAsync("video", store, restore, sess.Token);
            Assert.True(dn2.Ok); Assert.True(dn2.Deduplicated > dn2.Transferred);
            Assert.True(File.ReadAllBytes(restore).AsSpan().SequenceEqual(big2));
            var victim = Directory.GetFiles(Path.Combine(root, "cloud", "chunks"), "*", SearchOption.AllDirectories)[0];
            var vb = File.ReadAllBytes(victim); vb[0] ^= 1; File.WriteAllBytes(victim, vb);
            var bad = await sync.DownloadAsync("video", store, Path.Combine(root, "fresh.mp4"), sess.Token);
            Assert.False(bad.Ok); Assert.False(File.Exists(Path.Combine(root, "fresh.mp4"))); Assert.False(File.Exists(Path.Combine(root, "fresh.mp4.delta.tmp")));
            vb[0] ^= 1; File.WriteAllBytes(victim, vb);
            var peer = new Master.LocalFolderChunkStore(Path.Combine(root, "peer"), "peer", seed);
            var relay = await sync.RelayAsync("video", store, peer);
            Assert.True(relay.Ok, relay.Message);
            var relay2 = await sync.RelayAsync("video", store, peer);
            Assert.Equal(0, relay2.Transferred);
            var anyPeerChunk = Directory.GetFiles(Path.Combine(root, "peer", "chunks"), "*", SearchOption.AllDirectories)[0];
            var hashName = Path.GetFileName(anyPeerChunk);
            var raw = File.ReadAllBytes(anyPeerChunk);
            Assert.NotEqual(hashName, Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(raw)));
            var peerPlain = (await peer.GetAsync(hashName, default))!;
            Assert.Equal(raw, Master.CloudDeltaAssetSyncEngine.ConvergentEncrypt(seed, hashName, peerPlain));
            Assert.True((await sync.DownloadAsync("video", peer, Path.Combine(root, "frompeer.mp4"), sess.Token)).Ok);
            Assert.Null(Master.CloudDeltaAssetSyncEngine.ParseManifest("{\"asset\":\"a\",\"size\":10,\"hash\":\"" + new string('a', 64) + "\",\"at\":\"2026-01-01T00:00:00Z\",\"chunks\":[[0,5,\"" + new string('b', 64) + "\"],[6,4,\"" + new string('c', 64) + "\"]]}"));
            Assert.False(Master.CloudDeltaAssetSyncEngine.IsSafeAssetId("../etc"));

            // 5) 오케스트레이터 — 30 모듈 매트릭스 · 인가 · 단계 실행/재시도/[부분 구제]/QA 차단
            var analytics = new Ix.InteractiveConversionAnalytics();
            var sp = new MapProvider { [typeof(Master.ZeroTrustSecurityShieldService)] = zs, [typeof(Ix.InteractiveConversionAnalytics)] = analytics, [typeof(Master.CloudDeltaAssetSyncEngine)] = sync };
            using var orch = new Master.UniversalMasterStudioOrchestrator(sp, zs);
            Assert.Equal(30, orch.ModuleCount);
            var matrix = orch.RefreshMatrix();
            Assert.Equal(30, matrix.Count);
            Assert.Equal(Master.ModuleHealth.Online, matrix.First(m => m.Id == "shield").Health);
            Assert.Equal(Master.ModuleHealth.Online, matrix.First(m => m.Id == "ixstats").Health);
            Assert.Equal(Master.ModuleHealth.Unavailable, matrix.First(m => m.Id == "jobs").Health);
            Assert.Equal(3, orch.OnlineModules);
            var proj = new SB.StoryboardProject { Title = "마스터" };
            proj.Scenes.Add(new SB.StoryboardScene { Prompt = "a baby smiling" });
            var denied = await orch.RunAsync(new Master.MasterRunRequest(proj), null);
            Assert.Equal(Master.StageOutcome.Failed, denied![0].Outcome); Assert.Contains("인가 거부", denied[0].Message);
            var final = Path.Combine(root, "final.mp4");
            File.WriteAllBytes(final, big2);
            var genCalls = 0;
            orch.SetExecutor(Master.MasterStage.Generate, (c, ct) =>
            {
                if (++genCalls == 1) throw new IOException("일시 오류");
                c.MasterVideo = final;
                return Task.FromResult(new Master.StageResult(Master.MasterStage.Generate, Master.StageOutcome.Done, "생성", TimeSpan.Zero, final));
            });
            orch.SetExecutor(Master.MasterStage.Qa, (c, ct) => { c.QaRejected = true; return Task.FromResult(new Master.StageResult(Master.MasterStage.Qa, Master.StageOutcome.Failed, "QA 반려", TimeSpan.Zero)); });
            orch.SetStageEnabled(Master.MasterStage.Dubbing, false);
            var res = await orch.RunAsync(new Master.MasterRunRequest(proj, "baby", ReuseExistingVideo: false, PublishTargets: new[] { SocialPublishTarget.YouTubeShorts }, DeltaStoreFolder: Path.Combine(root, "cloud")), sess.Token);
            Assert.NotNull(res);
            Assert.Equal(2, genCalls);
            Assert.Equal(Master.StageOutcome.Done, res!.First(r => r.Stage == Master.MasterStage.Plan).Outcome);
            Assert.Equal(Master.StageOutcome.Done, res.First(r => r.Stage == Master.MasterStage.CharacterId).Outcome);
            Assert.Contains(SB.CharacterIdentityLockService.IdentityPrompt, proj.Scenes[0].Prompt);
            Assert.Equal(Master.StageOutcome.Done, res.First(r => r.Stage == Master.MasterStage.Generate).Outcome);
            Assert.Equal("사용자 비활성", res.First(r => r.Stage == Master.MasterStage.Dubbing).Message);
            Assert.Equal(Master.StageOutcome.Failed, res.First(r => r.Stage == Master.MasterStage.Qa).Outcome);
            Assert.Contains("QA 반려", res.First(r => r.Stage == Master.MasterStage.Publish).Message);
            Assert.Equal(Master.StageOutcome.Skipped, res.First(r => r.Stage == Master.MasterStage.Live).Outcome);
            var ds = res.First(r => r.Stage == Master.MasterStage.DeltaSync);
            Assert.Equal(Master.StageOutcome.Done, ds.Outcome);
            Assert.Equal(2, orch.FailedRuns);
            Assert.True(zs.VerifyAudit().Ok);
        }
        finally
        {
            try { Directory.Delete(root, true); } catch { }
        }
    }

