            Assert.Same(typeof(PromptFlowStudio.Plugins.Sdk.IVideoEnginePlugin), plugin.GetType().GetInterface(nameof(PromptFlowStudio.Plugins.Sdk.IVideoEnginePlugin)));
            using (var fw2 = new ME.PluginExtensionMarketplaceFramework(root, () => key))
            {
                fw2.ScanAndLoad();
                Assert.Equal(ME.PluginStatus.Loaded, fw2.Plugins.First(p => p.Manifest.Id == "test-engine").Status);
            }
            using (var fw3 = new ME.PluginExtensionMarketplaceFramework(root, () => new byte[32]))
            {
                fw3.ScanAndLoad();
                Assert.Equal(ME.PluginStatus.Untrusted, fw3.Plugins.First(p => p.Manifest.Id == "test-engine").Status);
            }
            Assert.Equal(42, fw.Invoke("test-engine", x => x.Version.Length + 37));
            for (var i = 0; i < ME.PluginExtensionMarketplaceFramework.FaultLimit; i++)
                Assert.Equal(0, fw.Invoke<int>("test-engine", _ => throw new InvalidOperationException("plugin bug")));
            Assert.Equal(ME.PluginStatus.Faulted, fw.Plugins.First(p => p.Manifest.Id == "test-engine").Status);
            Assert.Empty(fw.EnginePlugins());
            fw.SetEnabled("test-engine", true);
            Assert.Single(fw.EnginePlugins());

            using var pr = new ME.GenerativeVideoMultiEngineRouter(new ME.GenerativePromptTranspilerEngine(), null, null);
            var plug = fw.EnginePlugins()[0];
            pr.Register("plugin:test-engine", "Test", ME.PromptDialect.Passthrough, plug.Capabilities, () => plug.Enabled, (r, p, ct) => fw.GenerateWithPluginAsync(plug, r, ct));
            var pres = await pr.GenerateAsync(new WanVideoRequest { Prompt = "hello", Size = "1280*720" });
            Assert.True(pres.Ok); Assert.Contains("plugin:hello", pres.VideoUrl);

            Assert.True(fw.EnableHotReload());
            var reloadsBefore = fw.Plugins.First(p => p.Manifest.Id == "warm-look").Reloads;
            File.WriteAllText(Path.Combine(root, "warm-look", "plugin.json"), "{\"id\":\"warm-look\",\"name\":\"Warm Look 2\",\"version\":\"1.1.0\",\"kind\":\"filter\",\"filterTemplate\":\"eq=saturation={sat}\",\"params\":[\"sat\"]}");
            var sw = Stopwatch.StartNew();
            while (fw.Plugins.First(p => p.Manifest.Id == "warm-look").Manifest.Version != "1.1.0" && sw.Elapsed < TimeSpan.FromSeconds(10)) await Task.Delay(50);
            Assert.Equal("1.1.0", fw.Plugins.First(p => p.Manifest.Id == "warm-look").Manifest.Version);
            Assert.True(fw.Plugins.First(p => p.Manifest.Id == "warm-look").Reloads > reloadsBefore);
            fw.DisableHotReload();
            Assert.True(fw.UnloadCount >= 1);
        }
        finally
        {
            try { Directory.Delete(root, true); } catch { }
        }
