            Assert.Equal(DT.HandGesture.Point, clip.DominantRight);
            Assert.True(clip.MotionEnergy > 0.001, "energy " + clip.MotionEnergy);
            var bvhLines = File.ReadAllLines(ch.ExportBvh(clip, Path.Combine(dir, "dance.bvh")));
            Assert.Equal("Frames: " + clip.Frames, bvhLines[Array.IndexOf(bvhLines, "MOTION") + 1]);

            // 9) 1-Click MV 구성 — 컷 = 비트 플랜 · 스타일/동작/가사/트윈 · BGM
            var twin = DT.AiDigitalTwinGeneratorEngine.Analyze(new byte[64 * 64 * 3].Select((_, i) => (byte)(i % 3 == 0 ? 220 : i % 3 == 1 ? 170 : 140)).ToArray(), 64, 64, "트윈");
            var mv = new SB.StoryboardProject();
            mv.Scenes.Add(new SB.StoryboardScene { Prompt = "old" });
            t1.Path = "C:/x/song.wav";
            var n = ch.ComposeMusicVideo(mv, sync, plan, cp, t1, twin);
            Assert.Equal(plan.Cuts.Count, n);
            Assert.Equal(n, mv.Scenes.Count);
            Assert.Equal("C:/x/song.wav", mv.BgmPath);
            Assert.All(mv.Scenes, s => { Assert.Contains("K-pop idol choreography", s.Prompt); Assert.Contains("photorealistic digital twin", s.Prompt); Assert.Contains("off-beat motion", s.NegativePrompt); });
            Assert.Contains(mv.Scenes, s => s.Prompt.Contains("singing \""));
            Assert.Equal("fadewhite", mv.Scenes[dropCut.Index].EnterTransition!.XfadeName);
            Assert.Equal(SB.FacialEmotion.Surprised, mv.Scenes[dropCut.Index].Emotion);

            // 10) 원격 어댑터(Suno 호환) — 제출/폴링/다운로드/WAV · 스키마 위반 → 즉시 BCL 폴백
            var wavPath = Path.Combine(dir, "remote.wav");
            Snd.SoundDsp.WriteStereoWav(wavPath, t1.Left.AsSpan(0, 22050 * 3), t1.Right.AsSpan(0, 22050 * 3), 22050);
            var wav = File.ReadAllBytes(wavPath);
            var polls = 0;
            var cfg = new Mus.MusicApiConfig("http://127.0.0.1:9/api", "k", "suno");
            Assert.True(cfg.IsConfigured);
            Assert.False(new Mus.MusicApiConfig("http://example.com/api", null, "suno").IsConfigured);
            var good = new MusicFakeHandler(r =>
            {
                var path = r.RequestUri!.AbsolutePath;
                if (path.EndsWith("/generate")) { Assert.Equal("Bearer", r.Headers.Authorization!.Scheme); return Json("{\"id\":\"job_1\"}"); }
                if (path.EndsWith("/status/job_1")) return Json(++polls < 2 ? "{\"status\":\"running\"}" : "{\"status\":\"complete\",\"audio_url\":\"http://127.0.0.1:9/a.wav\"}");
                return new HttpResponseMessage(System.Net.HttpStatusCode.OK) { Content = new ByteArrayContent(wav) };
            });
            using (var eng = new Mus.AiGenerativeMusicEngine(() => cfg, () => null, dir, good, TimeSpan.FromMilliseconds(5)))
            {
                var rt1 = await eng.GenerateAsync(req with { Seconds = 8 });
                Assert.NotNull(rt1);
                Assert.Equal("Suno API", rt1!.Source);
                Assert.Equal(22050 * 3, rt1.Left.Length);
                Assert.Equal(1, eng.RemoteOk);
                Assert.True(File.Exists(rt1.Path));
                Assert.Same(rt1, eng.Current);
            }
            var bad = new MusicFakeHandler(r => Json("{\"job\":\"no-id\"}"));
            using (var eng = new Mus.AiGenerativeMusicEngine(() => cfg, () => null, dir, bad))
            {
                var sw = Stopwatch.StartNew();
                var fb = await eng.GenerateAsync(req with { Seconds = 8 });
                Assert.NotNull(fb);
                Assert.Equal("BCL 신디사이저", fb!.Source);
                Assert.Equal(1, eng.Fallbacks);
                Assert.Contains("폴백", eng.LastAction);
                Assert.True(File.Exists(fb.Path));
                Assert.True(sw.ElapsedMilliseconds < 5000);
            }
            var down = new MusicFakeHandler(r => new HttpResponseMessage(System.Net.HttpStatusCode.ServiceUnavailable));
            using (var eng = new Mus.AiGenerativeMusicEngine(() => cfg, () => null, dir, down))
            {
                var sw = Stopwatch.StartNew();
                var fb = await eng.GenerateAsync(new Mus.MusicRequest(Mus.MusicGenre.Lofi, null, null, 6, Rate: 16000, AllowRemote: true));
                Assert.Equal("BCL 신디사이저", fb!.Source);
                Assert.True(sw.ElapsedMilliseconds < 1000 + 6000, "fallback " + sw.ElapsedMilliseconds);
            }
        }
        finally
        {
            try { Directory.Delete(dir, true); } catch { /* 무시 */ }
        }

        static HttpResponseMessage Json(string s) => new(System.Net.HttpStatusCode.OK) { Content = new StringContent(s, System.Text.Encoding.UTF8, "application/json") };
    }

    // ── v16.38.0: V-Tuber 페르소나 RAG · 브릿지(VMC/VTS/OBS/오버레이) · 후원 리액션 · 자율 방송 ──
    private static (System.Net.Sockets.TcpListener Listener, int Port) FakeWsServer(Func<System.Net.WebSockets.WebSocket, Task> handler)
    {
        var l = new System.Net.Sockets.TcpListener(System.Net.IPAddress.Loopback, 0);
        l.Start();
        _ = Task.Run(async () =>
        {
            using var c = await l.AcceptTcpClientAsync();
            var s = c.GetStream();
            var buf = new byte[4096]; var n = 0;
            while (!System.Text.Encoding.ASCII.GetString(buf, 0, n).Contains("\r\n\r\n")) n += await s.ReadAsync(buf.AsMemory(n));
            var req = System.Text.Encoding.ASCII.GetString(buf, 0, n);
            var key = req.Split("\r\n").First(h => h.StartsWith("Sec-WebSocket-Key:", StringComparison.OrdinalIgnoreCase))[18..].Trim();
            var accept = Convert.ToBase64String(System.Security.Cryptography.SHA1.HashData(System.Text.Encoding.ASCII.GetBytes(key + "258EAFA5-E914-47DA-95CA-C5AB0DC85B11")));
            await s.WriteAsync(System.Text.Encoding.ASCII.GetBytes("HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Accept: " + accept + "\r\n\r\n"));
            using var ws = System.Net.WebSockets.WebSocket.CreateFromStream(s, new System.Net.WebSockets.WebSocketCreationOptions { IsServer = true });
            try { await handler(ws); } catch { /* 클라이언트 종료 */ }
        });
        return (l, ((System.Net.IPEndPoint)l.LocalEndpoint).Port);
    }

    private static async Task<string> WsRecv(System.Net.WebSockets.WebSocket ws)
    {
        var buf = new byte[65536]; var n = 0;
        while (true) { var r = await ws.ReceiveAsync(buf.AsMemory(n), default); n += r.Count; if (r.EndOfMessage) break; }
        return System.Text.Encoding.UTF8.GetString(buf, 0, n);
    }

    private static Task WsSend(System.Net.WebSockets.WebSocket ws, string s) => ws.SendAsync(System.Text.Encoding.UTF8.GetBytes(s), System.Net.WebSockets.WebSocketMessageType.Text, true, default);

    private static async Task<bool> Until(Func<bool> cond, int ms = 4000)
    {
        var sw = Stopwatch.StartNew();
        while (sw.ElapsedMilliseconds < ms) { if (cond()) return true; await Task.Delay(20); }
        return cond();
    }

