            // 8) VTube Studio 공식 API 핸드셰이크(가짜 서버) → 파라미터 주입 수신
            var injected = new TaskCompletionSource<string>();
            var (vl, vport) = FakeWsServer(async ws =>
            {
                var m1 = await WsRecv(ws);
