/// <summary>v17.89.0 무할당 인텐트 검색 엔진 · 165 카탈로그 1:1 도움말 레지스트리 · 허브 모달/도움말 서랍/Ctrl+K/HUD 결선.</summary>
[Collection("TimingSensitivePerformance")]   // 검색 1 ms 벽시계 게이트 · 스레드 할당 바이트 계측 → 비병렬
public sealed class IntentNavigationIsolatedTests
{
    [Fact]
    public void IntentNavigation_And_ExhaustiveHelpRegistry_Check()
    {
        var cat = PromptFlowStudio.Services.Ui.StudioCatalog.Entries;
        var reg = PromptFlowStudio.Services.Ui.StudioCatalogHelpRegistry.Entries;

        // ── NAV-2: 165 카탈로그 1:1 도움말 — 누락 · 빈칸 · 임시 문구 · 끊긴 연관 링크 0 건 ──
        Assert.True(cat.Length >= 166);   // v17.90.0 이후 카탈로그 증가 허용
        Assert.Equal(cat.Length, reg.Count);
        var report = new List<string>();
        Assert.True(PromptFlowStudio.Services.Ui.StudioCatalogHelpRegistry.CountDefects(report) == 0, string.Join("\n", report));
        var keys = new HashSet<string>(StringComparer.Ordinal);
        foreach (var h in reg)
        {
            Assert.True(keys.Add(h.Key), "중복 도움말 " + h.Key);
            Assert.NotNull(PromptFlowStudio.Services.Ui.StudioCatalogHelpRegistry.Entry(h.Key));
            Assert.True(h.RoleSummary.Length >= 20, "역할 요약 과소 " + h.Key);
            for (var s = 0; s < 3; s++) Assert.StartsWith("Step " + (s + 1).ToString(System.Globalization.CultureInfo.InvariantCulture), h.QuickWorkflow[s]);
            Assert.DoesNotContain(h.Key, h.RelatedMenuIds);
        }
        foreach (var e in cat) Assert.NotNull(PromptFlowStudio.Services.Ui.StudioCatalogHelpRegistry.Find(e.Key));
        Assert.Equal("_vodRepurposing", PromptFlowStudio.Services.Ui.StudioCatalogHelpRegistry.ResolveKeyByHeader("📝 VOD 리퍼포징 & 아티클 스튜디오 · ⚙️ 변환 중"));
        Assert.Equal("sb:_spatialOpen", PromptFlowStudio.Services.Ui.StudioCatalogHelpRegistry.ResolveKeyByHeader("🥽 공간 비디오 & Vision Pro 스튜디오"));
        Assert.Null(PromptFlowStudio.Services.Ui.StudioCatalogHelpRegistry.ResolveKeyByHeader("알 수 없는 대화상자"));

        // ── NAV-1: 주요 자연어 질의 상위 랭킹 정확도 ──
        var hits = new PromptFlowStudio.Services.Ui.IntentHit[PromptFlowStudio.Services.Ui.CatalogIntentSearchEngine.MaxHits];
        static bool Any(string t, params string[] w) { foreach (var x in w) if (t.Contains(x, StringComparison.OrdinalIgnoreCase)) return true; return false; }
        void Expect(string q, params string[] titleWords)
        {
            var n = PromptFlowStudio.Services.Ui.CatalogIntentSearchEngine.Search(q, hits);
            Assert.InRange(n, 3, 5);
            for (var i = 1; i < n; i++) Assert.True(hits[i - 1].Score >= hits[i].Score, q + " 정렬");
            Assert.True(Any(hits[0].Entry.Title, titleWords), q + " 1위 = " + hits[0].Entry.Title);
            var top3 = 0;
            for (var i = 0; i < 3; i++) if (Any(hits[i].Entry.Title, titleWords)) top3++;
            Assert.True(top3 >= 2, q + " 상위 3 정확도 " + top3 + " · " + hits[0].Entry.Title + " / " + hits[1].Entry.Title + " / " + hits[2].Entry.Title);
            Assert.InRange(hits[0].FitPercent, 1, 99);
            Assert.False(string.IsNullOrEmpty(PromptFlowStudio.Services.Ui.CatalogIntentSearchEngine.DescribeReason(hits[0])));
        }
        Expect("자막", "자막", "캡션", "타이포", "더빙", "로컬라이제이션");
        Expect("송출", "송출", "스트리밍", "스트림", "RTMPS", "게이트웨이", "MCR", "방송");
        Expect("조명", "조명", "라이팅", "섀도우", "VFX");
        Expect("더빙", "더빙", "로컬라이제이션", "립싱크");
        Expect("쇼츠 자막 달기", "숏폼", "쇼츠", "Shorts", "릴스", "자막", "타이포", "클립");
        Expect("얼굴 립싱크", "페이셜", "립싱크", "아바타", "디지털 휴먼", "더빙");
        Assert.Equal(0, PromptFlowStudio.Services.Ui.CatalogIntentSearchEngine.Search("   ", hits));
        Assert.Equal(0, PromptFlowStudio.Services.Ui.CatalogIntentSearchEngine.Search("zzqqxx", hits));

        // 동의어: "캡션"(제목에 없음) → 자막 개념 경유 추천 · "RTMPS" → 송출 개념
        var nc = PromptFlowStudio.Services.Ui.CatalogIntentSearchEngine.Search("캡션", hits);
        Assert.True(nc >= 3 && (hits[0].ConceptMask & 1UL) != 0, "캡션 → #자막");
        nc = PromptFlowStudio.Services.Ui.CatalogIntentSearchEngine.Search("RTMPS", hits);
        Assert.True(nc >= 1 && (hits[0].ConceptMask & 2UL) != 0, "RTMPS → #송출");

        // ── 무할당 · 1 ms 미만 ──
        const string Q = "유튜브 라이브하고 싶어 조명 어둡게";
        for (var w = 0; w < 50; w++) PromptFlowStudio.Services.Ui.CatalogIntentSearchEngine.Search(Q, hits);
        var a0 = GC.GetAllocatedBytesForCurrentThread();
        var t0 = System.Diagnostics.Stopwatch.GetTimestamp();
        for (var r = 0; r < 200; r++) PromptFlowStudio.Services.Ui.CatalogIntentSearchEngine.Search(Q, hits);
        var ms = System.Diagnostics.Stopwatch.GetElapsedTime(t0).TotalMilliseconds;
        Assert.Equal(0L, GC.GetAllocatedBytesForCurrentThread() - a0);
        Assert.True(ms / 200 < 1.0, "평균 검색 " + (ms / 200).ToString("0.000", System.Globalization.CultureInfo.InvariantCulture) + " ms");

        // ── 러너(HUD NavRun) ──
        var nav = new PromptFlowStudio.Services.Ui.IntentNavigationRunner();
        var changes = 0;
        nav.OnChange += () => changes++;
        nav.Search("쇼츠 자막 달기");
        Assert.InRange(nav.HitCount, 3, 5);
        Assert.True(nav.Searches == 1 && nav.LastSearchUs > 0 && nav.PeakSearchUs >= nav.LastSearchUs);
        nav.NoteOpen(nav.Hit(0).Entry.Key);
        nav.NoteHelp("_intentNavigationHub");
        Assert.True(nav.Opens == 1 && nav.HelpViews == 1 && changes == 3 && nav.HelpDefects == 0 && nav.HelpCovered == cat.Length);
        Assert.StartsWith("도움말 · AI 인텐트", nav.LastAction);
        nav.Search("");
        Assert.Equal(0, nav.HitCount);

        // ── NAV-3/4: 결선(카탈로그 · 레이아웃 · DI 양쪽 · Ctrl+K · ? 주입 · HUD) ──
        var root = RepoRoot();
        string Src(params string[] p) => File.ReadAllText(Path.Combine(root, Path.Combine(p)));
        Assert.Contains(cat, e => e.Key == "_intentNavigationHub" && e.Category == 5);
        var layout = Src("PromptFlowStudio", "Blazor", "MainLayout.razor");
        Assert.Contains("<IntentNavigationHubStudioModal OnClose=", layout);
        Assert.Contains("case \"_intentNavigationHub\": _intentNavigationHub = on;", layout);
        Assert.Contains("\"_intentNavigationHub\" => _intentNavigationHub,", layout);
        Assert.Contains("<StudioHelpDrawer Key=", layout);
        Assert.Contains("Palette.IntentHubRequested -= OnIntentHotkey;", layout);
        Assert.Contains("IntentNavigationRunner", Src("PromptFlowStudio", "MainForm.cs"));
        Assert.Contains("IntentNavigationRunner", Src("PromptFlowStudio.Mobile", "MauiProgram.cs"));
        var js = Src("PromptFlowStudio", "wwwroot", "promptflow.js");
        Assert.Contains("invokeMethodAsync('OnIntentHotkey')", js);
        Assert.Contains("window.siteMaticStudioHelp", js);
        var hud = Src("PromptFlowStudio", "Blazor", "Components", "Common", "GlobalTelemetryHudView.razor");
        Assert.Contains("gth-v1789", hud);
        Assert.Contains("NavRun.OnChange -= OnSwarmChanged;", hud);
        var hub = Src("PromptFlowStudio", "Blazor", "Components", "Common", "IntentNavigationHubStudioModal.razor");
        Assert.Contains("@implements IDisposable", hub);
        Assert.Contains("@implements IDisposable", Src("PromptFlowStudio", "Blazor", "Components", "Common", "StudioHelpDrawer.razor"));
    }

    private static string RepoRoot()
    {
        var dir = new DirectoryInfo(AppContext.BaseDirectory);
        while (dir is not null && !File.Exists(Path.Combine(dir.FullName, "build_titan_release.ps1"))) dir = dir.Parent;
        return dir?.FullName ?? throw new DirectoryNotFoundException("저장소 루트를 찾지 못함");
    }
}

/// <summary>v17.90.0 원클릭 7 노드 바이럴 DAG · 인터락 서킷브레이커 · 멀티플랫폼 K-Factor 텔레메트리 · 마스터 콕핏 결선.</summary>
[Collection("TimingSensitivePerformance")]   // 스레드 할당 바이트 · 100 ms 판정 벽시계 계측 → 비병렬
public sealed class OmniViralGrowthIsolatedTests
{
    [Fact]
    public async Task OmniViralGrowth_And_MasterOrchestrator_Check()
    {
        const long Now = 1_790_000_000_000;
        var events = new List<Ovg.StageEvent>();
        void Drain(Ovg.OneClickAutonomousViralOrchestratorEngine en) { while (en.Events.TryRead(out var ev)) events.Add(ev); }

        // ── OVP-1: 7 단계 DAG 완주 · 산출물 · 위상 순서 · 진행 이벤트 ──
        var eng = new Ovg.OneClickAutonomousViralOrchestratorEngine();
        var ctx = eng.Context;
        ctx.Load(600, 7, highlight: true);
        ctx.RefreshToken(Now);
        Assert.True(eng.Start());
        Assert.Equal(Ovg.PipelineRunState.Completed, eng.RunToBoundary());
        Drain(eng);
        for (var s = 0; s < 7; s++) Assert.True(ctx.States[s] == Ovg.StageState.Done && ctx.Progress[s] == 100 && ctx.Artifact[s] != 0, "노드 " + s);
        Assert.Equal(30, ctx.ClipSeconds);
        Assert.Equal(0, ctx.ClipStartSec % Ovg.ViralPipelineContext.GopSeconds);
        Assert.InRange(ctx.PeakSec, ctx.ClipStartSec, ctx.ClipEndSec);
        Assert.True(ctx.Total >= 70 && ctx.Grade >= PromptFlowStudio.Services.ViralExport.ViralGrade.B, "스코어 " + ctx.Total);
        Assert.True(ctx.Words == 78 && ctx.DubTracks == 3 && ctx.WordStartMs[ctx.Words - 1] > ctx.WordStartMs[1]);
        for (var p = 0; p < 4; p++)
        {
            Assert.True(ctx.VariantBytes[p] > 0 && ctx.VariantSec[p] == 30, "변형 " + p);
            Assert.Equal(ctx.SlotUnixMs[0] + Ovg.ViralPipelineContext.StaggerMinutes[p] * 60_000L, ctx.SlotUnixMs[p]);
        }
        Assert.True(ctx.SlotUnixMs[0] > Now && ctx.SlotUnixMs[0] % 3_600_000 == 0);
        Assert.True(ctx.ArticleChars == 1320 && ctx.Chapters == 2 && ctx.VaultParts >= 1 && ctx.VaultBytes > ctx.VariantBytes[0]);
        Assert.Equal(7 * (1 + Ovg.OneClickAutonomousViralOrchestratorEngine.SlicesPerStage), events.Count);
        var doneAt = new int[7];
        for (var i = 0; i < events.Count; i++)
        {
            Assert.Equal(i + 1, events[i].Seq);
            if (events[i].State == Ovg.StageState.Done) doneAt[(int)events[i].Stage] = i;
        }
        for (var s = 1; s < 7; s++) Assert.True(doneAt[s] > doneAt[0], "① 선행 " + s);
        Assert.True(doneAt[6] > doneAt[3] && doneAt[6] > doneAt[5] && doneAt[4] > doneAt[3] && doneAt[2] > doneAt[1]);

        // 무할당: 동일 컨텍스트 재실행(캐시 미사용) + 채널 드레인
        var clipArtifact = ctx.Artifact[0];
        Assert.True(eng.Start(reuseArtifacts: false));
        var a0 = GC.GetAllocatedBytesForCurrentThread();
        eng.RunToBoundary();
        var drained = 0;
        while (eng.Events.TryRead(out _)) drained++;
        Assert.Equal(0, GC.GetAllocatedBytesForCurrentThread() - a0);
        Assert.True(eng.RunState == Ovg.PipelineRunState.Completed && drained == 77 && ctx.Artifact[0] == clipArtifact);

        // 재실행(캐시) → 7 노드 전부 스킵 = 중복 렌더 0
        Assert.True(eng.Start());
        Assert.Equal(Ovg.PipelineRunState.Completed, eng.RunToBoundary());
        Assert.Equal(7, eng.ReusedStages);
        for (var s = 0; s < 7; s++) Assert.Equal(Ovg.StageState.Skipped, ctx.States[s]);
        Drain(eng);

        // ── OVP-3: C 등급 인터락 → 독립 분기(⑥) 진행 · 승인 시 재계산 없이 재개 ──
        ctx.Load(600, 7, highlight: false);
        Assert.True(eng.Start());
        Assert.Equal(Ovg.PipelineRunState.AwaitingApproval, eng.RunToBoundary());
        Assert.True(ctx.Total < 70 && ctx.Grade == PromptFlowStudio.Services.ViralExport.ViralGrade.C, "평범한 소스 " + ctx.Total);
        Assert.True(ctx.States[1] == Ovg.StageState.Halted && ctx.States[5] == Ovg.StageState.Done && ctx.States[2] == Ovg.StageState.Pending && ctx.States[6] == Ovg.StageState.Pending);
        var g = eng.Guard;
        Assert.True(g.State == Ovg.GuardState.AwaitingApproval && g.Reason == Ovg.HaltReason.LowScore && g.HaltedStage == Ovg.ViralStage.Score);
        Assert.True(g.CheckpointMask == ((1 << 0) | (1 << 5)) && g.VerifyCheckpoint(ctx));
        var lowTotal = ctx.Total; var lowClip = ctx.Artifact[0];
        Assert.False(eng.Start());   // 승인 대기 중 재시작 거부
        Assert.True(eng.ApproveAndResume());
        Assert.Equal(Ovg.PipelineRunState.Completed, eng.RunToBoundary());
        Assert.True(ctx.Total == lowTotal && ctx.Artifact[0] == lowClip && g.VerifyCheckpoint(ctx) && eng.CheckpointReuses >= 2 && g.Approvals == 1);

        // 거부 → 산출물 보존 · 중단
        ctx.Load(900, 3, highlight: false);
        eng.Start();
        eng.RunToBoundary();
        eng.Abort();
        Assert.True(eng.RunState == Ovg.PipelineRunState.Aborted && g.Rejections == 1 && ctx.Artifact[0] != 0 && ctx.States[0] == Ovg.StageState.Done);

        // 토큰 만료 → ⑤ 중단 · ⑦ 은 ④+⑥ 으로 완료 · 갱신 승인 시 ⑤ 만 재실행
        ctx.Load(600, 11, highlight: true);
        ctx.TokenExpiresUnixMs = ctx.NowUnixMs + 30_000;   // 스큐 60 s 이내 = 만료 취급
        Assert.True(eng.Start());
        Assert.Equal(Ovg.PipelineRunState.AwaitingApproval, eng.RunToBoundary());
        Assert.True(g.Reason == Ovg.HaltReason.TokenExpired && ctx.States[4] == Ovg.StageState.Halted && ctx.States[6] == Ovg.StageState.Done);
        var variantArt = ctx.Artifact[3];
        ctx.RefreshToken(Now);
        Assert.True(eng.ApproveAndResume());
        Assert.Equal(Ovg.PipelineRunState.Completed, eng.RunToBoundary());
        Assert.True(ctx.Artifact[3] == variantArt && ctx.SlotUnixMs[0] > 0 && ctx.States[4] == Ovg.StageState.Done);

        // 연속 예외 3 회 → 차단기 개방 · 쿨다운 전 시작 거부
        var trip = new Ovg.OneClickAutonomousViralOrchestratorEngine();
        trip.Context.Load(300, 5, true);
        trip.Context.RefreshToken(Now);
        trip.InjectFaultStage = 2;
        Assert.True(trip.Start());
        Assert.Equal(Ovg.PipelineRunState.AwaitingApproval, trip.RunToBoundary());
        Assert.Equal(Ovg.HaltReason.StageFault, trip.Guard.Reason);
        for (var k = 0; k < 2; k++) { trip.InjectFaultStage = 2; trip.ApproveAndResume(); trip.RunToBoundary(); }
        Assert.True(trip.RunState == Ovg.PipelineRunState.Aborted && trip.Guard.State == Ovg.GuardState.Tripped && trip.Guard.Trips == 1 && trip.Context.States[2] == Ovg.StageState.Failed);
        Assert.True(trip.Context.States[0] == Ovg.StageState.Done && trip.Context.States[1] == Ovg.StageState.Done && trip.Context.States[5] == Ovg.StageState.Done, "직전 완료 단계 보존");
        Assert.False(trip.Start());
        trip.Context.NowUnixMs += 31_000;
        Assert.True(trip.Start());
        Assert.Equal(Ovg.PipelineRunState.Completed, trip.RunToBoundary());
        Assert.True(trip.ReusedStages == 3, "쿨다운 후 ①②⑥ 캐시 재사용 " + trip.ReusedStages);

        // ── OVP-2: API 응답 파싱 · 정규화 · K ≥ 1.2 3 틱 지속 트리거 · 재무장 ──
        var tel = new Ovg.MultiPlatformGrowthTelemetryAggregator { ClipSeconds = 30 };
        var yt = "{\"kind\":\"youtube#videoListResponse\",\"items\":[{\"id\":\"abc\",\"statistics\":{\"viewCount\":\"20000\",\"likeCount\":\"1200\",\"commentCount\":\"77\"}}]}"u8.ToArray();
        var ya = "{\"columnHeaders\":[{\"name\":\"views\",\"columnType\":\"METRIC\"},{\"name\":\"likes\"},{\"name\":\"shares\"},{\"name\":\"averageViewDuration\"}],\"rows\":[[20000,1200,900,24.5]]}"u8.ToArray();
        var ig = "{\"data\":[{\"name\":\"plays\",\"period\":\"lifetime\",\"values\":[{\"value\":10000}]},{\"name\":\"likes\",\"values\":[{\"value\":800}]},{\"name\":\"shares\",\"values\":[{\"value\":450}]},{\"name\":\"ig_reels_avg_watch_time\",\"values\":[{\"value\":21000}]}]}"u8.ToArray();
        Assert.True(tel.IngestYouTubeJson(yt) && tel.Views(0) == 20000 && tel.Likes(0) == 1200);
        Assert.True(tel.IngestYouTubeJson(ya) && tel.Shares(0) == 900 && Math.Abs(tel.WatchSeconds(0) - 24.5) < 1e-9);
        Assert.True(tel.IngestInstagramJson(ig) && tel.Views(1) == 10000 && tel.Shares(1) == 450 && Math.Abs(tel.WatchSeconds(1) - 21) < 1e-9);
        Assert.False(tel.IngestYouTubeJson("{\"items\":[{"u8));
        Assert.False(tel.IngestInstagramJson("{\"data\":[]}"u8));
        Assert.Equal(2, tel.ParseErrors);
        Assert.False(tel.Evaluate());
        Assert.True(tel.KFactor >= 1.2 && tel.TotalViews == 30000 && tel.Index(0) > 50 && tel.Index(1) > 50, "K " + tel.KFactor);
        Assert.False(tel.Evaluate());
        Assert.True(tel.Evaluate());   // 3 틱 연속 → 1 회 발화
        Assert.False(tel.Evaluate());  // 재무장 전 재발화 없음
        tel.Ingest(0, 40000, 1300, 100, 10); tel.Ingest(1, 20000, 900, 60, 9);
        Assert.False(tel.Evaluate());
        Assert.True(tel.KFactor < 1.0);
        tel.Ingest(0, 50000, 3000, 2500, 25); tel.Ingest(1, 25000, 2000, 1200, 22);
        tel.Evaluate(); tel.Evaluate();
        Assert.True(tel.Evaluate() && tel.Triggers == 2);
        // 무할당 · 100 ms 판정 예산
        tel.IngestYouTubeJson(ya); tel.IngestInstagramJson(ig); tel.Evaluate();
        var sw = Stopwatch.StartNew();
        var a1 = GC.GetAllocatedBytesForCurrentThread();
        for (var r = 0; r < 1000; r++)
        {
            tel.IngestYouTubeJson(ya);
            tel.IngestInstagramJson(ig);
            tel.Ingest(2, 5000 + r, 300, 120, 18);
            tel.Evaluate();
        }
        var alloc1 = GC.GetAllocatedBytesForCurrentThread() - a1;
        sw.Stop();
        Assert.Equal(0, alloc1);
        Assert.True(sw.Elapsed.TotalMilliseconds / 1000 < 100, "판정 " + sw.Elapsed.TotalMilliseconds);

        // ── 러너: 원클릭 · 토큰 인터락 승인 · 성장 → 추가 신디케이션 ──
        using (var run = new Ovg.OmniViralGrowthStudioRunner { SliceDelayMs = 0 })
        {
            var changes = 0;
            run.OnChange += () => Interlocked.Increment(ref changes);
            Assert.True(await run.RunAsync(), run.LastAction);
            Assert.True(run.Engine.CompletedCount == 7 && run.Runs == 1 && run.Failures == 0 && run.EventCount == Ovg.OmniViralGrowthStudioRunner.LogSize && changes > 0);
            Assert.Equal(Ovg.ViralStage.Vault, run.RecentEvent(0).Stage);
            run.ToggleTokenExpiry();
            Assert.True(await run.RunAsync());   // 캐시 히트 → ⑤ 포함 전 노드 스킵(토큰 검사 불요)
            Assert.Equal(7, run.Engine.ReusedStages);
            run.SetMinutes(20);
            Assert.False(await run.RunAsync());
            Assert.True(run.Engine.RunState == Ovg.PipelineRunState.AwaitingApproval && run.Guard.Reason == Ovg.HaltReason.TokenExpired, run.LastAction);
            Assert.True(await run.Approve(), run.LastAction);
            Assert.True(!run.SimulateTokenExpiry && run.Engine.CheckpointReuses >= 4);
            run.Telemetry.ClipSeconds = run.Context.ClipSeconds;
            for (var t = 0; t < 120 && run.SyndicationWaves == 0; t++) run.TelemetryTick();
            Assert.True(run.SyndicationWaves >= 1 && run.Telemetry.PeakK >= 1.2, "K " + run.Telemetry.KFactor + " / " + run.Grade());
            run.SetSource(false);
            run.Reset();
            Assert.True(run.Runs == 0 && run.Engine.RunState == Ovg.PipelineRunState.Idle && run.EventCount == 0 && !run.Highlight);
        }

        // ── OVP-4: 카탈로그 166 · 도움말 · HUD · 레이아웃 · DI · 모달 규격 · 외부 의존 0 · 모달 렌더 ──
        var cat = PromptFlowStudio.Services.Ui.StudioCatalog.Entries;
        Assert.True(cat.Length >= 166);   // v17.91.0 이후 카탈로그 증가 허용
        Assert.Contains(cat, en => en.Key == "_omniViralMasterCockpit" && en.Category == 4 && en.Title == "옴니 바이럴 그로스 마스터 콕핏");
        Assert.Equal(cat.Length, PromptFlowStudio.Services.Ui.StudioCatalogHelpRegistry.Entries.Count);
        Assert.Equal(0, PromptFlowStudio.Services.Ui.StudioCatalogHelpRegistry.CountDefects());
        Assert.Equal("_omniViralMasterCockpit", PromptFlowStudio.Services.Ui.StudioCatalogHelpRegistry.ResolveKeyByHeader("👑 옴니 바이럴 그로스 마스터 콕핏 · ⚙️ 가동 중"));
        var root = RepoRoot();
        string Src(params string[] p) => File.ReadAllText(Path.Combine(root, Path.Combine(p)));
        var hud = Src("PromptFlowStudio", "Blazor", "Components", "Common", "GlobalTelemetryHudView.razor");
        var layout = Src("PromptFlowStudio", "Blazor", "MainLayout.razor");
        var modalSrc = Src("PromptFlowStudio", "Blazor", "Components", "Common", "OmniViralGrowthMasterCockpitStudioModal.razor");
        Assert.True(hud.IndexOf("gth-v1790", StringComparison.Ordinal) is > 0 and var i1790 && i1790 < hud.IndexOf("gth-v1789", StringComparison.Ordinal) && hud.Contains("OvgRun.OnChange += OnSwarmChanged", StringComparison.Ordinal) && hud.Contains("OvgRun.OnChange -= OnSwarmChanged", StringComparison.Ordinal));
        Assert.True(layout.Contains("<OmniViralGrowthMasterCockpitStudioModal", StringComparison.Ordinal) && layout.Contains("case \"_omniViralMasterCockpit\"", StringComparison.Ordinal) && layout.Contains("\"_omniViralMasterCockpit\" =>", StringComparison.Ordinal));
        Assert.True(Src("PromptFlowStudio", "MainForm.cs").Contains("OmniViral.OmniViralGrowthStudioRunner(sp)", StringComparison.Ordinal) && Src("PromptFlowStudio.Mobile", "MauiProgram.cs").Contains("OmniViral.OmniViralGrowthStudioRunner(sp)", StringComparison.Ordinal));
        Assert.True(modalSrc.Contains("@implements IDisposable", StringComparison.Ordinal) && modalSrc.Contains("flex: 1 1 auto; min-height: 0; overflow-y: auto;", StringComparison.Ordinal) && modalSrc.Contains("position: sticky", StringComparison.Ordinal) && modalSrc.Contains("aria-pressed", StringComparison.Ordinal));
        foreach (var src in Directory.GetFiles(Path.Combine(root, "PromptFlowStudio", "Services", "OmniViral"), "*.cs"))
        {
            var text = File.ReadAllText(src);
            Assert.True(!text.Contains("System.Linq", StringComparison.Ordinal) && !text.Contains("Process.Start", StringComparison.Ordinal) && !text.Contains("HttpClient", StringComparison.Ordinal) && !text.Contains("File.Write", StringComparison.Ordinal), "외부 의존 · 파일 I/O " + Path.GetFileName(src));
        }
        using var sp = new HeadlessUiRendererCheck.AutoWireProvider();
        var runner = (Ovg.OmniViralGrowthStudioRunner)sp.GetService(typeof(Ovg.OmniViralGrowthStudioRunner))!;
        Assert.True(runner.LinkedCount == 7, "연동 " + runner.LinkedCount);
        var html = await HeadlessUiRendererCheck.RenderAsync(typeof(PromptFlowStudio.Blazor.Components.Common.OmniViralGrowthMasterCockpitStudioModal), sp);
        Assert.True(html.Length > 500 && html.Contains("ovg-scrim", StringComparison.Ordinal) && html.Contains("ovg-body", StringComparison.Ordinal) && html.Contains("원클릭 전자동 실행", StringComparison.Ordinal) && html.Contains("오토파일럿", StringComparison.Ordinal) && html.Contains("ovg-node", StringComparison.Ordinal), "모달 렌더 " + html.Length);
        Assert.Equal(0, HeadlessUiRendererCheck.LiveSubscriberCount(runner));
        GC.Collect(); GC.WaitForPendingFinalizers(); GC.Collect();
    }

    private static string RepoRoot()
    {
        var dir = new DirectoryInfo(AppContext.BaseDirectory);
        while (dir is not null && !File.Exists(Path.Combine(dir.FullName, "build_titan_release.ps1"))) dir = dir.Parent;
        return dir?.FullName ?? throw new DirectoryNotFoundException("저장소 루트를 찾지 못함");
    }
}

/// <summary>v17.91.0 음향 지문 Content ID 분석 · 로열티 프리 BGM 치환 · 브랜드 세이프티 · 저작권 검역 콕핏 결선.</summary>
[Collection("TimingSensitivePerformance")]   // 프레임 1 ms 판정 벽시계 · 스레드 할당 바이트 계측 → 비병렬
public sealed class CopyrightComplianceIsolatedTests
{
    [Fact]
    public async Task CopyrightCompliance_And_ContentIdAnalyzer_Check()
    {
        const int Fs = Cpy.AcousticFingerprintContentIdAnalyzerEngine.Fs;

        // ── CPY-1: 지문 DB · 침해 구간 검출 · 10 ms 타임코드 · 무할당 · 1 ms 판정 ──
        var an = new Cpy.AcousticFingerprintContentIdAnalyzerEngine();
        Assert.True(an.IndexedHashes > 3_000 && an.TableDropped == 0, "DB " + an.IndexedHashes);
        var clip = new float[Cpy.CopyrightComplianceStudioRunner.ClipSamples];
        Cpy.CopyrightComplianceStudioRunner.BuildClip(clip, 1);
        var risk = an.Analyze(clip);
        var trace = new System.Text.StringBuilder();
        for (var w = 0; w < an.Windows; w++) trace.Append(an.WindowRisk(w).ToString("0", System.Globalization.CultureInfo.InvariantCulture)).Append('/').Append(an.WindowTrack(w)).Append(':').Append(an.WindowVotes(w)).Append('/').Append(an.WindowHashes(w)).Append(' ');
        Assert.True(risk >= 70 && an.MatchedTrack == 1 && an.SegmentCount == 1, "위험 " + risk + " · " + trace);
        var seg = an.Segment(0);
        Assert.True(seg.Track == 1 && seg.StartMs % 10 == 0 && seg.EndMs % 10 == 0, "구간 " + seg.StartMs + "~" + seg.EndMs);
        Assert.True(Math.Abs(seg.StartMs - 5000) <= 120 && Math.Abs(seg.EndMs - 13000) <= 120, "구간 " + seg.StartMs + "~" + seg.EndMs + " · " + trace);
        var hz = new float[Cpy.RoyaltyFreeBgmAutoSubstitutionMixer.MaxNotches];
        var notches = an.CollectSegmentPeakHz(0, hz);
        Assert.True(notches >= 4 && hz[0] > 50 && hz[0] < 12000, "노치 " + notches);
        var clean = new float[clip.Length];
        Cpy.CopyrightComplianceStudioRunner.BuildClip(clean, -1);
        Assert.True(an.Analyze(clean) < 70 && an.SegmentCount == 0, "무음원 위험 " + an.RiskIndex);
        for (var t = 0; t < 3; t++)
        {
            Cpy.CopyrightComplianceStudioRunner.BuildClip(clip, t);
            Assert.True(an.Analyze(clip) >= 70 && an.MatchedTrack == t, "트랙 " + t + " " + an.RiskIndex);
        }
        var a0 = GC.GetAllocatedBytesForCurrentThread();
        an.Analyze(clip);
        Assert.Equal(0, GC.GetAllocatedBytesForCurrentThread() - a0);
        Assert.True(an.FrameUs < 1000 && an.Frames == (clip.Length - Cpy.AcousticFingerprintContentIdAnalyzerEngine.FftSize) / Cpy.AcousticFingerprintContentIdAnalyzerEngine.Hop + 1, "프레임 " + an.FrameUs + "µs");
        // 스트리밍 공급(임의 블록) = 일괄 분석
        an.BeginRun();
        for (var o = 0; o < clip.Length; o += 777) an.Feed(clip.AsSpan(o, Math.Min(777, clip.Length - o)));
        an.Finish();
        Assert.True(an.RiskIndex >= 70 && an.SegmentCount == 1);

        // ── CPY-2: 치환 · −14 LUFS · 클리핑 0 · 재분석 안전 · 무할당 ──
        var mix = new Cpy.RoyaltyFreeBgmAutoSubstitutionMixer();
        for (var s = 0; s < 3; s++) Assert.True(mix.Loop((Cpy.BgmStyle)s).Length == Fs * 60 / Cpy.RoyaltyFreeBgmAutoSubstitutionMixer.Bpm[s] * 8);
        Cpy.CopyrightComplianceStudioRunner.BuildClip(clip, 1);
        an.Analyze(clip);
        var segs = an.Segments.ToArray();
        notches = an.CollectSegmentPeakHz(0, hz);
        var work = (float[])clip.Clone();
        mix.Style = Cpy.BgmStyle.Synthwave;
        a0 = GC.GetAllocatedBytesForCurrentThread();
        mix.Substitute(work, segs, hz.AsSpan(0, notches));
        var lufs = mix.Normalize(work);
        Assert.Equal(0, GC.GetAllocatedBytesForCurrentThread() - a0);
        Assert.True(Math.Abs(lufs + 14) <= 0.5 && mix.ClippedSamples == 0 && mix.PeakDbfs <= -0.9f, "LUFS " + lufs + " 피크 " + mix.PeakDbfs);
        Assert.True(Math.Abs(mix.LastCancelGain - 0.7f) < 0.05f && mix.LastCancelDb < -10 && mix.VoiceOpenRatio is > 0.3 and < 0.97 && mix.NotchCount == notches, "소거 g " + mix.LastCancelGain + " " + mix.LastCancelDb + "dB 보컬 " + mix.VoiceOpenRatio);
        var post = an.Analyze(work);
        trace.Clear();
        for (var w = 0; w < an.Windows; w++) trace.Append(an.WindowRisk(w).ToString("0", System.Globalization.CultureInfo.InvariantCulture)).Append('/').Append(an.WindowTrack(w)).Append(':').Append(an.WindowVotes(w)).Append('/').Append(an.WindowHashes(w)).Append(' ');
        Assert.True(post < 70 && an.SegmentCount == 0, "치환 후 위험 " + post + " · " + trace);
        Assert.True(Math.Abs(mix.MeasureLufs(work) + 14) <= 0.5);
        // 치환 구간 밖 원음 보존(크로스페이드 ±120 ms 바깥 · 정규화 이득만 적용)
        var g = (float)Math.Pow(10, (-14 - mix.PreLufs) / 20);
        Assert.True(Math.Abs(work[Fs] - clip[Fs] * g) < 0.02f + Math.Abs(clip[Fs] * g) * 0.05f, "보존 " + work[Fs] + " / " + clip[Fs] * g);

        // ── CPY-3: 50 금칙어 · 우회 · 허용 목록 · 마스킹 · 비프 · 무할당 ──
        var guard = new Cpy.PlatformPolicyBrandSafetyGuard();
        Assert.Equal(60, Cpy.PlatformPolicyBrandSafetyGuard.Terms.Length);
        var policy = 0;
        for (var t = 0; t < Cpy.PlatformPolicyBrandSafetyGuard.Terms.Length; t++) if (Cpy.PlatformPolicyBrandSafetyGuard.CategoryOf(t) != Cpy.PolicyCategory.Trademark) policy++;
        Assert.Equal(Cpy.PlatformPolicyBrandSafetyGuard.PolicyTerms, policy);
        var text = "오늘 폭 탄 제 조 얘기는 없고 P.O.R.N 도 아님. 대마도 여행 + 마약김밥 먹방, 나이키 협찬.";
        Assert.Equal(3, guard.Scan(text));
        Assert.True(guard.PolicyHitCount == 2 && guard.TrademarkHitCount == 1);
        var dst = new char[text.Length * 2];
        var wn = guard.Mask(text, dst);
        var masked = new string(dst, 0, wn);
        Assert.Equal("오늘 *** 얘기는 없고 *** 도 아님. 대마도 여행 + 마약김밥 먹방, *** 협찬.", masked);
        Assert.Equal(0, guard.Scan(masked));
        guard.ClearBeeps();
        guard.MaskCue(text, 1000, 5000, dst);
        Assert.True(guard.BeepCount == 3 && guard.Beep(0).StartMs >= 1000 && guard.Beep(2).EndMs <= 5000);
        var pcm = new float[6 * Fs];
        Assert.True(guard.RenderBeeps(pcm) > 0 && pcm.Max() > 0.2f && pcm.Max() <= 0.26f);
        a0 = GC.GetAllocatedBytesForCurrentThread();
        for (var r = 0; r < 100; r++) { guard.Mask(text, dst); guard.Scan(Cpy.CopyrightComplianceStudioRunner.DefaultScript); }
        Assert.Equal(0, GC.GetAllocatedBytesForCurrentThread() - a0);

        // ── 러너: 검역 → Safe to Publish · 비교/재생 토글 · 무음원 ──
        using (var run = new Cpy.CopyrightComplianceStudioRunner())
        {
            var changes = 0;
            run.OnChange += () => Interlocked.Increment(ref changes);
            var okA = await run.AuditAsync();
            var tra = new System.Text.StringBuilder();
            for (var w = 0; w < run.Windows; w++) tra.Append(run.WindowRiskAfter(w).ToString("0")).Append(' ');
            Assert.True(okA, run.LastAction + " · " + run.Segment(0).StartMs + "~" + run.Segment(0).EndMs + " · " + tra);
            Assert.True(run.RiskBefore >= 70 && run.RiskAfter < 70 && run.SegmentCount == 1 && run.SafeToPublish && run.MatchedTrack == 0 && changes > 0, run.LastAction);
            Assert.True(run.HitCount == 3 && run.ResidualHits == 0 && run.MaskedScript!.Contains("***", StringComparison.Ordinal) && run.MaskedScript.Contains("대마도", StringComparison.Ordinal), run.MaskedScript);
            Assert.True(run.Windows >= 39 && run.WindowRiskBefore(14) >= 70 && run.WindowRiskAfter(14) < 70 && run.PeakOriginal(100) > 0 && run.PeakSubstituted(100) > 0);
            var mon = run.MonitorSubstituted;
            run.ToggleMonitor();
            Assert.NotEqual(mon, run.MonitorSubstituted);
            run.TogglePlay();
            Assert.True(run.Playing);
            for (var i = 0; i < 60; i++) run.PlayTick();
            Assert.True(run.PlayheadMs >= 6000 && run.PlayheadInSegment());
            run.TogglePlay();
            Assert.False(run.Playing);
            run.SetTrack(-1);
            run.SetStyle(Cpy.BgmStyle.HipHop);
            Assert.False(run.Audited);
            Assert.True(await run.AuditAsync(), run.LastAction);
            Assert.True(run.SegmentCount == 0 && run.RiskBefore < 70 && Math.Abs(run.Mixer.PostLufs + 14) <= 0.5);
            run.SetScript("깨끗한 대본입니다");
            Assert.True(await run.AuditAsync() && run.HitCount == 0);
            run.Reset();
            Assert.True(run.Audits == 0 && !run.Audited && run.Track == 0 && !run.Playing);
        }

        // ── CPY-4: 카탈로그 167 · 도움말 · HUD · 레이아웃 · DI · 모달 규격 · 외부 의존 0 · 모달 렌더 ──
        var cat = PromptFlowStudio.Services.Ui.StudioCatalog.Entries;
        Assert.True(cat.Length >= 167);   // v17.92.0 이후 카탈로그 증가 허용
        Assert.Contains(cat, en => en.Key == "_copyrightCompliance" && en.Category == 4 && en.Title == "저작권 검역 & Content ID 가드");
        Assert.True(PromptFlowStudio.Services.Ui.StudioCatalogHelpRegistry.Entries.Count >= 167);
        Assert.Equal(0, PromptFlowStudio.Services.Ui.StudioCatalogHelpRegistry.CountDefects());
        Assert.Equal("_copyrightCompliance", PromptFlowStudio.Services.Ui.StudioCatalogHelpRegistry.ResolveKeyByHeader("🛡️ 저작권 검역 & Content ID 가드 · ✅ Safe to Publish"));
        var root = RepoRoot();
        string Src(params string[] p) => File.ReadAllText(Path.Combine(root, Path.Combine(p)));
        var hud = Src("PromptFlowStudio", "Blazor", "Components", "Common", "GlobalTelemetryHudView.razor");
        var layout = Src("PromptFlowStudio", "Blazor", "MainLayout.razor");
        var modalSrc = Src("PromptFlowStudio", "Blazor", "Components", "Common", "CopyrightComplianceAuditStudioModal.razor");
        Assert.True(hud.IndexOf("gth-v1791", StringComparison.Ordinal) is > 0 and var i1791 && i1791 < hud.IndexOf("gth-v1790", StringComparison.Ordinal) && hud.Contains("CpyRun.OnChange += OnSwarmChanged", StringComparison.Ordinal) && hud.Contains("CpyRun.OnChange -= OnSwarmChanged", StringComparison.Ordinal));
        Assert.True(layout.Contains("<CopyrightComplianceAuditStudioModal", StringComparison.Ordinal) && layout.Contains("case \"_copyrightCompliance\"", StringComparison.Ordinal) && layout.Contains("\"_copyrightCompliance\" =>", StringComparison.Ordinal));
        Assert.True(Src("PromptFlowStudio", "MainForm.cs").Contains("CopyrightCompliance.CopyrightComplianceStudioRunner(sp)", StringComparison.Ordinal) && Src("PromptFlowStudio.Mobile", "MauiProgram.cs").Contains("CopyrightCompliance.CopyrightComplianceStudioRunner(sp)", StringComparison.Ordinal));
        Assert.True(modalSrc.Contains("@implements IDisposable", StringComparison.Ordinal) && modalSrc.Contains("flex: 1 1 auto; min-height: 0; overflow-y: auto;", StringComparison.Ordinal) && modalSrc.Contains("position: sticky", StringComparison.Ordinal) && modalSrc.Contains("aria-pressed", StringComparison.Ordinal));
        foreach (var src in Directory.GetFiles(Path.Combine(root, "PromptFlowStudio", "Services", "CopyrightCompliance"), "*.cs"))
        {
            var body = File.ReadAllText(src);
            Assert.True(!body.Contains("System.Linq", StringComparison.Ordinal) && !body.Contains("Process.Start", StringComparison.Ordinal) && !body.Contains("HttpClient", StringComparison.Ordinal) && !body.Contains("File.Write", StringComparison.Ordinal), "외부 의존 · 파일 I/O " + Path.GetFileName(src));
        }
        using var sp = new HeadlessUiRendererCheck.AutoWireProvider();
        var runner = (Cpy.CopyrightComplianceStudioRunner)sp.GetService(typeof(Cpy.CopyrightComplianceStudioRunner))!;
        Assert.True(runner.LinkedCount == 2, "연동 " + runner.LinkedCount);
        var html = await HeadlessUiRendererCheck.RenderAsync(typeof(PromptFlowStudio.Blazor.Components.Common.CopyrightComplianceAuditStudioModal), sp);
        Assert.True(html.Length > 500 && html.Contains("cpy-scrim", StringComparison.Ordinal) && html.Contains("cpy-body", StringComparison.Ordinal) && html.Contains("검역 실행", StringComparison.Ordinal) && html.Contains("cpy-wave", StringComparison.Ordinal), "모달 렌더 " + html.Length);
        Assert.Equal(0, HeadlessUiRendererCheck.LiveSubscriberCount(runner));
        GC.Collect(); GC.WaitForPendingFinalizers(); GC.Collect();
    }

    private static string RepoRoot()
    {
        var dir = new DirectoryInfo(AppContext.BaseDirectory);
        while (dir is not null && !File.Exists(Path.Combine(dir.FullName, "build_titan_release.ps1"))) dir = dir.Parent;
        return dir?.FullName ?? throw new DirectoryNotFoundException("저장소 루트를 찾지 못함");
    }
}

/// <summary>v17.92.0 마스터 실러너 E2E 체인 · 헤드리스 배치 드라이버 · 인터락 스테이징 롤백 · 실러너 샌드박스 콕핏 결선.</summary>
[Collection("TimingSensitivePerformance")]   // 실러너 7 종 순차 호출(스레드 할당 바이트 계측 · 전용 배치 스레드 · 볼트 셰이핑 벽시계) → 비병렬
public sealed class MasterPipelineRealRunnerIsolatedTests
{
    [Fact]
    public async Task MasterPipeline_RealRunnerE2EChain_Check()
    {
        // ── RUN-3: 스테이징 리스 · 트립 래치 · 원자 롤백 · 중복 회수 0 · 리스 재사용 무할당 ──
        var g = new Mrr.PipelineInterlockStagingRollbackGuard();
        g.LeaseBytes(1000); g.LeaseFloats(256); g.LeaseChars(64);
        Assert.True(g.OutstandingLeases == 3 && g.OutstandingBytes >= 1000 + 256 * 4 + 64 * 2);
        Assert.True(g.Trip(2, Mrr.InterlockReason.ContentIdRisk, "위험도 초과") && !g.Trip(4, Mrr.InterlockReason.Exception, "후속"));
        Assert.True(g.IsTripped && g.TripStage == 2 && g.Reason == Mrr.InterlockReason.ContentIdRisk);
        Assert.Throws<Mrr.PipelineInterlockException>(() => g.LeaseBytes(16));   // 트립 후 하류 대여 차단
        var reclaimed = g.Rollback();
        Assert.True(reclaimed >= 1000 + 256 * 4 + 64 * 2 && g.OutstandingLeases == 0 && g.OutstandingBytes == 0 && g.Rollbacks == 1);
        Assert.Equal(0, g.Rollback());
        g.Arm();
        Assert.True(!g.IsTripped && g.TripStage == -1 && g.Reason == Mrr.InterlockReason.None);
        for (var w = 0; w < 4; w++) { g.LeaseBytes(2_000_000); g.LeaseFloats(240_000); g.LeaseChars(8192); g.ReleaseAll(); }
        var a0 = GC.GetAllocatedBytesForCurrentThread();
        for (var w = 0; w < 64; w++) { g.LeaseBytes(2_000_000).AsSpan(0, 4096).Fill(1); g.LeaseFloats(240_000); g.LeaseChars(8192); g.ReleaseAll(); }
        Assert.True(GC.GetAllocatedBytesForCurrentThread() - a0 == 0, "스테이징 리스 할당 " + (GC.GetAllocatedBytesForCurrentThread() - a0));

        // ── RUN-1: 실러너 7 종 실인스턴스 ①→⑦ 순차 호출 · 페이로드 파이핑 · µs/바이트 텔레메트리 ──
        using var clipper = new PromptFlowStudio.Services.LiveClipper.LiveToShortsAutoClipperStudioRunner();
        using var predictor = new PromptFlowStudio.Services.ViralExport.ViralPredictorShortsExportStudioRunner(clipper);
        using var cpy = new Cpy.CopyrightComplianceStudioRunner();
        using var dub = new PromptFlowStudio.Services.MultilingualDubbing.MultilingualDubbingStudioRunner();
        using var mtx = new PromptFlowStudio.Services.MatrixSyndication.MatrixSyndicationStudioRunner();
        using var vod = new PromptFlowStudio.Services.VodRepurposing.VodRepurposingStudioRunner();
        using var vault = new PromptFlowStudio.Services.LiveArchive.LiveArchiveCloudVaultStudioRunner();
        using (var stray = new PromptFlowStudio.Services.LiveClipper.LiveToShortsAutoClipperStudioRunner())
            Assert.Throws<ArgumentException>(() => new Mrr.RealRunnerE2EChainExecutionEngine(stray, predictor, cpy, dub, mtx, vod, vault));
        using var eng = new Mrr.RealRunnerE2EChainExecutionEngine(clipper, predictor, cpy, dub, mtx, vod, vault);
        var observed = 0;
        eng.Observer = _ => observed++;

        var sw = Stopwatch.StartNew();
        Assert.Equal(Mrr.RunnerChainState.Completed, await eng.RunAllAsync(40));
        var e2eMs = sw.Elapsed.TotalMilliseconds;
        var ctx = eng.Context;
        Assert.True(ctx.DoneCount == 7 && eng.Completions == 1 && eng.Aborts == 0 && eng.LastError is null, eng.LastError);
        for (var s = 0; s < 7; s++) Assert.True(ctx.States[s] == Mrr.RunnerStageState.Done && ctx.StageUs[s] > 0 && ctx.StageBytes[s] > 0, "스테이지 " + s + " " + ctx.StageUs[s] + "µs " + ctx.StageBytes[s] + "B");
        // ① 클리퍼 → ② 스코어러: 같은 클립 · 실제 fMP4(NALU) 바이트 동일
        Assert.True(ctx.ClipId > 0 && predictor.HasSelection && predictor.Selected.Id == ctx.ClipId && clipper.ClipsSliced >= 1);
        Assert.True(ctx.NaluLength > 1024 && ctx.NaluSpan.SequenceEqual(predictor.Exporter.Output.Span) && ctx.NaluSpan.Slice(4, 4).SequenceEqual("ftyp"u8));
        Assert.True(ctx.Score == predictor.Score.Total && ctx.Score > 0 && predictor.Analyses >= 1);
        // ③ 저작권 검역: 실검역 1 회 · 치환 PCM 그대로
        Assert.True(cpy.Audits == 1 && cpy.Audited && cpy.SafeToPublish && ctx.RiskBefore >= 70 && ctx.RiskAfter < 70, "위험도 " + ctx.RiskBefore + " → " + ctx.RiskAfter);
        Assert.True(ctx.PcmLength == cpy.Substituted.Length && ctx.Pcm.AsSpan(0, ctx.PcmLength).SequenceEqual(cpy.Substituted));
        // ④ 더빙: EN/ES/JA 연접
        Assert.True(dub.Prepared);
        var dubLen = 0;
        for (var t = 1; t <= 3; t++) { Assert.True(ctx.Dub.AsSpan(dubLen, dub.Pcm(t).Length).SequenceEqual(dub.Pcm(t))); dubLen += dub.Pcm(t).Length; }
        Assert.True(ctx.DubLength == dubLen && dubLen > 0);
        // ⑤ 채널 변형 썸네일
        Assert.True(ctx.VariantChannels == mtx.Router.ChannelCount && ctx.VariantChannels > 0 && ctx.Variant.AsSpan(0, mtx.Thumb(0).Length).SequenceEqual(mtx.Thumb(0)));
        // ⑥ 아티클 + 카드뉴스 5
        Assert.True(vod.Runs == 1 && ctx.TextSpan.SequenceEqual(vod.Markdown(PromptFlowStudio.Services.VodRepurposing.ArticleTemplate.Blog)) && ctx.TextLength > 200);
        long pkgBytes = ctx.NaluLength + System.Text.Encoding.UTF8.GetByteCount(ctx.TextSpan);
        for (var i = 0; i < 5; i++)
        {
            Assert.True(ctx.CardSpan(i).Length > 1000 && ctx.CardSpan(i)[..4].SequenceEqual(new byte[] { 0x89, (byte)'P', (byte)'N', (byte)'G' }) && ctx.CardSpan(i).SequenceEqual(vod.Rasterizer.Png(i)), "카드 " + i);
            pkgBytes += ctx.CardLength[i];
        }
        // ⑦ 볼트: 쇼츠 + 카드 5 + 아티클 = 7 객체 · 바이트 일치
        Assert.True(ctx.VaultObjects == 7 && vault.Gateway.Objects >= 7 && ctx.VaultBytes == pkgBytes, "볼트 " + ctx.VaultObjects + " " + ctx.VaultBytes + "/" + pkgBytes);
        // 텔레메트리: 시작/완료 14 · 시퀀스 단조 · 완료 바이트 = 컨텍스트 계측
        var ev = new System.Collections.Generic.List<Mrr.RunnerStageTelemetry>();
        while (eng.Telemetry.TryRead(out var e)) ev.Add(e);
        Assert.True(ev.Count == 14 && observed == 14, "텔레메트리 " + ev.Count + "/" + observed);
        for (var i = 0; i < ev.Count; i++)
        {
            Assert.True(ev[i].Seq == i + 1 && (int)ev[i].Stage == i / 2 && ev[i].State == (i % 2 == 0 ? Mrr.RunnerStageState.Running : Mrr.RunnerStageState.Done));
            if (i % 2 == 1) Assert.True(ev[i].Bytes == ctx.StageBytes[i / 2] && ev[i].ElapsedUs == ctx.StageUs[i / 2]);
        }
        Assert.True(eng.Guard.OutstandingLeases >= 10 && eng.Guard.OutstandingBytes >= ctx.NaluLength);
        Assert.True(eng.ReleaseStaging() > 0 && eng.Guard.OutstandingLeases == 0 && ctx.Nalu is null);

        // ── RUN-1: 페이로드 파이핑 핫패스 무할당(워밍 후 풀 리스 + 스팬 복사) ──
        var nalu = predictor.Exporter.Output;
        for (var w = 0; w < 2; w++) { nalu.Span.CopyTo(eng.Guard.LeaseBytes(nalu.Length)); cpy.Substituted.CopyTo(eng.Guard.LeaseFloats(cpy.Substituted.Length)); eng.Guard.ReleaseAll(); }
        a0 = GC.GetAllocatedBytesForCurrentThread();
        for (var w = 0; w < 16; w++) { nalu.Span.CopyTo(eng.Guard.LeaseBytes(nalu.Length)); cpy.Substituted.CopyTo(eng.Guard.LeaseFloats(cpy.Substituted.Length)); eng.Guard.ReleaseAll(); }
        Assert.True(GC.GetAllocatedBytesForCurrentThread() - a0 == 0, "페이로드 파이핑 할당 " + (GC.GetAllocatedBytesForCurrentThread() - a0));

        // ── RUN-3: 실패 인터락(③ Content ID 위반 주입) → 하류 차단 · 상류 버퍼 원자 회수 ──
        var audits = cpy.Audits; var vodRuns = vod.Runs; var objects = vault.Gateway.Objects;
        eng.InjectFaultStage = (int)Mrr.RunnerStage.Compliance;
        Assert.Equal(Mrr.RunnerChainState.Aborted, await eng.RunAllAsync(40));
        Assert.True(ctx.States[0] == Mrr.RunnerStageState.Done && ctx.States[1] == Mrr.RunnerStageState.Done && ctx.States[2] == Mrr.RunnerStageState.Failed);
        for (var s = 3; s < 7; s++) Assert.Equal(Mrr.RunnerStageState.Blocked, ctx.States[s]);
        Assert.True(cpy.Audits == audits + 1 && vod.Runs == vodRuns && vault.Gateway.Objects == objects, "하류 차단");
        Assert.True(eng.Guard.IsTripped && eng.Guard.TripStage == 2 && eng.Guard.Reason == Mrr.InterlockReason.ContentIdRisk && eng.LastError!.Contains("Content ID", StringComparison.Ordinal));
        Assert.True(eng.Guard.OutstandingLeases == 0 && eng.Guard.OutstandingBytes == 0 && ctx.Nalu is null && ctx.Pcm is null && eng.LastReclaimedBytes >= predictor.Exporter.Output.Length, "회수 " + eng.LastReclaimedBytes);
        // 실 위험도 상한 인터락(주입 없이 실검역 결과 > 상한)
        eng.InjectFaultStage = -1;
        eng.RiskCeiling = -1f;
        Assert.Equal(Mrr.RunnerChainState.Aborted, await eng.RunAllAsync(40));
        Assert.True(ctx.States[2] == Mrr.RunnerStageState.Failed && eng.Guard.Reason == Mrr.InterlockReason.ContentIdRisk && eng.Guard.OutstandingLeases == 0 && eng.Aborts == 2);
        eng.RiskCeiling = Mrr.RealRunnerE2EChainExecutionEngine.DefaultRiskCeiling;

        // ── RUN-1: 수동 단일 스텝 7 회 = 전단계 ──
        for (var s = 0; s < 7; s++)
        {
            Assert.True(await eng.StepAsync(40), "스텝 " + s + " " + eng.LastError);
            Assert.True(ctx.DoneCount == s + 1);
        }
        Assert.True(eng.State == Mrr.RunnerChainState.Completed && eng.Completions == 2 && !eng.Guard.IsTripped);
        eng.ReleaseStaging();

        // ── RUN-2: 헤드리스 배치 — 전용 단일 스레드 · 쇼츠 MP4 + 카드뉴스 5 + 마크다운 세트 · 실패 롤백 ──
        using (var drv = new Mrr.HeadlessBatchRenderDriver(eng))
        {
            Mrr.BatchMediaPackage? got = null;
            drv.OnPackage += p => got = p;
            Assert.False(drv.WorkerAlive);
            var id = drv.Enqueue(45);
            Assert.True(id > 0 && drv.WorkerAlive);
            Assert.True(await drv.DrainAsync(180_000), "배치 소진");
            var pkg = drv.Package(0)!;
            Assert.True(pkg is { Ok: true } && ReferenceEquals(pkg, got) && pkg.JobId == id && drv.Completed == 1, pkg.Error);
            Assert.True(drv.WorkerThreadId != Environment.CurrentManagedThreadId && drv.WorkerThreadId > 0);
            Assert.True(pkg.ShortsMp4.Length > 1024 && pkg.ShortsMp4.AsSpan(4, 4).SequenceEqual("ftyp"u8));
            Assert.Equal(5, pkg.Cards.Length);
            foreach (var card in pkg.Cards) Assert.True(card.Length > 1000 && card[0] == 0x89 && card[1] == (byte)'P');
            Assert.True(pkg.Markdown.Length > 200 && pkg.Markdown.Contains('#') && pkg.VaultObjects == 7 && pkg.TotalBytes == pkg.VaultBytes);
            Assert.True(eng.Guard.OutstandingLeases == 0 && ctx.Nalu is null, "배치 후 스테이징 회수");
            eng.InjectFaultStage = (int)Mrr.RunnerStage.Compliance;
            Assert.True(drv.Enqueue(40) > 0 && await drv.DrainAsync(120_000));
            var bad = drv.Package(0)!;
            Assert.True(!bad.Ok && bad.ReclaimedBytes > 0 && bad.ShortsMp4.Length == 0 && drv.Failed == 1 && drv.PackageCount == 2 && eng.Guard.OutstandingLeases == 0, bad.Error);
            eng.InjectFaultStage = -1;
        }

        // ── RUN-4: 카탈로그 168+ · 도움말 · HUD · 레이아웃 · DI · 모달 규격 · 외부 의존 0 · 모달 렌더 ──
        var cat = PromptFlowStudio.Services.Ui.StudioCatalog.Entries;
        Assert.True(cat.Length >= 168);   // v17.93.0 이후 카탈로그 증가 허용
        Assert.Contains(cat, en => en.Key == "_realRunnerBatchSandbox" && en.Category == 4 && en.Title == "마스터 실러너 E2E 샌드박스");
        Assert.Equal(cat.Length, PromptFlowStudio.Services.Ui.StudioCatalogHelpRegistry.Entries.Count);
        Assert.Equal(0, PromptFlowStudio.Services.Ui.StudioCatalogHelpRegistry.CountDefects());
        Assert.Equal("_realRunnerBatchSandbox", PromptFlowStudio.Services.Ui.StudioCatalogHelpRegistry.ResolveKeyByHeader("⚡ 마스터 실러너 E2E 샌드박스 · ✅ 완료"));
        var root = RepoRoot();
        string Src(params string[] p) => File.ReadAllText(Path.Combine(root, Path.Combine(p)));
        var hud = Src("PromptFlowStudio", "Blazor", "Components", "Common", "GlobalTelemetryHudView.razor");
        var layout = Src("PromptFlowStudio", "Blazor", "MainLayout.razor");
        var modalSrc = Src("PromptFlowStudio", "Blazor", "Components", "Common", "MasterPipelineRealRunnerStudioModal.razor");
        Assert.True(hud.IndexOf("gth-v1792", StringComparison.Ordinal) is > 0 and var i1792 && i1792 < hud.IndexOf("gth-v1791", StringComparison.Ordinal) && hud.Contains("MrrRun.OnChange += OnSwarmChanged", StringComparison.Ordinal) && hud.Contains("MrrRun.OnChange -= OnSwarmChanged", StringComparison.Ordinal));
        Assert.True(layout.Contains("<MasterPipelineRealRunnerStudioModal", StringComparison.Ordinal) && layout.Contains("case \"_realRunnerBatchSandbox\"", StringComparison.Ordinal) && layout.Contains("\"_realRunnerBatchSandbox\" =>", StringComparison.Ordinal));
        Assert.True(Src("PromptFlowStudio", "MainForm.cs").Contains("MasterPipeline.MasterPipelineRealRunnerStudioRunner(sp)", StringComparison.Ordinal) && Src("PromptFlowStudio.Mobile", "MauiProgram.cs").Contains("MasterPipeline.MasterPipelineRealRunnerStudioRunner(sp)", StringComparison.Ordinal));
        Assert.True(modalSrc.Contains("@implements IDisposable", StringComparison.Ordinal) && modalSrc.Contains("flex: 1 1 auto; min-height: 0; overflow-y: auto;", StringComparison.Ordinal) && modalSrc.Contains("position: sticky", StringComparison.Ordinal) && modalSrc.Contains("aria-pressed", StringComparison.Ordinal));
        foreach (var src in Directory.GetFiles(Path.Combine(root, "PromptFlowStudio", "Services", "MasterPipeline"), "*.cs"))
        {
            var body = File.ReadAllText(src);
            Assert.True(!body.Contains("System.Linq", StringComparison.Ordinal) && !body.Contains("Process.Start", StringComparison.Ordinal) && !body.Contains("HttpClient", StringComparison.Ordinal) && !body.Contains("File.Write", StringComparison.Ordinal), "외부 의존 · 파일 I/O " + Path.GetFileName(src));
        }
        using var sp = new HeadlessUiRendererCheck.AutoWireProvider();
        var runner = (Mrr.MasterPipelineRealRunnerStudioRunner)sp.GetService(typeof(Mrr.MasterPipelineRealRunnerStudioRunner))!;
        Assert.True(runner.InjectedCount == 7, "주입 " + runner.InjectedCount);
        Assert.True(ReferenceEquals(runner.Engine.Clipper, sp.GetService(typeof(PromptFlowStudio.Services.LiveClipper.LiveToShortsAutoClipperStudioRunner))) && ReferenceEquals(runner.Engine.Vault, sp.GetService(typeof(PromptFlowStudio.Services.LiveArchive.LiveArchiveCloudVaultStudioRunner))));
        Assert.True(await runner.StepAsync() && runner.Context.DoneCount == 1 && runner.LogCount == 2 && runner.Steps == 1);
        runner.ToggleContentIdBreach();
        Assert.True(runner.SimulateContentIdBreach);
        runner.ToggleContentIdBreach();
        var html = await HeadlessUiRendererCheck.RenderAsync(typeof(PromptFlowStudio.Blazor.Components.Common.MasterPipelineRealRunnerStudioModal), sp);
        Assert.True(html.Length > 500 && html.Contains("mrr-scrim", StringComparison.Ordinal) && html.Contains("mrr-body", StringComparison.Ordinal) && html.Contains("단일 단계 스텝", StringComparison.Ordinal) && html.Contains("E2E 원클릭 배치 실행", StringComparison.Ordinal) && html.Contains("Injected", StringComparison.Ordinal), "모달 렌더 " + html.Length);
        Assert.Equal(0, HeadlessUiRendererCheck.LiveSubscriberCount(runner));
        Assert.True(e2eMs < 60_000, "E2E " + e2eMs.ToString("0", System.Globalization.CultureInfo.InvariantCulture) + " ms");
        GC.Collect(); GC.WaitForPendingFinalizers(); GC.Collect();
    }

    private static string RepoRoot()
    {
        var dir = new DirectoryInfo(AppContext.BaseDirectory);
        while (dir is not null && !File.Exists(Path.Combine(dir.FullName, "build_titan_release.ps1"))) dir = dir.Parent;
        return dir?.FullName ?? throw new DirectoryNotFoundException("저장소 루트를 찾지 못함");
    }
}

/// <summary>v17.93.0 포스트-퍼블리시 A/B 추적 · 저성과 자동 회수 · 승자 매트릭스 승격 · 관제 콕핏 결선.</summary>
[Collection("TimingSensitivePerformance")]   // 스레드 할당 바이트 계측(시계열 기록 · 스코어링 · 승격 핸드오프) → 비병렬
public sealed class PostPublishSplitTestIsolatedTests
{
    private const long T0 = 1_800_000_000;
    private static long Va(long m) => m * 14 + m * m / 8;
    private static long Vb(long m) => m / 2;

    /// <summary>A/B 표준 시나리오 재생(B 10 분 시차) — 강세 쪽 14 뷰/분 · 완청 58 %, 약세 쪽 0.5 뷰/분 · 완청 27 %.</summary>
    private static void Play(Pst.PostPublishSplitTestingEngine x, int id, bool aStrong, long until)
    {
        x.Deploy(id, "A", 0, 0, "B", 1, 0, T0, 600);
        for (long now = T0 + 300; now <= until; now += 300)
        {
            long ma = (now - T0) / 60, mb = (now - T0 - 600) / 60;
            x.Record(Pst.SplitVariant.A, now, aStrong ? Va(ma) : Vb(ma), aStrong ? 0.58f : 0.27f, aStrong ? (int)(Va(ma) / 22) : 0);
            if (mb > 0) x.Record(Pst.SplitVariant.B, now, aStrong ? Vb(mb) : Va(mb), aStrong ? 0.27f : 0.58f, aStrong ? 0 : (int)(Va(mb) / 22));
            x.Evaluate(now);
        }
    }

    [Fact]
    public async Task PostPublishSplitTest_And_AutoPruner_Check()
    {
        // ── PST-1: 분기 배포 · 5 분 폴링 기록 · 거절 규칙 · 95 % 조기 승자 ──
        var e = new Pst.PostPublishSplitTestingEngine();
        Assert.False(e.Record(Pst.SplitVariant.A, T0, 10, 0.5f, 0));   // 배포 전 거절
        Assert.Throws<ArgumentException>(() => e.Deploy(1, "a", 0, 0, "b", 1, 0, T0, 0));   // 같은 채널 · 시차 0
        e.Deploy(9301, "훅 A", 0, 0, "훅 B", 1, 0, T0, 600);
        Assert.True(e.Phase == Pst.SplitTestPhase.Tracking && e.GoldenEndUnix == T0 + 600 + 5400 && e.RemainingSec(T0) == 6000 && Pst.PostPublishSplitTestingEngine.Capacity == 19);
        Assert.False(e.Record(Pst.SplitVariant.B, T0 + 300, 5, 0.3f, 0));   // B 발행 전
        var decidedAt = -1L;
        for (long now = T0 + 300; now <= T0 + 6000; now += 300)
        {
            var ma = (now - T0) / 60; var mb = (now - T0 - 600) / 60;
            Assert.True(e.Record(Pst.SplitVariant.A, now, Va(ma), 0.58f, (int)(Va(ma) / 22)) == (now <= T0 + 5400));
            if (mb > 0) Assert.True(e.Record(Pst.SplitVariant.B, now, Vb(mb), 0.27f, 0));
            if (e.Evaluate(now) && decidedAt < 0) decidedAt = now;
        }
        Assert.False(e.Record(Pst.SplitVariant.B, T0 + 6000, 999, 0.9f, 1));   // 역행/중복 시각
        Assert.True(decidedAt > 0 && decidedAt < e.GoldenEndUnix && e.HasWinner && e.Winner == Pst.SplitVariant.A && !e.ForcedWinner, "조기 확정 " + decidedAt);
        Assert.True(e.Confidence >= Pst.PostPublishSplitTestingEngine.WinnerConfidence && e.Track(Pst.SplitVariant.A).Score > e.Track(Pst.SplitVariant.B).Score);
        Assert.True(e.Phase == Pst.SplitTestPhase.Closed && e.Track(Pst.SplitVariant.A).Count == 18 && e.Track(Pst.SplitVariant.B).Count == 18);
        Assert.True(e.Track(Pst.SplitVariant.A).At(0).TSec == T0 + 300 && e.Track(Pst.SplitVariant.A).Last.Views == Va(90) && e.Track(Pst.SplitVariant.A).At(17).ViewsPerSec > 0);
        Assert.InRange(Pst.PostPublishSplitTestingEngine.NormalCdf(1.96), 0.9749, 0.9751);
        // 기록 · 스코어링 핫패스 무할당(워밍 후)
        Assert.Equal(0, AllocationProbe.MinAllocated(() =>
        {
            e.Deploy(9302, "훅 A", 0, 0, "훅 B", 1, 1, T0, 0);
            for (long now = T0 + 300; now <= T0 + 5400; now += 300)
            {
                var m = (now - T0) / 60;
                e.Record(Pst.SplitVariant.A, now, m * 9, 0.5f, (int)m);
                e.Record(Pst.SplitVariant.B, now, m * 10, 0.52f, (int)m);
                e.Evaluate(now);
            }
        }));

        // ── PST-2: 90 분 시점 패자 판정 · 자동 비공개 · 감사 · 중복 차단 · 재시도 · 삭제 모드 ──
        var gw = new Pst.SimulatedVideoVisibilityGateway();
        var pr = new Pst.LowPerformanceAutoPrunerEngine(gw);
        var e2 = new Pst.PostPublishSplitTestingEngine();
        Play(e2, 9311, true, T0 + 5700);
        Assert.Equal(0, pr.Evaluate(e2, T0 + 5700));   // 골든타임 전
        Assert.True(pr.Classify(e2, Pst.SplitVariant.A, T0 + 5700) == Pst.PruneReason.None);
        Play(e2, 9311, true, T0 + 6000);
        Assert.Equal(1, pr.Evaluate(e2, T0 + 6000));
        var ev = pr.Audit(0);
        Assert.True(ev.Ok && ev.Variant == Pst.SplitVariant.B && ev.Action == Pst.PruneAction.Private && ev.Status == 200 && ev.ContentId == 9311 && ev.Seq == 1, "감사 " + ev.Reason);
        Assert.True(ev.Reason == (Pst.PruneReason.Loser | Pst.PruneReason.LowVelocity | Pst.PruneReason.LowCompletion) && ev.ViewsPerHour < 50 && ev.Completion < 0.35f);
        Assert.Contains("저조한 완청률", Pst.LowPerformanceAutoPrunerEngine.ReasonText(ev.Reason), StringComparison.Ordinal);
        Assert.True(gw.Privates == 1 && gw.Deletes == 0 && e2.Track(Pst.SplitVariant.B).Pruned && !e2.Track(Pst.SplitVariant.A).Pruned);
        Assert.True(pr.Evaluate(e2, T0 + 6000) == 0 && pr.DuplicateBlocks == 1 && gw.Calls == 1);   // alreadyRegistered 중복 차단
        // 429/5xx 재시도 → 성공 · 4xx 즉시 실패 · 삭제 모드
        Play(e2, 9312, false, T0 + 6000);
        gw.InjectFailures(2, 503);
        pr.Mode = Pst.PruneAction.Delete;
        Assert.Equal(1, pr.Evaluate(e2, T0 + 6000));
        Assert.True(pr.Audit(0).Variant == Pst.SplitVariant.A && pr.Audit(0).Attempts == 3 && pr.Retries == 2 && gw.Deletes == 1 && pr.Audit(0).Action == Pst.PruneAction.Delete);
        Play(e2, 9313, true, T0 + 6000);
        gw.InjectFailures(1, 403);
        Assert.Equal(0, pr.Evaluate(e2, T0 + 6000));
        Assert.True(!pr.Audit(0).Ok && pr.Audit(0).Status == 403 && pr.Audit(0).Attempts == 1 && pr.Failures == 1 && !e2.Track(Pst.SplitVariant.B).Pruned && pr.AuditCount == 3);
        Assert.Equal(1, pr.Evaluate(e2, T0 + 6000));   // 실패분은 재평가 시 재시도
        // 감사 기록 무할당
        Assert.Equal(0, AllocationProbe.MinAllocated(() => { for (var i = 0; i < 32; i++) { e2.Track(Pst.SplitVariant.B).Pruned = false; pr.Prune(e2, Pst.SplitVariant.B, Pst.PruneReason.LowVelocity, T0 + 6000); } }));

        // ── PST-3: 승자 → v17.81 매트릭스 큐 승격 · 참조 전달 · 중복/상한/누락 차단 · 무할당 ──
        using var mtx = new PromptFlowStudio.Services.MatrixSyndication.MatrixSyndicationStudioRunner();
        var promo = new Pst.ViralWinnerSubChannelPromoterGuard(mtx.Router);
        var mp4 = new byte[4096]; mp4[4] = (byte)'f';
        var sub = "1\n00:00:00,000 --> 00:00:03,000\n훅".AsMemory();
        var meta = "{\"hook\":\"A\"}".AsMemory();
        var asset = new Pst.WinnerMasterAsset(9311, Pst.SplitVariant.A, mp4, sub, meta);
        var before = mtx.Router.Count;
        Assert.Equal(Pst.PromoteResult.Promoted, promo.Promote(asset, mtx.SimNow, out var routed));
        Assert.True(routed > 0 && routed <= mtx.Router.ChannelCount && mtx.Router.Count == before + routed && promo.RoutedPosts == routed, "예약 " + routed);
        var h = promo.History(0);
        Assert.True(h.Asset.Mp4.Span == mp4.AsSpan() && h.Asset.Subtitle.Span == sub.Span && h.Asset.Metadata.Span == meta.Span, "참조 전달(복사 0)");
        Assert.InRange(h.JitterSec, 0, Pst.ViralWinnerSubChannelPromoterGuard.MaxJitterMin * 60);
        Assert.True(h.ReadyUnix == mtx.SimNow + h.JitterSec && (routed < 2 || mtx.Router.MinCrossChannelGap(9311) >= mtx.Router.StaggerMinutes * 60L));
        Assert.Equal(Pst.PromoteResult.Duplicate, promo.Promote(asset, mtx.SimNow, out _));
        Assert.Equal(Pst.PromoteResult.InvalidAsset, promo.Promote(new Pst.WinnerMasterAsset(9399, Pst.SplitVariant.B, ReadOnlyMemory<byte>.Empty, sub, meta), mtx.SimNow, out _));
        promo.DailyCap = 1;
        Assert.Equal(Pst.PromoteResult.DailyCap, promo.Promote(new Pst.WinnerMasterAsset(9398, Pst.SplitVariant.A, mp4, sub, meta), mtx.SimNow, out _));
        Assert.True(promo.Promotions == 1 && promo.Duplicates == 1 && promo.CapBlocks == 1);
        promo.DailyCap = 10_000;
        var cid = 20_000;
        Assert.Equal(0, AllocationProbe.MinAllocated(() =>
        {
            mtx.Router.ClearQueue();
            for (var i = 0; i < 8; i++) promo.Promote(new Pst.WinnerMasterAsset(++cid, Pst.SplitVariant.A, mp4, sub, meta), mtx.SimNow, out _);
        }));
        mtx.Router.ClearQueue();

        // ── 러너 E2E: 골든타임 완주 → 승자 승격 + 패자 회수(A 우세 / B 우세) · 강제 승자 ──
        using (var run = new Pst.PostPublishSplitTestStudioRunner(mtx))
        {
            Assert.True(run.MatrixInjected && !run.PredictorInjected);
            var changes = 0;
            run.OnChange += () => changes++;
            var q = mtx.Router.Count;
            run.RunToGoldenEnd();
            Assert.True(run.Engine.Phase == Pst.SplitTestPhase.Closed && run.Engine.HasWinner && run.Engine.Winner == Pst.SplitVariant.A && run.RemainingSec == 0, "러너 판정");
            Assert.True(run.Pruner.Pruned == 1 && run.Engine.Track(Pst.SplitVariant.B).Pruned && run.Gateway.Privates == 1, "러너 회수");
            Assert.True(run.Promoter.Promotions == 1 && mtx.Router.Count > q && run.LastRouted > 0 && run.LogCount >= 3 && changes > 0);
            run.ToggleBWins(); run.ToggleDeleteMode(); run.ToggleSplitByChannel();
            Assert.True(run.BWinsScenario && run.DeleteMode && run.SplitByChannel);
            run.Deploy();
            Assert.True(run.Engine.StaggerSec == 0 && run.Engine.Track(Pst.SplitVariant.B).Channel == 1);
            run.RunToGoldenEnd();
            Assert.True(run.Engine.Winner == Pst.SplitVariant.B && run.Engine.Track(Pst.SplitVariant.A).Pruned && run.Gateway.Deletes == 1 && run.Promoter.Promotions == 2);
            run.Reset();
            run.ForceWinner(Pst.SplitVariant.A);
            Assert.Equal(Pst.SplitTestPhase.Idle, run.Engine.Phase);
            run.Advance(5);
            run.ForceWinner(Pst.SplitVariant.B);
            Assert.True(run.Engine.ForcedWinner && run.Engine.Winner == Pst.SplitVariant.B && run.Engine.Phase == Pst.SplitTestPhase.Decided && run.Promoter.Promotions == 3);
            run.SetStagger(99);
            Assert.Equal(Pst.PostPublishSplitTestStudioRunner.MaxStaggerMin, run.StaggerMinutes);
        }

        // ── PST-4: 카탈로그 169+ · 도움말 · HUD · 레이아웃 · DI · 모달 규격 · 외부 의존 0 · 모달 렌더 ──
        var cat = PromptFlowStudio.Services.Ui.StudioCatalog.Entries;
        Assert.True(cat.Length >= 169);   // v17.94.0 이후 카탈로그 증가 허용
        Assert.Contains(cat, en => en.Key == "_postPublishSplitTest" && en.Category == 4 && en.Title == "포스트-퍼블리시 A/B & 패자 회수기");
        Assert.Equal(cat.Length, PromptFlowStudio.Services.Ui.StudioCatalogHelpRegistry.Entries.Count);
        Assert.Equal(0, PromptFlowStudio.Services.Ui.StudioCatalogHelpRegistry.CountDefects());
        Assert.Equal("_postPublishSplitTest", PromptFlowStudio.Services.Ui.StudioCatalogHelpRegistry.ResolveKeyByHeader("⚖️ 포스트-퍼블리시 A/B & 패자 회수기 · 추적 중"));
        var root = RepoRoot();
        string Src(params string[] p) => File.ReadAllText(Path.Combine(root, Path.Combine(p)));
        var hud = Src("PromptFlowStudio", "Blazor", "Components", "Common", "GlobalTelemetryHudView.razor");
        var layout = Src("PromptFlowStudio", "Blazor", "MainLayout.razor");
        var modalSrc = Src("PromptFlowStudio", "Blazor", "Components", "Common", "PostPublishSplitTestStudioModal.razor");
        Assert.True(hud.IndexOf("gth-v1793", StringComparison.Ordinal) is > 0 and var i1793 && i1793 < hud.IndexOf("gth-v1792", StringComparison.Ordinal) && hud.Contains("PstRun.OnChange += OnSwarmChanged", StringComparison.Ordinal) && hud.Contains("PstRun.OnChange -= OnSwarmChanged", StringComparison.Ordinal));
        Assert.True(layout.Contains("<PostPublishSplitTestStudioModal", StringComparison.Ordinal) && layout.Contains("case \"_postPublishSplitTest\"", StringComparison.Ordinal) && layout.Contains("\"_postPublishSplitTest\" =>", StringComparison.Ordinal));
        Assert.True(Src("PromptFlowStudio", "MainForm.cs").Contains("PostPublishSplitTest.PostPublishSplitTestStudioRunner(sp)", StringComparison.Ordinal) && Src("PromptFlowStudio.Mobile", "MauiProgram.cs").Contains("PostPublishSplitTest.PostPublishSplitTestStudioRunner(sp)", StringComparison.Ordinal));
        Assert.True(modalSrc.Contains("@implements IDisposable", StringComparison.Ordinal) && modalSrc.Contains("flex: 1 1 auto; min-height: 0; overflow-y: auto;", StringComparison.Ordinal) && modalSrc.Contains("position: sticky", StringComparison.Ordinal) && modalSrc.Contains("aria-pressed", StringComparison.Ordinal));
        foreach (var src in Directory.GetFiles(Path.Combine(root, "PromptFlowStudio", "Services", "PostPublishSplitTest"), "*.cs"))
        {
            var body = File.ReadAllText(src);
            Assert.True(!body.Contains("System.Linq", StringComparison.Ordinal) && !body.Contains("Process.Start", StringComparison.Ordinal) && !body.Contains("HttpClient", StringComparison.Ordinal) && !body.Contains("File.Write", StringComparison.Ordinal), "외부 의존 · 파일 I/O " + Path.GetFileName(src));
        }
        using var sp = new HeadlessUiRendererCheck.AutoWireProvider();
        var runner = (Pst.PostPublishSplitTestStudioRunner)sp.GetService(typeof(Pst.PostPublishSplitTestStudioRunner))!;
        Assert.True(runner.MatrixInjected && ReferenceEquals(runner.Matrix, sp.GetService(typeof(PromptFlowStudio.Services.MatrixSyndication.MatrixSyndicationStudioRunner))) && runner.PredictorInjected);
        runner.Advance(30);
        var html = await HeadlessUiRendererCheck.RenderAsync(typeof(PromptFlowStudio.Blazor.Components.Common.PostPublishSplitTestStudioModal), sp);
        Assert.True(html.Length > 500 && html.Contains("pst-scrim", StringComparison.Ordinal) && html.Contains("pst-body", StringComparison.Ordinal) && html.Contains("A/B 분기 배포", StringComparison.Ordinal) && html.Contains("pst-pa", StringComparison.Ordinal) && html.Contains("강제 승자", StringComparison.Ordinal), "모달 렌더 " + html.Length);
        Assert.Equal(0, HeadlessUiRendererCheck.LiveSubscriberCount(runner));
        GC.Collect(); GC.WaitForPendingFinalizers(); GC.Collect();
    }

    private static string RepoRoot()
    {
        var dir = new DirectoryInfo(AppContext.BaseDirectory);
        while (dir is not null && !File.Exists(Path.Combine(dir.FullName, "build_titan_release.ps1"))) dir = dir.Parent;
        return dir?.FullName ?? throw new DirectoryNotFoundException("저장소 루트를 찾지 못함");
    }
}

[Collection("TimingSensitivePerformance")]   // 스레드 할당 바이트 계측(가시성 전환 · 폴링 라운드) → 비병렬
public sealed class PlatformVisibilityGatewayIsolatedTests
{
    private const double T0 = 1_800_000_000;

    private sealed class VClock { public double Now = T0; }

    /// <summary>인메모리 Mock HttpHandler — 실제 HttpClient 요청(메서드 · URL · 헤더 · 본문)을 계약 시뮬레이터로 중계하고 원문을 기록.</summary>
    private sealed class SimHandler : HttpMessageHandler
    {
        public readonly Pvg.PlatformApiContractSimulator Sim;
        public readonly System.Collections.Generic.List<string> Requests = new();
        public string LastBody = "", LastAuth = "";
        public SimHandler(Func<double> clock) => Sim = new Pvg.PlatformApiContractSimulator(clock);

        protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage req, CancellationToken ct)
        {
            var body = req.Content is null ? Array.Empty<byte>() : await req.Content.ReadAsByteArrayAsync(ct);
            LastBody = System.Text.Encoding.UTF8.GetString(body);
            LastAuth = req.Headers.TryGetValues("Authorization", out var av) ? string.Join(",", av) : "";
            var url = req.RequestUri!.OriginalString;
            Requests.Add(req.Method.Method + " " + url);
            var hdr = System.Text.Encoding.UTF8.GetBytes(LastAuth.Length > 0 ? "Authorization: " + LastAuth + "\r\n" : "");
            var m = req.Method == HttpMethod.Put ? Gb.GraphHttpMethod.Put : req.Method == HttpMethod.Post ? Gb.GraphHttpMethod.Post : req.Method == HttpMethod.Delete ? Gb.GraphHttpMethod.Delete : Gb.GraphHttpMethod.Get;
            var resp = new Gb.GraphResponseBuffer();
            var st = await Sim.SendAsync(m, System.Text.Encoding.UTF8.GetBytes(url), hdr, body, resp, ct);
            var r = new HttpResponseMessage((System.Net.HttpStatusCode)st) { Content = new ByteArrayContent(resp.Body, 0, resp.Length) };
            if (resp.RetryAfterSec > 0) r.Headers.RetryAfter = new System.Net.Http.Headers.RetryConditionHeaderValue(TimeSpan.FromSeconds(resp.RetryAfterSec));
            return r;
        }
    }

    private static Pvg.TokenLifecycleRateLimitBackoffGuard NewGuard(VClock c, out Pvg.SimulatedPlatformTokenSource tokens)
    {
        tokens = new Pvg.SimulatedPlatformTokenSource();
        return new Pvg.TokenLifecycleRateLimitBackoffGuard(tokens) { Delay = (sec, _) => { c.Now += sec; return default; } };
    }

    [Fact]
    public async Task ProductionPlatformVisibilityGateway_And_Telemetry_Check()
    {
        // ── PVG-1: 실 HttpClient 경로(Mock HttpHandler) — YouTube videos.update/delete · IG 숨김/삭제 API 계약 ──
        var c = new VClock();
        var handler = new SimHandler(() => c.Now);
        using (var guard = NewGuard(c, out var tokens))
        using (var http = new Gb.HttpGraphTransport(handler))
        using (var gw = new Pvg.ProductionPlatformVisibilityGatewayEngine(guard, () => c.Now, liveEndpoints: true, liveTransport: http))
        {
            Assert.True(gw.LiveEndpoints && gw.ModeName == "LIVE" && ReferenceEquals(gw.Transport, http));
            handler.Sim.Seed(Lp.LiveProvider.YouTube, "ytVideo00A1", T0, true);
            handler.Sim.Seed(Lp.LiveProvider.Instagram, "17940000000001", T0, true);
            Assert.Equal(-1, gw.Bind(Lp.LiveProvider.YouTube, "bad/../id?x=1", 1, Pst.SplitVariant.A, 0));   // URL 주입 차단
            var yt = gw.Bind(Lp.LiveProvider.YouTube, "ytVideo00A1", 9401, Pst.SplitVariant.A, 0);
            var ig = gw.Bind(Lp.LiveProvider.Instagram, "17940000000001", 9401, Pst.SplitVariant.B, 1);
            Assert.Equal(yt, gw.Bind(Lp.LiveProvider.YouTube, "ytVideo00A1", 9401, Pst.SplitVariant.A, 0));   // 중복 결선 = 같은 슬롯
            Assert.True(yt >= 0 && ig >= 0 && gw.BindingCount == 2 && gw.SchemaRejections == 1);

            Pst.IVideoVisibilityGateway contract = gw;
            Assert.Equal(200, contract.Apply(9401, 0, Pst.SplitVariant.A, Pst.PruneAction.Private));
            Assert.Equal("PUT https://www.googleapis.com/youtube/v3/videos?part=status", handler.Requests[^1]);
            Assert.True(handler.LastBody == "{\"id\":\"ytVideo00A1\",\"status\":{\"privacyStatus\":\"private\"}}" && handler.LastAuth == "Bearer sim-yt-1", handler.LastBody + " | " + handler.LastAuth);
            Assert.True(gw.Binding(yt).Visibility == Pvg.VideoVisibility.Private && handler.Sim.StateOf(Lp.LiveProvider.YouTube, "ytVideo00A1") == Pvg.VideoVisibility.Private && gw.Privates == 1);
            var calls = handler.Requests.Count;
            Assert.Equal(200, contract.Apply(9401, 0, Pst.SplitVariant.A, Pst.PruneAction.Private));   // 이미 비공개 → 호출 생략
            Assert.True(handler.Requests.Count == calls && gw.DuplicateSkips == 1);
            Assert.Equal(200, await gw.ApplyAsync(yt, Pvg.VideoVisibility.Public));
            Assert.True(handler.LastBody.Contains("\"privacyStatus\":\"public\"", StringComparison.Ordinal) && gw.Binding(yt).Visibility == Pvg.VideoVisibility.Public);
            Assert.Equal(200, await gw.RefreshStatusAsync(yt));
            Assert.Equal("GET https://www.googleapis.com/youtube/v3/videos?part=status&id=ytVideo00A1", handler.Requests[^1]);

            Assert.Equal(200, contract.Apply(9401, 1, Pst.SplitVariant.B, Pst.PruneAction.Private));
            Assert.Equal("POST https://graph.facebook.com/v21.0/17940000000001?comment_enabled=false", handler.Requests[^1]);
            Assert.True(handler.LastAuth == "Bearer sim-ig-2" && gw.Binding(ig).Visibility == Pvg.VideoVisibility.Hidden && gw.Hides == 1);
            Assert.Equal(422, await gw.ApplyAsync(ig, Pvg.VideoVisibility.Unlisted));   // IG 일부 공개 없음

            Assert.Equal(204, await gw.ApplyAsync(yt, Pvg.VideoVisibility.Deleted));
            Assert.Equal("DELETE https://www.googleapis.com/youtube/v3/videos?id=ytVideo00A1", handler.Requests[^1]);
            Assert.True(gw.Binding(yt).Visibility == Pvg.VideoVisibility.Deleted && handler.Sim.StateOf(Lp.LiveProvider.YouTube, "ytVideo00A1") == Pvg.VideoVisibility.Deleted);
            Assert.Equal(410, await gw.ApplyAsync(yt, Pvg.VideoVisibility.Public));   // 삭제 후 전환 차단
            Assert.Equal(200, contract.Apply(9401, 1, Pst.SplitVariant.B, Pst.PruneAction.Delete));
            Assert.True(handler.Requests[^1] == "DELETE https://graph.facebook.com/v21.0/17940000000001" && gw.Binding(ig).Visibility == Pvg.VideoVisibility.Deleted && gw.Deletes == 2);
            Assert.Equal(404, contract.Apply(1, 0, Pst.SplitVariant.A, Pst.PruneAction.Private));   // 미결선
            Assert.True(tokens.Issued == 2 && guard.QuotaUsed(Lp.LiveProvider.YouTube) == 50 + 50 + 1 + 50 && guard.QuotaUsed(Lp.LiveProvider.Instagram) == 2);
        }

        // ── PVG-2: 토큰 만료 5 분 전 갱신 · 401 재발급 · 429 지수 백오프 · Retry-After · 쿼터 안전 정지(시뮬 폴백) ──
        c = new VClock();
        using (var guard = NewGuard(c, out var tokens))
        using (var gw = new Pvg.ProductionPlatformVisibilityGatewayEngine(guard, () => c.Now, liveEndpoints: false))
        {
            Assert.True(!gw.LiveEndpoints && gw.Transport is Pvg.PlatformApiContractSimulator);
            gw.Simulator.Seed(Lp.LiveProvider.YouTube, "ytVideo00B1", T0, true);
            gw.Simulator.Seed(Lp.LiveProvider.Instagram, "17940000000002", T0, true);
            var yt = gw.Bind(Lp.LiveProvider.YouTube, "ytVideo00B1", 9402, Pst.SplitVariant.A, 0);
            var ig = gw.Bind(Lp.LiveProvider.Instagram, "17940000000002", 9402, Pst.SplitVariant.B, 1);

            Assert.True(guard.EnsureToken(Lp.LiveProvider.YouTube, T0) && tokens.Issued == 1 && guard.ExpiresAt(Lp.LiveProvider.YouTube) == T0 + 3600);
            guard.Tick(T0 + 3600 - 301);
            Assert.Equal(0, guard.BackgroundRefreshes);   // 5 분 1 초 전 = 아직
            guard.Tick(T0 + 3600 - 299);
            Assert.True(guard.BackgroundRefreshes == 1 && guard.Refreshes == 2 && guard.ExpiresAt(Lp.LiveProvider.YouTube) == T0 + 3600 - 299 + 3600, "5 분 전 자동 갱신");
            Assert.False(guard.HasToken(Lp.LiveProvider.Instagram));   // 미보유 플랫폼은 첫 요청 시 지연 발급
            tokens.InjectFailures(1);
            guard.ForceExpiry(Lp.LiveProvider.YouTube, T0 + 10);
            guard.Tick(T0);
            Assert.Equal(1, guard.RefreshFailures);
            guard.Tick(T0);
            Assert.True(guard.Refreshes == 3 && guard.SecondsLeft(Lp.LiveProvider.YouTube, T0) == 3600);
            guard.Invalidate(Lp.LiveProvider.YouTube);
            Assert.Equal(200, await gw.ApplyAsync(yt, Pvg.VideoVisibility.Unlisted));   // 토큰 폐기 → 요청 직전 재발급
            Assert.True(guard.Refreshes == 4 && gw.Binding(yt).Visibility == Pvg.VideoVisibility.Unlisted);

            // 429 × 2 → 1.5 s · 3 s(+지터 0~25 %) 백오프 후 성공 · 연속 카운터 리셋
            gw.Simulator.InjectRateLimit(2);
            var t = c.Now;
            Assert.Equal(200, await gw.ApplyAsync(yt, Pvg.VideoVisibility.Private));
            Assert.True(gw.Backoffs == 2 && gw.Retries == 2 && guard.RateLimitHits == 2 && guard.ConsecutiveHits(Lp.LiveProvider.YouTube) == 0, "백오프 " + gw.Backoffs);
            Assert.True(c.Now - t is >= 4.5 and <= 5.625, "백오프 누적 " + (c.Now - t));
            // Retry-After 우선 · IG Graph 코드 4(400) 레이트 본문 인식
            gw.Simulator.InjectRateLimit(1, retryAfterSec: 20);
            Assert.Equal(200, await gw.ApplyAsync(yt, Pvg.VideoVisibility.Public));
            Assert.Equal(20, guard.LastBackoffSec);
            gw.Simulator.InjectRateLimit(1);
            Assert.Equal(200, await gw.ApplyAsync(ig, Pvg.VideoVisibility.Private));
            Assert.True(guard.RateLimitHits == 4 && gw.Binding(ig).Visibility == Pvg.VideoVisibility.Hidden);
            // 지속 429 → 최대 4 회 시도 후 429 반환
            gw.Simulator.InjectRateLimit(10);
            Assert.Equal(429, await gw.ApplyAsync(yt, Pvg.VideoVisibility.Private));
            Assert.True(gw.Retries >= 2 + 1 + 1 + 3 && gw.Binding(yt).Visibility == Pvg.VideoVisibility.Public && gw.Failures == 1);
            gw.Simulator.InjectRateLimit(0);
            c.Now += 60;
            // quotaExceeded → 당일 안전 정지(시뮬레이터 미호출) → UTC 일 경계 후 재개
            gw.Simulator.InjectQuotaExceeded(1);
            Assert.Equal(403, await gw.ApplyAsync(yt, Pvg.VideoVisibility.Private));
            Assert.True(guard.QuotaExhaustions == 1 && guard.Throttled(Lp.LiveProvider.YouTube));
            var req = gw.Simulator.Requests;
            Assert.Equal(403, await gw.ApplyAsync(yt, Pvg.VideoVisibility.Private));
            Assert.True(gw.Simulator.Requests == req && guard.SafetyThrottles >= 1);
            c.Now += 86400;
            Assert.Equal(200, await gw.ApplyAsync(yt, Pvg.VideoVisibility.Private));
        }

        // 백오프 곡선 — Base 1.5 s × 2ⁿ⁻¹ · 지터 ≤ 25 % · 상한 30 s · 90 % 쿼터 안전선
        using (var g = new Pvg.TokenLifecycleRateLimitBackoffGuard(new Pvg.SimulatedPlatformTokenSource()))
        {
            double[] lo = { 1.5, 3, 6, 12, 24, 30, 30 }, hi = { 1.875, 3.75, 7.5, 15, 30, 30, 30 };
            for (var k = 0; k < lo.Length; k++)
            {
                var d = g.OnRateLimited(Lp.LiveProvider.YouTube, T0, 0);
                Assert.True(d >= lo[k] && d <= hi[k], "백오프 " + k + " = " + d);
                Assert.Equal(T0 + d, g.BlockedUntil(Lp.LiveProvider.YouTube));
            }
            Assert.Equal(Pvg.QuotaDecision.NoToken, g.TryAcquire(Lp.LiveProvider.YouTube, 1, T0 + 60));
            Assert.True(g.EnsureToken(Lp.LiveProvider.YouTube, T0));
            Assert.Equal(Pvg.QuotaDecision.BackingOff, g.TryAcquire(Lp.LiveProvider.YouTube, 1, T0 + 1));
            g.SetQuotaLimit(Lp.LiveProvider.YouTube, 1000);
            var allowed = 0;
            while (g.TryAcquire(Lp.LiveProvider.YouTube, Pvg.TokenLifecycleRateLimitBackoffGuard.CostYtUpdate, T0 + 60) == Pvg.QuotaDecision.Allowed) allowed++;
            Assert.True(allowed == 18 && g.QuotaUsed(Lp.LiveProvider.YouTube) == 900 && g.Throttled(Lp.LiveProvider.YouTube) && g.SafetyThrottles == 1, "안전선 " + allowed);
            Assert.True(Pvg.TokenLifecycleRateLimitBackoffGuard.IsRateLimitBody("{\"error\":{\"code\":613}}"u8) && Pvg.TokenLifecycleRateLimitBackoffGuard.IsQuotaBody("{\"reason\":\"quotaExceeded\"}"u8) && !Pvg.TokenLifecycleRateLimitBackoffGuard.IsRateLimitBody("{\"error\":{\"code\":100}}"u8));
        }

        // ── PVG-3: 5 분 시계열 폴링 → 유속 · A/B 피딩 → 회수기 → 프로덕션 게이트웨이 · 핫패스 무할당 ──
        c = new VClock();
        using (var guard = NewGuard(c, out _))
        using (var gw = new Pvg.ProductionPlatformVisibilityGatewayEngine(guard, () => c.Now, liveEndpoints: false))
        {
            gw.Simulator.Seed(Lp.LiveProvider.YouTube, "ytVideo00CA", T0, true);
            gw.Simulator.Seed(Lp.LiveProvider.YouTube, "ytVideo00CB", T0, false);
            gw.Simulator.Seed(Lp.LiveProvider.Instagram, "17940000000003", T0, true);
            var sa = gw.Bind(Lp.LiveProvider.YouTube, "ytVideo00CA", 9403, Pst.SplitVariant.A, 0);
            var sb = gw.Bind(Lp.LiveProvider.YouTube, "ytVideo00CB", 9403, Pst.SplitVariant.B, 1);
            var si = gw.Bind(Lp.LiveProvider.Instagram, "17940000000003", 99403, Pst.SplitVariant.A, 2);
            var split = new Pst.PostPublishSplitTestingEngine();
            split.Deploy(9403, "A", 0, 0, "B", 1, 1, (long)T0, 0);
            var poller = new Pvg.RealtimeTimeseriesMetricPollingEngine(gw) { Sink = split };
            Assert.True(poller.Add(sa, (long)T0, true) == 0 && poller.Add(sb, (long)T0, true) == 1 && poller.Add(si, (long)T0, false) == 2 && poller.TrackCount == 3);
            Assert.Equal(0, await poller.PollDueAsync((long)T0 + 120));   // 주기 미도래
            long allocMax = 0;
            for (var k = 1; k <= 18; k++)
            {
                c.Now = T0 + 300 * k;
                guard.Tick(c.Now);
                var a0 = GC.GetAllocatedBytesForCurrentThread();
                var n = await poller.PollDueAsync((long)c.Now);
                if (k > 2) allocMax = Math.Max(allocMax, GC.GetAllocatedBytesForCurrentThread() - a0);
                Assert.Equal(3, n);
                split.Evaluate((long)c.Now);
            }
            Assert.True(allocMax == 0, "폴링 라운드 할당 " + allocMax);
            var ta = poller.Track(0); var tb = poller.Track(1); var ti = poller.Track(2);
            Assert.True(ta.Count == 18 && tb.Count == 18 && ti.Count == 18 && poller.Fed == 36 && poller.SinkRejected == 0 && poller.Requests == 18 * 4, "폴링 " + poller.Requests);
            Assert.Equal(90 * 14 + (long)(8100 * 0.12), ta.Last.Views);
            Assert.True(Math.Abs(ta.Last.ViewsPerMin - (ta.Last.Views - ta.At(16).Views) / 5f) < 1e-3 && ta.Last.Completion is > 0.54f and < 0.62f && tb.Last.Completion is > 0.24f and < 0.30f, "유속 · 완청");
            Assert.True(tb.Last.ViewsPerMin < 1f && ti.Last.Shares > 0 && ti.Last.LikesPerMin > 0 && guard.QuotaUsed(Lp.LiveProvider.YouTube) == 18 * 3);
            Assert.True(split.Phase == Pst.SplitTestPhase.Closed && split.HasWinner && split.Winner == Pst.SplitVariant.A && split.Samples == 36);
            Assert.Equal(0, await poller.PollDueAsync((long)T0 + 5700));   // 골든타임 밖
            var pr = new Pst.LowPerformanceAutoPrunerEngine(gw);
            Assert.Equal(1, pr.Evaluate(split, (long)T0 + 5400));
            Assert.True(gw.Binding(sb).Visibility == Pvg.VideoVisibility.Private && gw.Simulator.StateOf(Lp.LiveProvider.YouTube, "ytVideo00CB") == Pvg.VideoVisibility.Private && pr.Audit(0).Status == 200 && pr.Audit(0).Ok);

            // 가시성 전환 핫패스 무할당(워밍 후 공개 ↔ 비공개 16 회)
            for (var w = 0; w < 2; w++) { await gw.ApplyAsync(sa, Pvg.VideoVisibility.Private); await gw.ApplyAsync(sa, Pvg.VideoVisibility.Public); }
            var b0 = GC.GetAllocatedBytesForCurrentThread();
            for (var w = 0; w < 8; w++) { await gw.ApplyAsync(sa, Pvg.VideoVisibility.Private); await gw.ApplyAsync(sa, Pvg.VideoVisibility.Public); }
            Assert.True(GC.GetAllocatedBytesForCurrentThread() - b0 == 0, "가시성 전환 할당 " + (GC.GetAllocatedBytesForCurrentThread() - b0));
        }

        // ── 러너 E2E: 배포 → 골든타임 완주(폴링 · 판정 · 회수) · 수동 전환 · 429/토큰 데모 ──
        using (var run = new Pvg.PlatformVisibilityGatewayStudioRunner(liveEndpoints: false))
        {
            Assert.True(!run.LiveInjected && run.Gateway.ModeName == "시뮬레이션");
            var changes = 0;
            run.OnChange += () => changes++;
            await run.RunToGoldenEndAsync();
            Assert.True(run.Split.Phase == Pst.SplitTestPhase.Closed && run.Split.Winner == Pst.SplitVariant.A && run.RemainingSec == 0, "러너 판정");
            Assert.True(run.Pruner.Pruned == 1 && run.Gateway.Binding(run.SlotB).Visibility == Pvg.VideoVisibility.Private && run.Poller.Fed >= 34 && run.Poller.Track(2).Count == 18, "러너 회수 " + run.Poller.Fed);
            Assert.True(run.Connected(Lp.LiveProvider.YouTube) && run.Connected(Lp.LiveProvider.Instagram) && run.LogCount >= 4 && changes > 0);
            var bg = run.Guard.BackgroundRefreshes;
            run.ExpireTokensSoon();
            await run.AdvanceAsync(5);
            Assert.True(run.Guard.BackgroundRefreshes == bg + 2 && run.Guard.SecondsLeft(Lp.LiveProvider.YouTube, run.NowUnix) > 3000);
            run.InjectRateLimit();
            Assert.Equal(200, await run.SetVisibilityAsync(run.SlotA, Pvg.VideoVisibility.Unlisted));
            Assert.True(run.Gateway.Backoffs >= 2 && run.Gateway.Binding(run.SlotA).Visibility == Pvg.VideoVisibility.Unlisted);
            Assert.Equal(422, await run.SetVisibilityAsync(run.SlotIg, Pvg.VideoVisibility.Unlisted));
            Assert.Equal(204, await run.SetVisibilityAsync(run.SlotA, Pvg.VideoVisibility.Deleted));
            Assert.Equal(410, await run.SetVisibilityAsync(run.SlotA, Pvg.VideoVisibility.Public));
            Assert.Equal(200, await run.RefreshStatusAsync(run.SlotB));
            run.ToggleBWins(); run.ToggleDeleteMode();
            Assert.True(run.BWinsScenario && run.DeleteMode);
            await run.DeployAsync();
            await run.RunToGoldenEndAsync();
            Assert.True(run.Split.Winner == Pst.SplitVariant.B && run.Gateway.Binding(run.SlotA).Visibility == Pvg.VideoVisibility.Deleted && run.Pruner.Pruned == 2);
            run.InjectQuotaExceeded();
            Assert.Equal(403, await run.SetVisibilityAsync(run.SlotB, Pvg.VideoVisibility.Private));
            Assert.True(run.Guard.Throttled(Lp.LiveProvider.YouTube) && !run.Connected(Lp.LiveProvider.YouTube));
            run.Reset();
            Assert.True(run.SlotA == -1 && run.LogCount == 0 && run.Split.Phase == Pst.SplitTestPhase.Idle);
            Assert.Equal(404, await run.SetVisibilityAsync(run.SlotA, Pvg.VideoVisibility.Private));
        }

        // ── PVG-4: 카탈로그 170 · 도움말 · HUD · 레이아웃 · DI · 모달 규격 · 외부 의존 0 · 모달 렌더 ──
        var cat = PromptFlowStudio.Services.Ui.StudioCatalog.Entries;
        Assert.True(cat.Length >= 170);   // v17.95.0 이후 카탈로그 증가 허용
        Assert.Contains(cat, en => en.Key == "_platformVisibilityGateway" && en.Category == 4 && en.Title == "플랫폼 비지빌리티 게이트웨이");
        Assert.Equal(cat.Length, PromptFlowStudio.Services.Ui.StudioCatalogHelpRegistry.Entries.Count);
        Assert.Equal(0, PromptFlowStudio.Services.Ui.StudioCatalogHelpRegistry.CountDefects());
        Assert.Equal("_platformVisibilityGateway", PromptFlowStudio.Services.Ui.StudioCatalogHelpRegistry.ResolveKeyByHeader("🌐 플랫폼 비지빌리티 게이트웨이 · 시뮬레이션"));
        var root = RepoRoot();
        string Src(params string[] p) => File.ReadAllText(Path.Combine(root, Path.Combine(p)));
        var hud = Src("PromptFlowStudio", "Blazor", "Components", "Common", "GlobalTelemetryHudView.razor");
        var layout = Src("PromptFlowStudio", "Blazor", "MainLayout.razor");
        var modalSrc = Src("PromptFlowStudio", "Blazor", "Components", "Common", "PlatformVisibilityGatewayStudioModal.razor");
        Assert.True(hud.IndexOf("gth-v1794", StringComparison.Ordinal) is > 0 and var i1794 && i1794 < hud.IndexOf("gth-v1793", StringComparison.Ordinal) && hud.Contains("PvgRun.OnChange += OnSwarmChanged", StringComparison.Ordinal) && hud.Contains("PvgRun.OnChange -= OnSwarmChanged", StringComparison.Ordinal));
        Assert.True(layout.Contains("<PlatformVisibilityGatewayStudioModal", StringComparison.Ordinal) && layout.Contains("case \"_platformVisibilityGateway\"", StringComparison.Ordinal) && layout.Contains("\"_platformVisibilityGateway\" =>", StringComparison.Ordinal));
        Assert.True(Src("PromptFlowStudio", "MainForm.cs").Contains("PlatformVisibility.PlatformVisibilityGatewayStudioRunner(sp)", StringComparison.Ordinal) && Src("PromptFlowStudio.Mobile", "MauiProgram.cs").Contains("PlatformVisibility.PlatformVisibilityGatewayStudioRunner(sp)", StringComparison.Ordinal));
        Assert.True(modalSrc.Contains("@implements IDisposable", StringComparison.Ordinal) && modalSrc.Contains("flex: 1 1 auto; min-height: 0; overflow-y: auto;", StringComparison.Ordinal) && modalSrc.Contains("position: sticky", StringComparison.Ordinal) && modalSrc.Contains("aria-pressed", StringComparison.Ordinal));
        foreach (var src in Directory.GetFiles(Path.Combine(root, "PromptFlowStudio", "Services", "PlatformVisibility"), "*.cs"))
        {
            var body = File.ReadAllText(src);
            Assert.True(!body.Contains("System.Linq", StringComparison.Ordinal) && !body.Contains("Process.Start", StringComparison.Ordinal) && !body.Contains("File.Write", StringComparison.Ordinal) && !body.Contains("new HttpClient", StringComparison.Ordinal), "외부 의존 · 파일 I/O " + Path.GetFileName(src));
        }
        using var sp = new HeadlessUiRendererCheck.AutoWireProvider();
        var runner = (Pvg.PlatformVisibilityGatewayStudioRunner)sp.GetService(typeof(Pvg.PlatformVisibilityGatewayStudioRunner))!;
        Assert.True(runner.LiveInjected && !runner.Gateway.LiveEndpoints);
        await runner.AdvanceAsync(30);
        Assert.True(runner.Poller.Samples > 0 && runner.Guard.Refreshes >= 2);   // 볼트 계약 Mock → 시뮬 토큰 폴백
        var html = await HeadlessUiRendererCheck.RenderAsync(typeof(PromptFlowStudio.Blazor.Components.Common.PlatformVisibilityGatewayStudioModal), sp);
        Assert.True(html.Length > 500 && html.Contains("pvg-scrim", StringComparison.Ordinal) && html.Contains("pvg-body", StringComparison.Ordinal) && html.Contains("릴스 배포", StringComparison.Ordinal) && html.Contains("pvg-quota", StringComparison.Ordinal) && html.Contains("일부 공개", StringComparison.Ordinal), "모달 렌더 " + html.Length);
        Assert.Equal(0, HeadlessUiRendererCheck.LiveSubscriberCount(runner));
        GC.Collect(); GC.WaitForPendingFinalizers(); GC.Collect();
    }

    private static string RepoRoot()
    {
        var dir = new DirectoryInfo(AppContext.BaseDirectory);
        while (dir is not null && !File.Exists(Path.Combine(dir.FullName, "build_titan_release.ps1"))) dir = dir.Parent;
        return dir?.FullName ?? throw new DirectoryNotFoundException("저장소 루트를 찾지 못함");
    }
}

[Collection("TimingSensitivePerformance")]   // 스레드 할당 바이트 계측(감정 분류 · 답글 조합 · 속도 가드 허가) → 비병렬
public sealed class GoldenHourEngagementIsolatedTests
{
    private const double T0 = 1_800_000_000;

    [Fact]
    public void GoldenHourCommentEngagement_And_Sentiment_Check()
    {
        // ── ENG-1: 감정 분류 정확도 · 스팸 자동 격리 ──
        var gw = new Ghe.SimulatedCommentModerationGateway();
        var tri = new Ghe.ZeroAllocCommentSentimentTriageEngine(gw);
        (string Text, Ghe.CommentSentiment Want, bool Hide)[] cases =
        {
            ("와 이번 편 진짜 최고예요 👍", Ghe.CommentSentiment.Positive, false),
            ("꿀팁 감사합니다 덕분에 해결했어요", Ghe.CommentSentiment.Positive, false),
            ("awesome edit, love it 🔥", Ghe.CommentSentiment.Positive, false),
            ("ㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋ 편집 센스 대박", Ghe.CommentSentiment.Positive, false),
            ("이거 어떤 프로그램으로 편집하셨나요?", Ghe.CommentSentiment.Question, false),
            ("what mic do you use?", Ghe.CommentSentiment.Question, false),
            ("다음 편은 언제 올라와요", Ghe.CommentSentiment.Question, false),
            ("방금 봤어요", Ghe.CommentSentiment.Neutral, false),
            ("이번 건 좀 지루하고 아쉽네요", Ghe.CommentSentiment.Negative, false),
            ("부업으로 월 500 수익 보장 👉 https://bit.ly/x9 무료 상담 카톡", Ghe.CommentSentiment.Spam, true),
            ("free money dm me https://t.me/xx www.scam.xyz", Ghe.CommentSentiment.Spam, true),
            ("ㅅㅂ 이게 뭐냐 시간 버렸네", Ghe.CommentSentiment.Negative, true),
            ("이딴 걸 영상이라고 올리냐 구독취소함", Ghe.CommentSentiment.Negative, true),
            ("ㅏㅏㅏㅏㅏㅏㅏㅏㅏㅏㅏㅏㅏㅏ", Ghe.CommentSentiment.Spam, true),
        };
        for (var i = 0; i < cases.Length; i++)
        {
            var r = tri.Triage(1000 + i, cases[i].Text.AsSpan());
            Assert.True(r.Sentiment == cases[i].Want, cases[i].Text + " → " + r.Sentiment);
            Assert.True(r.ShouldHide == cases[i].Hide, cases[i].Text + " hide " + r.Hide);
        }
        Assert.Equal(5, tri.Hidden);
        Assert.Equal(5, gw.Hides);
        Assert.Equal(cases.Length, tri.Scanned);
        Assert.Equal(Ghe.CommentHideReason.LinkFlood, Ghe.ZeroAllocCommentSentimentTriageEngine.Score("a https://x.com/1 b https://y.com/2".AsSpan()).Hide & Ghe.CommentHideReason.LinkFlood);
        Assert.False(Ghe.ZeroAllocCommentSentimentTriageEngine.Score("영상 링크 https://youtu.be 참고했어요 감사".AsSpan()).ShouldHide);   // 단일 링크 단독 = 허용
        // 중복 숨김 차단 · 게이트웨이 실패 격리
        tri.Triage(1009, cases[9].Text.AsSpan());
        Assert.Equal(1, tri.DuplicateSkips);
        Assert.Equal(5, gw.Hides);
        gw.InjectFailures(1, 503);
        tri.Triage(2000, cases[10].Text.AsSpan());
        Assert.Equal(1, tri.HideFailures);
        Assert.False(tri.AlreadyHidden(2000));
        tri.Triage(2000, cases[10].Text.AsSpan());
        Assert.True(tri.AlreadyHidden(2000));

        // ── ENG-2: 앵커 고정 60 s · 톤 맞춤 답글 ──
        var res = new Ghe.GoldenHourSmartEngagementResponder();
        Assert.False(res.TryPublishPinned(T0, gw));   // 업로드 전
        res.MarkUploaded(T0);
        gw.InjectFailures(1, 503);
        Assert.False(res.TryPublishPinned(T0 + 5, gw));
        Assert.True(res.TryPublishPinned(T0 + 10, gw));
        Assert.True(res.PinnedInWindow && res.PinDelaySec == 10 && res.PinAttempts == 2);
        Assert.False(res.TryPublishPinned(T0 + 15, gw));   // 중복 고정 차단
        res.PinnedTemplate = "   ";
        Assert.Equal(Ghe.GoldenHourSmartEngagementResponder.DefaultPinnedTemplate, res.PinnedTemplate);
        res.PinnedTemplate = new string('x', 500);
        Assert.Equal(Ghe.GoldenHourSmartEngagementResponder.ReplyCap, res.PinnedTemplate.Length);
        Assert.False(res.TryCompose(Ghe.CommentSentiment.Spam, 1, "spam".AsSpan()));
        Assert.False(res.TryCompose(Ghe.CommentSentiment.Negative, 1, "x".AsSpan()));
        var seen = new System.Collections.Generic.HashSet<string>(StringComparer.Ordinal);
        for (var t = 0; t < 3; t++)
        {
            res.Tone = (Ghe.ChannelTone)t;
            Assert.True(res.TryCompose(Ghe.CommentSentiment.Question, 42, "민지".AsSpan()));
            var q = res.LastReply.ToString();
            Assert.StartsWith("@민지 ", q);
            Assert.True(seen.Add(q), "톤별 답글 상이 " + q);
            Assert.True(res.TryCompose(Ghe.CommentSentiment.Positive, 43, new string('가', 50).AsSpan()));
            Assert.InRange(res.LastReply.Length, 10, Ghe.GoldenHourSmartEngagementResponder.ReplyCap);
            Assert.StartsWith("@" + new string('가', Ghe.GoldenHourSmartEngagementResponder.AuthorCap) + " ", res.LastReply.ToString());
        }

        // ── ENG-3: 15~45 s 지터 · 시간당 상한 쿨다운 ──
        var g = new Ghe.EngagementVelocityAntiBotSafetyGuard(1234);
        for (var i = 0; i < 2000; i++) Assert.InRange(g.NextJitterSec(), 15.0, 45.0);
        g.Reset();
        double now = T0, prevGrant = double.NaN;
        var gaps = new System.Collections.Generic.HashSet<double>();
        while (g.Granted < 30)
        {
            var d = g.TryAcquire(now, out var wait);
            if (d == Ghe.VelocityDecision.Granted)
            {
                if (!double.IsNaN(prevGrant)) { Assert.InRange(now - prevGrant, 15.0, 46.0); gaps.Add(Math.Round(now - prevGrant)); }
                prevGrant = now;
            }
            else Assert.True(d == Ghe.VelocityDecision.Jitter && wait > 0 && wait <= 45);
            now += 1;
        }
        Assert.True(gaps.Count >= 5, "지터 간격 다양성 " + gaps.Count);   // 기계적 등간격 아님
        Assert.InRange(g.MinJitterSeen, 15.0, 45.0);
        Assert.InRange(g.MaxJitterSeen, 15.0, 45.0);
        Assert.True(g.JitterDeferrals > 0);
        now = g.NextAllowedUnix + 1;
        Assert.Equal(Ghe.VelocityDecision.CoolDown, g.TryAcquire(now, out var cool));
        Assert.True(g.CoolingDown && g.CoolDowns == 1 && cool > 0 && cool <= 3600);
        Assert.Equal(Ghe.VelocityDecision.CoolDown, g.TryAcquire(now + 5, out _));
        Assert.Equal(1, g.CoolDowns);   // 진입은 1 회만 카운트
        Assert.Equal(30, g.CountInWindow(now));
        Assert.Equal(Ghe.VelocityDecision.Granted, g.TryAcquire(now + cool + 0.001, out _));
        Assert.False(g.CoolingDown);
        g.HourlyCap = 1; Assert.Equal(Ghe.EngagementVelocityAntiBotSafetyGuard.MinHourlyCap, g.HourlyCap);
        g.HourlyCap = 999; Assert.Equal(Ghe.EngagementVelocityAntiBotSafetyGuard.RingCap, g.HourlyCap);

        // ── 무할당: 분류 · 답글 조합 · 허가 핫패스 ──
        var spans = new string[cases.Length];
        for (var i = 0; i < cases.Length; i++) spans[i] = cases[i].Text;
        var hot = new Ghe.ZeroAllocCommentSentimentTriageEngine(new Ghe.SimulatedCommentModerationGateway());
        var hg = new Ghe.EngagementVelocityAntiBotSafetyGuard();
        for (var w = 0; w < 3; w++) for (var i = 0; i < spans.Length; i++) { hot.Triage(i, spans[i].AsSpan()); res.TryCompose(Ghe.CommentSentiment.Question, i, "민지".AsSpan()); hg.TryAcquire(T0 + i * 50, out _); }
        var a0 = GC.GetAllocatedBytesForCurrentThread();
        for (var k = 0; k < 200; k++)
            for (var i = 0; i < spans.Length; i++)
            {
                hot.Triage(10_000 + k * 64 + i, spans[i].AsSpan());
                res.TryCompose(Ghe.CommentSentiment.Positive, k + i, "jay_k".AsSpan());
                hg.TryAcquire(T0 + 10_000 + (k * spans.Length + i) * 3.0, out _);
            }
        var alloc = GC.GetAllocatedBytesForCurrentThread() - a0;
        Assert.True(alloc == 0, "골든아워 핫패스 할당 " + alloc);

        // ── 러너 E2E: 업로드 → 60 s 내 고정 → 60 분 완주 · 상한 준수 ──
        using var run = new Ghe.GoldenHourEngagementStudioRunner();
        var changes = 0;
        run.OnChange += () => changes++;
        run.SetHourlyCap(30);
        run.Upload();
        Assert.True(run.Responder.PinnedInWindow);
        run.InjectSpamRaid();
        Assert.True(run.Triage.Hidden >= 6);
        run.InjectQuestionFlood();
        run.RunGoldenHour();
        Assert.Equal(0, run.RemainingSec);
        Assert.True(run.Replies > 0 && run.Replies <= 30, "답글 " + run.Replies);
        Assert.True(run.HourlyCount <= run.Guard.HourlyCap);
        Assert.True(run.Triage.Count(Ghe.CommentSentiment.Question) > 0 && run.Triage.Count(Ghe.CommentSentiment.Positive) > 0);
        Assert.True(run.Guard.CoolDowns >= 1, "질문 폭주 → 쿨다운 진입");
        Assert.True(run.LogCount > 0 && changes > 0);
        run.Reset();
        Assert.Equal(0, run.Triage.Scanned);
        Assert.False(run.Responder.Uploaded);

        // ── 카탈로그 · 도움말 결선(171) ──
        var cat = PromptFlowStudio.Services.Ui.StudioCatalog.Entries;
        Assert.True(cat.Length >= 171);
        Assert.Contains(cat, e => e.Key == "_goldenHourEngagement" && e.Category == 4);
        Assert.NotNull(PromptFlowStudio.Services.Ui.StudioCatalogHelpRegistry.Find("_goldenHourEngagement"));
        Assert.Equal(cat.Length, PromptFlowStudio.Services.Ui.StudioCatalogHelpRegistry.Entries.Count);
        Assert.Equal(0, PromptFlowStudio.Services.Ui.StudioCatalogHelpRegistry.CountDefects());
    }
}

[Collection("TimingSensitivePerformance")]   // 스레드 할당 바이트 계측 · 100 ms 스캔 예산(피드 파싱 · 연관도 스캔 · 메타데이터 조합) → 비병렬
public sealed class SocialTrendJackingIsolatedTests
{
    private const double T0 = 1_800_000_000;
    private const string Script = "아이폰16 카메라로 야간 촬영할 때 꼭 바꿔야 할 설정 3가지! 야간 모드 노출 고정과 프로레스 촬영, 그리고 캡컷 보정까지 아이폰16 하나로 끝냅니다.";
    private const string Tags = "아이폰16,야간촬영,카메라꿀팁,아이폰카메라,캡컷";
    private const string Summary = "아이폰16 야간 촬영 설정 3가지로 밤 사진 퀄리티 2배 올리기";
    private const string Niche = "야간촬영,카메라꿀팁,아이폰카메라,폰카꿀팁";

    [Fact]
    public void SocialTrendJacking_And_HashtagInjector_Check()
    {
        // ── TRJ-1: Span 피드 파싱 · 분당 가속도 · 연관도 0~100 · 골든 ≥ 80 ──
        var radar = new Trj.RealtimeSocialTrendSpikeRadarEngine();
        radar.SetContent(Script.AsSpan(), Tags.AsSpan());
        Assert.Equal(100, radar.ScoreRelevance("아이폰16".AsSpan()));
        Assert.Equal(100, radar.ScoreRelevance("야간 촬영".AsSpan()));     // 공백 무시 태그 일치
        Assert.Equal(100, radar.ScoreRelevance("#카메라 꿀팁".AsSpan()));
        Assert.Equal(85, radar.ScoreRelevance("프로레스".AsSpan()));       // 대본 1회 출현
        Assert.Equal(35, radar.ScoreRelevance("캡컷 템플릿".AsSpan()));    // 토큰 1/2 커버
        Assert.Equal(70, radar.ScoreRelevance("아이폰16이 야간".AsSpan())); // 조사 제거 2/2 → 70(구문 불일치)
        Assert.Equal(0, radar.ScoreRelevance("흑백요리사".AsSpan()));
        Assert.Equal(0, radar.ScoreRelevance("로제 아파트".AsSpan()));

        Assert.Equal(4, radar.Ingest("아이폰16:100;흑백요리사:300\n야간 촬영:40; 카메라 꿀팁 : 20 ;".AsSpan()));
        Assert.Equal(0, radar.Ingest("bad;:5;키워드:-3;x:12a;이건스물네자를넘어가는아주아주긴키워드입니다정말로진짜:5".AsSpan()));
        Assert.Equal(5, radar.Malformed);
        radar.CloseMinute();
        radar.Ingest("아이폰16:160;흑백요리사:290;야간 촬영:55;카메라 꿀팁:21;로제 아파트:500".AsSpan());
        Assert.Equal(5, radar.TopicCount);
        Assert.Equal(3, radar.Scan());
        Assert.Equal(60, radar.Velocity(0));
        Assert.Equal(-10, radar.Velocity(1));
        Assert.Equal(60 * 100 / (100 + Trj.RealtimeSocialTrendSpikeRadarEngine.SpikeDamp), radar.SpikeIndex(0));
        Assert.Equal(0, radar.SpikeIndex(1));
        Assert.Equal("로제 아파트", radar.Keyword(radar.Ranked(0)).ToString());   // 가속도 1위(무관)
        Assert.Equal("아이폰16", radar.Keyword(radar.Ranked(1)).ToString());
        Assert.False(radar.IsGolden(radar.Ranked(0)));
        Assert.True(radar.IsGolden(0) && !radar.IsGolden(1));
        for (var i = 0; i < 40; i++) radar.Ingest(("t" + i + ":1").AsSpan());
        Assert.Equal(Trj.RealtimeSocialTrendSpikeRadarEngine.TopicCap, radar.TopicCount);
        Assert.True(radar.Dropped > 0);

        // ── TRJ-3: 무관 < 70 차단 · 4 시간 회전 쿨다운 ──
        var guard = new Trj.TrendSpikeCooldownAntiSpamGuard();
        Assert.Equal(Trj.TrendInjectDecision.BlockedIrrelevant, guard.Evaluate("흑백요리사".AsSpan(), 69, T0));
        Assert.Equal(Trj.TrendInjectDecision.Allowed, guard.Evaluate("아이폰16".AsSpan(), 70, T0));
        guard.Record("아이폰16".AsSpan(), T0);
        Assert.Equal(Trj.TrendInjectDecision.CoolingDown, guard.Evaluate("#아이폰 16".AsSpan(), 100, T0 + 3600));   // 정규형 동일 태그
        Assert.Equal(3 * 3600, guard.RemainingCooldownSec("아이폰16".AsSpan(), T0 + 3600), 3);
        Assert.Equal(1, guard.ActiveCooldowns(T0 + 100));
        Assert.Equal(Trj.TrendInjectDecision.Allowed, guard.Evaluate("아이폰16".AsSpan(), 100, T0 + Trj.TrendSpikeCooldownAntiSpamGuard.CooldownSec + 1));
        Assert.Equal(0, guard.ActiveCooldowns(T0 + Trj.TrendSpikeCooldownAntiSpamGuard.CooldownSec + 1));
        Assert.Equal(1, guard.BlockedIrrelevant);
        Assert.Equal(1, guard.BlockedCooldown);
        guard.Reset();

        // ── TRJ-2: 3 플랫폼 메타데이터 합성 ──
        var inj = new Trj.ViralHashtagDynamicMetadataInjector();
        var r2 = new Trj.RealtimeSocialTrendSpikeRadarEngine();
        r2.SetContent(Script.AsSpan(), Tags.AsSpan());
        r2.Ingest("아이폰16:100;야간 촬영:40;카메라 꿀팁:20;흑백요리사:300;캡컷 템플릿:50".AsSpan());
        r2.CloseMinute();
        r2.Ingest("아이폰16:180;야간 촬영:70;카메라 꿀팁:30;흑백요리사:400;캡컷 템플릿:90".AsSpan());
        r2.Scan();
        Assert.Equal(3, inj.Compose(r2, guard, T0, Summary.AsSpan(), Niche.AsSpan()));
        var title = inj.YouTubeTitle.ToString();
        Assert.True(title.Length <= 100, title);
        Assert.StartsWith("🔥 아이폰16 | ", title);
        Assert.Equal(3, inj.YouTubeTagCount);
        Assert.EndsWith("#아이폰16 #야간촬영 #카메라꿀팁", inj.YouTubeDescription.ToString());
        Assert.Equal(5, inj.InstagramTagCount);
        Assert.True(inj.InstagramTrendTags == 2 && inj.InstagramNicheTags == 2 && inj.InstagramMegaTags == 1);
        Assert.EndsWith("#아이폰16 #야간촬영 #카메라꿀팁 #아이폰카메라 #reels", inj.InstagramCaption.ToString());   // 틈새 중복(#야간촬영) 생략
        Assert.Contains(Summary, inj.InstagramCaption.ToString());
        Assert.True(inj.TikTokCaption.Length <= Trj.ViralHashtagDynamicMetadataInjector.TtCaptionCap);
        Assert.EndsWith("#fyp", inj.TikTokCaption.ToString());
        Assert.Equal(4, inj.TikTokTagCount);
        Assert.DoesNotContain("흑백요리사", inj.InstagramCaption.ToString());
        Assert.DoesNotContain("캡컷템플릿", inj.YouTubeDescription.ToString());
        // 100 자 절단 · 서로게이트 보존
        inj.Compose(r2, guard, T0, (new string('가', 120) + "🔥").AsSpan(), Niche.AsSpan());
        Assert.Equal(100, inj.YouTubeTitle.Length);
        Assert.EndsWith("…", inj.YouTubeTitle.ToString());
        // 커밋 → 재조합 시 쿨다운으로 트렌드 0 · 틈새/메가만 유지
        inj.Compose(r2, guard, T0, Summary.AsSpan(), Niche.AsSpan());
        inj.Commit(r2, guard, T0);
        Assert.Equal(0, inj.Compose(r2, guard, T0 + 60, Summary.AsSpan(), Niche.AsSpan()));
        Assert.Equal(5, inj.InstagramTagCount);
        Assert.Equal(0, inj.InstagramTrendTags);
        Assert.DoesNotContain("🔥", inj.YouTubeTitle.ToString());
        Assert.Equal(3, inj.Compose(r2, guard, T0 + Trj.TrendSpikeCooldownAntiSpamGuard.CooldownSec, Summary.AsSpan(), Niche.AsSpan()));

        // ── 무할당 · 100 ms 예산: 피드 파싱 · 스캔 · 조합 · 가드 판정 ──
        var feeds = new string[8];
        for (var m = 0; m < feeds.Length; m++)
        {
            var sb = new System.Text.StringBuilder();
            for (var i = 0; i < Trj.TrendJackingStudioRunner.FeedKeywords.Length; i++) sb.Append(Trj.TrendJackingStudioRunner.FeedKeywords[i]).Append(':').Append(100 + i * 7 + m * (i + 3)).Append(';');
            feeds[m] = sb.ToString();
        }
        var hr = new Trj.RealtimeSocialTrendSpikeRadarEngine();
        var hg = new Trj.TrendSpikeCooldownAntiSpamGuard();
        var hi = new Trj.ViralHashtagDynamicMetadataInjector();
        hr.SetContent(Script.AsSpan(), Tags.AsSpan());
        for (var w = 0; w < 3; w++) { hr.CloseMinute(); hr.Ingest(feeds[w].AsSpan()); hr.Scan(); hi.Compose(hr, hg, T0, Summary.AsSpan(), Niche.AsSpan()); hg.Evaluate("흑백요리사".AsSpan(), 0, T0); }
        var sw = new System.Diagnostics.Stopwatch();   // 계측 구간 밖 생성(객체 40 B)
        var a0 = GC.GetAllocatedBytesForCurrentThread();
        sw.Start();
        for (var k = 0; k < 400; k++)
        {
            hr.CloseMinute();
            hr.Ingest(feeds[k % feeds.Length].AsSpan());
            hr.Scan();
            hi.Compose(hr, hg, T0 + k, Summary.AsSpan(), Niche.AsSpan());
            hg.Evaluate("흑백요리사".AsSpan(), hr.ScoreRelevance("흑백요리사".AsSpan()), T0 + k);
        }
        sw.Stop();
        var alloc = GC.GetAllocatedBytesForCurrentThread() - a0;
        Assert.True(alloc == 0, "트렌드재킹 핫패스 할당 " + alloc);
        Assert.True(sw.Elapsed.TotalMilliseconds / 400 < 100, "1 사이클 " + sw.Elapsed.TotalMilliseconds / 400 + " ms");

        // ── 러너 E2E: 수신 → 주입 → 쿨다운 재주입 차단 → 무관 강제 차단 → 4 시간 후 재주입 ──
        using var run = new Trj.TrendJackingStudioRunner();
        var changes = 0;
        run.OnChange += () => changes++;
        Assert.Equal(3, run.Advance(3));
        Assert.True(run.LastScanMicros < 100_000);
        Assert.Equal(3, run.Inject());
        Assert.Equal(1, run.Injections);
        Assert.Equal(3, run.ActiveCooldowns);
        Assert.Equal(0, run.Inject());
        Assert.True(run.Guard.BlockedCooldown >= 3);
        Assert.Equal(Trj.TrendInjectDecision.BlockedIrrelevant, run.ForceIrrelevant());
        Assert.True(run.Guard.BlockedIrrelevant >= 1);
        run.SkipCooldown();
        Assert.Equal(0, run.ActiveCooldowns);
        Assert.Equal(3, run.Inject());
        run.SetPreset(1);
        Assert.Equal(2, run.Radar.GoldenCount);   // 할로윈 메이크업(태그) · 좀비 분장(대본)
        run.SetPlatform(Trj.TrendPlatform.InstagramReels);
        Assert.Contains("#reels", run.Injector.Primary(run.Platform).ToString());
        run.SetSummary("   ");
        Assert.False(string.IsNullOrWhiteSpace(run.Summary));
        Assert.True(run.LogCount > 0 && changes > 0);
        run.Reset();
        Assert.Equal(0, run.Radar.TopicCount);
        Assert.Equal(0, run.Injections);

        // ── 카탈로그 · 도움말 결선(172) ──
        var cat = PromptFlowStudio.Services.Ui.StudioCatalog.Entries;
        Assert.Equal(175, cat.Length);
        Assert.Contains(cat, e => e.Key == "_socialTrendJackingRadar" && e.Category == 4 && e.Title == "실시간 트렌드재킹 & 해시태그 레이더");
        Assert.NotNull(PromptFlowStudio.Services.Ui.StudioCatalogHelpRegistry.Find("_socialTrendJackingRadar"));
        Assert.Equal(cat.Length, PromptFlowStudio.Services.Ui.StudioCatalogHelpRegistry.Entries.Count);
        Assert.Equal(0, PromptFlowStudio.Services.Ui.StudioCatalogHelpRegistry.CountDefects());
        Assert.Equal("_socialTrendJackingRadar", PromptFlowStudio.Services.Ui.StudioCatalogHelpRegistry.ResolveKeyByHeader("🔥 실시간 트렌드재킹 & 해시태그 레이더"));
    }
}

[Collection("TimingSensitivePerformance")]   // 스레드 할당 바이트 계측 · 100 ms 예산(상품 매칭 · 숏링크/고지 조립 · 클릭 판정) → 비병렬
public sealed class ViralCommerceAffiliateIsolatedTests
{
